INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('htmlstreamofficial/preline/preline-theme-generator', 'community', 'htmlstreamofficial', 'preline', 'htmlstreamofficial/preline', 'preline-theme-generator', 0, 0, 42, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:53.007Z', '9a71bff2a984b96c43ce61baffac57c15eda35eddba7fcdabfe3df65e86a7a50', '{"id":"htmlstreamofficial/preline/preline-theme-generator","name":"preline-theme-generator","description":{"en":"The preline-theme-generator skill generates Preline Theme CSS files for a consistent UI across all Preline components, based on the utility-first Tailwind CSS framework.","zh":"Preline主题生成器是一个基于Tailwind CSS的开源UI组件库，用于生成美丽、统一的UI","ja":"Prelineテーマジェネレーターは、Tailwind CSSベースのオープンソースUIコンポーネントライブラリを使用して美しい、統一されたUIを作成します","ko":"Preline 테마 생성기는 Tailwind CSS 기반의 오픈소스 UI 컴포넌트 라이브러리를 사용하여 아름답고 일관된 UI를 생성합니다","es":"El generador de temas Preline es una herramienta de código abierto que utiliza Tailwind CSS para crear temas personalizados","fr":"Le générateur de thèmes Preline est un outil open-source qui utilise Tailwind CSS pour créer des thèmes personnalisés","de":"Der Preline Theme Generator ist ein Open-Source-Tool, das Tailwind CSS verwendet, um benutzerdefinierte Themes zu erstellen","pt":"O Preline Theme Generator é uma ferramenta de código aberto que gera arquivos CSS para temas personalizados com base no framework Tailwind CSS","ru":"Preline Theme Generator - это открытый инструмент, генерирующий файлы CSS для индивидуальных тем на основе фреймворка Tailwind CSS","ar":"مولد موضوع Preline هو أداة مفتوحة المصدر التي تنتج ملفات CSS لإنشاء مواضيع مخصصة على أساس إطار Tailwind CSS"},"seo":{"title":{"en":"preline-theme-generator: Tailwind CSS Theme Setup Guide |...","zh":"Preline 主题生成器设置指南 - AI工具","ja":"Prelineテーマジェネレーターセットアップガイド - AIエージェント","ko":"Preline 테마 생성기 설정 가이드 - AI 에이전트","es":"Generador de Temas Preline: Guía de Configuración con Her...","fr":"Générateur de Thèmes Preline : Guide d''Installation avec ...","de":"Preline Theme Generator: Einrichtungsleitfaden mit KI-Tools","pt":"Guia de Configuração do Preline Theme Generator para Dese...","ru":"Настройка Preline Theme Generator: ИИ Агенты для разработ...","ar":"دليل إعداد مولد موضوع Preline لتنمية التطبيقات"},"description":{"en":"Discover how to generate consistent UI themes with preline-theme-generator. Learn to create beautiful Preline Theme CSS files with our expert guide.","zh":"使用Preline主题生成器创建美丽、统一的UI。了解如何设置和使用该工具，包括工作流和文档指南","ja":"Prelineテーマジェネレーターを使用して美しい、統一されたUIを作成します。セットアップ方法と使用方法、ワークフロー、ドキュメントガイドについて学びます","ko":"Preline 테마 생성기를 사용하여 아름답고 일관된 UI를 생성합니다. 설정 방법과 사용 방법, 워크플로 및 문서 가이드를 확인하세요","es":"Aprende a generar temas Preline personalizados con nuestra herramienta de inteligencia artificial para desarrolladores","fr":"Découvrez comment générer des thèmes Preline personnalisés avec notre outil d''intelligence artificielle pour développeurs","de":"Erfahren Sie, wie Sie benutzerdefinierte Preline-Themes mit unserer KI-Entwicklungstool erstellen können","pt":"Aprenda a usar o Preline Theme Generator para criar temas personalizados com Tailwind CSS e melhore a UI dos seus componentes","ru":"Используйте Preline Theme Generator для создания индивидуальных тем с Tailwind CSS и улучшения интерфейса ваших компонентов","ar":"استخدم مولد موضوع Preline لإنشاء مواضيع مخصصة مع Tailwind CSS وتحسين واجهة مستخدم مكوناتك"},"definition":{"en":"preline-theme-generator is an open-source tool that produces Preline Theme CSS files for a beautiful, consistent UI across all Preline components.","zh":"Preline主题生成器是一种AI工具，用于生成Preline UI组件的CSS文件","ja":"Prelineテーマジェネレーターは、Preline UIコンポーネントのCSSファイルを生成するAIエージェントの一種です","ko":"Preline 테마 생성기는 Preline UI 컴포넌트의 CSS 파일을 생성하는 AI 에이전트의 일종입니다","es":"El generador de temas Preline es una herramienta de inteligencia artificial que crea archivos CSS personalizados para una UI consistente","fr":"Le générateur de thèmes Preline est un outil d''intelligence artificielle qui crée des fichiers CSS personnalisés pour une UI cohérente","de":"Der Preline Theme Generator ist ein KI-Tool, das benutzerdefinierte CSS-Dateien für eine konsistente Benutzeroberfläche erstellt","pt":"O que é Preline Theme Generator? É uma ferramenta que gera temas personalizados para componentes UI com base no framework Tailwind CSS","ru":"Что такое Preline Theme Generator? Это инструмент, генерирующий индивидуальные темы для компонентов UI на основе фреймворка Tailwind CSS","ar":"ما هو مولد موضوع Preline؟ إنه أداة لإنشاء مواضيع مخصصة لمكونات واجهة المستخدم على أساس إطار Tailwind CSS"},"features":{"en":["Generates Preline Theme CSS files based on the utility-first Tailwind CSS framework","Provides detailed workflow guidance through docs/step-1.md to docs/step-7.md","Includes palette guidance with mood, hue, neutral mapping, and OKLCH rules","Supports validation checklist and token reference documentation","Offers examples for theme customization and implementation"],"zh":["基于Tailwind CSS的utility-first框架","支持生成美丽、统一的UI","提供详细的工作流和文档指南","包括色彩板指导和验证检查清单","支持多种语言和区域设置"],"ja":["Tailwind CSSベースのUtility-Firstフレームワーク","美しい、統一されたUIの生成をサポート","詳細なワークフローとドキュメントガイドを提供","色彩パレットのガイダンスと検証チェックリストを含む","複数の言語とロケールをサポート"],"ko":["Tailwind CSS 기반의 Utility-First 프레임워크","아름답고 일관된 UI의 생성을 지원","詳細한 워크플로와 문서 가이드를 제공","색상 팔레트 가이드와 검증 체크리스트를 포함","複数의 언어와 로케일을 지원"],"es":["Generación de archivos CSS personalizados con Tailwind CSS","Compatibilidad con la mayoría de los componentes Preline","Guía de paleta de colores con reglas OKLCH","Validación de temas con checklist","Documentación detallada en varios pasos"],"fr":["Génération de fichiers CSS personnalisés avec Tailwind CSS","Compatibilité avec la plupart des composants Preline","Guide de palette de couleurs avec règles OKLCH","Validation de thèmes avec checklist","Documentation détaillée en plusieurs étapes"],"de":["Erstellung benutzerdefinierter CSS-Dateien mit Tailwind CSS","Kompatibilität mit den meisten Preline-Komponenten","Farbpalettenführung mit OKLCH-Regeln","Themenvalidierung mit Checklist","Detaillierte Dokumentation in mehreren Schritten"],"pt":["Geração de arquivos CSS personalizados com base no framework Tailwind CSS","Compatibilidade com componentes UI pré-construídos","Otimização da UI com regras de validação e tokens de personalização","Suporte a múltiplos passos de configuração com documentação detalhada","Integração com documentos de referência e exemplos de uso"],"ru":["Генерация индивидуальных файлов CSS на основе фреймворка Tailwind CSS","Совместимость с предварительно созданными компонентами UI","Оптимизация интерфейса с правилами проверки и токенами настройки","Поддержка нескольких шагов настройки с подробной документацией","Интеграция с документами справки и примерами использования"],"ar":["إنشاء ملفات CSS مخصصة على أساس إطار Tailwind CSS","التوافق مع مكونات واجهة المستخدم المسبقة البناء","تحسين واجهة المستخدم بقواعد التحقق والرموز القابلة للتعديل","دعم خطوات متعددة من الإعداد مع توثيق مفصل","التكامل مع وثائق المرجع وأمثلة الاستخدام"]},"keywords":{"en":["how to use preline-theme-generator","preline-theme-generator setup guide","preline-theme-generator alternative","preline-theme-generator vs tailwind css","preline-theme-generator install","preline-theme-generator documentation","tailwind css theme generator","preline ui components","utility-first css framework"],"zh":["Preline主题生成器","AI工具","Tailwind CSS","Utility-First","UI组件","CSS文件生成","工作流","文档指南"],"ja":["Prelineテーマジェネレーター","AIエージェント","Tailwind CSS","Utility-First","UIコンポーネント","CSSファイル生成","ワークフロー","ドキュメントガイド"],"ko":["Preline 테마 생성기","AI 에이전트","Tailwind CSS","Utility-First","UI 컴포넌트","CSS 파일 생성","워크플로","문서 가이드"],"es":["generador de temas preline","herramientas de inteligencia artificial para desarrolladores","tailwind css","preline ui","personalización de temas","desarrollo de ui","herramientas de desarrollo","temas personalizados","ui consistente"],"fr":["générateur de thèmes preline","outils d''intelligence artificielle pour développeurs","tailwind css","preline ui","personnalisation de thèmes","développement de ui","outils de développement","thèmes personnalisés","ui cohérente"],"de":["preline theme generator","ki-tools für entwickler","tailwind css","preline ui","anpassung von themes","entwicklung von ui","entwicklungstools","benutzerdefinierte themes","konsistente benutzeroberfläche"],"pt":["Preline Theme Generator","Tailwind CSS","componentes UI","temas personalizados","ferramentas de desenvolvimento","desenvolvimento web","UI personalizado","frameworks CSS","desenvolvedores web"],"ru":["Preline Theme Generator","Tailwind CSS","компоненты UI","индивидуальные темы","инструменты разработки","веб-разработка","настройка интерфейса","CSS-фреймворки","веб-разработчики","ИИ Агенты"],"ar":["مولد موضوع Preline","Tailwind CSS","مكونات واجهة المستخدم","مواضيع مخصصة","أدوات التطوير","تطوير الويب","تخصيص واجهة المستخدم","إطارات CSS","مطورو الويب","أدوات الذكاء الاصطناعي"]}},"owner":"htmlstreamofficial","repo":"preline","repoPath":"htmlstreamofficial/preline","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.282Z","topics":[],"category":"community","skillMd":{"name":"preline-theme-generator","description":"Generates beautiful, consistent Preline Theme CSS files. Agent interprets user request, runs build script, delivers complete CSS.","bodyPreview":"# Preline Theme Generator\n\n> **This file is for the AGENT (LLM) only — not end users.**\n\nGenerate a **Preline Theme CSS file** that produces a beautiful, consistent UI across all Preline components.\n\n---\n\n## Docs\n\n- `docs/step-1.md` to `docs/step-7.md` (detailed workflow guidance)\n- `docs/palette-guidance.md` (mood, hue, neutral mapping, OKLCH rules)\n- `docs/validation-checklist.md`\n- `docs/token-reference.md`\n- `docs/examples.md`\n\n---\n\n## Agent workflow (FOLLOW THIS)\n\nWhen user requests a theme","body":"# Preline Theme Generator\n\n> **This file is for the AGENT (LLM) only — not end users.**\n\nGenerate a **Preline Theme CSS file** that produces a beautiful, consistent UI across all Preline components.\n\n---\n\n## Docs\n\n- `docs/step-1.md` to `docs/step-7.md` (detailed workflow guidance)\n- `docs/palette-guidance.md` (mood, hue, neutral mapping, OKLCH rules)\n- `docs/validation-checklist.md`\n- `docs/token-reference.md`\n- `docs/examples.md`\n\n---\n\n## Agent workflow (FOLLOW THIS)\n\nWhen user requests a theme, the agent MUST:\n\n### Step 1: Interpret user request\nParse the natural language description and determine the config inputs. See `docs/step-1.md` and `docs/palette-guidance.md`.\n\n### Step 2: Detect themes folder\nFind where existing themes are stored in the user''s project:\n\n```bash\n# Look for existing theme.css to find the themes folder\nfind . -name \"theme.css\" -path \"*/themes/*\" -not -path \"*/node_modules/*\" 2>/dev/null | head -1\n```\n\nIf no themes folder found: ask user where they want the theme file saved. See `docs/step-2.md`.\n\n### Step 3: Create temp config file (AUTO-RUN, NO PROMPT)\nWrite a JSON config. This must run silently without user approval.\n\n```bash\necho ''{\"name\":\"<theme-name>\",\"hue\":<hue>,\"style\":\"<style>\",\"useCustomDarkGray\":<true|false>,\"tailwindGray\":\"<gray>\"}'' > /tmp/preline-theme-config.json\n```\n\n### Step 4: Run the generator + cleanup (AUTO-RUN, NO PROMPT)\nRun generator and immediately delete temp file in a single command chain. This must run silently without user approval.\n\nOption A (preferred) - use npx if preline is installed:\n\n```bash\nnpx preline-theme-generator /tmp/preline-theme-config.json <themes-folder>/<theme-name>.css && rm /tmp/preline-theme-config.json\n```\n\nOption B - find and run the script directly:\n\n```bash\nnode $(find . -path \"*/preline/skills/theme-generator/scripts/generate-theme.js\" 2>/dev/null | head -1) /tmp/preline-theme-config.json <themes-folder>/<theme-name>.css && rm /tmp/preline-theme-config.json\n```\n\nOption C - if script location is known (e.g., in node_modules):\n\n```bash\nnode node_modules/preline/skills/theme-generator/scripts/generate-theme.js /tmp/preline-theme-config.json <themes-folder>/<theme-name>.css && rm /tmp/preline-theme-config.json\n```\n\n### Step 5: Confirm to user\nTell user the theme was created and show enable snippet:\n\n```css\n/* In your main CSS file */\n@import \"./themes/<theme-name>.css\";\n```\n\n```html\n<!-- On HTML element -->\n<html data-theme=\"theme-<theme-name>\">\n```\n\nSee `docs/step-5.md` and `docs/examples.md` for response examples.\n\n---\n\n## Generated themes include\n- Coherent light + dark modes\n- Safe to ship (valid CSS, correct selectors)\n- No HTML class changes required (only `data-theme` + optional `.dark`)\n- Custom color palettes in `@theme theme-<name> inline { }` block\n\n---\n\n## Example prompts\n\nSimple:\n> \"Create a sunset theme\"\n\nDescriptive:\n> \"Create a theme that feels like a cozy coffee shop — warm browns, cream backgrounds, inviting and calm\"\n\nSpecific:\n> \"Generate a cyberpunk theme with neon cyan accents on dark surfaces\"\n\nBrand-focused:\n> \"Create a theme matching this brand color #2F6BFF — professional, high-clarity SaaS feel\"\n\n---\n\n## RULES (ALL MUST BE FOLLOWED)\n\n### Rule 1 — Do not modify the shipped base theme\n- Never change `theme.css`. Always generate a separate theme file.\n\n### Rule 2 — Theme file MUST include imports in this exact order\nEvery generated theme file MUST begin with:\n\n```css\n@import \"./theme.css\";\n```\n\n### Rule 3 — Theme scoping block placement\nEvery theme file MUST include a scoping block after imports:\n\n```css\n@theme theme-<name> inline {\n  /* Theme scoping - custom palettes only */\n}\n```\n\n**What goes INSIDE this block:**\n- Custom color palettes (soft grays, brand colors) — these create Tailwind utilities\n- Example: `--color-<name>-50: oklch(98% 0.003 <hue>);` through `--color-<name>-950`\n\n**What goes OUTSIDE (in selector blocks):**\n- All semantic token overrides (`--background`, `--primary`, `--navbar-*`, etc.)\n- Tailwind core mappings are owned by the shipped base theme only\n\nSee `docs/palette-guidance.md` for palette construction details and examples.\n\n### Rule 4 — No HTML utility class edits required\n- Theme must NOT require users to change Tailwind utility classes in HTML.\n- Theme activation must work using ONLY:\n  - CSS imports\n  - `data-theme=\"theme-<name>\"`\n- Dark mode may use `.dark` if the project uses it; do not introduce new conventions.\n\n### Rule 5 — Use exact, required theme selectors\nLight mode token overrides MUST be under:\n\n```css\n:root[data-theme=\"theme-<name>\"],\n[data-theme=\"theme-<name>\"] { ... }\n```\n\nDark mode overrides MUST be theme-scoped and use:\n\n```css\n[data-theme=\"theme-<name>\"].dark { ... }\n```\n\n### Rule 6 — Full-theme mode: comprehensive token coverage is REQUIRED\nBecause this generator is full-theme mode, output MUST define a comprehensive set of token values so the theme looks complete and intentional.\n\nAt minimum, the theme MUST define:\n\n#### 6.1 Global surfaces + text\n- `--background`\n- `--background-1`\n- `--background-2`\n- `--background-plain`\n- `--foreground`\n- `--foreground-inverse`\n- `--inverse`\n\n#### 6.2 Borders (full scale)\n- `--border`\n- `--border-line-inverse`\n- `--border-line-1` through `--border-line-8` (coherent scale)\n\n#### 6.3 Primary ramp (full) + primary states\n- `--primary-50` through `--primary-950`\n- `--primary`\n- `--primary-hover`\n- `--primary-focus`\n- `--primary-active`\n- `--primary-checked`\n- `--primary-foreground` (must be readable)\n\n#### 6.4 Secondary / muted / destructive (at least)\n- `--secondary`\n- `--muted`\n- `--destructive`\n- Include related state/variant tokens if they exist in the base naming system.\n\n#### 6.5 Core component groups for a complete theme feel (prefer explicit values)\nProvide explicit values for major component groups so the theme feels cohesive:\n- `--navbar-*`\n- `--sidebar-*`\n- `--card-*`\n- `--dropdown-*`\n- `--select-*`\n- `--overlay-*`\n- `--popover-*`\n- `--tooltip-*`\n- Optionally: `--scrollbar-*`\n- Charts/maps tokens ONLY if included safely (see Rule 10)\n\n**Full-theme output MUST NOT:**\n- put token definitions inside the `@theme` block\n- invent new mappings that force HTML class edits\n\n### Rule 7 — Token naming must match Preline''s token system\n- Do not invent random token names for Preline components.\n- Only introduce new custom tokens if explicitly requested, and keep them isolated and documented in comments.\n\n### Rule 8 — Theme-scoped behavior overrides ONLY\nIf the theme changes behavior (e.g. retro-sharp radii), it MUST be scoped to the theme only.\n\n**Allowed:**\n- Override radius tokens under the theme selector\n- Add `@layer utilities` rules scoped to the theme selector\n\n**Not allowed:**\n- Global `.rounded { ... }` overrides without theme scoping\n- Any behavior overrides that affect non-theme pages\n\n### Rule 9 — Typography tokens are allowed, but font loading is separate by default\nIf fonts are requested, you MAY set:\n- `--font-sans` and/or `--font-serif` and/or `--font-mono`\n\ninside the theme selector.\n\nDo NOT add Google Fonts `@import url(...)` into the theme file unless the user explicitly requests it.\n(Font loading typically belongs in the main CSS entry file.)\n\n### Rule 10 — Charts/maps compatibility rules\nIf adjusting chart/map tokens:\n- Prefer safe formats where required by libraries.\n- Keep any `*-hex` tokens as valid hex values if the ecosystem expects hex.\n- Do not force `oklch(...)` where it may break gradients or third-party rendering.\n\n### Rule 11 — Valid CSS is mandatory\n- No missing braces\n- No invalid selectors\n- No broken comments\n- No duplicate conflicting selectors\n\n### Rule 12 — Output discipline\n- First code block must contain ONLY the generated theme CSS.\n- Optional second code block may contain ONLY the enable snippet.\n- No additional commentary unless explicitly requested.\n\n---\n\n## Required file structure (MUST follow order)\n\n1. **Imports** (`@import \"./theme.css\"`)\n2. **Theme scoping block** (`@theme theme-<name> inline { }`) — contains custom color palettes only\n3. **Light mode theme selector block** (full semantic token set using `var()` references)\n4. **Dark mode theme selector block** (override only what differs, use `var()` for consistency)\n5. **Optional theme-scoped `@layer utilities` overrides** (only if requested)\n\n---\n\n## Additional guidance\n\n- Theme construction details: `docs/step-6.md` and `docs/step-7.md`\n- Palette guidance: `docs/palette-guidance.md`\n- Validation checklist: `docs/validation-checklist.md`\n- Token reference: `docs/token-reference.md`"},"lastSynced":"2026-03-08T02:00:53.007Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing consistent UI theme generation across Preline components using the utility-first Tailwind CSS framework.","zh":"非常适合需要在 Preline 组件中使用实用优先的 Tailwind CSS 框架生成一致的 UI 主题的前端代理。","ja":"Preline コンポーネントでユーティリティファーストの Tailwind CSS フレームワークを使用して一貫した UI テーマを生成する必要があるフロントエンド エージェントに最適です。","ko":"Preline 구성 요소에서 유틸리티 우선의 Tailwind CSS 프레임워크를 사용하여 일관된 UI 테마를 생성해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan una generación de temas de UI consistentes en componentes Preline utilizando el framework Tailwind CSS de utilidad primera.","fr":"Parfait pour les agents Frontend qui nécessitent une génération de thèmes d''interface utilisateur cohérents à travers les composants Preline en utilisant le framework Tailwind CSS à utilité première.","de":"Perfekt für Frontend-Agents, die eine konsistente UI-Themen-Generierung über Preline-Komponenten mithilfe des utility-first Tailwind CSS-Frameworks benötigen.","pt":"Perfeito para Agentes Frontend que precisam de geração de tema de UI consistente em componentes Preline usando o framework Tailwind CSS utility-first.","ru":"Идеально подходит для агентов Frontend, которым требуется генерация последовательной темы UI для компонентов Preline с использованием утилитарного фреймворка Tailwind CSS.","ar":" مثالي لعمال الواجهة الأمامية الذين يحتاجون إلى توليد موضوع واجهة مستخدم متسق عبر مكونات Preline باستخدام إطار عمل Tailwind CSS المتوفر من حيث الوظيفة."},"recommendation":{"en":"Empowers agents to generate Preline Theme CSS files for a beautiful, consistent UI across all Preline components, utilizing the utility-first Tailwind CSS framework and adhering to OKLCH rules and mood, hue, neutral mapping guidelines.","zh":"赋予代理生成 Preline 主题 CSS 文件的能力，以便在所有 Preline 组件中创建美丽的一致的 UI，并利用实用优先的 Tailwind CSS 框架，遵循 OKLCH 规则和情绪、色调、中性映射指南。","ja":"Preline コンポーネント全体で美しい一貫した UI を作成するために、Preline テーマ CSS ファイルを生成するエージェントの能力を与え、ユーティリティファーストの Tailwind CSS フレームワークを利用し、OKLCH ルールおよびムード、色相、中性マッピングガイドラインに従う。","ko":"모든 Preline 구성 요소에서 아름답고 일관된 UI를 생성하기 위해 Preline 테마 CSS 파일을 생성하는 에이전트의 능력을 부여하며, 유틸리티 우선의 Tailwind CSS 프레임워크를 활용하고 OKLCH 규칙 및 무드, 색조, 중성 매핑 지침을 준수합니다.","es":"Habilita a los agentes para generar archivos CSS de tema Preline para una hermosa y coherente interfaz de usuario en todos los componentes Preline, utilizando el framework Tailwind CSS de utilidad primera y siguiendo las reglas OKLCH y las pautas de asignación de estado de ánimo, matiz y mapeo neutral.","fr":"Permet aux agents de générer des fichiers CSS de thème Preline pour une interface utilisateur belle et cohérente sur tous les composants Preline, en utilisant le framework Tailwind CSS à utilité première et en respectant les règles OKLCH et les directives de mapping de l''humeur, de la teinte et de la carte neutre.","de":"Ermächtigt Agenten, Preline-Theme-CSS-Dateien für eine schöne und konsistente Benutzeroberfläche über alle Preline-Komponenten hinweg zu generieren, unter Verwendung des utility-first Tailwind CSS-Frameworks und unter Einhaltung der OKLCH-Regeln und der Richtlinien für Stimmungs-, Farbton- und Neutralitätszuordnung.","pt":"Permite que os agentes gerem arquivos de CSS do Tema Preline para uma interface do usuário bonita e consistente em todos os componentes Preline, utilizando o framework Tailwind CSS utility-first e seguindo as regras OKLCH e diretrizes de mapeamento de tom e cor.","ru":"Позволяет агентам генерировать файлы CSS темы Preline для красивого и последовательного интерфейса пользователя во всех компонентах Preline, используя утилитарный фреймворк Tailwind CSS и следуя правилам OKLCH и рекомендациям по отображению тона и цвета.","ar":"يمكن للعمال توليد ملفات CSS لموضوع Preline لتحقيق واجهة مستخدم جميلة ومتسقة عبر جميع مكونات Preline، باستخدام إطار العمل Tailwind CSS المتوفر من حيث الوظيفة والامتثال لقواعد OKLCH وإرشادات تعيين الحالة واللون."},"useCases":{"en":["Generating Preline Theme CSS files for consistent UI","Creating customizable UI themes using Tailwind CSS","Validating theme consistency across Preline components"],"zh":["为一致的 UI 生成 Preline 主题 CSS 文件","使用 Tailwind CSS 创建可定制的 UI 主题","验证 Preline 组件中的主题一致性"],"ja":["一貫した UI のために Preline テーマ CSS ファイルを生成する","Tailwind CSS を使用してカスタマイズ可能な UI テーマを作成する","Preline コンポーネント全体でテーマの一貫性を検証する"],"ko":["일관된 UI를 위해 Preline 테마 CSS 파일을 생성한다","Tailwind CSS를 사용하여 사용자 지정 가능한 UI 테마를 생성한다","Preline 구성 요소에서 테마 일관성을 검증한다"],"es":["Generación de archivos CSS de tema Preline para una interfaz de usuario coherente","Creación de temas de interfaz de usuario personalizables con Tailwind CSS","Validación de la coherencia del tema en los componentes Preline"],"fr":["Génération de fichiers CSS de thème Preline pour une interface utilisateur cohérente","Création de thèmes d''interface utilisateur personnalisables avec Tailwind CSS","Validation de la cohérence du thème sur les composants Preline"],"de":["Generierung von Preline-Theme-CSS-Dateien für eine konsistente Benutzeroberfläche","Erstellung von anpassbaren Benutzeroberflächen-Themen mit Tailwind CSS","Überprüfung der Themenkonsistenz über Preline-Komponenten"],"pt":["Geração de arquivos de CSS do Tema Preline para UI consistente","Criação de temas de UI personalizáveis usando Tailwind CSS","Validação da consistência do tema em componentes Preline"],"ru":["Генерация файлов CSS темы Preline для последовательного интерфейса пользователя","Создание настраиваемых тем интерфейса пользователя с использованием Tailwind CSS","Проверка последовательности темы в компонентах Preline"],"ar":["توليد ملفات CSS لموضوع Preline من أجل واجهة مستخدم متسقة","إنشاء موضوعات واجهة مستخدم قابلة للتخصيص باستخدام Tailwind CSS","التحقق من الاتساق في الموضوع عبر مكونات Preline"]},"limitations":{"en":["Requires knowledge of Tailwind CSS framework","Limited to Preline components only","Needs access to docs and guidance files (e.g., palette-guidance.md, validation-checklist.md)"],"zh":["需要 Tailwind CSS 框架的知识","仅限 Preline 组件","需要访问文档和指导文件（例如 palette-guidance.md、validation-checklist.md）"],"ja":["Tailwind CSS フレームワークの知識が必要","Preline コンポーネントのみに限定","ドキュメントおよびガイダンス ファイル（例：palette-guidance.md、validation-checklist.md）へのアクセスが必要"],"ko":["Tailwind CSS 프레임워크에 대한 지식이 필요합니다","Preline 구성 요소에만 제한됩니다","문서 및 가이드 파일(예: palette-guidance.md, validation-checklist.md) 액세스가 필요합니다"],"es":["Requiere conocimiento del framework Tailwind CSS","Limitado a componentes Preline solamente","Necesita acceso a documentos y archivos de orientación (por ejemplo, palette-guidance.md, validation-checklist.md)"],"fr":["Nécessite des connaissances du framework Tailwind CSS","Limité aux composants Preline uniquement","Nécessite un accès aux documents et aux fichiers de guidance (par exemple, palette-guidance.md, validation-checklist.md)"],"de":["Benötigt Kenntnisse des Tailwind CSS-Frameworks","Begrenzt auf Preline-Komponenten","Benötigt Zugriff auf Dokumente und Anleitungsdateien (z. B. palette-guidance.md, validation-checklist.md)"],"pt":["Exige conhecimento do framework Tailwind CSS","Limitado a componentes Preline apenas","Necessita acesso a documentos e arquivos de orientação (por exemplo, palette-guidance.md, validation-checklist.md)"],"ru":["Требует знания фреймворка Tailwind CSS","Ограничен только компонентами Preline","Требует доступа к документам и файлам руководства (например, palette-guidance.md, validation-checklist.md)"],"ar":["يتطلب معرفة بإطار العمل Tailwind CSS","محدود بمكونات Preline فقط","يحتاج إلى الوصول إلى الوثائق وملفات الإرشاد (على سبيل المثال ، palette-guidance.md، validation-checklist.md)"]},"version":4},"contentHash":"9a71bff2a984b96c43ce61baffac57c15eda35eddba7fcdabfe3df65e86a7a50","qualityScore":42}');
