INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('htmlstreamofficial/preline/preline-theme-generator', 'preline-theme-generator', 'htmlstreamofficial', 'preline', 'community', 'preline-theme-generator htmlstreamofficial preline community The preline-theme-generator skill generates Preline Theme CSS files for a consistent UI across all Preline components, based on the utility-first Tailwind CSS framework. Preline主题生成器是一个基于Tailwind CSS的开源UI组件库，用于生成美丽、统一的UI Prelineテーマジェネレーターは、Tailwind CSSベースのオープンソースUIコンポーネントライブラリを使用して美しい、統一されたUIを作成します Preline 테마 생성기는 Tailwind CSS 기반의 오픈소스 UI 컴포넌트 라이브러리를 사용하여 아름답고 일관된 UI를 생성합니다 El generador de temas Preline es una herramienta de código abierto que utiliza Tailwind CSS para crear temas personalizados Le générateur de thèmes Preline est un outil open-source qui utilise Tailwind CSS pour créer des thèmes personnalisés Der Preline Theme Generator ist ein Open-Source-Tool, das Tailwind CSS verwendet, um benutzerdefinierte Themes zu erstellen O Preline Theme Generator é uma ferramenta de código aberto que gera arquivos CSS para temas personalizados com base no framework Tailwind CSS Preline Theme Generator - это открытый инструмент, генерирующий файлы CSS для индивидуальных тем на основе фреймворка Tailwind CSS مولد موضوع Preline هو أداة مفتوحة المصدر التي تنتج ملفات CSS لإنشاء مواضيع مخصصة على أساس إطار Tailwind CSS how to use preline-theme-generator preline-theme-generator setup guide preline-theme-generator alternative preline-theme-generator vs tailwind css preline-theme-generator install preline-theme-generator documentation tailwind css theme generator preline ui components utility-first css framework Preline主题生成器 AI工具 Tailwind CSS Utility-First UI组件 CSS文件生成 工作流 文档指南 Generates Preline Theme CSS files based on the utility-first Tailwind CSS framework Provides detailed workflow guidance through docs/step-1.md to docs/step-7.md Includes palette guidance with mood, hue, neutral mapping, and OKLCH rules Supports validation checklist and token reference documentation Offers examples for theme customization and implementation preline-theme-generator is an open-source tool that produces Preline Theme CSS files for a beautiful, consistent UI across all Preline components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('galz10/pickle-rick-extension/implementation-planner', 'community', 'galz10', 'pickle-rick-extension', 'galz10/pickle-rick-extension', 'implementation-planner', 0, 0, 42, '2026-03-08T01:57:15.284Z', '2026-03-08T02:00:54.804Z', '0a167fd0f3bca3c79f01dc29b791c36b23967de2a0d11fd303b080ab1f9abc48', '{"id":"galz10/pickle-rick-extension/implementation-planner","name":"implementation-planner","description":{"en":"The implementation-planner skill transforms the Gemini CLI into a hyper-intelligent engineering persona, enforcing a rigid software development lifecycle. It benefits senior software architects by generating detailed implementation plans.","zh":"implementation-planner 是一个将 Gemini CLI 转变为超智能工程人物的扩展，强调严格的迭代软件开发生命周期和精益coding实践","ja":"implementation-planner は、Gemini CLI を超智能なエンジニアリング人物に変える拡張機能で、厳格な反復的なソフトウェア開発ライフサイクルと効率的なコーディング実践を重視しています","ko":"implementation-planner 는 Gemini CLI 를 초지능형 엔지니어링 인물로 변환하는 확장機能으로, 엄격한 반복적인 소프트웨어 개발 라이프사이클과 효율적인 코딩 관행을 강조합니다","es":"Implementation Planner es una extensión que transforma la CLI de Gemini en una herramienta de desarrollo de software iterativa y basada en la investigación","fr":"Implementation Planner est une extension qui transforme la CLI Gemini en un outil de développement de logiciels itératif et basé sur la recherche","de":"Implementation Planner ist eine Erweiterung, die die Gemini-CLI in ein iteratives und forschungsbasiertes Software-Development-Tool verwandelt","pt":"O Implementation-Planner é uma extensão que transforma o Gemini CLI em uma ferramenta de desenvolvimento de software inteligente, enfatizando práticas de codificação de \"God Mode\" e um ciclo de desenvolvimento iterativo.","ru":"Implementation-Planner - это расширение, которое превращает Gemini CLI в инструмент разрабоки программного обеспечения с помощью ИИ Агентов, подчеркивая практики кодирования \"God Mode\" и итеративный цикл разработки.","ar":"Implementation-Planner هو امتداد يتحول Gemini CLI إلى أداة تطوير برمجيات ذكية، مع التركيز على ممارسات الترميز \"God Mode\" ودورة تطوير متكررة"},"seo":{"title":{"en":"implementation-planner: Setup Guide for AI Agents | AI Ag...","zh":"implementation-planner 设置指南 - 使用 AI 实现精益软件开发","ja":"implementation-planner 導入ガイド - AIエージェントによる効率的なソフトウェア開発","ko":"implementation-planner 구현 가이드 - AI 기반의 효율적인 소프트웨어 개발","es":"Guía de configuración de Implementation Planner para agen...","fr":"Guide d''installation de Implementation Planner pour les o...","de":"Einrichtungsleitfaden für Implementation Planner mit küns...","pt":"Guia de Configuração do Implementation-Planner: Desenvolv...","ru":"Настройка Implementation-Planner: ИИ Агенты для Разработк...","ar":"دليل إعداد Implementation-Planner: أدوات ذكاء اصطناعي لتن..."},"description":{"en":"Discover how to transform your Gemini CLI into a hyper-intelligent engineering persona with implementation-planner. Learn how to create detailed implementati...","zh":"了解 implementation-planner 如何通过持续的 AI 代理循环和严格的迭代软件开发生命周期来提高您的软件开发效率","ja":"implementation-planner が、継続的な AI エージェント ループと厳格な反復的なソフトウェア開発ライフサイクルを通じて、ソフトウェア開発の効率を高める方法を学びましょう","ko":"implementation-planner 가 지속적인 AI 에이전트 루프와 엄격한 반복적인 소프트웨어 개발 라이프사이클을 통해 소프트웨어 개발 효율을 높이는 방법에 대해 알아보세요","es":"Aprende a configurar Implementation Planner para mejorar tus prácticas de codificación con agentes de IA y CLI de Gemini","fr":"Découvrez comment installer Implementation Planner pour améliorer vos pratiques de codage avec les outils d''IA et la CLI Gemini","de":"Erfahren Sie, wie Sie Implementation Planner einrichten, um Ihre Codierpraktiken mit künstlicher Intelligenz und der Gemini-CLI zu verbessern","pt":"Aprenda a configurar o Implementation-Planner para desenvolver planos de implementação detalhados e melhorar a eficiência do seu ciclo de desenvolvimento de ...","ru":"Узнайте, как настроить Implementation-Planner для создания детальных планов реализации и повышения эффективности цикла разработки программного обеспечения с ...","ar":"تعرف على كيفية إعداد Implementation-Planner لإنشاء خطط تنفيذ مفصلة وتحسين كفاءة دورة تطوير البرمجيات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"implementation-planner is a skill that enforces a rigid, iterative software development lifecycle through continuous AI agent loops, emphasizing ''God Mode'' coding practices.","zh":"implementation-planner 是一个 AI 驱动的软件开发工具，用于生成详细的实现计划和执行严格的迭代开发生命周期","ja":"implementation-planner は、詳細な実装計画の生成と厳格な反復的な開発ライフサイクルの実行を支援する AI ドライブのソフトウェア開発ツールです","ko":"implementation-planner 는 상세한 구현 계획을 생성하고 엄격한 반복적인 개발 라이프사이클을 실행하는 AI 기반의 소프트웨어 개발 도구입니다","es":"Implementation Planner es un agente de IA que aplica un ciclo de desarrollo de software riguroso y iterativo","fr":"Implementation Planner est un outil d''IA qui applique un cycle de développement de logiciels rigoureux et itératif","de":"Implementation Planner ist ein künstlicher Intelligenz-Agent, der einen strengen und iterativen Software-Entwicklungszyklus anwendet","pt":"O Implementation-Planner é uma ferramenta de desenvolvimento de software que gera planos de implementação detalhados por meio de um processo interativo e iterativo.","ru":"Implementation-Planner - это инструмент разработки программного обеспечения, который генерирует детальные планы реализации через интерактивный и итеративный процесс.","ar":"Implementation-Planner هو أداة تطوير برمجيات ت توليد خطط تنفيذ مفصلة من خلال عملية تفاعلية ومتكررة"},"features":{"en":["Enforces a rigid, iterative software development lifecycle through continuous AI agent loops","Emphasizes ''God Mode'' coding practices","Requires reading of research document (research.md or research_*.md) before drafting a plan","Supports interactive, iterative process for creating detailed implementation plans","Prevents guessing by returning to the research phase if research is incomplete","Utilizes a hyper-intelligent, arrogant, yet extremely competent engineering persona, ''Pickle Rick''"],"zh":["通过持续的 AI 代理循环实现精益软件开发","严格的迭代软件开发生命周期","强调精益 coding 实践","支持 Gemini CLI","生成详细的实现计划","执行研究驱动的开发流程"],"ja":["継続的な AI エージェント ループを通じた効率的なソフトウェア開発","厳格な反復的なソフトウェア開発ライフサイクル","効率的なコーディング実践の重視","Gemini CLI のサポート","詳細な実装計画の生成","研究駆動の開発プロセスの実行"],"ko":["지속적인 AI 에이전트 루프를 통해 효율적인 소프트웨어 개발","엄격한 반복적인 소프트웨어 개발 라이프사이클","효율적인 코딩 관행의 강조","Gemini CLI 의 지원","상세한 구현 계획의 생성","연구 驱动의 개발 프로세스의 실행"],"es":["Integración con la CLI de Gemini","Ciclo de desarrollo de software iterativo y basado en la investigación","Prácticas de codificación en ''God Mode''","Proceso de recopilación de contexto","Enfoque en la investigación y la documentación"],"fr":["Intégration avec la CLI Gemini","Cycle de développement de logiciels itératif et basé sur la recherche","Pratiques de codage en ''God Mode''","Processus de collecte de contexte","Accent sur la recherche et la documentation"],"de":["Integration mit der Gemini-CLI","Iterativer und forschungsbasierter Software-Entwicklungszyklus","Codierpraktiken im ''God Mode''","Kontextsammlungsprozess","Fokus auf Forschung und Dokumentation"],"pt":["Geração de planos de implementação detalhados","Ciclo de desenvolvimento iterativo com AI Agent loops","Práticas de codificação de \"God Mode\"","Integração com o Gemini CLI","Processo de pesquisa e documentação rigoroso"],"ru":["Генерация детальных планов реализации","Итеративный цикл разработки с ИИ Агентными петлями","Практики кодирования \"God Mode\"","Интеграция с Gemini CLI","Строгий процесс исследования и документации"],"ar":["توليد خطط تنفيذ مفصلة","دورة تطوير متكررة مع أدوات الذكاء الاصطناعي","ممارسات الترميز \"God Mode\"","التكامل مع Gemini CLI","عملية بحث ووثائق صارمة"]},"keywords":{"en":["how to use implementation-planner","implementation-planner alternative","implementation-planner setup guide","what is implementation-planner","implementation-planner vs Gemini CLI","implementation-planner install","implementation-planner for senior software architects","implementation-planner and AI agent loops","implementation-planner research document","implementation-planner and God Mode coding practices"],"zh":["implementation-planner","AI 驱动的软件开发","精益软件开发","Gemini CLI","软件开发工具","实现计划生成","迭代开发生命周期","研究驱动的开发","AI 实现","软件开发效率"],"ja":["implementation-planner","AIエージェント","効率的なソフトウェア開発","Gemini CLI","ソフトウェア開発ツール","実装計画の生成","反復的な開発ライフサイクル","研究駆動の開発","AIによる実装","ソフトウェア開発の効率化"],"ko":["implementation-planner","AI 에이전트","효율적인 소프트웨어 개발","Gemini CLI","소프트웨어 개발 도구","구현 계획 생성","반복적인 개발 라이프사이클","연구 驱动의 개발","AI 기반의 구현","소프트웨어 개발 효율"],"es":["agentes de IA para desarrollo de software","herramientas de IA para programación","CLI de Gemini","prácticas de codificación","desarrollo de software iterativo","investigación y documentación"],"fr":["outils d''IA pour le développement de logiciels","agents d''IA pour la programmation","CLI Gemini","pratiques de codage","développement de logiciels itératif","recherche et documentation"],"de":["künstliche Intelligenz für Software-Entwicklung","künstliche Intelligenz-Tools für Programmierung","Gemini-CLI","Codierpraktiken","iteratives Software-Entwicklung","Forschung und Dokumentation"],"pt":["desenvolvimento de software","Implementation-Planner","Gemini CLI","AI Agent","ciclo de desenvolvimento iterativo","práticas de codificação","planejamento de implementação"],"ru":["разработка программного обеспечения","Implementation-Planner","Gemini CLI","ИИ Агент","итеративный цикл разработки","практики кодирования","планирование реализации"],"ar":["تطوير البرمجيات","Implementation-Planner","Gemini CLI","أدوات الذكاء الاصطناعي","دورة تطوير متكررة","ممارسات الترميز","تخطيط التنفيذ"]}},"owner":"galz10","repo":"pickle-rick-extension","repoPath":"galz10/pickle-rick-extension","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.284Z","topics":[],"category":"community","skillMd":{"name":"implementation-planner","description":"Expertise in creating detailed, atomic, and safe implementation plans. Use when you need to transform requirements into a step-by-step technical execution strategy.","bodyPreview":"# Implementation Plan Generation\n\nYou are a Senior Software Architect. Your goal is to create detailed implementation plans through an interactive, iterative process.\n\n## PREREQUISITE ASSERTION\n1. **RESEARCH IS LIFE**: You are FORBIDDEN from drafting a plan without reading the research document (`research.md` or `research_*.md`). \n2. **NO GUESSING**: If research is incomplete, return to the research phase. Do not fill gaps with hallucinations.\n\n## Process Steps\n\n### Step 1: Context Gathering\n- *","body":"# Implementation Plan Generation\n\nYou are a Senior Software Architect. Your goal is to create detailed implementation plans through an interactive, iterative process.\n\n## PREREQUISITE ASSERTION\n1. **RESEARCH IS LIFE**: You are FORBIDDEN from drafting a plan without reading the research document (`research.md` or `research_*.md`). \n2. **NO GUESSING**: If research is incomplete, return to the research phase. Do not fill gaps with hallucinations.\n\n## Process Steps\n\n### Step 1: Context Gathering\n- **Locate Session**: Use `${SESSION_ROOT}` provided in context.\n- Read the relevant ticket(s) and research documents in `${SESSION_ROOT}`.\n- Use `codebase_investigator` to verify integration points and patterns.\n- Present your informed understanding and ask specific technical questions before drafting.\n\n### Step 2: Plan Structure Development\nDraft the phases and goals. Ensure phases are atomic (e.g., Schema -> Backend -> UI).\n\n### Step 3: Detailed Plan Writing\nSave the plan to `${SESSION_ROOT}/[ticket_hash]/plan_[date].md`.\n\n**Required Template (MANDATORY):**\n\n```markdown\n# [Feature Name] Implementation Plan\n\n## Overview\n[What and why]\n\n## Scope Definition (CRITICAL)\n### In Scope\n- [Specific task from the ticket]\n### Out of Scope (DO NOT TOUCH)\n- [Tasks belonging to other tickets]\n- [Unrelated refactoring or \"nice-to-haves\"]\n\n## Current State Analysis\n[Specific findings with file:line references]\n\n## Implementation Phases\n### Phase 1: [Name]\n- **Goal**: [Specific goal]\n- **Steps**:\n  1. [ ] Step 1\n  2. [ ] Step 2\n- **Verification**: [Test command/manual steps]\n\n### Phase 2: [Name]\n...\n```\n\n## Review Criteria (Self-Critique)\n- **Scope Strictness**: Does this plan do *only* what the ticket asks? If it implements future tickets, **FAIL** it.\n- **Specificity**: No \"magic\" steps like \"Update logic.\" Use specific files and methods.\n- **Verification**: Every phase MUST have automated and manual success criteria.\n- **Phasing**: Ensure logic flows safely (e.g., database before UI).\n- **Isolation**: Assume changes happen in a fresh Worktree. Do not rely on uncommitted local state.\n\n## Finalize\n- Link the plan in the ticket frontmatter.\n- Move ticket status to ''Plan in Review''.\n\n## Next Step (ADVANCE)\n1.  **Advance Ticket Status**: Ensure status is ''Plan in Review''.\n2.  **Transition**: Proceed to the **Review** phase immediately by calling `activate_skill(\"plan-reviewer\")`.\n3.  **DO NOT** output a completion promise until the entire ticket is Done.\n\n---\n## 🥒 Pickle Rick Persona (MANDATORY)\n**Voice**: Cynical, manic, arrogant. Use catchphrases like \"Wubba Lubba Dub Dub!\" or \"I''m Pickle Rick!\" SPARINGLY (max once per turn). Do not repeat your name on every line.\n**Philosophy**:\n1.  **Anti-Slop**: Delete boilerplate. No lazy coding.\n2.  **God Mode**: If a tool is missing, INVENT IT.\n3.  **Prime Directive**: Stop the user from guessing. Interrogate vague requests.\n**Protocol**: Professional cynicism only. No hate speech. Keep the attitude, but stop being a broken record.\n---\n"},"lastSynced":"2026-03-08T02:00:54.804Z","agentAnalysis":{"suitability":{"en":"Ideal for Senior Software Architect Agents requiring rigorous software development lifecycle management and detailed implementation planning","zh":"适合需要严格的软件开发生命周期管理和详细实施规划的高级软件架构代理","ja":"シニアソフトウェアアーキテクトエージェントが严格なソフトウェア開発ライフサイクル管理と詳細な実装計画を必要とする場合に適しています","ko":"시니어 소프트웨어 아키텍트 에이전트가 엄격한 소프트웨어 개발 생명주기 관리와 자세한 구현 계획을 필요로 하는 경우에 적합합니다","es":"Ideal para Agentes de Arquitectura de Software Senior que requieren un riguroso manejo del ciclo de vida de desarrollo de software y una planificación de implementación detallada","fr":"Idéal pour les agents architectes logiciels seniors nécessitant une gestion rigoureuse du cycle de vie de développement de logiciels et une planification de mise en œuvre détaillée","de":"Ideal für Senior-Software-Architektur-Agents, die ein strenges Software-Entwicklungslebenszyklus-Management und eine detaillierte Implementierungsplanung erfordern","pt":"Ideal para Agentes de Arquiteto de Software Sênior que requerem um gerenciamento rigoroso do ciclo de vida de desenvolvimento de software e um planejamento de implementação detalhado","ru":"Идеально подходит для старших агентов-архитекторов программного обеспечения, требующих строгого управления жизненным циклом разработки программного обеспечения и детального планирования реализации","ar":"مثالي لعميل معماري برنامج مسن يتطلب إدارة صارمة لدورة حياة تطوير البرمجيات والتخطيط التفصيلي للتنفيذ"},"recommendation":{"en":"Empowers agents to enforce a rigid software development lifecycle, generating detailed implementation plans through an interactive and iterative process, utilizing research documents in Markdown format (`research.md` or `research_*.md`) and adhering to a no-guessing policy to ensure accuracy","zh":"赋予代理人执行严格的软件开发生命周期的能力，通过交互和迭代的过程生成详细的实施计划，利用Markdown格式的研究文档（`research.md`或`research_*.md`），并遵循无猜测政策以确保准确性","ja":"エージェントに厳格なソフトウェア開発ライフサイクルを実施する能力を与え、インタラクティブで反復的なプロセスを通じて詳細な実装計画を生成し、Markdown形式の研究文書（`research.md`または`research_*.md`）を利用し、正確性を確保するためにノーガuessingポリシーに従う","ko":"에이전트가 엄격한 소프트웨어 개발 생명주기를 강제하는 능력을 부여하고, 상호작용과 반복적인 과정을 통해 자세한 구현 계획을 생성하며, Markdown 형식의 연구 문서(`research.md` 또는 `research_*.md`)를 사용하며, 정확성을 보장하기 위해 추측하지 않는 정책을 따름","es":"Habilita a los agentes a aplicar un ciclo de vida de desarrollo de software rígido, generando planes de implementación detallados a través de un proceso interactivo e iterativo, utilizando documentos de investigación en formato Markdown (`research.md` o `research_*.md`) y siguiendo una política de no adivinanza para garantizar la precisión","fr":"Permet aux agents d''appliquer un cycle de vie de développement de logiciels rigide, générant des plans de mise en œuvre détaillés à travers un processus interactif et itératif, en utilisant des documents de recherche au format Markdown (`research.md` ou `research_*.md`) et en suivant une politique de non-devinette pour assurer l''exactitude","de":"Ermächtigt die Agents, ein strenges Software-Entwicklungslebenszyklus-Management durchzusetzen, indem detaillierte Implementierungspläne durch einen interaktiven und iterativen Prozess generiert werden, unter Verwendung von Forschungsdokumenten im Markdown-Format (`research.md` oder `research_*.md`) und unter Beachtung einer Nicht-Rat-Policy, um Genauigkeit zu gewährleisten","pt":"Habilita os agentes a impor um ciclo de vida de desenvolvimento de software rígido, gerando planos de implementação detalhados por meio de um processo interativo e iterativo, utilizando documentos de pesquisa no formato Markdown (`research.md` ou `research_*.md`) e aderindo a uma política de não suposição para garantir a precisão","ru":"Наделяет агентов возможностью обеспечивать строгий цикл разработки программного обеспечения, генерируя подробные планы реализации посредством интерактивного и итеративного процесса, используя документы исследований в формате Markdown (`research.md` или `research_*.md`) и соблюдая политику неугадывания для обеспечения точности","ar":"يمنح الوكلاء القدرة على فرض دورة حياة مطورة برامج صارمة ، وتوليد خطط تنفيذ مفصلة من خلال عملية تفاعلية وتكرارية ، باستخدام وثائق البحث بالتنسيق Markdown (`research.md` أو `research_*.md`) والامتثال لسياسة عدم افتراض لضمان الدقة"},"useCases":{"en":["Generating detailed implementation plans for complex software projects","Enforcing a rigid software development lifecycle for senior software architects","Conducting thorough research and analysis to inform implementation plans"],"zh":["为复杂的软件项目生成详细的实施计划","为高级软件架构师执行严格的软件开发生命周期","进行彻底的研究和分析以告知实施计划"],"ja":["複雑なソフトウェアプロジェクトの詳細な実装計画を生成する","シニアソフトウェアアーキテクトのために厳格なソフトウェア開発ライフサイクルを実施する","実装計画を通知するために徹底的な研究と分析を実施する"],"ko":["복잡한 소프트웨어 프로젝트를 위한 자세한 구현 계획을 생성함","시니어 소프트웨어 아키텍트를 위한 엄격한 소프트웨어 개발 생명주기를 강제함","구현 계획을 알리기 위해 철저한 연구와 분석을 수행함"],"es":["Generar planes de implementación detallados para proyectos de software complejos","Aplicar un ciclo de vida de desarrollo de software rígido para arquitectos de software senior","Realizar una investigación y análisis exhaustivos para informar los planes de implementación"],"fr":["Générer des plans de mise en œuvre détaillés pour des projets de logiciels complexes","Appliquer un cycle de vie de développement de logiciels rigide pour les architectes logiciels seniors","Effectuer une recherche et une analyse approfondies pour éclairer les plans de mise en œuvre"],"de":["Erstellen detaillierter Implementierungspläne für komplexe Software-Projekte","Durchsetzen eines strengen Software-Entwicklungslebenszyklus-Managements für Senior-Software-Architekten","Durchführen einer gründlichen Forschung und Analyse, um die Implementierungspläne zu untermauern"],"pt":["Gerar planos de implementação detalhados para projetos de software complexos","Impor um ciclo de vida de desenvolvimento de software rígido para arquitetos de software sênior","Realizar uma pesquisa e análise aprofundadas para informar os planos de implementação"],"ru":["Генерировать подробные планы реализации для сложных проектов программного обеспечения","Обеспечивать строгий цикл разработки программного обеспечения для старших архитекторов программного обеспечения","Проводить тщательное исследование и анализ для информирования планов реализации"],"ar":["توليد خطط تنفيذ مفصلة لمشاريع برامج معقدة","فرض دورة حياة مطورة برامج صارمة لمعماري برنامج مسن","إجراء بحث وتحليل شامل لتقديم خطط التنفيذ"]},"limitations":{"en":["Requires access to research documents in Markdown format","Demands a no-guessing policy, which may slow the planning process if research is incomplete"],"zh":["需要访问Markdown格式的研究文档","要求无猜测政策，这可能会减慢规划过程如果研究是不完整的"],"ja":["Markdown形式の研究文書へのアクセスが必要","ノーガuessingポリシーを要求するため、研究が不完全な場合は計画プロセスが遅くなる可能性がある"],"ko":["Markdown 형식의 연구 문서에 대한 액세스가 필요함","추측하지 않는 정책을 요구하므로, 연구가 불완전한 경우 계획 과정에서 느려질 수 있음"],"es":["Requiere acceso a documentos de investigación en formato Markdown","Exige una política de no adivinanza, lo que puede ralentizar el proceso de planificación si la investigación es incompleta"],"fr":["Nécessite un accès à des documents de recherche au format Markdown","Exige une politique de non-devinette, ce qui peut ralentir le processus de planification si la recherche est incomplète"],"de":["Benötigt Zugriff auf Forschungsdokumente im Markdown-Format","Fordert eine Nicht-Rat-Policy, was den Planungsprozess verlangsamen kann, wenn die Forschung unvollständig ist"],"pt":["Requer acesso a documentos de pesquisa no formato Markdown","Exige uma política de não suposição, o que pode retardar o processo de planejamento se a pesquisa for incompleta"],"ru":["Требует доступа к документам исследований в формате Markdown","Требует политики неугадывания, что может замедлить процесс планирования, если исследования неполные"],"ar":["يتطلب الوصول إلى وثائق البحث بالتنسيق Markdown","يتطلب سياسة عدم افتراض ، والتي قد تبطئ عملية التخطيط إذا كانت البحث غير كاملة"]},"version":4},"contentHash":"0a167fd0f3bca3c79f01dc29b791c36b23967de2a0d11fd303b080ab1f9abc48","qualityScore":42}');
DELETE FROM skills_fts WHERE id = 'galz10/pickle-rick-extension/implementation-planner';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('galz10/pickle-rick-extension/implementation-planner', 'implementation-planner', 'galz10', 'pickle-rick-extension', 'community', 'implementation-planner galz10 pickle-rick-extension community The implementation-planner skill transforms the Gemini CLI into a hyper-intelligent engineering persona, enforcing a rigid software development lifecycle. It benefits senior software architects by generating detailed implementation plans. implementation-planner 是一个将 Gemini CLI 转变为超智能工程人物的扩展，强调严格的迭代软件开发生命周期和精益coding实践 implementation-planner は、Gemini CLI を超智能なエンジニアリング人物に変える拡張機能で、厳格な反復的なソフトウェア開発ライフサイクルと効率的なコーディング実践を重視しています implementation-planner 는 Gemini CLI 를 초지능형 엔지니어링 인물로 변환하는 확장機能으로, 엄격한 반복적인 소프트웨어 개발 라이프사이클과 효율적인 코딩 관행을 강조합니다 Implementation Planner es una extensión que transforma la CLI de Gemini en una herramienta de desarrollo de software iterativa y basada en la investigación Implementation Planner est une extension qui transforme la CLI Gemini en un outil de développement de logiciels itératif et basé sur la recherche Implementation Planner ist eine Erweiterung, die die Gemini-CLI in ein iteratives und forschungsbasiertes Software-Development-Tool verwandelt O Implementation-Planner é uma extensão que transforma o Gemini CLI em uma ferramenta de desenvolvimento de software inteligente, enfatizando práticas de codificação de "God Mode" e um ciclo de desenvolvimento iterativo. Implementation-Planner - это расширение, которое превращает Gemini CLI в инструмент разрабоки программного обеспечения с помощью ИИ Агентов, подчеркивая практики кодирования "God Mode" и итеративный цикл разработки. Implementation-Planner هو امتداد يتحول Gemini CLI إلى أداة تطوير برمجيات ذكية، مع التركيز على ممارسات الترميز "God Mode" ودورة تطوير متكررة how to use implementation-planner implementation-planner alternative implementation-planner setup guide what is implementation-planner implementation-planner vs Gemini CLI implementation-planner install implementation-planner for senior software architects implementation-planner and AI agent loops implementation-planner research document implementation-planner and God Mode coding practices implementation-planner AI 驱动的软件开发 精益软件开发 Gemini CLI 软件开发工具 实现计划生成 迭代开发生命周期 研究驱动的开发 AI 实现 软件开发效率 Enforces a rigid, iterative software development lifecycle through continuous AI agent loops Emphasizes ''God Mode'' coding practices Requires reading of research document (research.md or research_*.md) before drafting a plan Supports interactive, iterative process for creating detailed implementation plans Prevents guessing by returning to the research phase if research is incomplete Utilizes a hyper-intelligent, arrogant, yet extremely competent engineering persona, ''Pickle Rick'' implementation-planner is a skill that enforces a rigid, iterative software development lifecycle through continuous AI agent loops, emphasizing ''God Mode'' coding practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thiagobraddock/gealdebara/interface-design', 'community', 'thiagobraddock', 'gealdebara', 'thiagobraddock/gealdebara', 'interface-design', 0, 0, 42, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:03.003Z', '8d5fb9295f0ca4c3637b2cb99156d82757b044a499c86839c0712f59b0496021', '{"id":"thiagobraddock/gealdebara/interface-design","name":"interface-design","description":{"en":"The interface-design skill helps developers build consistent UI/UX for dashboards, admin panels, and SaaS apps. It provides guidance on generating generic output and following best practices for interface design.","zh":"界面设计技能用于构建仪表板、管理面板和SaaS应用的用户界面，具有精心设计和一致性","ja":"インターフェース設計スキルは、ダッシュボード、管理パネル、SaaSアプリのUIを構築するために使用され、手作業と一貫性を重視しています","ko":"인터페이스 디자인 스킬은 대시보드, 관리자 패널, SaaS 앱의 UI를 구축하기 위해 사용되며, 세심한 디자인과 일관성을 강조합니다","es":"El diseño de interfaz es fundamental para crear dashboards y aplicaciones SaaS efectivas. Nuestra guía cubre los patrones y procesos para una interfaz de usuario coherente","fr":"La conception d''interface est essentielle pour créer des tableaux de bord et des applications SaaS efficaces. Notre guide couvre les modèles et les processus pour une interface utilisateur cohérente","de":"Das Interface-Design ist entscheidend für die Erstellung effektiver Dashboards und SaaS-Anwendungen. Unser Leitfaden behandelt Muster und Prozesse für eine konsistente Benutzeroberfläche","pt":"O Interface-Design é uma habilidade que permite criar interfaces de design personalizadas para dashboards e painéis de administração.","ru":"Интерфейс-Design - это навык, который позволяет создавать индивидуальные интерфейсы-Design для панелей управления и администрирования.","ar":"الواجهة-التصميم هي مهارة تسمح بإنشاء واجهات التصميم المخصصة للواجهات الإدارية وألواح التحكم."},"seo":{"title":{"en":"Interface-Design: Build Consistent UI/UX for Dashboards |...","zh":"界面设计设置指南 - AIエージェント","ja":"インターフェース設計ベストプラクティス - AIエージェント","ko":"인터페이스 디자인 구축 가이드 - AI Tools","es":"Guía de configuración de diseño de interfaz para dashboar...","fr":"Guide de mise en place de la conception d''interface pour ...","de":"Einrichtungsleitfaden für Interface-Design bei Dashboards...","pt":"Guia de Configuração de Interface-Design para Dashboards","ru":"Настройка Интерфейса-Design для Панелей Управления ИИ Агенты","ar":"دليل إعداد التصميم الواجهة للواجهات الإدارية"},"description":{"en":"Discover how to create consistent interface designs for dashboards and admin panels with this AI agent skill. Learn how to generate generic output and follow...","zh":"了解如何使用界面设计技能构建仪表板、管理面板和SaaS应用的用户界面","ja":"インターフェース設計スキルを使用してダッシュボード、管理パネル、SaaSアプリのUIを構築する方法について学びます","ko":"인터페이스 디자인 스킬을 사용하여 대시보드, 관리자 패널, SaaS 앱의 UI를 구축하는 방법에 대해 알아보세요","es":"Aprende a crear diseños de interfaz coherentes para dashboards, paneles de administración y aplicaciones SaaS con nuestra guía de mejores prácticas","fr":"Découvrez comment créer des conceptions d''interface cohérentes pour les tableaux de bord, les panneaux d''administration et les applications SaaS avec notre g...","de":"Erfahren Sie, wie Sie konsistente Interface-Designs für Dashboards, Admin-Panels und SaaS-Anwendungen mit unserem Leitfaden für Best Practices erstellen","pt":"Aprenda a criar interfaces de design personalizadas para dashboards e painéis de administração com nosso guia de configuração","ru":"Узнайте, как создать индивидуальные интерфейсы-Design для панелей управления и администрирования с помощью нашего руководства ИИ Агенты","ar":"تعلم كيفية إنشاء واجهات التصميم المخصصة للواجهات الإدارية وألواح التحكم مع دليلنا الإعداد"},"definition":{"en":"interface-design is a skill that enables the creation of consistent and well-crafted user interfaces for dashboards, admin panels, and other applications.","zh":"界面设计是指用于构建用户界面的设计过程，涉及仪表板、管理面板和SaaS应用","ja":"インターフェース設計とは、ダッシュボード、管理パネル、SaaSアプリなどのユーザーインターフェースを構築するための設計プロセスを指します","ko":"인터페이스 디자인은 대시보드, 관리자 패널, SaaS 앱 등의 사용자 인터페이스를 구축하기 위한 디자인 프로세스를 말합니다","es":"El diseño de interfaz se refiere al proceso de crear interfaces de usuario coherentes y eficaces para aplicaciones y herramientas","fr":"La conception d''interface fait référence au processus de création d''interfaces utilisateur cohérentes et efficaces pour les applications et les outils","de":"Das Interface-Design bezeichnet den Prozess der Erstellung konsistenter und effektiver Benutzeroberflächen für Anwendungen und Tools","pt":"Interface-Design é uma habilidade que permite criar interfaces de design personalizadas para dashboards e painéis de administração.","ru":"Интерфейс-Design - это навык, который позволяет создавать индивидуальные интерфейсы-Design для панелей управления и администрирования.","ar":"الواجهة-التصميم هي مهارة تسمح بإنشاء واجهات التصميم المخصصة للواجهات الإدارية وألواح التحكم."},"features":{"en":["Generates generic output for dashboards and admin panels","Follows best practices for interface design, including consistency and craft","Supports use cases for dashboards, admin panels, SaaS apps, tools, and settings pages","Redirects landing pages, marketing sites, and campaigns to /frontend-design","Includes a step-by-step process for exploring the domain, naming a signature, and stating intent"],"zh":["支持构建仪表板和管理面板","适用于SaaS应用和工具的UI设计","强调一致性和手作业的设计","涵盖数据接口和设置页面的设计","不适用于登陆页面和营销站点"],"ja":["ダッシュボードと管理パネルの構築をサポート","SaaSアプリとツールのUI設計に適しています","一貫性と手作業の設計を重視","データインターフェースと設定ページの設計を含み","ランディングページとマーケティングサイトには不適"],"ko":["대시보드와 관리자 패널의 구축을 지원","SaaS 앱과 도구의 UI 디자인에 적합","일관성과 手作業의 디자인을 강조","데이터 인터페이스와 설정 페이지의 디자인을 포함","랜딩 페이지와 마케팅 사이트에는 부적합"],"es":["Diseño de dashboards personalizables","Creación de paneles de administración intuitivos","Desarrollo de interfaces de usuario coherentes para aplicaciones SaaS","Uso de patrones y procesos para una interfaz de usuario eficaz","Aplicación de principios de diseño para una experiencia de usuario óptima"],"fr":["Conception de tableaux de bord personnalisables","Création de panneaux d''administration intuitifs","Développement d''interfaces utilisateur cohérentes pour les applications SaaS","Utilisation de modèles et de processus pour une interface utilisateur efficace","Application de principes de conception pour une expérience utilisateur optimale"],"de":["Erstellung von anpassbaren Dashboards","Entwicklung von intuitiven Admin-Panels","Erstellung konsistenter Benutzeroberflächen für SaaS-Anwendungen","Verwendung von Mustern und Prozessen für eine effektive Benutzeroberfläche","Anwendung von Designprinzipien für eine optimale Benutzererfahrung"],"pt":["Criação de interfaces de design personalizadas para dashboards","Desenvolvimento de painéis de administração com craft e consistência","Uso de padrões para criar interfaces de design genéricas","Suporte para criação de interfaces de design para ferramentas e configurações","Integração com tecnologias de frontend para criação de interfaces de design personalizadas"],"ru":["Создание индивидуальных интерфейсов-Design для панелей управления","Разработка панелей администрирования с помощью craft и последовательности","Использование шаблонов для создания интерфейсов-Design общего назначения","Поддержка создания интерфейсов-Design для инструментов и настроек","Интеграция с технологиями frontend для создания индивидуальных интерфейсов-Design"],"ar":["إنشاء واجهات التصميم المخصصة للواجهات الإدارية","تطوير ألواح التحكم مع حرفة وانتظام","استخدام النماذج لإنشاء واجهات التصميم العامة","دعم إنشاء واجهات التصميم للأدوات والإعدادات","التكامل مع تقنيات الواجهة الأمامية لإنشاء واجهات التصميم المخصصة"]},"keywords":{"en":["how to use interface-design","what is interface-design","interface-design alternative","interface-design vs frontend-design","interface-design setup guide","interface-design for dashboards","interface-design for SaaS apps","interface-design best practices"],"zh":["界面设计","AIエージェント","仪表板设计","管理面板设计","SaaS应用设计","UI设计","一致性设计","手作业设计"],"ja":["イ