INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thiagobraddock/gealdebara/interface-design', 'interface-design', 'thiagobraddock', 'gealdebara', 'community', 'interface-design thiagobraddock gealdebara community The interface-design skill helps developers build consistent UI/UX for dashboards, admin panels, and SaaS apps. It provides guidance on generating generic output and following best practices for interface design. 界面设计技能用于构建仪表板、管理面板和SaaS应用的用户界面，具有精心设计和一致性 インターフェース設計スキルは、ダッシュボード、管理パネル、SaaSアプリのUIを構築するために使用され、手作業と一貫性を重視しています 인터페이스 디자인 스킬은 대시보드, 관리자 패널, SaaS 앱의 UI를 구축하기 위해 사용되며, 세심한 디자인과 일관성을 강조합니다 El diseño de interfaz es fundamental para crear dashboards y aplicaciones SaaS efectivas. Nuestra guía cubre los patrones y procesos para una interfaz de usuario coherente La conception d''interface est essentielle pour créer des tableaux de bord et des applications SaaS efficaces. Notre guide couvre les modèles et les processus pour une interface utilisateur cohérente Das Interface-Design ist entscheidend für die Erstellung effektiver Dashboards und SaaS-Anwendungen. Unser Leitfaden behandelt Muster und Prozesse für eine konsistente Benutzeroberfläche O Interface-Design é uma habilidade que permite criar interfaces de design personalizadas para dashboards e painéis de administração. Интерфейс-Design - это навык, который позволяет создавать индивидуальные интерфейсы-Design для панелей управления и администрирования. الواجهة-التصميم هي مهارة تسمح بإنشاء واجهات التصميم المخصصة للواجهات الإدارية وألواح التحكم. how to use interface-design what is interface-design interface-design alternative interface-design vs frontend-design interface-design setup guide interface-design for dashboards interface-design for SaaS apps interface-design best practices 界面设计 AIエージェント 仪表板设计 管理面板设计 SaaS应用设计 UI设计 一致性设计 手作业设计 Generates generic output for dashboards and admin panels Follows best practices for interface design, including consistency and craft Supports use cases for dashboards, admin panels, SaaS apps, tools, and settings pages Redirects landing pages, marketing sites, and campaigns to /frontend-design Includes a step-by-step process for exploring the domain, naming a signature, and stating intent interface-design is a skill that enables the creation of consistent and well-crafted user interfaces for dashboards, admin panels, and other applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lemline/lemline/core-dev', 'community', 'lemline', 'lemline', 'lemline/lemline', 'core-dev', 0, 0, 42, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:06.811Z', 'e891aeb18da30381354870b7a33aae591d079eb0292ed29610bedff23a636ab0', '{"id":"lemline/lemline/core-dev","name":"core-dev","description":{"en":"core-dev is a serverless workflow DSL runtime for existing infrastructure, providing a highly efficient and event-driven execution engine. It benefits developers seeking to implement stateless workflow execution.","zh":"Core-Dev 是一个 Serverless Workflow DSL runtime，用于现有的基础设施，实现高效、事件驱动的工作流，降低数据库依赖","ja":"Core-Dev はサーバーレスワークフロー DSL 実行エンジンであり、既存のインフラストラクチャに対応し、高效なイベント駆動型ワークフローを実現し、データベース依存を最小限に抑える","ko":"Core-Dev 는 기존 인프라에 대한 서버리스 워크플로우 DSL 런타임으로 효율적이고 이벤트駆動의 워크플로우를 구현하여 데이터베이스 의존도를 최소화 합니다","es":"Core-dev es un motor de flujo de trabajo sin servidor para infraestructuras existentes, con una arquitectura eficiente y basada en eventos, y una dependencia mínima de la base de datos","fr":"Core-dev est un moteur de workflow sans serveur pour les infrastructures existantes, avec une architecture efficace et basée sur les événements, et une dépendance minimale à la base de données","de":"Core-dev ist ein serverloses Workflow-Laufzeit-System für bestehende Infrastrukturen, mit einer effizienten und ereignisbasierten Architektur und einer minimalen Abhängigkeit von der Datenbank","pt":"O módulo lemline-core é um mecanismo de execução de workflows serverless altamente eficiente e baseado em eventos, com mínimo uso de banco de dados.","ru":"Модуль lemline-core - это высокоэффективный и событийно-ориентированный механизм выполнения серверных рабочих процессов с минимальным использованием базы данных","ar":"الوحدة النمطية lemline-core هي آلية تشغيل سير عمل بدون خادم بكفاءة عالية ومبنية على الأحداث مع تخزين بيانات قليل"},"seo":{"title":{"en":"core-dev: Serverless Workflow Runtime Setup Guide | AI Ag...","zh":"Core-Dev Serverless 工作流设置指南","ja":"Core-Dev サーバーレスワークフロー DSL 実行エンジンのベストプラクティス","ko":"Core-Dev 서버리스 워크플로우 런타임 개발자 가이드","es":"Guía de configuración de core-dev: Motor de tiempo de eje...","fr":"Guide de configuration de core-dev : Moteur d''exécution d...","de":"Einrichtungsleitfaden für core-dev: Serverloses Workflow-...","pt":"Guia de Configuração core-dev: Runtime de Workflow Server...","ru":"ИИ Агенты core-dev: Настройка Серверного Workflow Runtime","ar":"دليل إعداد core-dev: تشغيل 워크플로 بدون خادم"},"description":{"en":"Unlock efficient event-driven workflows with core-dev. Discover how to implement Serverless Workflow DSL v1.0 and integrate with existing infrastructure.","zh":"了解 Core-Dev 的 Serverless Workflow DSL runtime，实现高效、事件驱动的工作流，降低数据库依赖","ja":"Core-Dev のサーバーレスワークフロー DSL 実行エンジンについて学び、効率的なイベント駆動型ワークフローを実現し、データベース依存を最小限に抑える","ko":"Core-Dev 서버리스 워크플로우 런타임에 대해 알아보고 효율적이고 이벤트 驱动의 워크플로우를 구현하여 데이터베이스 의존도를 최소화 하세요","es":"Aprende a implementar core-dev, un motor de flujo de trabajo sin servidor para infraestructuras existentes, con eficiencia y minimalismo en la base de datos","fr":"Découvrez comment mettre en œuvre core-dev, un moteur de workflow sans serveur pour les infrastructures existantes, avec efficacité et minimalisme de base de...","de":"Erfahren Sie, wie Sie core-dev implementieren, ein serverloses Workflow-Laufzeit-System für bestehende Infrastrukturen, mit Effizienz und Minimalismus in der...","pt":"Aprenda a configurar o módulo lemline-core para execução de workflows serverless com alta eficiência e mínimo uso de banco de dados","ru":"Узнайте как настроить модуль lemline-core для выполнения серверных рабочих процессов с высокой эффективностью и минимальным использованием базы данных","ar":"تعلم كيفية تفعيل الوحدة النمطية lemline-core لتشغيل سير عمل بدون خادم بكفاءة عالية وتخزين بيانات قليل"},"definition":{"en":"core-dev is a serverless workflow runtime implementing the Serverless Workflow DSL v1.0 specification, enabling pure and stateless workflow execution.","zh":"Core-Dev 是一个 Serverless Workflow DSL runtime，用于实现高效、事件驱动的工作流","ja":"Core-Dev はサーバーレスワークフロー DSL 実行エンジンであり、高效なイベント駆動型ワークフローを実現する","ko":"Core-Dev 는 서버리스 워크플로우 DSL 런타임으로 효율적이고 이벤트駆動의 워크플로우를 구현하는 것을 목적으로 합니다","es":"Core-dev es un motor de flujo de trabajo sin servidor que implementa la especificación Serverless Workflow DSL v1.0","fr":"Core-dev est un moteur de workflow sans serveur qui met en œuvre la spécification Serverless Workflow DSL v1.0","de":"Core-dev ist ein serverloses Workflow-Laufzeit-System, das die Spezifikation Serverless Workflow DSL v1.0 implementiert","pt":"O que é core-dev? É um runtime de workflow serverless para infraestrutura existente","ru":"Что такое core-dev? Это runtime для серверных рабочих процессов для существующей инфраструктуры","ar":"ما هو core-dev؟ هو وقت تشغيل سير عمل بدون خادم للبنية التحتية الحالية"},"features":{"en":["Implements Serverless Workflow DSL v1.0 specification","Provides a pure and stateless workflow execution engine","Supports event-driven workflow execution with minimal database reliance","Includes documentation for module structure, DSL parsing, and adding tasks","Features Node tree, NodePosition, and navigation capabilities","Offers StepByStep and Full execution orchestrators"],"zh":["支持 Serverless Workflow DSL v1.0 规范","高效、事件驱动的工作流执行","最小化数据库依赖","模块化的结构，易于扩展","支持多种节点类型，包括 StepByStep 和 Full 执行"],"ja":["サーバーレスワークフロー DSL v1.0仕様をサポート","効率的なイベント駆動型ワークフローの実行","データベース依存を最小限に抑える","モジュール化された構造、拡張性が高い","複数のノードタイプをサポート、StepByStep と Full 実行を含む"],"ko":["서버리스 워크플로우 DSL v1.0 규격을 지원","효율적이고 이벤트駆動의 워크플로우 실행","데이터베이스 의존도를 최소화","모듈화된 구조, 확장성이 높음","여러 노드 유형을 지원, StepByStep 및 Full 실행 포함"],"es":["Implementación de la especificación Serverless Workflow DSL v1.0","Arquitectura eficiente y basada en eventos","Dependencia mínima de la base de datos","Ejecución de flujo de trabajo sin servidor","Soporte para nodos y orquestadores","Documentación detallada para desarrolladores"],"fr":["Mise en œuvre de la spécification Serverless Workflow DSL v1.0","Architecture efficace et basée sur les événements","Dépendance minimale à la base de données","Exécution de workflow sans serveur","Prise en charge des nœuds et des orchestrateurs","Documentation détaillée pour les développeurs"],"de":["Implementierung der Spezifikation Serverless Workflow DSL v1.0","Effiziente und ereignisbasierte Architektur","Minimale Abhängigkeit von der Datenbank","Ausführung von Workflow ohne Server","Unterstützung für Knoten und Orchestrierer","Detaillierte Dokumentation für Entwickler"],"pt":["Execução de workflows serverless com alta eficiência","Mecanismo de execução baseado em eventos","Mínimo uso de banco de dados","Suporte à especificação Serverless Workflow DSL v1.0","Modularidade com documentação para nodes, orchestrators e processors"],"ru":["Высокая эффективность выполнения серверных рабочих процессов","Механизм выполнения на основе событий","Минимальное использование базы данных","Поддержка спецификации Serverless Workflow DSL v1.0","Модульность с документацией для узлов, оркестраторов и процессоров"],"ar":["تشغيل سير عمل بدون خادم بكفاءة عالية","آلية تشغيل مبنية على الأحداث","تخزين بيانات قليل","دعم مواصفة سير عمل بدون خادم DSL v1.0","الوحدة النمطية مع توثيق لعناصر، منسقين ومعالجين"]},"keywords":{"en":["how to use core-dev","core-dev serverless workflow","what is core-dev","core-dev alternative","core-dev vs AWS Step Functions","core-dev install guide","core-dev setup tutorial","serverless workflow DSL implementation","event-driven workflow execution"],"zh":["Serverless Workflow","DSL runtime","事件驱动","数据库依赖","模块化结构","Serverless Workflow DSL v1.0","高效工作流","AIエージェント","云计算"],"ja":["サーバーレスワークフロー","DSL 実行エンジン","イベント駆動","データベース依存","モジュール化された構造","サーバーレスワークフロー DSL v1.0","効率的なワークフロー","AIエージェント","クラウドコンピューティング"],"ko":["서버리스 워크플로우","DSL 런타임","이벤트駆動","데이터베이스 의존","모듈화된 구조","서버리스 워크플로우 DSL v1.0","효율적인 워크플로우","AI 에이전트","클라우드 컴퓨팅"],"es":["core-dev","Serverless Workflow","DSL","infraestructura sin servidor","eficiencia","eventos","base de datos mínima","desarrollo de software","Guía de configuración"],"fr":["core-dev","Serverless Workflow","DSL","infrastructure sans serveur","efficacité","événements","base de données minimale","développement de logiciels","Guide de configuration"],"de":["core-dev","Serverless Workflow","DSL","serverlose Infrastruktur","Effizienz","Ereignisse","minimale Datenbank","Software-Entwicklung","Einrichtungsleitfaden"],"pt":["core-dev","workflow serverless","runtime de workflow","Serverless Workflow DSL","infraestrutura existente","desenvolvimento de software","técnologias de desenvolvimento"],"ru":["core-dev","ИИ Агенты","серверные рабочие процессы","runtime для рабочих процессов","Serverless Workflow DSL","существующая инфраструктура","разработка программного обеспечения","технологии разработки"],"ar":["core-dev","أدوات الذكاء الاصطناعي","سير عمل بدون خادم","وقت تشغيل سير عمل","سير عمل بدون خادم DSL","البنية التحتية الحالية","تطوير البرمجيات","تكنولوجيا التطوير"]}},"owner":"lemline","repo":"lemline","repoPath":"lemline/lemline","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.293Z","topics":[],"category":"community","skillMd":{"name":"core-dev","description":">","bodyPreview":"# Lemline Core Development Guide\n\n## Purpose\n\nGuide development of the lemline-core module - the pure, stateless workflow execution engine implementing the Serverless\nWorkflow DSL v1.0 specification.\n\n**Documentation:**\n\n- [Overview](lemline-core/docs/core-overview.md) - Module structure, DSL parsing, adding tasks\n- [Nodes](lemline-core/docs/core-nodes.md) - Node tree, NodePosition, navigation\n- [Orchestrators](lemline-core/docs/core-orchestrators.md) - StepByStep vs Full execution\n- [Processors","body":"# Lemline Core Development Guide\n\n## Purpose\n\nGuide development of the lemline-core module - the pure, stateless workflow execution engine implementing the Serverless\nWorkflow DSL v1.0 specification.\n\n**Documentation:**\n\n- [Overview](lemline-core/docs/core-overview.md) - Module structure, DSL parsing, adding tasks\n- [Nodes](lemline-core/docs/core-nodes.md) - Node tree, NodePosition, navigation\n- [Orchestrators](lemline-core/docs/core-orchestrators.md) - StepByStep vs Full execution\n- [Processors](lemline-core/docs/core-processors.md) - NodeProcessor, control flows, activities\n- [Fork](lemline-core/docs/core-fork.md) - Parallel branches, error boundaries\n- [Errors](lemline-core/docs/core-errors.md) - Exceptions, retry, error handling\n- [States](lemline-core/docs/core-states.md) - TaskState, WorkflowCommand, WorkflowEvent\n- [Expressions](lemline-core/docs/core-expressions.md) - JQ evaluation, scope variables\n\n---\n\n## Quick Reference\n\n### If you need to change something in...\n\n**Orchestration:**\n\nFirst, read [core-orchestrators.md](lemline-core/docs/core-orchestrators.md)\n\n- **Change step execution flow** →\n  Modify [StepByStepOrchestrator.kt](lemline-core/src/main/kotlin/com/lemline/core/orchestrator/StepByStepOrchestrator.kt)\n- **Change synchronous test execution** →\n  Modify [FullOrchestrator.kt](lemline-core/src/main/kotlin/com/lemline/core/orchestrator/FullOrchestrator.kt)\n- **Add a new WorkflowCommand/Event** →\n  Modify [WorkflowState.kt](lemline-core/src/main/kotlin/com/lemline/core/orchestrator/WorkflowState.kt)\n\n**Nodes:**\n\nFirst, read [core-nodes.md](lemline-core/docs/core-nodes.md)\n\n- **Change node tree structure** →\n  Modify [Node.kt](lemline-core/src/main/kotlin/com/lemline/core/nodes/Node.kt)\n- **Add a new Token type** →\n  Modify [Token.kt](lemline-core/src/main/kotlin/com/lemline/core/nodes/Token.kt)\n- **Change position addressing** →\n  Modify [NodePosition.kt](lemline-core/src/main/kotlin/com/lemline/core/nodes/NodePosition.kt)\n\n**Processors:**\n\nFirst, read [core-processors.md](lemline-core/docs/core-processors.md)\n\n- **Add a new task type** → Read [core-overview.md](lemline-core/docs/core-overview.md#adding-a-new-task-type)\n- **Change control flow logic (Do, For, Switch)** →\n  Modify `processors/DoProcessor.kt`, `ForProcessor.kt`, `SwitchProcessor.kt`\n- **Change activity behavior (Wait, Call, Run)** →\n  Modify `processors/WaitProcessor.kt`, `CallProcessor.kt`, `RunProcessor.kt`\n\n**States:**\n\nFirst, read [core-states.md](lemline-core/docs/core-states.md)\n\n- **Add a new TaskState** → Create in `states/` directory, extend `TaskState`\n- **Change scope variables** → Modify the `scope` property in the relevant state class\n- **Change state serialization** → Modify `TaskStates.kt`\n\n**Error Handling:**\n\nFirst, read [core-errors.md](lemline-core/docs/core-errors.md)\n\n- **Change retry logic** →\n  Modify [TryProcessor.kt](lemline-core/src/main/kotlin/com/lemline/core/processors/TryProcessor.kt)\n- **Add a new AsyncTaskException** →\n  Modify [AsyncTaskException.kt](lemline-core/src/main/kotlin/com/lemline/core/errors/AsyncTaskException.kt)\n- **Change error types** →\n  Modify [WorkflowException.kt](lemline-core/src/main/kotlin/com/lemline/core/errors/WorkflowException.kt)\n\n**Expressions:**\n\nFirst, read [core-expressions.md](lemline-core/docs/core-expressions.md)\n\n- **Change JQ evaluation** →\n  Modify [JQExpression.kt](lemline-core/src/main/kotlin/com/lemline/core/expressions/JQExpression.kt)\n- **Add scope variables** → Modify the relevant state class''s `scope` property\n- **Change input/output transformation** → Modify transformation helpers in orchestrator\n\n**Fork/Parallel:**\n\nFirst, read [core-fork.md](lemline-core/docs/core-fork.md)\n\n- **Change fork execution** →\n  Modify [ForkProcessor.kt](lemline-core/src/main/kotlin/com/lemline/core/processors/ForkProcessor.kt)\n- **Change branch detection** → Modify `forkBranchCompleted`/`forkBranchFailed` in `StepByStepOrchestrator.kt`\n\n**DSL Parsing:**\n\nFirst, read [core-overview.md](lemline-core/docs/core-overview.md#dsl-parsing)\n\n- **Change parsing logic** →\n  Modify [DefinitionCache.kt](lemline-core/src/main/kotlin/com/lemline/core/definitions/DefinitionCache.kt)\n\n---\n\n## Critical Rules\n\n### ✅ ALWAYS Do This\n\n1. **Keep processors stateless** - receive state, return updated state via `NextStepInfo`\n2. **Use exception-driven control flow** - throw `AsyncTaskException` for wait/fork/runWorkflow\n3. **Serialize all state** - `TaskState` subclasses must be `@Serializable`\n4. **Clean up states** - return `null` in `stateUpdates` when leaving a node\n5. **Provide scope variables** - override `scope` property when state provides expression variables\n6. **Test with FullOrchestrator** - use for unit testing workflow logic\n7. **Build node tree lazily** - use `by lazy` for `children` property\n8. **Use `FlowDirective`** - `Continue`, `End`, or `Then(target)` for navigation\n\n### ❌ NEVER Do This\n\n1. **Store mutable state in processors** - processors are stateless\n2. **Modify Node objects** - nodes are immutable definitions\n3. **Skip state serialization** - breaks stateless worker pattern\n4. **Use blocking operations** - all I/O should be in `suspend` functions\n5. **Throw regular exceptions for control flow** - use `AsyncTaskException` subtypes\n6. **Ignore `Direction` parameter** - behavior differs based on entry direction\n7. **Leak state across branches** - clean states when completing fork branches\n\n---\n\n## Architecture Overview\n\n### Step-by-Step Execution Model\n\n```\nWorkflowCommand\n    │\n    ▼\nOrchestrator.runByTask()\n    │\n    ├── Check if condition (skip if false)\n    ├── Transform input (inputFrom)\n    ├── Get processor for node\n    └── Call processor.getNextStepInfo()\n            │\n            ├── AsyncTaskException ──► WaitStarted/ForkStarted/RunWorkflowStarted\n            │\n            └── NextStepInfo ──► completeTask()\n                                    ├── Transform output (outputAs)\n                                    ├── Export to context (exportAs)\n                                    └── Navigate to next\n                                            │\n                                            └── TaskScheduled/WorkflowCompleted/WorkflowFailed\n```\n\n### Key Files\n\n| Purpose | File |\n|---------|------|\n| Step orchestration | `orchestrator/StepByStepOrchestrator.kt` |\n| Full execution | `orchestrator/FullOrchestrator.kt` |\n| Node structure | `nodes/Node.kt` |\n| Position addressing | `nodes/NodePosition.kt` |\n| Processor interface | `processors/NodeProcessor.kt` |\n| Base state | `states/TaskState.kt` |\n| Commands/Events | `orchestrator/WorkflowState.kt` |\n| JQ evaluation | `expressions/JQExpression.kt` |\n| DSL parsing | `definitions/DefinitionCache.kt` |\n\n---\n\n## Common Patterns\n\n### Creating a New Processor\n\n```kotlin\n// 1. State class\n@Serializable\ndata class CustomState(\n    override val startedAt: Instant = Clock.System.now(),\n    val customField: String = \"\"\n) : TaskState() {\n    // Optional: provide scope variables\n    override val scope: Scope get() = buildJsonObject {\n        put(\"custom\", JsonPrimitive(customField))\n    }\n}\n\n// 2. Processor\nclass CustomProcessor(override val node: Node<CustomTask>) : NodeProcessor<CustomTask, CustomState> {\n    override fun createInitialState() = CustomState()\n\n    override fun getNextStepInfo(state: CustomState, dataset: JsonElement, scope: Scope, direction: Direction): NextStepInfo<CustomState> {\n        return when (direction) {\n            FROM_PARENT -> {\n                // Process task\n                NextStepInfo(\n                    state = state,\n                    rawOutput = result,\n                    stateUpdates = mapOf(node.position to null), // Clean up\n                    flowDirective = FlowDirective.Continue\n                )\n            }\n            FROM_CHILD -> { /* Handle child completion */ }\n            else -> { /* Handle other directions */ }\n        }\n    }\n}\n\n// 3. Register in factory\nfun createProcessor(node: Node<*>) = when (node.task) {\n    is CustomTask -> CustomProcessor(node as Node<CustomTask>)\n    // ...\n}\n```\n\n### Throwing AsyncTaskException\n\n```kotlin\n// For activities that need orchestrator coordination\noverride fun getNextStepInfo(...): NextStepInfo<WaitState> {\n    throw AsyncTaskException.WaitStartedException(\n        state = state,\n        transformedInput = dataset,\n        config = WaitStartedException.Config(waitUntil = calculateWaitUntil())\n    )\n}\n```\n\n### Handling Navigation\n\n```kotlin\noverride fun getNextStepInfo(state, dataset, scope, direction) = when (direction) {\n    FROM_PARENT -> {\n        // First entry - initialize and go to first child\n        NextStepInfo(state = initialState, flowDirective = Continue)\n    }\n    FROM_CHILD -> {\n        if (hasMoreChildren) {\n            NextStepInfo(state = nextState, flowDirective = Continue)\n        } else {\n            // Done - clean up state and return to parent\n            NextStepInfo(stateUpdates = mapOf(node.position to null), flowDirective = Continue)\n        }\n    }\n}\n```\n\n---\n\n## Testing Patterns\n\n### Unit Test with FullOrchestrator\n\n```kotlin\n@Test\nfun `should execute workflow`() = runTest {\n    val yaml = \"\"\"\n        document:\n          name: test\n          version: \"1.0\"\n        do:\n          - myTask:\n              set:\n                result: \"success\"\n    \"\"\".trimIndent()\n\n    val workflow = DefinitionCache.parse(yaml)\n    val orchestrator = FullOrchestrator(activityRunner, definitionLoader)\n\n    val result = orchestrator.start(workflow, JsonObject(mapOf()))\n\n    assertEquals(\"success\", result.jsonObject[\"result\"]?.jsonPrimitive?.content)\n}\n```\n\n### Testing Individual Processors\n\n```kotlin\n@Test\nfun `DoProcessor should iterate children`() {\n    val node = createDoNode(childCount = 3)\n    val processor = DoProcessor(node)\n\n    val result = processor.getNextStepInfo(\n        state = processor.createInitialState(),\n        dataset = JsonObject(mapOf()),\n        scope = JsonObject(mapOf()),\n        direction = Direction.FROM_PARENT\n    )\n\n    assertEquals(0, (result.state as DoState).index)\n}\n```\n\n---\n\n## Running Tests\n\n```bash\n# All tests\n./gradlew :lemline-core:test\n\n# Specific test class\n./gradlew :lemline-core:test --tests \"com.lemline.core.tests.MyTest\"\n\n# Specific test method\n./gradlew :lemline-core:test --tests \"com.lemline.core.tests.MyTest.should do something\"\n```\n\n---\n\n## Related Documentation\n\n- **CLAUDE.md** - Project-wide guidelines and architecture overview\n- **runner-dev skill** - lemline-runner module (messaging, persistence, CLI)\n- **Serverless Workflow DSL** - https://serverlessworkflow.io/\n"},"lastSynced":"2026-03-08T02:01:06.811Z","agentAnalysis":{"suitability":{"en":"Perfect for Workflow Automation Agents needing efficient stateless workflow execution and event-driven processing.","zh":"适合需要高效无状态工作流执行和事件驱动处理的工作流自动化代理。","ja":"ステートレスなワークフロー実行とイベント駆動処理が必要なワークフロー自動化エージェントに適しています。","ko":"무상태 워크플ロー 실행 및 이벤트 주도 처리가 필요한 워크플ロー 자동화 에이전트에 적합합니다.","es":"Perfecto para agentes de automatización de flujo de trabajo que necesitan una ejecución de flujo de trabajo sin estado eficiente y un procesamiento basado en eventos.","fr":"Parfait pour les agents d''automatisation de workflow nécessitant une exécution de workflow sans état efficace et un traitement basé sur les événements.","de":"Perfekt für Workflow-Automatisierungsagenten, die eine effiziente ausführung von workflow ohne Zustand und ereignisgesteuerte Verarbeitung benötigen.","pt":"Perfeito para Agentes de Automação de Fluxo de Trabalho que precisam de execução de fluxo de trabalho stateless eficiente e processamento baseado em eventos.","ru":"Идеально подходит для агентов автоматизации рабочих процессов, требующих эффективного безсостоянего выполнения рабочих процессов и обработки событий.","ar":"مثالي لعميل автомatisation تدفق العمل الذي يحتاج إلى تنفيذ تدفق العمل stateless فعال والобработات القائمة على الأحداث."},"recommendation":{"en":"Empowers agents to execute serverless workflows using the Serverless Workflow DSL v1.0 specification, providing a highly efficient and event-driven execution engine with features like node tree navigation and step-by-step orchestrators.","zh":"赋予代理使用Serverless Workflow DSL v1.0规范执行服务器无工作流，提供高效且事件驱动的执行引擎，具有节点树导航和步骤式编排器等功能。","ja":"Serverless Workflow DSL v1.0の仕様を使用してサーバーレスワークフローを実行するエージェントを可能にし、高度に効率的でイベント駆動の実行エンジンを提供し、ノードツリーのナビゲーションやステップバイステップのオーケストレーターなどの機能を備えています。","ko":"에이전트가 Serverless Workflow DSL v1.0 사양을 사용하여 서버리스 워크플ロー를 실행할 수 있도록 하며, 노드 트리 탐색 및 단계별 오케스트레이터와 같은 기능을 갖춘 고도로 효율적이고 이벤트 주도적인 실행 엔진을 제공합니다.","es":"Habilita a los agentes a ejecutar flujos de trabajo sin servidor utilizando la especificación Serverless Workflow DSL v1.0, proporcionando un motor de ejecución altamente eficiente y basado en eventos con características como navegación de árbol de nodos y orquestadores paso a paso.","fr":"Permet aux agents d''exécuter des flux de travail sans serveur en utilisant la spécification Serverless Workflow DSL v1.0, fournissant un moteur d''exécution hautement efficace et basé sur les événements avec des fonctionnalités comme la navigation d''arbre de nœuds et les orchestrateurs étape par étape.","de":"Ermöglicht es Agenten, serverlose Workflows mit der Serverless Workflow DSL v1.0-Spezifikation auszuführen und bietet einen hoch effizienten und ereignisgesteuerten Ausführungsmotor mit Funktionen wie Baumknotennavigation und schrittweiser Orchestrierung.","pt":"Habilita agentes a executar fluxos de trabalho sem servidor usando a especificação Serverless Workflow DSL v1.0, fornecendo um mecanismo de execução altamente eficiente e baseado em eventos com recursos como navegação de árvore de nós e orquestradores passo a passo.","ru":"Позволяет агентам выполнять серверные рабочие процессы, используя спецификацию Serverless Workflow DSL v1.0, обеспечивая высокоэффективный и событийный движок выполнения с функциями, такими как навигация по дереву узлов и пошаговые оркестраторы.","ar":"تمكين العملاء من تشغيل تدفقات العمل بدون خادم باستخدام مواصفة Serverless Workflow DSL v1.0، وتوفير محرك تنفيذ فعال للغاية وقائم على الأحداث مع ميزات مثل التنقل في شجرة العقد والمنسقون خطوة بخطوة."},"useCases":{"en":["Implementing stateless workflow execution for existing infrastructure","Parsing and executing Serverless Workflow DSL v1.0 specifications","Navigating node trees and managing node positions for complex workflows"],"zh":["为现有基础设施实施无状态工作流执行","解析和执行Serverless Workflow DSL v1.0规范","导航节点树并管理复杂工作流的节点位置"],"ja":["既存のインフラストラクチャのためのステートレスなワークフロー実行の実装","Serverless Workflow DSL v1.0の仕様の解析と実行","複雑なワークフローのノードツリーのナビゲーションとノード位置の管理"],"ko":["기존 인프라를 위한 무상태 워크플ロー 실행 구현","Serverless Workflow DSL v1.0 사양 解析 및 실행","복잡한 워크플로우의 노드 트리 탐색 및 노드 위치 관리"],"es":["Implementar la ejecución de flujo de trabajo sin estado para infraestructuras existentes","Analizar y ejecutar especificaciones de Serverless Workflow DSL v1.0","Navegar por árboles de nodos y gestionar posiciones de nodos para flujos de trabajo complejos"],"fr":["Mettre en œuvre l''exécution de workflow sans état pour les infrastructures existantes","Analyser et exécuter les spécifications Serverless Workflow DSL v1.0","Naviguer dans les arbres de nœuds et gérer les positions de nœuds pour les flux de travail complexes"],"de":["Implementierung der ausführung von workflow ohne Zustand für bestehende Infrastrukturen","Analysieren und Ausführen von Serverless Workflow DSL v1.0-Spezifikationen","Navigieren in Baumknoten und Verwalten von Knotenpositionen für komplexe Workflows"],"pt":["Implementação de execução de fluxo de trabalho stateless para infraestrutura existente","Análise e execução de especificações Serverless Workflow DSL v1.0","Navegação em árvores de nós e gerenciamento de posições de nós para fluxos de trabalho complexos"],"ru":["Реализация безсостоянего выполнения рабочих процессов для существующей инфраструктуры","Парсинг и выполнение спецификаций Serverless Workflow DSL v1.0","Навигация по дереву узлов и управление позициями узлов для сложных рабочих процессов"],"ar":["تنفيذ تنفيذ تدفق العمل stateless لبيئة موجودة","تحليل وتشغيل مواصفات Serverless Workflow DSL v1.0","تنقل في شجرة العقد وإدارة مواقع العقد لتدفقات العمل المعقدة"]},"limitations":{"en":["Requires understanding of Serverless Workflow DSL v1.0 specification","Limited to stateless workflow execution","Dependent on existing infrastructure for deployment"],"zh":["需要理解Serverless Workflow DSL v1.0规范","仅限无状态工作流执行","依赖现有基础设施进行部署"],"ja":["Serverless Workflow DSL v1.0の仕様の理解が必要","ステートレスなワークフロー実行に限定される","既存のインフラストラクチャに依存してデプロイされる"],"ko":["Serverless Workflow DSL v1.0 사양의 이해가 필요함","무상태 워크플ロー 실행에만 제한됨","기존 인프라에 의존하여 배포됨"],"es":["Requiere comprensión de la especificación Serverless Workflow DSL v1.0","Limitado a la ejecución de flujo de trabajo sin estado","Dependiente de la infraestructura existente para la implementación"],"fr":["Nécessite une compréhension de la spécification Serverless Workflow DSL v1.0","Limité à l''exécution de workflow sans état","Dépendant de l''infrastructure existante pour le déploiement"],"de":["Benötigt das Verständnis der Serverless Workflow DSL v1.0-Spezifikation","Begrenzt auf die ausführung von workflow ohne Zustand","Von der bestehenden Infrastruktur für die Bereitstellung abhängig"],"pt":["Exige compreensão da especificação Serverless Workflow DSL v1.0","Limitado à execução de fluxo de trabalho stateless","Dependente da infraestrutura existente para implantação"],"ru":["Требует понимания спецификации Serverless Workflow DSL v1.0","Ограничен безсостоянием выполнением рабочих процессов","Зависит от существующей инфраструктуры для развертывания"],"ar":["يتطلب فهم مواصفة Serverless Workflow DSL v1.0","محدود بتنفيذ تدفق العمل stateless","يعتمد على بيئة موجودة للتطوير"]},"version":4},"contentHash":"e891aeb18da30381354870b7a33aae591d079eb0292ed29610bedff23a636ab0","qualityScore":42}');
