INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mburdo/knowledge_and_vibes/ground', 'ground', 'Mburdo', 'knowledge_and_vibes', 'community', 'ground Mburdo knowledge_and_vibes community Ground is an opinionated AI agent development stack providing tools, guides, templates, and workflows for efficient development. It benefits developers by streamlining the development process. Ground AI工具提供直接执行和验证功能，帮助开发者快速高效地完成任务 Ground AIエージェントは直接実行と検証機能を備え，開発者が迅速かつ効率的にタスクを完了できるようにする Ground AI 에이전트는 직접 실행 및 검증 기능을 제공하여 개발자가 빠르고 효율적으로 작업을 완료할 수 있도록 한다 Ground es una pila de desarrollo de agentes de AI opinionada con herramientas, guías, plantillas y flujos de trabajo para mejorar la productividad Ground est une pile de développement d''agents d''IA opinionée avec des outils, des guides, des modèles et des flux de travail pour améliorer la productivité Ground ist ein opinionierter AI-Agent-Entwicklungsstapel mit Tools, Anleitungen, Vorlagen und Workflows zur Produktivitätssteigerung O Ground é uma pilha de desenvolvimento de agentes de IA opinativa, com ferramentas e guias para melhorar a eficiência do desenvolvimento. Ele executa diretamente, sem spawnar subagentes, para tarefas simples de consulta e verificação Ground — это opinativa стек разработки ИИ Агентов, с инструментами и руководствами для повышения эффективности разработки. Он выполняет direkt, без создания субагентов, для простых задач запроса и верификации Ground هو حزمة تطوير وكلاء الذكاء الاصطناعي ذات رأي، مع أدوات ومرشدين لتحسين كفاءة التطوير. وهو يعمل مباشرة، دون إنشاء وكلاء فرعيين، لمهام بسيطة من الاستعلام والتحقق how to use ground ground alternative ground setup guide what is ground ground vs other AI agents ground install ground documentation ground development stack ground AI agent AI工具设置 直接执行与验证 Ground AI工具 AI开发效率 Lita研究 AIエージェント开发 Executes directly without spawning subagents for simple queries Verifies external dependencies against current documentation Follows design rationale for efficient performance Applies Lita research for optimized code reduction Supports direct execution for query + verification sequences Ground is an opinionated AI agent development stack with tools and guides for streamlined development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShunsukeHayashi/Miyabi/ccg', 'community', 'ShunsukeHayashi', 'Miyabi', 'ShunsukeHayashi/Miyabi', 'ccg', 0, 0, 42, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:08.993Z', '0903675e6dc91dab917da75ce76876366651933df8b7bb0857dce8972638a860', '{"id":"ShunsukeHayashi/Miyabi/ccg","name":"ccg","description":{"en":"ccg is an open-source, economically-governed, beginner-friendly autonomous development framework built on Issue-Driven Development, enabling developers to generate courses and apps efficiently.","zh":"CCG 是一个开源、经济治理的自动开发框架，支持 Issue-Driven Development","ja":"CCG は、Issue-Driven Development をサポートするオープンソースの自律型開発フレームワークです","ko":"CCG는 오픈소스 AI 에이전트 개발 프레임워크로 Issue-Driven Development를 지원합니다","es":"CCG es un marco de desarrollo autónomo que permite la generación de contenido de cursos de AI de manera eficiente. Está construido sobre Issue-Driven Development","fr":"CCG est un cadre de développement autonome qui permet la génération de contenu de cours d''IA de manière efficace. Il est construit sur Issue-Driven Development","de":"CCG ist ein autonomes Entwicklungsframework, das die effiziente Erstellung von KI-Kursinhalten ermöglicht. Es basiert auf Issue-Driven Development","pt":"O CCG é uma ferramenta de geração de conteúdo de curso de IA de código aberto e governada economicamente, projetada para desenvolvedores.","ru":"CCG - это открытый и экономически управляемый инструмент для создания курсов ИИ, предназначенный для разработчиков.","ar":"CCG هي أداة مفتوحة المصدر وحكومية اقتصاديًا لإنشاء محتوى الدورات التدريبية للوكلاء الذكية، مصممة للمطورين."},"seo":{"title":{"en":"ccg: Autonomous Development Framework Setup Guide | AI Ag...","zh":"CCG Setup Guide: AI课程内容生成器","ja":"CCG を使ってみよう: 自律型開発フレームワークのベストプラクティス","ko":"CCG 시작하기: 오픈소스 AI 에이전트 개발 프레임워크","es":"Guía de configuración de CCG: Marco de desarrollo autónomo","fr":"Guide de setup de CCG : Cadre de développement autonome","de":"CCG-Setup-Anleitung: Autonomes Entwicklungsframework","pt":"Guia de Configuração CCG: Ferramenta de Geração de Conteú...","ru":"Настройка CCG: Инструмент для создания курсов ИИ","ar":"دليل إعداد CCG: أداة إنشاء محتوى الدورة التدريبية للوكلاء..."},"description":{"en":"Unlock the power of autonomous development with ccg! Learn how to setup and utilize this open-source framework for Issue-Driven Development and start generat...","zh":"了解如何使用 CCG 实现 Issue-Driven Development，提高开发效率","ja":"CCG を使用して自動開発フレームワークを構築し、開発効率を向上させる","ko":"CCG를 사용하여 오픈소스 AI 에이전트 개발 프레임워크를 설정하고 개발 효율성을 높여보세요","es":"Aprende a configurar CCG, el primer marco de desarrollo autónomo de código abierto, para generar contenido de cursos de AI de manera eficiente","fr":"Découvrez comment configurer CCG, le premier cadre de développement autonome open-source, pour générer du contenu de cours d''IA de manière efficace","de":"Erfahren Sie, wie Sie CCG, das erste Open-Source-Autonomie-Entwicklungsframework, für die effiziente Erstellung von KI-Kursinhalten konfigurieren","pt":"Aprenda a configurar e utilizar o CCG, uma ferramenta de geração de conteúdo de curso de IA de código aberto e governada economicamente.","ru":"Узнайте, как настроить и использовать CCG, открытый и экономически управляемый инструмент для создания курсов ИИ.","ar":"تعرف على كيفية إعداد واستخدام CCG، أداة مفتوحة المصدر وحكومية اقتصاديًا لإنشاء محتوى الدورات التدريبية للوكلاء الذكية."},"definition":{"en":"ccg is an autonomous development framework that utilizes Issue-Driven Development to generate courses and apps, providing a beginner-friendly and economically-governed solution for developers.","zh":"CCG 是一个开源的自动开发框架，用于生成 AI 课程内容","ja":"CCG は、AI コースコンテンツを生成するためのオープンソースの自律型開発フレームワークです","ko":"CCG는 AI 코스 콘텐츠를 생성하는 오픈소스 AI 에이전트 개발 프레임워크입니다","es":"CCG es un marco de desarrollo autónomo de código abierto que permite la generación de contenido de cursos de AI","fr":"CCG est un cadre de développement autonome open-source qui permet la génération de contenu de cours d''IA","de":"CCG ist ein Open-Source-Autonomie-Entwicklungsframework, das die Erstellung von KI-Kursinhalten ermöglicht","pt":"CCG é uma ferramenta de geração de conteúdo de curso de IA que utiliza Issue-Driven Development.","ru":"CCG - это инструмент для создания курсов ИИ, который использует Issue-Driven Development.","ar":"CCG هي أداة لإنشاء محتوى الدورات التدريبية للوكلاء الذكية التي تستخدم Issue-Driven Development."},"features":{"en":["Supports Issue-Driven Development for efficient course generation","Utilizes npm run dev for development and npm run build for production","Triggers course creation with commands like ''create course'' and ''generate course''","Enables development with commands like ''ccg dev'' and ''start course generator''","Builds course apps with commands like ''ccg build'' and ''build course app''","Provides quick commands for development and production environments"],"zh":["支持 Issue-Driven Development","使用 npm 运行开发环境","提供快速命令行工具","支持课程创建和生成","提供生产环境构建功能","使用 JavaScript 和 Node.js 开发"],"ja":["Issue-Driven Development をサポート","npm を使用して開発環境を実行","クイックコマンドラインツールを提供","コース作成と生成をサポート","プロダクション環境ビルド機能を提供","JavaScript と Node.js で開発"],"ko":["Issue-Driven Development 지원","npm 사용하여 개발 환경 실행","빠른 명령줄 도구 제공","코스 생성 및 생성 지원","생산 환경 빌드 기능 제공","JavaScript 및 Node.js로 개발"],"es":["Generación de contenido de cursos de AI mediante Issue-Driven Development","Compatibilidad con desarrollo y producción mediante npm run dev y npm run build","Triggers para la creación de cursos, desarrollo y compilación","Comandos rápidos para el desarrollo y la compilación de cursos","Soporte para la versión 1.0.0","Localización en /Users/shunsukehayashi/dev/ai-course-content-generator-v2"],"fr":["Génération de contenu de cours d''IA via Issue-Driven Development","Compatibilité avec le développement et la production via npm run dev et npm run build","Triggers pour la création de cours, le développement et la construction","Commandes rapides pour le développement et la construction de cours","Prise en charge de la version 1.0.0","Localisation dans /Users/shunsukehayashi/dev/ai-course-content-generator-v2"],"de":["Erstellung von KI-Kursinhalten mittels Issue-Driven Development","Kompatibilität mit Entwicklung und Produktion über npm run dev und npm run build","Triggers für die Kurs-Erstellung, Entwicklung und Kompilierung","Schnellbefehle für die Entwicklung und Kompilierung von Kursen","Unterstützung für Version 1.0.0","Lokalisierung in /Users/shunsukehayashi/dev/ai-course-content-generator-v2"],"pt":["Desenvolvimento baseado em Issue-Driven Development","Comandos rápidos para desenvolvimento e produção","Suporte a npm para execução de tarefas","Código aberto e governado economicamente","Fácil de usar para desenvolvedores iniciantes"],"ru":["Разработка на основе Issue-Driven Development","Быстрые команды для разработки и производства","Поддержка npm для выполнения задач","Открытый и экономически управляемый код","Легко использовать для начинающих разработчиков"],"ar":["التطوير المستند إلى Issue-Driven Development","الأوامر السريعة للتنمية والإنتاج","دعم npm لتنفيذ المهام","الرمز المفتوح والمدار اقتصاديًا","سهل الاستخدام للمطورين المبتدئين"]},"keywords":{"en":["how to use ccg","what is ccg","ccg alternative","ccg vs other frameworks","ccg install","ccg setup guide","autonomous development framework","issue-driven development","course generation"],"zh":["CCG","AI 课程内容生成器","自动开发框架","Issue-Driven Development","npm","JavaScript","Node.js","AI 开发工具","自律型开发"],"ja":["CCG","AI コースコンテンツ生成器","自律型開発フレームワーク","Issue-Driven Development","npm","JavaScript","Node.js","AI 開発ツール","AI エージェント"],"ko":["CCG","AI 코스 콘텐츠 생성기","오픈소스 AI 에이전트 개발 프레임워크","Issue-Driven Development","npm","JavaScript","Node.js","AI 개발 도구","AI 에이전트"],"es":["CCG","desarrollo autónomo"," Issue-Driven Development","generación de contenido de cursos de AI","npm run dev","npm run build","triggers de desarrollo","comandos rápidos para el desarrollo","Herramientas de AI","Agentes de IA"],"fr":["CCG","développement autonome","Issue-Driven Development","génération de contenu de cours d''IA","npm run dev","npm run build","triggers de développement","commandes rapides pour le développement","Outils d''IA","Agents d''IA"],"de":["CCG","autonomes Entwicklungsframework","Issue-Driven Development","Erstellung von KI-Kursinhalten","npm run dev","npm run build","Triggers für die Entwicklung","Schnellbefehle für die Entwicklung","KI-Tools","KI-Agents"],"pt":["CCG","Ferramenta de geração de conteúdo de curso de IA","Issue-Driven Development","Desenvolvimento de software","Ferramentas de desenvolvimento","Código aberto","Governança econômica","npm","Comandos rápidos"],"ru":["CCG","Инструмент для создания курсов ИИ","Issue-Driven Development","Разработка программного обеспечения","Инструменты для разработки","Открытый код","Экономическая управляемость","npm","Быстрые команды"],"ar":["CCG","أداة إنشاء محتوى الدورات التدريبية للوكلاء الذكية","Issue-Driven Development","تطوير البرمجيات","أدوات التطوير","الرمز المفتوح","المدار الاقتصادي","npm","الأوامر السريعة"]}},"owner":"ShunsukeHayashi","repo":"Miyabi","repoPath":"ShunsukeHayashi/Miyabi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.294Z","topics":[],"category":"community","skillMd":{"name":"ccg","description":"AI Course Content Generator - Generate complete online courses with Gemini API. Triggers on create course, generate lesson, course content, ccg, /ccg.","bodyPreview":"# AI Course Content Generator (CCG)\n\n**Version**: 1.0.0\n**Location**: `/Users/shunsukehayashi/dev/ai-course-content-generator-v2`\n\n---\n\n## Triggers\n\n| Trigger | Examples |\n|---------|----------|\n| Course creation | \"create course\", \"generate course\", \"/ccg\" |\n| Development | \"ccg dev\", \"start course generator\" |\n| Build | \"ccg build\", \"build course app\" |\n\n---\n\n## Quick Commands\n\n```bash\n# Development\ncd /Users/shunsukehayashi/dev/ai-course-content-generator-v2 && npm run dev\n\n# Production build","body":"# AI Course Content Generator (CCG)\n\n**Version**: 1.0.0\n**Location**: `/Users/shunsukehayashi/dev/ai-course-content-generator-v2`\n\n---\n\n## Triggers\n\n| Trigger | Examples |\n|---------|----------|\n| Course creation | \"create course\", \"generate course\", \"/ccg\" |\n| Development | \"ccg dev\", \"start course generator\" |\n| Build | \"ccg build\", \"build course app\" |\n\n---\n\n## Quick Commands\n\n```bash\n# Development\ncd /Users/shunsukehayashi/dev/ai-course-content-generator-v2 && npm run dev\n\n# Production build\ncd /Users/shunsukehayashi/dev/ai-course-content-generator-v2 && npm run build\n\n# Electron dev\ncd /Users/shunsukehayashi/dev/ai-course-content-generator-v2 && npm run electron:dev\n\n# Electron build\ncd /Users/shunsukehayashi/dev/ai-course-content-generator-v2 && npm run electron:build\n```\n\n---\n\n## Key Capabilities\n\n1. **Course Structure Generation** - JSON curriculum generation\n2. **Lesson Script Generation** - Customizable narration scripts\n3. **Text-to-Speech** - Gemini TTS audio generation\n4. **Slide Generation** - Graphic recording style\n5. **Video Rendering** - WebCodecs API MP4 creation\n6. **Bulk Export** - ZIP download of all assets\n\n---\n\n## Architecture\n\n```\nVision Panel → Structure → Content Pipeline → Export\n     ↓              ↓              ↓            ↓\n Image/PDF/URL  JSON Structure  Slides/Audio  MP3/MP4/ZIP\n```\n\n---\n\n## Key Files\n\n| File | Purpose |\n|------|---------|\n| `services/geminiService.ts` | Gemini API calls + retry logic |\n| `templates/prompts.ts` | Zod schemas + prompt builders |\n| `utils/audioUtils.ts` | PCM→MP3 encoding (lamejs) |\n| `utils/videoUtils.ts` | MP4 muxing (WebCodecs) |\n| `types.ts` | Course structure interfaces |\n| `constants.ts` | Defaults + TTS voice options |\n\n---\n\n## Gemini Models\n\n- **Primary**: `gemini-3-flash-preview` (with thinking)\n- **Backup**: `gemini-2.5-flash` (quota fallback)\n- **TTS**: `gemini-2.5-flash-preview-tts`\n- **Image**: `gemini-3-pro-image-preview`\n\n---\n\n## Environment\n\n- `GEMINI_API_KEY` required in `.env`\n"},"lastSynced":"2026-03-08T02:01:08.993Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing efficient course and app development capabilities based on Issue-Driven Development","zh":"非常适合需要高效课程和应用开发功能的教育代理，基于问题驱动开发","ja":"問題駆動開発に基づいた効率的なコースとアプリ開発機能を必要とする教育エージェントに最適","ko":"문제 驱动 개발을 기반으로 효율적인 과정 및 앱 개발 기능이 필요한 교육 에이전트에 적합","es":"Perfecto para Agentes Educativos que necesitan capacidades de desarrollo de cursos y aplicaciones eficientes basadas en Desarrollo Dirigido por Problemas","fr":"Parfait pour les Agents Éducatifs ayant besoin de capacités de développement de cours et d''applications efficaces basées sur le Développement Dirigé par les Problèmes","de":"Perfekt für Bildungsagenten, die effiziente Kurs- und App-Entwicklungsfähigkeiten auf Basis von issuegetriebenem Entwicklungsprozess benötigen","pt":"Perfeito para Agentes Educacionais que necessitam de capacidades de desenvolvimento de cursos e aplicativos eficientes baseadas no Desenvolvimento Orientado a Problemas","ru":"Идеально подходит для образовательных агентов, которым требуются эффективные возможности разработки курсов и приложений на основе развития, основанного на проблемах","ar":"مثالي ل와كلاء التعليم الذين يحتاجون إلى قدرات تطوير الدورات والتطبيقات الفعالة على أساس開発 الموجهة بالمشاكل"},"recommendation":{"en":"Empowers agents to generate comprehensive course content and apps efficiently using open-source and economically-governed frameworks, leveraging Issue-Driven Development and npm for development and production builds","zh":"赋予代理生成全面课程内容和应用的能力，利用开源和经济管辖的框架，利用问题驱动开发和npm进行开发和生产构建","ja":"問題駆動開発とnpmを使用して開発とプロダクションビルドを行うオープンソースと経済的に管理されたフレームワークを利用して、エージェントが包括的なコースコンテンツとアプリを効率的に生成することができる","ko":"문제 驱动 개발과 npm을 사용하여 개발 및 프로덕션 빌드를 수행하는 오픈 소스 및 경제적으로 관리되는 프레임워크를 활용하여 에이전트가 포괄적인 과정 내용 및 앱을 효율적으로 생성할 수 있게 함","es":"Habilita a los agentes a generar contenido de cursos y aplicaciones de manera eficiente utilizando frameworks de código abierto y gobernados económicamente, aprovechando el Desarrollo Dirigido por Problemas y npm para compilaciones de desarrollo y producción","fr":"Permet aux agents de générer des contenus de cours et des applications de manière efficace en utilisant des frameworks open-source et économiquement gérés, en exploitant le Développement Dirigé par les Problèmes et npm pour les constructions de développement et de production","de":"Ermächtigt Agenten, umfassende Kursinhalte und Apps effizient zu generieren, indem open-source- und wirtschaftlich regierte Frameworks verwendet werden, die den issuegetriebenen Entwicklungsprozess und npm für Entwicklung- und Produktionsbuilds nutzen","pt":"Habilita os agentes a gerar conteúdo de curso abrangente e aplicativos de forma eficiente, utilizando frameworks de código aberto e economicamente governados, aproveitando o Desenvolvimento Orientado a Problemas e npm para compilações de desenvolvimento e produção","ru":"Наделяет агентов возможностью генерировать комплексный контент курсов и приложений эффективно, используя открытые и экономически управляемые фреймворки, используя развитие, основанное на проблемах, и npm для сборок разработки и производства","ar":"يمنح الوكلاء القدرة على generar محتوى دورة شاملة وتطبيقات بطريقة فعالة، باستخدام إطار العمل مفتوح المصدر واقتصادي محكوم، واستخدام التطوير الموجهة بالمشاكل وnpm لتجميعات التطوير والإنتاج"},"useCases":{"en":["Automating course creation with triggers like ''create course'' or ''/ccg''","Generating course apps with ''ccg build'' or ''build course app'' commands","Streamlining development workflows with ''ccg dev'' or ''start course generator''"],"zh":["使用诸如''创建课程''或''/ccg''的触发器自动创建课程","使用''ccg build''或''构建课程应用''命令生成课程应用","使用''ccg dev''或''启动课程生成器''命令简化开发工作流"],"ja":["''コースを作成''または''/ccg''などのトリガーを使用してコースの自動作成","''ccg build''または''コースアプリをビルド''コマンドを使用してコースアプリを生成","''ccg dev''