INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ShunsukeHayashi/Miyabi/ccg', 'ccg', 'ShunsukeHayashi', 'Miyabi', 'community', 'ccg ShunsukeHayashi Miyabi community ccg is an open-source, economically-governed, beginner-friendly autonomous development framework built on Issue-Driven Development, enabling developers to generate courses and apps efficiently. CCG 是一个开源、经济治理的自动开发框架，支持 Issue-Driven Development CCG は、Issue-Driven Development をサポートするオープンソースの自律型開発フレームワークです CCG는 오픈소스 AI 에이전트 개발 프레임워크로 Issue-Driven Development를 지원합니다 CCG es un marco de desarrollo autónomo que permite la generación de contenido de cursos de AI de manera eficiente. Está construido sobre Issue-Driven Development CCG est un cadre de développement autonome qui permet la génération de contenu de cours d''IA de manière efficace. Il est construit sur Issue-Driven Development CCG ist ein autonomes Entwicklungsframework, das die effiziente Erstellung von KI-Kursinhalten ermöglicht. Es basiert auf Issue-Driven Development O CCG é uma ferramenta de geração de conteúdo de curso de IA de código aberto e governada economicamente, projetada para desenvolvedores. CCG - это открытый и экономически управляемый инструмент для создания курсов ИИ, предназначенный для разработчиков. CCG هي أداة مفتوحة المصدر وحكومية اقتصاديًا لإنشاء محتوى الدورات التدريبية للوكلاء الذكية، مصممة للمطورين. how to use ccg what is ccg ccg alternative ccg vs other frameworks ccg install ccg setup guide autonomous development framework issue-driven development course generation CCG AI 课程内容生成器 自动开发框架 Issue-Driven Development npm JavaScript Node.js AI 开发工具 自律型开发 Supports Issue-Driven Development for efficient course generation Utilizes npm run dev for development and npm run build for production Triggers course creation with commands like ''create course'' and ''generate course'' Enables development with commands like ''ccg dev'' and ''start course generator'' Builds course apps with commands like ''ccg build'' and ''build course app'' Provides quick commands for development and production environments ccg is an autonomous development framework that utilizes Issue-Driven Development to generate courses and apps, providing a beginner-friendly and economically-governed solution for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yi-john-huang/sdd-mcp/sdd-tasks', 'community', 'yi-john-huang', 'sdd-mcp', 'yi-john-huang/sdd-mcp', 'sdd-tasks', 0, 0, 42, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:09.092Z', 'f2f59de25d8b290440a84f6f1202b1807c851b29a105ed03a2fec28951d1b0b3', '{"id":"yi-john-huang/sdd-mcp/sdd-tasks","name":"sdd-tasks","description":{"en":"The sdd-tasks skill generates TDD-based task breakdowns from approved designs, benefiting developers and project managers. It streamlines the development process by creating implementable work items.","zh":"SDD-Tasks生成全面的TDD-based任务分解，实现设计到开发的无缝转换","ja":"SDD-Tasksは、設計から開発への無縫な転換を実現するためのTDD-basedタスクブレイクダウンを生成","ko":"SDD-Tasks는 설계에서 개발로의 무중단 전환을 위한 포괄적인 TDD 기반 태스크 분해를 생성","es":"sdd-tasks genera tareas TDD detalladas a partir de diseños aprobados. Revisa los prerequisitos y el flujo de trabajo para configurar esta herramienta","fr":"sdd-tasks génère des tâches TDD détaillées à partir de conceptions approuvées. Vérifiez les prérequis et le flux de travail pour configurer cet outil","de":"sdd-tasks erzeugt detaillierte TDD-Aufgaben aus genehmigten Designs. Überprüfen Sie die Voraussetzungen und den Workflow, um dieses Tool zu konfigurieren","pt":"O sdd-tasks gera tarefas TDD a partir de designs aprovados. Saiba como configurá-lo com o MCP tool.","ru":"Sdd-tasks генерирует задачи TDD из утвержденных дизайнов. Узнайте, как настроить его с помощью ИИ Агентов и MCP tool.","ar":"سد-مهام يولد مهام TDD من التصاميم المعتمدة. تعلم كيفية إعداده مع أداة MCP."},"seo":{"title":{"en":"sdd-tasks: TDD-Based Task Breakdown Generation for AI Agents","zh":"SDD-Tasks 设计生成指南","ja":"SDD-Tasks AIエージェントのタスクブレイクダウン生成","ko":"SDD-Tasks 설계 생성 워크플로우 가이드","es":"Guía de configuración de sdd-tasks para generar tareas TDD","fr":"Guide de mise en place de sdd-tasks pour la génération de...","de":"Einrichtungsleitfaden für 