INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yi-john-huang/sdd-mcp/sdd-tasks', 'sdd-tasks', 'yi-john-huang', 'sdd-mcp', 'community', 'sdd-tasks yi-john-huang sdd-mcp community The sdd-tasks skill generates TDD-based task breakdowns from approved designs, benefiting developers and project managers. It streamlines the development process by creating implementable work items. SDD-Tasks生成全面的TDD-based任务分解，实现设计到开发的无缝转换 SDD-Tasksは、設計から開発への無縫な転換を実現するためのTDD-basedタスクブレイクダウンを生成 SDD-Tasks는 설계에서 개발로의 무중단 전환을 위한 포괄적인 TDD 기반 태스크 분해를 생성 sdd-tasks genera tareas TDD detalladas a partir de diseños aprobados. Revisa los prerequisitos y el flujo de trabajo para configurar esta herramienta sdd-tasks génère des tâches TDD détaillées à partir de conceptions approuvées. Vérifiez les prérequis et le flux de travail pour configurer cet outil sdd-tasks erzeugt detaillierte TDD-Aufgaben aus genehmigten Designs. Überprüfen Sie die Voraussetzungen und den Workflow, um dieses Tool zu konfigurieren O sdd-tasks gera tarefas TDD a partir de designs aprovados. Saiba como configurá-lo com o MCP tool. Sdd-tasks генерирует задачи TDD из утвержденных дизайнов. Узнайте, как настроить его с помощью ИИ Агентов и MCP tool. سد-مهام يولد مهام TDD من التصاميم المعتمدة. تعلم كيفية إعداده مع أداة MCP. how to use sdd-tasks sdd-tasks setup guide TDD-based task breakdown generation sdd-tasks alternative sdd-tasks vs MCP tools sdd-tasks install what is sdd-tasks sdd-tasks workflow integration sdd-tasks design phase approval SDD-Tasks TDD-based任务分解 设计生成 MCP工具 CLI命令 AI工具 任务管理 设计审批 Generates task breakdowns using the /sdd-design command Verifies design prerequisites with the sdd-status MCP tool Reviews design documents in .spec/specs/{feature}/design.md format Creates implementable work items based on approved designs Utilizes the sdd-approve design MCP tool for design phase approval Integrates with MCP tools for seamless workflow sdd-tasks is a skill that generates comprehensive TDD-based task breakdowns, translating approved designs into implementable work items using the /sdd-design and sdd-approve design MCP tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('asteroid-belt/skulto/teach', 'community', 'asteroid-belt', 'skulto', 'asteroid-belt/skulto', 'teach', 0, 0, 42, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:09.407Z', 'faa36cbc7bc24db027707c0fb4c930aa49b3377d5b4ec4b7c5a126553620719b', '{"id":"asteroid-belt/skulto/teach","name":"teach","description":{"en":"The teach skill transforms technical documents into mastery-based learning paths, benefiting AI agents and developers alike by ensuring demonstrated mastery at each stage.","zh":"教程功能是离线和安全的AI工具，用于同步和管理AI代理技能。它可以将技术文档转化为严格的学习旅程","ja":"AIエージェントの教える機能は、オフラインでセキュリティを優先したツールで、エージェントのスキルを同期して管理します。技術文書を厳格な学習の旅に変換します","ko":"가르치는 기능은 오프라인 보안 同期 AI 도구로, 에이전트의 스킬을 동기화하고 관리합니다. 기술 문서를 엄격한 학습 여정으로 변환합니다","es":"Teach es una herramienta de sincronización de habilidades de agentes de IA que permite transformar documentos técnicos en jornadas de aprendizaje rigurosas","fr":"Teach est un outil de synchronisation des compétences des agents d''IA qui permet de transformer des documents techniques en parcours d''apprentissage rigoureux","de":"Teach ist ein Offline-Tool für die Synchronisierung von KI-Agenten-Fähigkeiten, das die Umwandlung von technischen Dokumenten in strenge Lernreisen ermöglicht","pt":"A ferramenta Teach é uma solução offline e segura para sincronizar e gerenciar habilidades de agentes, permitindo a transformação de documentos técnicos em jornadas de aprendizado rigorosas","ru":"ИИ Агенты: Teach - это offline и безопасный инструмент для синхронизации и управления навыками, позволяющий преобразовывать технические документы в строгие обучающие пути","ar":"أداة Teach هي حل متقدم لتنظيم مهارات الوكلاء بطرق آمنة و离线، مما يسمح بتحويل المستندات الفنية إلى رحلات تعلم شديدة"},"seo":{"title":{"en":"teach: Mastery Learning Setup Guide | AI Agent Skill","zh":"教程设置指南：离线安全同步AI工具","ja":"AIエージェントの教える機能：オフラインセキュリティ同期ツール","ko":"가르치는 기능 설정 가이드: 오프라인 보안 同期 AI 도구","es":"Guía de configuración de teach: Herramienta de sincroniza...","fr":"Guide de configuration de teach : Outil de synchronisatio...","de":"Einrichtungsleitfaden für teach: Offline-Tool für die Syn...","pt":"Guia de Configuração do Teach: Ferramenta de Sincronizaçã...","ru":"ИИ Агенты: Руководство по Настройке Teach для Синхронизац...","ar":"دليل إعداد Teach: أداة متقدمة لتنظيم مهارات الوكلاء"},"description":{"en":"Unlock rigorous learning journeys with teach, the offline and security-first tool for syncing and managing AI agent skills - get started now!","zh":"通过教程功能，实现技术文档的转化为严格的学习旅程，要求每个阶段都有证明的掌握。了解教程设置和同期管理","ja":"AIエージェントの教える機能により、技術文書を厳格な学習の旅に変換します。マスタリーの証明を段階的に取得することができます","ko":"가르치는 기능을 통해 기술 문서를 엄격한 학습 여정으로 변환하고, 각 단계에서 증명된 마스터리를 요구합니다. 설정 및 동기화 관리에 대해 알아보세요","es":"Aprende a configurar teach, una herramienta de sincronización de habilidades de agentes de IA que prioriza la seguridad y el aprendizaje basado en la maestría","fr":"Découvrez comment configurer teach, un outil de synchronisation des compétences des agents d''IA qui privilégie la sécurité et l''apprentissage basé sur la maî...","de":"Erfahren Sie, wie Sie teach konfigurieren, ein Offline-Tool für die Synchronisierung von KI-Agenten-Fähigkeiten mit Sicherheitsfunktionen und Lernmöglichkeit...","pt":"Aprenda a configurar a ferramenta Teach para sincronizar e gerenciar habilidades de agentes de forma segura e offline","ru":"Изучите руководство по настройке Teach для синхронизации и управления навыками ИИ Агентов в условиях offline и безопасности","ar":"تعرف على كيفية إعداد Teach لتكون أداة متقدمة لتنظيم مهارات الوكلاء بسهولة وأمان"},"definition":{"en":"teach is an offline and security-first tool for syncing and managing AI agent skills, focusing on deep mastery teaching and rigorous learning journeys.","zh":"教程功能是一种离线安全的AI工具，用于同步和管理AI代理技能","ja":"AIエージェントの教える機能は、オフラインでセキュリティを優先したエージェントのスキルを同期して管理するツールです","ko":"가르치는 기능은 오프라인 보안 同期 AI 도구로, 에이전트의 스킬을 동기화하고 관리하는 것을 지원합니다","es":"Teach es una herramienta de sincronización de habilidades de agentes de IA que prioriza la seguridad y el aprendizaje basado en la maestría","fr":"Teach est un outil de synchronisation des compétences des agents d''IA qui privilégie la sécurité et l''apprentissage basé sur la maîtrise","de":"Teach ist ein Offline-Tool für die Synchronisierung von KI-Agenten-Fähigkeiten, das die Sicherheit und das Lernen basierend auf der Meisterschaft priorisiert","pt":"O Teach é uma ferramenta de sincronização de habilidades de agentes que permite a criação de jornadas de aprendizado rigorosas e personalizadas","ru":"Teach - это инструмент синхронизации навыков ИИ Агентов, позволяющий создавать строгие и персонализированные обучающие пути","ar":"أداة Teach هي أداة متقدمة لتنظيم مهارات الوكلاء، تسمح بإنشاء رحلات تعلم شديدة ومتخصصة"},"features":{"en":["Transforms technical documents into rigorous learning journeys","Requires demonstrated mastery at each stage of the learning path","References evidence base from mastery-learning-research.md","Utilizes core principles from learning-science.md for effective learning","Supports session walkthroughs as seen in example-session.md","Provides question templates from verification-examples.md for assessment"],"zh":["离线安全同步","技术文档转化为严格的学习旅程","要求每个阶段都有证明的掌握","支持多种技术文档格式","集成学习科学和 마스터リー 학습原理"],"ja":["オフラインセキュリティ同期","技術文書を厳格な学習の旅に変換","段階的にマスタリーの証明を取得","複数の技術文書形式をサポート","学習科学とマスタリー学習原理の統合"],"ko":["오프라인 보안 동기화","기술 문서를 엄격한 학습 여정으로 변환","각 단계에서 증명된 마스터리를 요구","다양한 기술 문서 형식을 지원","학습 과학과 마스터리 학습 원리의 통합"],"es":["Transformación de documentos técnicos en jornadas de aprendizaje rigurosas","Aprendizaje basado en la maestría con demostración de habilidades en cada etapa","Sincronización de habilidades de agentes de IA de manera segura","Compatibilidad con herramientas de aprendizaje basado en la ciencia","Soporte para la creación de sesiones de aprendizaje personalizadas","Integración con tecnologías de verificación de habilidades"],"fr":["Transformation de documents techniques en parcours d''apprentissage rigoureux","Apprentissage basé sur la maîtrise avec démonstration de compétences à chaque étape","Synchronisation des compétences des agents d''IA de manière sécurisée","Compatibilité avec des outils d''apprentissage basés sur la science","Support pour la création de sessions d''apprentissage personnalisées","Intégration avec des technologies de vérification de compétences"],"de":["Umwandlung von technischen Dokumenten in strenge Lernreisen","Lernen basierend auf der Meisterschaft mit Demonstration von Fähigkeiten in jeder Phase","Synchronisierung von KI-Agenten-Fähigkeiten auf sichere Weise","Kompatibilität mit Lernwerkzeugen basierend auf der Wissenschaft","Unterstützung für die Erstellung von personalisierten Lernsitzungen","Integration mit Technologien zur Überprüfung von Fähigkeiten"],"pt":["Transformação de documentos técnicos em jornadas de aprendizado rigorosas","Sincronização de habilidades de agentes de forma segura e offline","Criação de jornadas de aprendizado personalizadas com demonstração de mestria","Integração com referências de pesquisa e ciência de aprendizado","Suporte a templates de verificação e exemplos de sessões"],"ru":["Преобразование технических документов в строгие обучающие пути","Синхронизация навыков ИИ Агентов в условиях offline и безопасности","Создание персонализированных обучающих путей с демонстрацией мастерства","Интеграция с ссылками на исследование и науку об обучении","Поддержка шаблонов верификации и примеров сессий"],"ar":["تحويل المستندات الفنية إلى رحلات تعلم شديدة","تنظيم مهارات الوكلاء بطرق آمنة و离线","إنشاء رحلات تعلم شديدة ومتخصصة مع إثبات الإتقان","التكامل مع المراجع البحثية وعلوم التعلم","دعم قوالب التحقق وأمثلة الجلسات"]},"keywords":{"en":["how to use teach for AI agents","what is teach skill","teach alternative for mastery learning","teach vs traditional learning methods","teach install guide for developers","teach setup for AI agent skills","mastery learning with teach","security-first AI agent skill management","offline AI agent skill syncing with teach"],"zh":["AI工具教程","离线安全同步","技术文档转化","马斯特里学习","AI代理技能管理","教程设置指南","AIエージェント开发"],"ja":["AIエージェントの教える機能","オフラインセキュリティ同期","技術文書の変換","マスタリー学習","AIエージェントのスキル管理","教える機能の設定","AIエージェント開発"],"ko":["AI 도구 가르치기","오프라인 보안 동기화","기술 문서 변환","마스터리 학습","에이전트 스킬 관리","가르치는 기능 설정","AI 에이전트 개발"],"es":["teach","agentes de IA","herramienta de sincronización","aprendizaje basado en la maestría","seguridad","documentos técnicos","jornadas de aprendizaje","ciencia del aprendizaje","tecnologías de verificación de habilidades"],"fr":["teach","agents d''IA","outil de synchronisation","apprentissage basé sur la maîtrise","sécurité","documents techniques","parcours d''apprentissage","science de l''apprentissage","technologies de vérification de compétences"],"de":["teach","KI-Agenten","Synchronisierungstool","Lernen basierend auf der Meisterschaft","Sicherheit","technische Dokumente","Lernreisen","Lernwissenschaft","Technologien zur Überprüfung von Fähigkeiten"],"pt":["teach","ferramenta de sincronização de habilidades de agentes","sincronização de habilidades de agentes","jornadas de aprendizado rigorosas","documentos técnicos","aprendizado personalizado","demonstração de mestria","referências de pesquisa","ciência de aprendizado"],"ru":["ИИ Агенты","инструмент синхронизации навыков","синхронизация навыков ИИ Агентов","строгие обучающие пути","технические документы","персонализированное обучение","демонстрация мастерства","ссылки на исследование","наука об обучении"],"ar":["وكلاء الذكاء الاصطناعي","أداة متقدمة لتنظيم مهارات الوكلاء","تنظيم مهارات الوكلاء","رحلات تعلم شديدة","مستندات فنية","تعلم متخصص","إثبات الإتقان","مراجع بحثية","علوم التعلم"]}},"owner":"asteroid-belt","repo":"skulto","repoPath":"asteroid-belt/skulto","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.294Z","topics":[],"category":"community","skillMd":{"name":"teach","description":"Transforms technical documents into rigorous learning journeys with collegiate-level mastery requirements. Uses Blooms taxonomy progression, 80%+ mastery thresholds, and multi-level verification before advancing. Treats learning as a high school to college graduation progression. Use when user wants deep understanding, not surface familiarity.","bodyPreview":"# Deep Mastery Teaching\n\nTransform technical documents into rigorous learning journeys requiring demonstrated mastery at each stage.\n\n**References:** See [mastery-learning-research.md](references/mastery-learning-research.md) for evidence base, [learning-science.md](references/learning-science.md) for core principles, [example-session.md](references/example-session.md) for session walkthrough, [verification-examples.md](references/verification-examples.md) for question templates.\n\n## Philosophy","body":"# Deep Mastery Teaching\n\nTransform technical documents into rigorous learning journeys requiring demonstrated mastery at each stage.\n\n**References:** See [mastery-learning-research.md](references/mastery-learning-research.md) for evidence base, [learning-science.md](references/learning-science.md) for core principles, [example-session.md](references/example-session.md) for session walkthrough, [verification-examples.md](references/verification-examples.md) for question templates.\n\n## Philosophy\n\nYou are a professor guiding a student from first-year undergraduate through graduate-level mastery. **Never accept surface familiarity as understanding.** A concept is not learned until the student can:\n\n1. Explain it in their own words\n2. Apply it to novel situations\n3. Identify when it does/doesn''t apply\n4. Critique alternative approaches\n5. Teach it to someone else\n\n## Invocation\n\n```bash\n/teach @doc1.md @doc2.md    # Explicit files (preferred)\n/teach                       # Prompts for topic/files\n```\n\n## Session Initialization (Check for Existing Progress)\n\n**Before teaching begins, always check for existing progress using fuzzy matching.**\n\n**Progress location:** `~/.skulto/teach/{topic-slug}/progress.md`\n\n### Startup Flow (Fuzzy Match First)\n\n```\n1. User invokes /teach @doc.md\n\n2. List ALL existing topic directories:\n   ls ~/.skulto/teach/\n\n   Example output:\n   - vector-databases-deep-dive/\n   - phase-2-infrastructure/\n   - react-testing-patterns/\n\n3. Generate a topic slug from document name (lowercase, hyphens)\n   Example: \"Vector Databases\" → \"vector-databases\"\n\n4. FUZZY MATCH against existing directories (90%+ similarity):\n\n   Your slug: \"vector-databases\"\n   Existing:  \"vector-databases-deep-dive\"  ← 90%+ match!\n\n   Match examples that SHOULD match:\n   - \"vector-db\" ↔ \"vector-databases\" (same topic)\n   - \"phase2-infra\" ↔ \"phase-2-infrastructure\" (same topic)\n   - \"rag-system\" ↔ \"rag-systems-architecture\" (same topic)\n\n   DO NOT create a new directory if a close match exists.\n\n5. If MATCH FOUND (90%+ similar):\n\n   Read the existing progress.md, show summary:\n\n     \"Found existing progress for ''Vector Databases'':\n      ✓ 2/5 chunks mastered\n      ⚠ 1 chunk in progress\n      ○ 2 chunks remaining\n      Last session: 2024-01-23\n\n      Resume where you left off, or start fresh?\"\n\n   Resume → Load state, run recall quiz, continue\n   Start fresh → Archive old file (rename with date), create new\n\n6. If NO MATCH (nothing 90%+ similar):\n   Create new directory and progress.md, proceed normally\n```\n\n**CRITICAL:** Do NOT look for an exact filename match. Always `ls` the directory first and fuzzy match against what exists. Claude tends to generate slightly different slugs between sessions—this prevents orphaned progress files.\n\n### Creating Progress File\n\nWhen starting a new topic, create the directory and file using tools:\n\n```bash\nmkdir -p ~/.skulto/teach/{topic-slug}\n```\n\nThen write initial `progress.md` with the template from [progress-template.md](references/progress-template.md).\n\n### Updating Progress File\n\n**After each chunk is mastered**, immediately update `progress.md`:\n1. Update the chunk''s status in the Learning Path table\n2. Add session notes if significant (struggles, breakthroughs, backfills)\n3. Update \"Last session\" date\n\n**At session end**, add a Session History entry summarizing:\n- Chunks completed\n- Any backfills performed\n- Key observations about learner''s strengths/gaps\n\n## Session Flow\n\n```dot\ndigraph teach_flow {\n    rankdir=TB;\n    node [shape=box];\n\n    intake [label=\"1. INTAKE\\nReview docs deeply\\nIdentify complexity level\"];\n    chunk [label=\"2. CHUNK\\nBreak into teachable sections\\nAssign Bloom''s target level per chunk\"];\n    probe [label=\"3. PROBE PREREQUISITES\\nMultiple questions if needed\\nDon''t proceed until solid\"];\n\n    assess [label=\"Prerequisites Solid?\" shape=diamond];\n    backfill [label=\"BACKFILL\\nTeach foundation thoroughly\\nVerify foundation mastery\\nBefore returning to main\"];\n\n    teach_chunk [label=\"4. TEACH CHUNK\\nExplain with depth\\nMultiple examples\\nConnect to prior chunks\"];\n\n    mastery [label=\"5. MASTERY LADDER\\n3-5 verification questions\\nProgress through Bloom''s levels\\nMust pass 80%+ to advance\"];\n\n    mastery_check [label=\"80%+ Correct?\" shape=diamond];\n    reteach [label=\"RETEACH\\nDifferent angle/analogy\\nMore examples\\nCheck for foundation gaps\"];\n\n    foundation_check [label=\"Foundation Problem?\" shape=diamond];\n    deep_backfill [label=\"DEEP BACKFILL\\nGo back 2+ levels\\nRebuild from basics\\nExtend widely\"];\n\n    consolidate [label=\"6. CONSOLIDATE\\nConnect to previous chunks\\nBuild integrated understanding\"];\n\n    break_check [label=\"Natural break?\" shape=diamond];\n    offer_pause [label=\"Progress summary\\nMastery status\\nOffer to continue\"];\n\n    more_chunks [label=\"More chunks?\" shape=diamond];\n    synthesis [label=\"7. SYNTHESIS TEST\\nCross-chunk integration\\nNovel problem solving\\nDefend design decisions\"];\n\n    complete [label=\"SESSION COMPLETE\\nMastery summary\\nGaps identified\\nNext steps\"];\n\n    intake -> chunk -> probe -> assess;\n    assess -> teach_chunk [label=\"solid\"];\n    assess -> backfill [label=\"gaps\"];\n    backfill -> probe;\n\n    teach_chunk -> mastery -> mastery_check;\n    mastery_check -> consolidate [label=\">=80%\"];\n    mastery_check -> reteach [label=\"<80%\"];\n    reteach -> foundation_check;\n    foundation_check -> mastery [label=\"no, just needs practice\"];\n    foundation_check -> deep_backfill [label=\"yes\"];\n    deep_backfill -> probe;\n\n    consolidate -> break_check;\n    break_check -> offer_pause [label=\"yes\"];\n    break_check -> more_chunks [label=\"no\"];\n    offer_pause -> more_chunks [label=\"continue\"];\n\n    more_chunks -> probe [label=\"yes\"];\n    more_chunks -> synthesis [label=\"no\"];\n    synthesis -> complete;\n}\n```\n\n## The Mastery Ladder\n\n**This is the core of deep teaching.** Each chunk requires verification at multiple cognitive levels before advancement.\n\n### Bloom''s Levels (Low → High)\n\n| Level | What It Tests | Question Starters |\n|-------|--------------|-------------------|\n| **Remember** | Can recall facts | \"What is...?\", \"List the...\", \"Define...\" |\n| **Understand** | Can explain in own words | \"Explain why...\", \"In your own words...\", \"What''s the difference between...\" |\n| **Apply** | Can use in new situation | \"Given this scenario...\", \"How would you use...\", \"Solve this...\" |\n| **Analyze** | Can break down, compare | \"Compare X and Y...\", \"What are the trade-offs...\", \"Why does this fail when...\" |\n| **Evaluate** | Can judge, critique | \"Which approach is better for...\", \"What''s wrong with...\", \"Defend this choice...\" |\n| **Create** | Can synthesize new solutions | \"Design a...\", \"How would you modify...\", \"Propose an alternative...\" |\n\n### Mastery Ladder Per Chunk\n\nFor each chunk, ask **3-5 questions** that climb the ladder:\n\n```\nCHUNK: Understanding Vector Embeddings\n\nQ1 (Understand): \"In your own words, what does it mean for two texts\n    to be ''close'' in embedding space?\"\n\nQ2 (Apply): \"Given this query about ''making React faster'', which of\n    these documents would have the closest embedding:\n    (a) ''React component lifecycle''\n    (b) ''Performance optimization in React applications''\n    (c) ''Getting started with React''\"\n\nQ3 (Analyze): \"Why would semantic search fail for the query ''FTS5 syntax''\n    but keyword search would succeed? What''s different about these query types?\"\n\nQ4 (Evaluate): \"A team argues they should use 1536-dimensional embeddings\n    instead of 384-dimensional for better accuracy. What''s your response?\n    What factors should they consider?\"\n\nPASSING: 3/4 correct (75%+) with solid explanations\n         If 2/4 or worse → reteach and retry\n```\n\n### Mastery Thresholds\n\n| Situation | Threshold | Action if Not Met |\n|-----------|-----------|-------------------|\n| Standard chunk | 80% (4/5 or 3/4) | Reteach, different angle |\n| Foundational/critical | 90% (must get nearly all) | Go deeper, more examples |\n| After reteach | 70% minimum to proceed | If still failing, backfill foundations |\n| Synthesis test | 80% | Review weak areas, retest |\n\n## Prerequisite Probing\n\nBefore each chunk, identify **2-4 foundational concepts** it requires. Probe each:\n\n**Probing Protocol:**\n```\nTeacher: \"Before we discuss vector databases, I need to check\nyour foundation. What do you understand about how machine\nlearning models represent text as numbers?\"\n\n[If vague or wrong]\nTeacher: \"That''s a gap we need to fill first. Let me explain\nembeddings from the ground up, then we''ll verify you''ve got it\nbefore continuing to vector databases.\"\n\n[Teach embedding basics with multiple examples]\n[Verify with 2-3 questions at Understand/Apply level]\n[Only then proceed to vector databases]\n```\n\n**Never proceed with shaky foundations.** The single biggest cause of learning failure is building on unstable ground.\n\n## Backfill Protocol\n\nWhen a foundation gap is detected:\n\n1. **Acknowledge:** \"You''ll need a solid understanding of X first.\"\n2. **Get permission:** \"Want me to teach the fundamentals, or point to resources?\"\n3. **Teach thoroughly:** Don''t rush—treat backfill with same rigor as main content\n4. **Verify mastery:** 2-3 questions at Understand/Apply level minimum\n5. **Connect forward:** \"Now that you understand X, here''s why it matters for Y...\"\n\n### Deep Backfill (When Main Content Repeatedly Fails)\n\nIf a learner repeatedly fails mastery checks despite reteaching:\n- The prerequisite assessment was too shallow\n- **Go back 2+ levels**—not just the immediate prerequisite\n- Expand the backfill **widely**—related concepts, alternative framings\n- Rebuild comprehensively before returning\n\n## Teaching Chunks\n\n### Structure of Excellent Chunk Teaching\n\n1. **Context connection** (30 seconds)\n   - \"We covered X. Now we''ll see how Y builds on it...\"\n\n2. **Core explanation** (2-3 minutes)\n   - Clear, direct explanation\n   - One main concept at a time\n   - Define every term\n\n3. **Concrete example** (1-2 minutes)\n   - Real, specific example\n   - Walk through step by step\n\n4. **Second example** (1-2 minutes)\n   - Different context\n   - Shows the concept generalizes\n\n5. **Edge case or common mistake** (1 minute)\n   - \"A common misconception is...\"\n   - \"This breaks down when...\"\n\n6. **Summary statement** (30 seconds)\n   - Crystallize the key insight\n\n### Do Not\n\n- Rush through to cover more material\n- Assume understanding from silence\n- Use jargon without defining it\n- Give one example and move on\n- Accept \"I think I get it\" as mastery\n\n## Consolidation Between Chunks\n\nAfter mastery is demonstrated, **connect the chunk to the bigger picture**:\n\n```\nTeacher: \"Good. Let''s consolidate. You now understand:\n- Embeddings convert text to vectors (Chunk 1)\n- Similar meanings cluster together (Chunk 2)\n- LanceDB stores and searches these vectors (Chunk 3)\n\nNotice how each piece enables the next—without embeddings,\nthere''s nothing to store; without the clustering property,\nsearching would be useless.\n\nNext chunk will cover the indexing pipeline. You''ll need to\nhold all three concepts together. Ready?\"\n```\n\n## Synthesis Test (End of Session)\n\nAfter all chunks, test **integrated understanding**:\n\n### Synthesis Question Types\n\n1. **Cross-chunk integration:**\n   \"Walk me through what happens from when a document enters the system\n   to when it''s returned in a search result. Touch on all the components\n   we covered.\"\n\n2. **Novel problem:**\n   \"A user reports that searches for ''authentication'' miss documents\n   about ''login security.'' Using what you learned, diagnose the issue\n   and propose a fix.\"\n\n3. **Design defense:**\n   \"Someone proposes storing all data in just LanceDB without SQLite.\n   Argue both for and against this change.\"\n\n4. **Teaching it:**\n   \"Explain to a junior developer why this system uses two databases\n   instead of one. Keep it under 2 minutes.\"\n\n### Synthesis Threshold\nMust demonstrate integrated understanding. If failing here, identify which chunks need reinforcement and either revisit or assign for next session.\n\n## Session Management\n\n### Natural Breaks\n- After completing a major section (2-3 chunks)\n- After difficult backfill sequences\n- After 30-40 minutes of intensive learning\n- When learner shows fatigue signals\n\n### At Breaks (Provide Mastery Status)\n\n```\nGood stopping point.\n\nMASTERY STATUS:\n✓ Vector embeddings (5/5 mastery ladder, solid)\n✓ Similarity search (4/5, one edge case to review)\n⚠ LanceDB schema (3/5, passed threshold but recommend practice)\n\nCOVERED: How embeddings enable semantic search\nNEXT: Indexing pipeline, hybrid retrieval strategies\n\nContinue, or save progress for later?\n```\n\n### Resuming Sessions\n\nWhen user chooses \"Resume\" from the initialization prompt:\n\n1. **Read progress.md** to understand current state\n2. **Show status summary:**\n   ```\n   Welcome back. Here''s where we are:\n\n   MASTERED:\n   ✓ Dual storage architecture (4/4)\n   ✓ SQLite FTS5 (3.5/4)\n\n   IN PROGRESS:\n   ⚠ Vector embeddings (2/4 last attempt - needs reteach)\n\n   REMAINING:\n   ○ Indexing pipeline\n   ○ Retrieval strategies\n   ```\n3. **Run recall quiz** (3-4 questions on mastered chunks)\n4. If rusty (< 60% correct): Brief refresher, update notes in progress.md\n5. If solid (80%+ correct): Proceed with confidence\n6. **Resume at current chunk** or reteach if previous attempt failed\n7. Always reconnect: \"Last time we established X. Today we''ll build on that...\"\n\n## Tone\n\n**Baseline:** Rigorous professor—high standards, clear expectations, structured\n**Layer in:** Supportive mentor—encouraging, patient, believes in learner\n**Adapt to:** Learner''s pace, but never lower standards\n\n| Situation | Say | Avoid |\n|-----------|-----|-------|\n| Wrong answer | \"Not quite. Let''s think through this—what did we say about...\" | \"Wrong.\" / \"That''s incorrect.\" |\n| Repeated struggles | \"This is genuinely difficult material. Let''s approach it differently.\" | \"It''s easy, you should get this.\" |\n| Mastery achieved | \"Solid. You''ve demonstrated understanding.\" | \"Great job!\" / excessive praise |\n| Frustration | \"Take a breath. This confusion is normal—it means you''re learning.\" | Rushing past the difficulty |\n\n## Key Principles\n\n1. **Mastery before advancement** — Never proceed until 80%+ demonstrated\n2. **Multiple verification levels** — Test understand, apply, AND analyze\n3. **Deep foundations** — Backfill thoroughly, never patch over gaps\n4. **Progressive complexity** — Build from novice toward expert cognition\n5. **Integrated understanding** — Connect chunks, test synthesis\n6. **High standards, high support** — Rigorous but patient\n7. **No false confidence** — \"Got it?\" tells you nothing; test instead\n"},"lastSynced":"2026-03-08T02:01:09.407Z","agentAnalysis":{"suitability":{"en":"Ideal for Educational Agents requiring rigorous learning path creation and demonstrated mastery tracking.","zh":"适合需要创建严格的学习路径和跟踪掌握情况的教育代理。","ja":"教育エージェントが厳格な学習パスの作成とマスターした状況の追跡を必要とする場合に最適です。","ko":"교육 에이전트가 엄격한 학습 경로 생성과 증명된 마스터 추적을 요구하는 경우에 적합합니다.","es":"Ideal para Agentes Educativos que requieren la creación de un camino de aprendizaje riguroso y el seguimiento de la maestría demostrada.","fr":"Idéal pour les agents éducatifs nécessitant la création d''un parcours d''apprentissage rigoureux et le suivi d''une maîtrise démontrée.","de":"Ideal für Bildungsagenten, die die Erstellung eines strengen Lernpfads und die Nachverfolgung der demonstrierten Meisterschaft erfordern.","pt":"Ideal para Agentes Educacionais que exigem a criação de caminhos de aprendizado rigorosos e o acompanhamento da demonstração de domínio.","ru":"Идеально подходит для образовательных агентов, требующих создания строгих образовательных путей и отслеживания демонстрируемого мастерства.","ar":"مثالي لعميل التعليم الذي يتطلب إنشاء مسار تعليمي صارم وتتبع إتقان مقدم"},"recommendation":{"en":"Empowers agents to transform technical documents into mastery-based learning journeys using demonstrated mastery at each stage, incorporating core principles from learning science and verified through question templates and session walkthroughs.","zh":"赋予代理人将技术文档转化为基于掌握的学习旅程的能力，使用每个阶段的掌握证明，并结合学习科学的核心原则，通过问题模板和会话演练验证。","ja":"エージェントが技術文書をマスターベースの学習ジャーニーに変換する能力を付与し、各段階でのマスター証明を使用し、学習科学の核心原則を組み込み、質問テンプレートとセッションのウォークスルーを介して検証します。","ko":"에이전트가 기술 문서를 마스터 기반의 학습 여정으로 변환할 수 있는 기능을 부여하며, 각 단계에서 증명된 마스터를 사용하고, 학습 과학의 핵심 원리를 통합하며, 질문 템플릿과 세션 워크 스루를 통해 검증합니다.","es":"Habilita a los agentes a transformar documentos técnicos en trayectorias de aprendizaje basadas en la maestría utilizando la maestría demostrada en cada etapa, incorporando principios básicos de la ciencia del aprendizaje y verificados a través de plantillas de preguntas y sesiones de práctica.","fr":"Permet aux agents de transformer des documents techniques en parcours d''apprentissage basés sur la maîtrise en utilisant la maîtrise démontrée à chaque étape, en intégrant les principes fondamentaux de la science de l''apprentissage et en les vérifiant à l''aide de modèles de questions et de séances de démonstration.","de":"Ermächtigt Agenten, technische Dokumente in Lernreisen auf der Grundlage der Meisterschaft umzuwandeln, indem die demonstrierte Meisterschaft in jedem Stadium unter Verwendung von Grundsätzen der Lernwissenschaft und durch Fragevorlagen und Sitzungs-Durchgänge verifiziert wird.","pt":"Habilita os agentes a transformar documentos técnicos em jornadas de aprendizado baseadas no domínio demonstrado, incorporando princípios fundamentais da ciência do aprendizado e verificados por meio de modelos de perguntas e simulações de sessões.","ru":"Наделяет агентов возможностью преобразовывать технические документы в обучающие программы на основе демонстрируемого мастерства, включающие основные принципы обучающей науки и подтвержденные с помощью шаблонов вопросов и симуляций сессий.","ar":"تمكّن الوكلاء من تحويل المستندات الفنية إلى رحلات تعلم قائمة على الإتقان المثبت، ودمج المبادئ الأساسية للعلوم التعليمية والمدققة من خلال قوالب الأسئلة ومحاكاة الجلسات"},"useCases":{"en":["Creating customized learning paths from technical documents","Developing mastery-based training programs","Verifying learner understanding through question templates"],"zh":["从技术文档创建自定义的学习路径","开发基于掌握的培训计划","通过问题模板验证学习者理解"],"ja":["技術文書からカスタマイズされた学習パスを作成する","マスターベースのトレーニングプログラムを開発する","質問テンプレートを使用して学習者の理解を検証する"],"ko":["기술 문서에서 맞춤형 학습 경로 생성","마스터 기반의 훈련 프로그램 개발","질문 템플릿을 통해 학습자 이해력을 검증"],"es":["Crear caminos de aprendizaje personalizados a partir de documentos técnicos","Desarrollar programas de capacitación basados en la maestría","Verificar la comprensión del aprendiz mediante plantillas de preguntas"],"fr":["Créer des parcours d''apprentissage personnalisés à partir de documents techniques","Développer des programmes de formation basés sur la maîtrise","Vérifier la compréhension de l''apprenant à l''aide de modèles de questions"],"de":["Erstellen von individuellen Lernpfaden aus technischen Dokumenten","Entwicklung von Schulungsprogrammen auf der Grundlage der Meisterschaft","Überprüfung des Lernverständnisses durch Fragevorlagen"],"pt":["Criar caminhos de aprendizado personalizados a partir de documentos técnicos","Desenvolver programas de treinamento baseados no domínio","Verificar a compreensão do aluno por meio de modelos de perguntas"],"ru":["Создание индивидуальных образовательных путей из технических документов","Разработка программ обучения на основе мастерства","Проверка понимания учащимися с помощью шаблонов вопросов"],"ar":["إنشاء مسارات تعلم مخصصة من المستندات الفنية","تطوير برامج تدريبية قائمة على الإتقان","التحقق من فهم المتعلم من خلال قوالب الأسئلة"]},"limitations":{"en":["Requires access to technical documents and learning materials","Dependent on mastery-learning research and learning science principles"],"zh":["需要访问技术文档和学习材料","依赖于掌握学习研究和学习科学原则"],"ja":["技術文書と学習材料へのアクセスが必要","マスター学習研究と学習科学原則に依存する"],"ko":["기술 문서와 학습 자료에 대한 액세스가 필요","마스터 학습 연구와 학습 과학 원리에 의존"],"es":["Requiere acceso a documentos técnicos y materiales de aprendizaje","Depende de la investigación sobre el aprendizaje de la maestría y los principios de la ciencia del aprendizaje"],"fr":["Nécessite l''accès à des documents techniques et à des matériaux pédagogiques","Dépend de la recherche sur l''apprentissage de la maîtrise et des principes de la science de l''apprentissage"],"de":["Benötigt den Zugriff auf technische Dokumente und Lernmaterialien","Hängt von der Meisterschaftsforschung und den Grundsätzen der Lernwissenschaft ab"],"pt":["Exige acesso a documentos técnicos e materiais de aprendizado","Depende da pesquisa de aprendizado de domínio e dos princípios da ciência do aprendizado"],"ru":["Требует доступа к техническим документам и учебным материалам","Зависит от исследований обучения мастерству и принципов обучающей науки"],"ar":["يتطلب الوصول إلى المستندات الفنية ووضع مواد التعلم","يعتمد على أبحاث تعلم الإتقان ومبادئ العلوم التعليمية"]},"version":4},"contentHash":"faa36cbc7bc24db027707c0fb4c930aa49b3377d5b4ec4b7c5a126553620719b","qualityScore":42}');
