INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('asteroid-belt/skulto/teach', 'teach', 'asteroid-belt', 'skulto', 'community', 'teach asteroid-belt skulto community The teach skill transforms technical documents into mastery-based learning paths, benefiting AI agents and developers alike by ensuring demonstrated mastery at each stage. 教程功能是离线和安全的AI工具，用于同步和管理AI代理技能。它可以将技术文档转化为严格的学习旅程 AIエージェントの教える機能は、オフラインでセキュリティを優先したツールで、エージェントのスキルを同期して管理します。技術文書を厳格な学習の旅に変換します 가르치는 기능은 오프라인 보안 同期 AI 도구로, 에이전트의 스킬을 동기화하고 관리합니다. 기술 문서를 엄격한 학습 여정으로 변환합니다 Teach es una herramienta de sincronización de habilidades de agentes de IA que permite transformar documentos técnicos en jornadas de aprendizaje rigurosas Teach est un outil de synchronisation des compétences des agents d''IA qui permet de transformer des documents techniques en parcours d''apprentissage rigoureux Teach ist ein Offline-Tool für die Synchronisierung von KI-Agenten-Fähigkeiten, das die Umwandlung von technischen Dokumenten in strenge Lernreisen ermöglicht A ferramenta Teach é uma solução offline e segura para sincronizar e gerenciar habilidades de agentes, permitindo a transformação de documentos técnicos em jornadas de aprendizado rigorosas ИИ Агенты: Teach - это offline и безопасный инструмент для синхронизации и управления навыками, позволяющий преобразовывать технические документы в строгие обучающие пути أداة Teach هي حل متقدم لتنظيم مهارات الوكلاء بطرق آمنة و离线، مما يسمح بتحويل المستندات الفنية إلى رحلات تعلم شديدة how to use teach for AI agents what is teach skill teach alternative for mastery learning teach vs traditional learning methods teach install guide for developers teach setup for AI agent skills mastery learning with teach security-first AI agent skill management offline AI agent skill syncing with teach AI工具教程 离线安全同步 技术文档转化 马斯特里学习 AI代理技能管理 教程设置指南 AIエージェント开发 Transforms technical documents into rigorous learning journeys Requires demonstrated mastery at each stage of the learning path References evidence base from mastery-learning-research.md Utilizes core principles from learning-science.md for effective learning Supports session walkthroughs as seen in example-session.md Provides question templates from verification-examples.md for assessment teach is an offline and security-first tool for syncing and managing AI agent skills, focusing on deep mastery teaching and rigorous learning journeys.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Mineru98/skills-store/subagents-creator', 'community', 'Mineru98', 'skills-store', 'Mineru98/skills-store', 'subagents-creator', 0, 0, 42, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:19.366Z', '80fde25307576b668bfd922e78c619abf1772d063042301e6e51f6fac6337ad6', '{"id":"Mineru98/skills-store/subagents-creator","name":"subagents-creator","description":{"en":"The subagents-creator skill provides guidance for defining and using Claude subagents, helping developers handle specific domains efficiently.","zh":"Subagents Creator 提供了定义、使用和改进 Claude 子代理的指导，包括 TASK、EXPECTED OUTCOME 和 REQUIRED SKILLS","ja":"Subagents Creator は Claude サブエージェントを定義、使用、改善するためのガイダンスを提供します","ko":"Subagents Creator는 Claude 서브 에이전트를 정의하고 사용하는 방법을 제공합니다","es":"El creador de subagentes proporciona orientación para definir, utilizar y mejorar subagentes de Claude, que manejan dominios específicos","fr":"Le créateur de sous-agents fournit des conseils pour définir, utiliser et améliorer les sous-agents de Claude, qui gèrent des domaines spécifiques","de":"Der Subagenten-Ersteller bietet Anleitung zur Definition, Verwendung und Verbesserung von Claude-Subagenten, die spezifische Bereiche verwalten","pt":"O Subagents Creator é uma habilidade que fornece orientação para definir, usar e melhorar subagentes especializados. Aprenda a delegar tarefas com eficiência.","ru":"Subagents Creator — это навык, который обеспечивает руководство по определению, использованию и улучшению специализированных субагентов. Изучите, как эффективно делегировать задачи.","ar":"Subagents Creator هو مهارة توفر إرشادات لتعريف واختبار وتحسين الوسائط الفرعية المتخصصة. تعلم كيفية تفويض المهام بكفاءة"},"seo":{"title":{"en":"subagents-creator: Delegation Setup Guide | AI Agent Skill","zh":"Subagents Creator 快速入门指南","ja":"Subagents Creator のベストプラクティス","ko":"Subagents Creator 설정 가이드","es":"Creador de Subagentes: Guía de Configuración para Desarro...","fr":"Créateur de Sous-agents : Guide de Mise en Route pour les...","de":"Subagenten-Ersteller: Einrichtungsanleitung für Entwickle...","pt":"Guia de Configuração do Subagents Creator para Desenvolve...","ru":"Настройка ИИ Агентов: Subagents Creator Руководство","ar":"دليل إنشاء واختبار_subagents Creator للاساتذة"},"description":{"en":"Discover how to effectively delegate work to subagents with our expert guide, featuring the mandatory 7-section structure for optimal results.","zh":"了解 Subagents Creator 的定义、使用和改进方法，包括 Claude 子代理的 7 部分结构","ja":"Subagents Creator を使用して Claude サブエージェントを定義、使用、改善する方法","ko":"Subagents Creator로 Claude 서브 에이전트를 정의하고 사용하는 방법을 알아보세요","es":"Aprende a crear y utilizar subagentes especializados para dominios como explore, librarian y oracle con el creador de subagentes","fr":"Découvrez comment créer et utiliser des sous-agents spécialisés pour des domaines tels que explore, librarian et oracle avec le créateur de sous-agents","de":"Erfahren Sie, wie Sie spezialisierte Subagenten für Bereiche wie explore, librarian und oracle mit dem Subagenten-Ersteller erstellen und verwenden","pt":"Aprenda a delegar tarefas com eficiência usando o Subagents Creator. Descubra como definir e melhorar subagentes para domínios específicos.","ru":"Изучите, как эффективно делегировать задачи с помощью Subagents Creator. Узнайте, как определять и улучшать субагентов для конкретных доменов.","ar":"تعلم كيفية تفويض المهام بكفاءة باستخدام Subagents Creator. اكتشف كيفية تعريف وتحسين الوسائط الفرعية لأصحاب المجالات الخاصة"},"definition":{"en":"subagents-creator is a skill that enables the creation and management of specialized agents for specific tasks, such as explore, librarian, and oracle.","zh":"Subagents Creator 是一种技能，用于定义、使用和改进 Claude 子代理","ja":"Subagents Creator は Claude サブエージェントを定義、使用、改善するためのスキル","ko":"Subagents Creator는 Claude 서브 에이전트를 정의하고 사용하는 스_kill","es":"Un subagente es un agente especializado que maneja un dominio específico, como explore o librarian","fr":"Un sous-agent est un agent spécialisé qui gère un domaine spécifique, tel que explore ou librarian","de":"Ein Subagent ist ein spezialisierter Agent, der einen bestimmten Bereich wie explore oder librarian verwaltet","pt":"O Subagents Creator é uma habilidade que permite definir e melhorar subagentes para domínios específicos, como explore, librarian e oracle.","ru":"Subagents Creator — это навык, который позволяет определять и улучшать субагентов для конкретных доменов, таких как explore, librarian и oracle.","ar":"Subagents Creator هو مهارة يسمح بتعريف وتحسين الوسائط الفرعية لأصحاب المجالات الخاصة مثل explore وlibrarian وoracle"},"features":{"en":["Utilizes a mandatory 7-section structure for delegating work to subagents","Defines atomic, specific goals for tasks using the TASK section","Specifies concrete deliverables with success criteria in the EXPECTED OUTCOME section","Identifies required skills for subagents using the REQUIRED SKILLS section","Supports delegation to specialized agents like explore, librarian, and oracle","Enables improvement of Claude subagents for enhanced performance"],"zh":["支持 Claude 子代理的 7 部分结构","TASK、EXPECTED OUTCOME 和 REQUIRED SKILLS 的定义","子代理的委托和管理","改进 Claude 子代理的性能"],"ja":["Claude サブエージェントの 7 部分構造をサポート","TASK、EXPECTED OUTCOME、REQUIRED SKILLS の定義","サブエージェントの委託と管理","Claude サブエージェントのパフォーマンスの改善"],"ko":["Claude 서브 에이전트의 7 부분 구조 지원","TASK, EXPECTED OUTCOME, REQUIRED SKILLS 정의","서브 에이전트의 위임과 관리","Claude 서브 에이전트의 성능 개선"],"es":["Estructura de 7 secciones obligatoria para la delegación de tareas","Definición de objetivos atómicos y específicos para cada subagente","Especificación de resultados esperados con criterios de éxito","Requisitos de habilidades para cada subagente","Usabilidad en dominios como explore, librarian y oracle","Mejora continua de los subagentes"],"fr":["Structure de 7 sections obligatoire pour la délégation de tâches","Définition d''objectifs atomiques et spécifiques pour chaque sous-agent","Spécification des résultats attendus avec des critères de réussite","Exigences de compétences pour chaque sous-agent","Utilisation dans des domaines tels que explore, librarian et oracle","Amélioration continue des sous-agents"],"de":["Obligatorische 7-Sektions-Struktur für die Delegation von Aufgaben","Definition von atomaren und spezifischen Zielen für jeden Subagenten","Spezifikation der erwarteten Ergebnisse mit Erfolgskriterien","Anforderungen an Fähigkeiten für jeden Subagenten","Verwendbarkeit in Bereichen wie explore, librarian und oracle","Kontinuierliche Verbesserung der Subagenten"],"pt":["Delegação de tarefas com estrutura de 7 seções","Definição de subagentes para domínios específicos","Melhoria de subagentes para aumentar a eficiência","Uso de habilidades específicas para cada subagente","Definição de resultados concretos com critérios de sucesso"],"ru":["Делегирование задач с помощью структуры из 7 секций","Определение субагентов для конкретных доменов","Улучшение субагентов для повышения эффективности","Использование специфических навыков для каждого субагента","Определение конкретных результатов с критериями успеха"],"ar":["تفويض المهام بSTRUCTURE من 7 أجزاء","تعريف الوسائط الفرعية لأصحاب المجالات الخاصة","تحسين الوسائط الفرعية لزيادة الكفاءة","استخدام مهارات محددة لكل وسيط فرعي","تعريف نتائج محددة مع معايير النجاح"]},"keywords":{"en":["how to use subagents-creator","subagents-creator setup guide","subagents-creator alternative","subagents-creator vs claude","what is subagents-creator","subagents-creator install","delegating work to subagents","claude subagents best practices","subagents-creator documentation"],"zh":["AI エージェント","Subagents Creator","Claude 子代理","7 部分结构","TASK 定义","EXPECTED OUTCOME 定义","REQUIRED SKILLS 定义"],"ja":["AIエージェント","Subagents Creator","Claude サブエージェント","7 部分構造","TASK 定義","EXPECTED OUTCOME 定義","REQUIRED SKILLS 定義"],"ko":["AI 에이전트","Subagents Creator","Claude 서브 에이전트","7 부분 구조","TASK 정의","EXPECTED OUTCOME 정의","REQUIRED SKILLS 정의"],"es":["subagentes","AI Agentes","creador de subagentes","desarrollo de AI","dominios específicos","explore","librarian","oracle","subagentes especializados"],"fr":["sous-agents","Outils d''IA","créateur de sous-agents","développement d''IA","domaines spécifiques","explore","librarian","oracle","sous-agents spécialisés"],"de":["Subagenten","KI-Agents","Subagenten-Ersteller","KI-Entwicklung","spezifische Bereiche","explore","librarian","oracle","spezialisierte Subagenten"],"pt":["Subagents Creator","desenvolvimento de subagentes","delegação de tarefas","domínios específicos","habilidades de subagentes","melhoria de subagentes","estrutura de 7 seções","resultados concretos"],"ru":["Subagents Creator","разработка субагентов","делегирование задач","конкретные домены","навыки субагентов","улучшение субагентов","структура из 7 секций","конкретные результаты"],"ar":["Subagents Creator","تطوير الوسائط الفرعية","تفويض المهام","مجالات خاصة","مهارات الوسائط الفرعية","تحسين الوسائط الفرعية","STRUCTURE من 7 أجزاء","نتائج محددة"]}},"owner":"Mineru98","repo":"skills-store","repoPath":"Mineru98/skills-store","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"subagents-creator","description":"Guide for defining and using Claude subagents effectively. Use when (1) creating new subagent types, (2) learning how to delegate work to specialized subagents, (3) improving subagent delegation prompts, (4) understanding subagent orchestration patterns, or (5) debugging ineffective subagent usage.","bodyPreview":"# Subagents Creator\n\nThis skill provides guidance for defining, using, and improving Claude subagents—the specialized agents that handle specific domains like `explore`, `librarian`, `oracle`, and `frontend-ui-ux-engineer`.\n\n## Quick Start\n\n### Delegating Work\n\nWhen delegating to subagents, use the **mandatory 7-section structure**:\n\n```\n1. TASK: Atomic, specific goal (one action per delegation)\n2. EXPECTED OUTCOME: Concrete deliverables with success criteria\n3. REQUIRED SKILLS: Which skill to i","body":"# Subagents Creator\n\nThis skill provides guidance for defining, using, and improving Claude subagents—the specialized agents that handle specific domains like `explore`, `librarian`, `oracle`, and `frontend-ui-ux-engineer`.\n\n## Quick Start\n\n### Delegating Work\n\nWhen delegating to subagents, use the **mandatory 7-section structure**:\n\n```\n1. TASK: Atomic, specific goal (one action per delegation)\n2. EXPECTED OUTCOME: Concrete deliverables with success criteria\n3. REQUIRED SKILLS: Which skill to invoke\n4. REQUIRED TOOLS: Explicit tool whitelist (prevents tool sprawl)\n5. MUST DO: Exhaustive requirements - leave NOTHING implicit\n6. MUST NOT DO: Forbidden actions - anticipate and block rogue behavior\n7. CONTEXT: File paths, existing patterns, constraints\n```\n\n### Choosing a Subagent\n\nSee [subagent-types.md](references/subagent-types.md) for detailed guidance on which subagent to use:\n- **`explore`**: Contextual grep for codebases\n- **`librarian`**: Reference search (docs, OSS, web)\n- **`oracle`**: Deep reasoning for architecture/complex decisions\n- **`frontend-ui-ux-engineer`**: Visual UI/UX changes\n\n## Defining New Subagents\n\n**Only create subagents when**: The task domain has distinct tooling, expertise, or patterns that benefit from specialization.\n\nSee [delegation-patterns.md](references/delegation-patterns.md) for:\n- Subagent definition templates\n- When to create a new subagent vs using existing ones\n- Naming and description guidelines\n\n## Common Pitfalls\n\nSee [common-pitfalls.md](references/common-pitfalls.md) for:\n- Vague delegation prompts and why they fail\n- Over-delegating trivial tasks\n- Subagent misalignment with task type\n- Anti-patterns in agent orchestration\n\n## Best Practices\n\n1. **One action per delegation**: Combine tasks in parallel calls, not one call\n2. **Be exhaustive**: \"MUST DO\" and \"MUST NOT DO\" sections prevent drift\n3. **Background everything**: Use `background_task` for `explore` and `librarian`\n4. **Explicit tool lists**: Prevent subagents from using unauthorized tools\n5. **Verify results**: Check that delegated work meets expectations before proceeding\n\n## Delegation Example\n\n```python\n# GOOD: Specific, exhaustive\nbackground_task(\n    agent=\"explore\",\n    prompt=\"\"\"\n    1. TASK: Find all authentication implementations\n    2. EXPECTED OUTCOME: List of files with auth logic, patterns used\n    3. REQUIRED SKILLS: explore\n    4. REQUIRED TOOLS: Grep, Read\n    5. MUST DO: Search for ''jwt'', ''session'', ''auth'' patterns; identify middleware; list all endpoints\n    6. MUST NOT DO: Don''t modify any files; don''t run build/test commands\n    7. CONTEXT: Working in ./src directory, looking for Express.js patterns\n    \"\"\"\n)\n\n# BAD: Vague, implicit expectations\nbackground_task(\n    agent=\"explore\",\n    prompt=\"Find auth stuff in the codebase\"\n)\n```\n\n## Reference Files\n\n- [subagent-types.md](references/subagent-types.md) - When to use each subagent type\n- [delegation-patterns.md](references/delegation-patterns.md) - Prompt templates and patterns\n- [common-pitfalls.md](references/common-pitfalls.md) - Anti-patterns and how to avoid them\n"},"lastSynced":"2026-03-08T02:01:19.366Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents like Claude, needing efficient domain-specific task handling through subagents","zh":"适合于高级AI代理，如Claude，需要通过子代理实现高效的域特定任务处理","ja":"Claudeなどの高度なAIエージェントに適しており、サブエージェントを介したドメイン特定のタスク処理が効率的に行える","ko":"고급 AI 에이전트인 Claude와 같이 서브 에이전트를 통해 효율적인 도메인 특정 작업 처리가 필요한 경우에 적합","es":"Ideal para Agentes de IA Avanzados como Claude, que necesitan un manejo eficiente de tareas específicas del dominio a través de subagentes","fr":"Idéal pour les agents IA avancés comme Claude, nécessitant une gestion efficace de tâches spécifiques au domaine via des sous-agents","de":"Ideal für erweiterte KI-Agents wie Claude, die ein effizientes Handling von domänenspezifischen Aufgaben durch Subagenten benötigen","pt":"Ideal para Agentes de IA Avançados como Claude, necessitando de tratamento de tarefas eficientes e específicos de domínio por meio de subagentes","ru":"Идеально для продвинутых агентов ИИ, таких как Claude, требующих эффективного обработки задач в конкретных доменах через субагентов","ar":"مثالي لوكلاء الذكاء الاصطناعي المتقدمين مثل Claude ، الذين يحتاجون إلى معالجة كفؤة للمهام الخاصة بالمجال من خلال وكلاء فرعيين"},"recommendation":{"en":"Empowers agents to define and utilize specialized subagents for domains like explore, librarian, and oracle, streamlining task delegation with a mandatory 7-section structure, including TASK, EXPECTED OUTCOME, and REQUIRED SKILLS","zh":"赋予代理定义和利用专门的子代理来处理诸如探索、图书管理员和预言家等领域的任务，并通过强制性的7部分结构（包括TASK、EXPECTED OUTCOME和REQUIRED SKILLS）来简化任务委托","ja":"エージェントが探索、ライブラリアン、オラクルなどのドメインに特化したサブエージェントを定義して利用できるようにし、TASK、EXPECTED OUTCOME、REQUIRED SKILLSを含む7つのセクションからなる強制的な構造を使用してタスクの委託を簡素化する","ko":"에이전트가 탐색, 사서, 오라클 등의 도메인에 특화된 서브 에이전트를 정의하고 사용할 수 있도록 하며, TASK, EXPECTED OUTCOME, REQUIRED SKILLS를 포함한 7개 섹션으로 구성된 강제 구조를 통해 작업 위임을 간소화","es":"Habilita a los agentes a definir y utilizar subagentes especializados para dominios como explorar, bibliotecario y oráculo, simplificando la delegación de tareas con una estructura obligatoria de 7 secciones, incluyendo TASK, EXPECTED OUTCOME y REQUIRED SKILLS","fr":"Permet aux agents de définir et d''utiliser des sous-agents spécialisés pour des domaines tels que explorer, bibliothécaire et oracle, en simplifiant la délégation de tâches avec une structure obligatoire de 7 sections, incluant TASK, EXPECTED OUTCOME et REQUIRED SKILLS","de":"Ermöglicht es Agents, spezialisierte Subagenten für Bereiche wie explore, librarian und oracle zu definieren und zu nutzen, wodurch die Aufgabenverteilung mit einer obligatorischen 7-Abschnitts-Struktur, einschließlich TASK, EXPECTED OUTCOME und REQUIRED SKILLS, rationalisiert wird","pt":"Habilita os agentes a definir e utilizar subagentes especializados para domínios como explorar, bibliotecário e oráculo, otimizando a delegação de tarefas com uma estrutura de 7 seções obrigatória, incluindo TAREFA, RESULTADO ESPERADO e HABILIDADES REQUERIDAS","ru":"Наделяет агентов возможностью определять и использовать специализированных субагентов для доменов, таких как исследование, библиотекарь и оракул, оптимизируя делегирование задач с обязательной 7-разделной структурой, включая ЗАДАЧА, ОЖИДАЕМЫЙ РЕЗУЛЬТАТ и ТРЕБУЕМЫЕ НАВЫКИ","ar":"يمنح الوكلاء القدرة على تعريف وكلاء فرعيين متخصصين لمجالات مثل الاستكشاف و أمين المكتبة و المنجم ، وبتصريف المهام ب بنية من 7 أقسام إجبارية ، بما في ذلك المهمة و النتيجة المتوقعة و المهارات المطلوبة"},"useCases":{"en":["Delegating tasks to subagents for efficient domain handling","Improving subagent performance through structured outcome expectations","Developing specialized subagents for unique domains like frontend-ui-ux-engineer"],"zh":["将任务委托给子代理以高效处理域","通过结构化的结果期望来提高子代理的性能","为前端UI/UX工程师等独特域开发专用子代理"],"ja":["ドメインを効率的に処理するためにタスクをサブエージェントに委託する","構造化された結果の期待値を使用してサブエージェントのパフォーマンスを向上させる","フロントエンドUI/UXエンジニアなどのユニークなドメイン向けに特化したサブエージェントを開発する"],"ko":["서브 에이전트에게 작업을 위임하여 도메인을 효율적으로 처리","구조화된 결과 예상치를 사용하여 서브 에이전트의 성능을 향상","프론트엔드 UI/UX 엔지니어와 같은 고유한 도메인에 특화된 서브 에이전트를 개발"],"es":["Delegar tareas a subagentes para un manejo eficiente del dominio","Mejorar el rendimiento de los subagentes a través de expectativas de resultados estructuradas","Desarrollar subagentes especializados para dominios únicos como frontend-ui-ux-engineer"],"fr":["Déléguer des tâches à des sous-agents pour un traitement efficace du domaine","Améliorer les performances des sous-agents via des attentes de résultats structurées","Développer des sous-agents spécialisés pour des domaines uniques comme frontend-ui-ux-engineer"],"de":["Aufgaben an Subagenten delegieren, um ein effizientes Domänen-Handling zu ermöglichen","Die Leistung von Subagenten durch strukturierte Ergebniserwartungen verbessern","Entwicklung spezialisierter Subagenten für einzigartige Bereiche wie frontend-ui-ux-engineer"],"pt":["Delegar tarefas para subagentes para tratamento de domínio eficiente","Melhorar o desempenho do subagente por meio de expectativas de resultados estruturadas","Desenvolver subagentes especializados para domínios únicos como frontend-ui-ux-engineer"],"ru":["Делегировать задачи субагентам для эффективного xử lý доменов","Улучшать производительность субагента за счет структурированных ожиданий результатов","Разрабатывать специализированных субагентов для уникальных доменов, таких как frontend-ui-ux-engineer"],"ar":["تفويض المهام إلى وكلاء فرعيين من أجل معالجة المجال بكفاءة","تحسين أداء الوكيل الفرعي من خلال توقع نتائج منظم","تطوير وكلاء فرعيين متخصصين لمجالات فريدة مثل frontend-ui-ux-engineer"]},"limitations":{"en":["Requires understanding of Claude subagent architecture","Mandatory 7-section structure for task delegation"],"zh":["需要了解Claude子代理架构","任务委托需要强制性的7部分结构"],"ja":["Claudeのサブエージェントアーキテクチャを理解する必要がある","タスクの委託には強制的な7つのセクションからなる構造が必要"],"ko":["Claude 서브 에이전트 아키텍처를 이해해야 함","작업 위임에는 강제적인 7개 섹션으로 구성된 구조가 필요"],"es":["Requiere comprensión de la arquitectura de subagentes de Claude","Estructura obligatoria de 7 secciones para la delegación de tareas"],"fr":["Nécessite une compréhension de l''architecture des sous-agents de Claude","Structure obligatoire de 7 sections pour la délégation de tâches"],"de":["Benötigt Verständnis der Claude-Subagenten-Architektur","Obligatorische 7-Abschnitts-Struktur für die Aufgabenverteilung"],"pt":["Exige compreensão da arquitetura de subagentes do Claude","Estrutura de 7 seções obrigatória para delegação de tarefas"],"ru":["Требует понимания архитектуры субагентов Claude","Обязательная 7-разделная структура для делегирования задач"],"ar":["يتطلب فهم هيئة وكلاء فرعيين Claude","هيئة من 7 أقسام إجبارية لتصريف المهام"]},"version":4},"contentHash":"80fde2530757