INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mineru98/skills-store/subagents-creator', 'subagents-creator', 'Mineru98', 'skills-store', 'community', 'subagents-creator Mineru98 skills-store community The subagents-creator skill provides guidance for defining and using Claude subagents, helping developers handle specific domains efficiently. Subagents Creator 提供了定义、使用和改进 Claude 子代理的指导，包括 TASK、EXPECTED OUTCOME 和 REQUIRED SKILLS Subagents Creator は Claude サブエージェントを定義、使用、改善するためのガイダンスを提供します Subagents Creator는 Claude 서브 에이전트를 정의하고 사용하는 방법을 제공합니다 El creador de subagentes proporciona orientación para definir, utilizar y mejorar subagentes de Claude, que manejan dominios específicos Le créateur de sous-agents fournit des conseils pour définir, utiliser et améliorer les sous-agents de Claude, qui gèrent des domaines spécifiques Der Subagenten-Ersteller bietet Anleitung zur Definition, Verwendung und Verbesserung von Claude-Subagenten, die spezifische Bereiche verwalten O Subagents Creator é uma habilidade que fornece orientação para definir, usar e melhorar subagentes especializados. Aprenda a delegar tarefas com eficiência. Subagents Creator — это навык, который обеспечивает руководство по определению, использованию и улучшению специализированных субагентов. Изучите, как эффективно делегировать задачи. Subagents Creator هو مهارة توفر إرشادات لتعريف واختبار وتحسين الوسائط الفرعية المتخصصة. تعلم كيفية تفويض المهام بكفاءة how to use subagents-creator subagents-creator setup guide subagents-creator alternative subagents-creator vs claude what is subagents-creator subagents-creator install delegating work to subagents claude subagents best practices subagents-creator documentation AI エージェント Subagents Creator Claude 子代理 7 部分结构 TASK 定义 EXPECTED OUTCOME 定义 REQUIRED SKILLS 定义 Utilizes a mandatory 7-section structure for delegating work to subagents Defines atomic, specific goals for tasks using the TASK section Specifies concrete deliverables with success criteria in the EXPECTED OUTCOME section Identifies required skills for subagents using the REQUIRED SKILLS section Supports delegation to specialized agents like explore, librarian, and oracle Enables improvement of Claude subagents for enhanced performance subagents-creator is a skill that enables the creation and management of specialized agents for specific tasks, such as explore, librarian, and oracle.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('olivenet-iot/olivenet-social-bot/instagram-api', 'community', 'olivenet-iot', 'olivenet-social-bot', 'olivenet-iot/olivenet-social-bot', 'instagram-api', 0, 0, 42, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:37.194Z', 'fe9adadbddc2273d13bf19b60a44614c7efce562884df0410e173832c632d012', '{"id":"olivenet-iot/olivenet-social-bot/instagram-api","name":"instagram-api","description":{"en":"The instagram-api skill enables developers to interact with Instagram''s Graph API, allowing them to create containers, publish media, and retrieve insights. This skill is ideal for developers building social media integrations.","zh":"Instagram API 提供了媒体发布、状态检查和洞察获取的功能，帮助开发者提高效率","ja":"Instagram API はメディアの公開、ステータスの確認、インサイトの取得機能を提供し、開発者の効率を向上させます","ko":"인스타그램 API는 미디어 발행, 상태 확인 및 인사이트 가져오기 기능을 제공하여 개발자의 효율성을 향상시킵니다","es":"La API de Instagram permite a los desarrolladores crear contenedores, publicar contenido y obtener información sobre el rendimiento de sus publicaciones","fr":"L''API Instagram permet aux développeurs de créer des conteneurs, de publier du contenu et d''obtenir des informations sur les performances de leurs publications","de":"Die Instagram-API ermöglicht es Entwicklern, Container zu erstellen, Inhalte zu veröffentlichen und Informationen über die Leistung ihrer Veröffentlichungen zu erhalten","pt":"A API do Instagram permite criar contêineres, publicar mídia e obter insights. Use o endpoint https://graph.instagram.com/v21.0 para criar contêineres e publicar mídia.","ru":"Instagram API позволяет создавать контейнеры, публиковать медиа и получать аналитику. Используйте endpoint https://graph.instagram.com/v21.0 для создания контейнеров и публикации медиа.","ar":"واجهة برمجة تطبيقات إنستغرام تسمح بإنشاء حاويات ونشر الوسائط والحصول على رؤى. استخدم نقطة النهاية https://graph.instagram.com/v21.0 لإنشاء حاويات ونشر الوسائط."},"seo":{"title":{"en":"instagram-api: API Setup Guide for AI Agents","zh":"Instagram API 集成指南","ja":"Instagram API 導入ガイド","ko":"인스타그램 API 설정 가이드","es":"Guía de Configuración de Instagram API para Desarrolladores","fr":"Guide d''Installation de l''API Instagram pour les Développ...","de":"Einrichtungsleitfaden für die Instagram-API für Entwickler","pt":"Guia de Configuração da API do Instagram","ru":"Настройка Instagram API: Руководство","ar":"دليل إعداد واجهة برمجة تطبيقات إنستغرام"},"description":{"en":"Unlock Instagram''s Graph API potential with our expert guide. Learn how to create containers, publish media, and get insights with ease. Get started now!","zh":"了解如何使用 Instagram Graph API 进行媒体发布、状态检查和洞察获取，提高开发效率","ja":"Instagram Graph API を使用してメディアの公開、ステータスの確認、インサイトの取得を行う方法を学びましょう","ko":"인스타그램 그래프 API를 사용하여 미디어 발행, 상태 확인 및 인사이트 가져오기를 수행하는 방법을 알아보세요","es":"Aprende a utilizar la API de Instagram para crear contenedores, publicar contenido y obtener información sobre el rendimiento de tus publicaciones","fr":"Découvrez comment utiliser l''API Instagram pour créer des conteneurs, publier du contenu et obtenir des informations sur les performances de vos publications","de":"Erfahren Sie, wie Sie die Instagram-API verwenden, um Container zu erstellen, Inhalte zu veröffentlichen und Informationen über die Leistung Ihrer Veröffentl...","pt":"Aprenda a usar a API do Instagram para criar contêineres, publicar mídia e obter insights com o endpoint https://graph.instagram.com/v21.0","ru":"Узнайте, как использовать Instagram API для создания контейнеров, публикации медиа и получения аналитики с помощью endpoint https://graph.instagram.com/v21.0","ar":"تعرف على كيفية استخدام واجهة برمجة تطبيقات إنستغرام لإنشاء حاويات ونشر الوسائط الحصول على رؤى من خلال نقطة النهاية https://graph.instagram.com/v21.0"},"definition":{"en":"instagram-api is a skill that provides access to Instagram''s Graph API, enabling developers to create, publish, and manage media, as well as retrieve engagement insights.","zh":"Instagram API 是一种用于与 Instagram 交互的图形 API","ja":"Instagram API は Instagram と対話するためのグラフィカル API です","ko":"인스타그램 API는 인스타그램과 상호 작용하기 위한 그래프 API입니다","es":"La API de Instagram es un conjunto de herramientas para desarrolladores que permite interactuar con la plataforma de Instagram","fr":"L''API Instagram est un ensemble d''outils pour les développeurs qui permet d''interagir avec la plateforme Instagram","de":"Die Instagram-API ist ein Satz von Tools für Entwickler, die es ermöglicht, mit der Instagram-Plattform zu interagieren","pt":"A API do Instagram é um conjunto de endpoints que permitem criar contêineres, publicar mídia e obter insights.","ru":"Instagram API - это набор endpoint, которые позволяют создавать контейнеры, публиковать медиа и получать аналитику.","ar":"واجهة برمجة تطبيقات إنستغرام هي مجموعة من نقاط النهاية التي تسمح بإنشاء حاويات ونشر الوسائط والحصول على رؤى."},"features":{"en":["Creates containers using the `{user_id}/media` endpoint with a POST method","Publishes media using the `{user_id}/media_publish` endpoint with a POST method","Retrieves media status using the `{container_id}` endpoint with a GET method","Gets insights using the `{media_id}/insights` endpoint with a GET method","Supports two-phase publishing for video content","Polls until FINISHED for video content"],"zh":["创建容器并获取 container_id","发布媒体并获取 post_id","检查媒体状态","获取媒体洞察","支持两阶段发布流程","使用 HTTPS 进行安全请求"],"ja":["コンテナを作成し、container_id を取得","メディアを公開し、post_id を取得","メディアのステータスを確認","メディアのインサイトを取得","2 段階の公開プロセスをサポート","HTTPS を使用した安全なリクエスト"],"ko":["컨테이너 생성 및 container_id 가져오기","미디어 발행 및 post_id 가져오기","미디어 상태 확인","미디어 인사이트 가져오기","2단계 발행 프로세스 지원","HTTPS를 사용한 안전한 요청"],"es":["Creación de contenedores mediante el endpoint /{user_id}/media","Publicación de contenido mediante el endpoint /{user_id}/media_publish","Obtención de información sobre el rendimiento de las publicaciones mediante el endpoint /{media_id}/insights","Compatibilidad con la publicación en dos fases para videos","Polling hasta que el estado de la publicación sea FINISHED","Compatibilidad con la versión v21.0 de la API"],"fr":["Création de conteneurs via l''endpoint /{user_id}/media","Publication de contenu via l''endpoint /{user_id}/media_publish","Obtention d''informations sur les performances des publications via l''endpoint /{media_id}/insights","Prise en charge de la publication en deux phases pour les vidéos","Polling jusqu''à ce que l''état de la publication soit FINISHED","Prise en charge de la version v21.0 de l''API"],"de":["Erstellung von Containern über den Endpoint /{user_id}/media","Veröffentlichung von Inhalten über den Endpoint /{user_id}/media_publish","Abruf von Informationen über die Leistung der Veröffentlichungen über den Endpoint /{media_id}/insights","Unterstützung für die Veröffentlichung in zwei Phasen für Videos","Polling bis zum Status FINISHED","Unterstützung für die Version v21.0 der API"],"pt":["Criação de contêineres via endpoint /{user_id}/media","Publicação de mídia via endpoint /{user_id}/media_publish","Obtenção de insights via endpoint /{media_id}/insights","Suporte à publicação em duas fases para vídeos","Polling até o status FINISHED para vídeos","Compatibilidade com o endpoint https://graph.instagram.com/v21.0"],"ru":["Создание контейнеров через endpoint /{user_id}/media","Публикация медиа через endpoint /{user_id}/media_publish","Получение аналитики через endpoint /{media_id}/insights","Поддержка двухфазной публикации для видео","Опрос до статуса FINISHED для видео","Совместимость с endpoint https://graph.instagram.com/v21.0"],"ar":["إنشاء حاويات عبر نقطة النهاية /{user_id}/media","نشر الوسائط عبر نقطة النهاية /{user_id}/media_publish","الحصول على رؤى عبر نقطة النهاية /{media_id}/insights","دعم النشر في مرحلتين للفيديو","استطلاع حتى الحالة FINISHED للفيديو","التوافق مع نقطة النهاية https://graph.instagram.com/v21.0"]},"keywords":{"en":["how to use instagram-api","instagram-api setup guide","instagram-api alternative","instagram-api vs facebook api","instagram-api install","instagram graph api tutorial","instagram-api media publishing","instagram-api insights retrieval","instagram-api two-phase publishing"],"zh":["Instagram API","图形 API","媒体发布","状态检查","洞察获取","两阶段发布","HTTPS 请求","AI エージェント","开发者指南"],"ja":["Instagram API","グラフィカル API","メディアの公開","ステータスの確認","インサイトの取得","2 段階の公開","HTTPS リクエスト","AI エージェント","開発者ガイド"],"ko":["인스타그램 API","그래프 API","미디어 발행","상태 확인","인사이트 가져오기","2단계 발행","HTTPS 요청","AI 에이전트","개발자 가이드"],"es":["instagram api","desarrollo de instagram","api de instagram para desarrolladores","creación de contenedores en instagram","publicación de contenido en instagram","información sobre el rendimiento de las publicaciones","publicación en dos fases para videos","polling en instagram","version v21.0 de la api de instagram"],"fr":["api instagram","développement instagram","api instagram pour les développeurs","création de conteneurs sur instagram","publication de contenu sur instagram","informations sur les performances des publications","publication en deux phases pour les vidéos","polling sur instagram","version v21.0 de l''api instagram"],"de":["instagram api","entwicklung von instagram","api von instagram für entwickler","erstellung von containern auf instagram","veröffentlichung von inhalten auf instagram","informationen über die leistung der veröffentlichungen","veröffentlichung in zwei phasen für videos","polling auf instagram","version v21.0 der api von instagram"],"pt":["instagram api","criar contêiner","publicar mídia","obter insights","endpoint https://graph.instagram.com/v21.0","desenvolvimento de aplicativos","integração com instagram","api de mídia social","programação de redes sociais"],"ru":["instagram api","создать контейнер","опубликовать медиа","получить аналитику","endpoint https://graph.instagram.com/v21.0","разработка приложений","интеграция с инстаграм","api социальных медиа","программирование социальных сетей"],"ar":["واجهة برمجة تطبيقات إنستغرام","إنشاء حاوية","نشر الوسائط","الحصول على رؤى","نقطة النهاية https://graph.instagram.com/v21.0","تطوير التطبيقات","التكامل مع إنستغرام","واجهة برمجة تطبيقات وسائل الإعلام الاجتماعية","برمجة الشبكات الاجتماعية"]}},"owner":"olivenet-iot","repo":"olivenet-social-bot","repoPath":"olivenet-iot/olivenet-social-bot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.301Z","topics":[],"category":"community","skillMd":{"name":"instagram-api","description":"Instagram Graph API entegrasyonu. Use when publishing content, fetching insights, or working with Instagram media.","bodyPreview":"# Instagram Graph API\n\n**Version:** v21.0 | **Base:** `https://graph.instagram.com/v21.0`\n\n## Quick Reference\n\n| Action | Endpoint | Method |\n|--------|----------|--------|\n| Create Container | `/{user_id}/media` | POST |\n| Publish | `/{user_id}/media_publish` | POST |\n| Check Status | `/{container_id}` | GET |\n| Get Insights | `/{media_id}/insights` | GET |\n\n## Two-Phase Publishing\n\n```\n1. Create Container → container_id\n2. (Video only) Poll until FINISHED\n3. Publish Container → post_id\n```\n\n##","body":"# Instagram Graph API\n\n**Version:** v21.0 | **Base:** `https://graph.instagram.com/v21.0`\n\n## Quick Reference\n\n| Action | Endpoint | Method |\n|--------|----------|--------|\n| Create Container | `/{user_id}/media` | POST |\n| Publish | `/{user_id}/media_publish` | POST |\n| Check Status | `/{container_id}` | GET |\n| Get Insights | `/{media_id}/insights` | GET |\n\n## Two-Phase Publishing\n\n```\n1. Create Container → container_id\n2. (Video only) Poll until FINISHED\n3. Publish Container → post_id\n```\n\n## Publishing Functions\n\n```python\nfrom app.instagram_helper import (\n    post_photo_to_instagram,\n    post_video_to_instagram,\n    post_carousel_to_instagram\n)\n\n# Image\nresult = await post_photo_to_instagram(image_url, caption)\n\n# Reels\nresult = await post_video_to_instagram(video_url, caption)\n\n# Carousel (2-10 images)\nresult = await post_carousel_to_instagram(image_urls, caption)\n```\n\n## Video Requirements\n\n| Spec | Value |\n|------|-------|\n| Resolution | 720x1280 (9:16) |\n| Codec | H.264 video, AAC audio |\n| FPS | 30 |\n| Max | 90 seconds |\n\n```python\n# Auto-convert\nfrom app.instagram_helper import convert_video_for_instagram\nresult = await convert_video_for_instagram(input_path)\n# Returns: {success, output_path, converted, file_size_mb}\n```\n\n## Insights\n\n```python\nfrom app.insights_helper import get_instagram_media_insights\n\ninsights = await get_instagram_media_insights(media_id)\n# Returns: {plays, reach, saves, shares, likes, comments, engagement_rate}\n```\n\n**Reels metrics:** plays, reach, saved, shares, comments, likes\n**Image metrics:** impressions, reach, saved\n\n## Rate Limiting\n\n- Container creation: 2s delay\n- Video polling: 10s interval, max 30 attempts\n- Insights fetch: 0.3s delay between calls\n\n## Environment Variables\n\n```bash\nINSTAGRAM_ACCESS_TOKEN=...\nINSTAGRAM_USER_ID=...\nINSTAGRAM_BUSINESS_ID=...  # Optional\n```\n\n## Return Format\n\n```python\n# Success\n{\"success\": True, \"id\": \"17901234567890123\", \"platform\": \"instagram\"}\n\n# Error\n{\"success\": False, \"error\": \"Error message\"}\n```\n\n## Common Errors\n\n| Error | Solution |\n|-------|----------|\n| OAuthException | Token expired - refresh |\n| MediaTypeNotSupported | Wrong format - convert |\n| RateLimitError | Too many calls - add delay |\n\n## Deep Links\n\n- `app/instagram_helper.py` - Publishing\n- `app/insights_helper.py` - Metrics\n- `app/cloudinary_helper.py` - Video CDN\n"},"lastSynced":"2026-03-08T02:01:37.194Z","agentAnalysis":{"suitability":{"en":"Ideal for Social Media Agents requiring Instagram Graph API integration for automated content publishing and insights retrieval.","zh":"适合需要使用Instagram Graph API集成进行自动内容发布和检索分析的社交媒体代理。","ja":"Instagram Graph APIを介した自動コンテンツ公開と分析の取得が必要なソーシャルメディアエージェントに最適です。","ko":"인스타그램 그래프 API 통합을 통한 자동 콘텐츠 게시 및 인사이트检索가 필요한 소셜 미디어 에이전트에 적합합니다.","es":"Ideal para agentes de redes sociales que requieren integración con Instagram Graph API para publicación de contenido automatizada y recuperación de informes.","fr":"Idéal pour les agents de médias sociaux nécessitant une intégration avec l''API Instagram Graph pour la publication de contenu automatisée et la récupération d''informations.","de":"Ideal für Social-Media-Agents, die eine Integration mit der Instagram Graph API für automatisierte Inhaltsveröffentlichung und Informationsabruf benötigen.","pt":"Ideal para Agentes de Mídia Social que exigem integração com o Instagram Graph API para publicação automática de conteúdo e recuperação de informações.","ru":"Идеально для социальных медиа-агентов, требующих интеграции с Instagram Graph API для автоматизированной публикации контента и получения информации.","ar":"مثالي لعميل وسائل الإعلام الاجتماعية التي تتطلب تكامل مع Instagram Graph API لنشر المحتوى التلقائي واسترجاع Informationen."},"recommendation":{"en":"Empowers agents to create containers, publish media, and retrieve insights using Instagram''s Graph API v21.0, enabling seamless interaction with the platform via endpoints like `{/user_id}/media` and `{/media_id}/insights` using HTTP methods such as POST and GET.","zh":"赋予代理创建容器、发布媒体、检索分析的能力，使用Instagram的Graph API v21.0，实现与平台的无缝交互，通过诸如`{/user_id}/media`和`{/media_id}/insights`的端点，使用HTTP方法如POST和GET。","ja":"エージェントがコンテナを作成し、メディアを公開し、分析を取得する機能を提供し、InstagramのGraph API v21.0を使用して、プラットフォームとのシームレスなやり取りを可能にし、`{/user_id}/media`や`{/media_id}/insights`などのエンドポイントを使用して、POSTやGETなどのHTTPメソッドを使用します。","ko":"에이전트가 컨테이너를 생성하고 미디어를 게시하고 인사이트를 검색할 수 있는 기능을 제공하여 인스타그램의 그래프 API v21.0을 사용하여 플랫폼과 원활한 상호 작용을 가능하게 하며, `{/user_id}/media` 및 `{/media_id}/insights}`와 같은 엔드ポイント를 사용하여 POST 및 GET와 같은 HTTP 메서드를 사용합니다.","es":"Habilita a los agentes a crear contenedores, publicar medios y recuperar informes utilizando la API de Instagram Graph v21.0, lo que permite una interacción fluida con la plataforma a través de puntos de conexión como `{/user_id}/media` y `{/media_id}/insights` utilizando métodos HTTP como POST y GET.","fr":"Permet aux agents de créer des conteneurs, de publier des médias et de récupérer des informations en utilisant l''API Instagram Graph v21.0, ce qui permet une interaction fluide avec la plateforme via des points de terminaison tels que `{/user_id}/media` et `{/media_id}/insights` en utilisant des méthodes HTTP telles que POST et GET.","de":"Ermöglicht es Agenten, Container zu erstellen, Medien zu veröffentlichen und Informationen abzurufen, indem sie die Instagram Graph API v21.0 verwenden, was eine nahtlose Interaktion mit der Plattform über Endpunkte wie `{/user_id}/media` und `{/media_id}/insights` mithilfe von HTTP-Methoden wie POST und GET ermöglicht.","pt":"Habilita agentes a criar contêineres, publicar mídia e recuperar informações usando o Instagram''s Graph API v21.0, permitindo interação sem problemas com a plataforma por meio de endpoints como `{/user_id}/media` e `{/media_id}/insights` usando métodos HTTP como POST e GET.","ru":"Наделяет агентов возможностью создавать контейнеры, публиковать медиа и получать информацию, используя Instagram''s Graph API v21.0, что позволяет осуществлять бесперебойное взаимодействие с платформой через конечные точки, такие как `{/user_id}/media` и `{/media_id}/insights`, используя методы HTTP, такие как POST и GET.","ar":"يمنح الوكلاء khảية إنشاء حاويات، ونشر الوسائط، و استرجاع المعلومات باستخدام Instagram''s Graph API v21.0، مما يتيح التفاعل السلس مع المنصة عبر نهايات مثل `{/user_id}/media` و `{/media_id}/insights}` باستخدام أساليب HTTP مثل POST و GET."},"useCases":{"en":["Automating Instagram content publishing using the two-phase publishing process","Generating media insights reports by retrieving data from `{/media_id}/insights`","Creating custom containers for media using the `{/user_id}/media` endpoint","Polling container status for video uploads until FINISHED"],"zh":["使用两阶段发布流程自动发布Instagram内容","通过检索`{/media_id}/insights`的数据生成媒体分析报告","使用`{/user_id}/media`端点为媒体创建自定义容器","轮询容器状态，直到视频上传完成"],"ja":["2段階の公開プロセスを使用してInstagramコンテンツを自動公開する","`{/media_id}/insights`からデータを取得してメディア分析レポートを生成する","`{/user_id}/media`エンドポイントを使用してメディア用のカスタムコンテナを作成する","コンテナの状態をポーリングして、ビデオのアップロードが完了するまで"],"ko":["2단계 공개 프로세스를 사용하여 인스타그램 콘텐츠를 자동으로 게시하는 것","`{/media_id}/insights}`에서 데이터를 검색하여 미디어 분석 보고서를 생성하는 것","`{/user_id}/media` 엔드포인트를 사용하여 미디어용 사용자 정의 컨테이너를 생성하는 것","컨테이너 상태를 폴링하여 비디오 업로드가 완료될 때까지"],"es":["Automatizar la publicación de contenido de Instagram mediante el proceso de publicación de dos fases","Generar informes de análisis de medios recuperando datos de `{/media_id}/insights`","Crear contenedores personalizados para medios utilizando el punto de conexión `{/user_id}/media`","Sondar el estado del contenedor para cargas de video hasta que esté FINALIZADO"],"fr":["Automatiser la publication de contenu Instagram à l''aide du processus de publication en deux phases","Générer des rapports d''analyse de médias en récupérant des données de `{/media_id}/insights`","Créer des conteneurs personnalisés pour les médias en utilisant le point de terminaison `{/user_id}/media`","Sondage de l''état du conteneur pour les téléchargements de vidéo jusqu''à ce qu''il soit TERMINÉ"],"de":["Automatisieren der Veröffentlichung von Instagram-Inhalten mithilfe des zweiphasigen Veröffentlichungsprozesses","Generieren von Medienanalyseberichten durch Abrufen von Daten von `{/media_id}/insights`","Erstellen benutzerdefinierter Container für Medien mithilfe des Endpunkts `{/user_id}/media`","Abfragen des Containerstatus für Videouploads bis dieser ABGESCHLOSSEN ist"],"pt":["Automatizar a publicação de conteúdo do Instagram usando o processo de publicação em duas fases","Gerar relatórios de informações de mídia, recuperando dados de `{/media_id}/insights`","Criar contêineres personalizados para mídia usando o endpoint `{/user_id}/media`","Realizar polling do status do contêiner para uploads de vídeo até que seja FINALIZADO"],"ru":["Автоматизировать публикацию контента в Instagram, используя двухфазный процесс публикации","Генерировать отчеты о медиа-информации, получая данные из `{/media_id}/insights`","Создавать пользовательские контейнеры для медиа, используя конечную точку `{/user_id}/media`","Осуществлять опрос состояния контейнера для загрузки видео до тех пор, пока он не будет ЗАВЕРШЕН"],"ar":["توفير نشر المحتوى تلقائيًا على Instagram باستخدام عملية النشر في مرحلتين","توليد تقارير المعلومات الوسائطية عن طريق استرجاع البيانات من `{/media_id}/insights`","إنشاء حاويات مخصصة للوسائط باستخدام نهاية `{/user_id}/media`","استطلاع حالة الحاوية لنقل الفيديو حتى الانتهاء"]},"limitations":{"en":["Requires Instagram Graph API access token","Limited to Instagram''s Graph API v21.0","Needs user ID and media ID for specific actions"],"zh":["需要Instagram Graph API访问令牌","仅限于Instagram的Graph API v21.0","需要用户ID和媒体ID来执行特定操作"],"ja":["Instagram Graph APIのアクセストークンが必要","InstagramのGraph API v21.0に限定される","特定のアクションを実行するには、ユーザーIDとメディアIDが必要"],"ko":["인스타그램 그래프 API 액세스 토큰이 필요함","인스타그램의 그래프 API v21.0로 제한됨","특정 작업을 수행하려면 사용자 ID 및 미디어 ID가 필요함"],"es":["Requiere token de acceso a la API de Instagram Graph","Limitado a la API de Instagram Graph v21.0","Necesita ID de usuario y ID de medio para acciones específicas"],"fr":["Nécessite un jeton d''accès à l''API Instagram Graph","Limité à l''API Instagram Graph v21.0","Nécessite un ID d''utilisateur et un ID de média pour des actions spécifiques"],"de":["Benötigt Zugriffstoken für die Instagram Graph API","Begrenzt auf die Instagram Graph API v21.0","Benötigt Benutzer-ID und Medien-ID für bestimmte Aktionen"],"pt":["Exige token de acesso do Instagram Graph API","Limitado à versão v21.0 do Instagram''s Graph API","Necessita de ID do usuário e ID da mídia para ações específicas"],"ru":["Требует токена доступа к Instagram Graph API","Ограничен версией v21.0 Instagram''s Graph API","Требует идентификатора пользователя и идентификатора медиа для конкретных действий"],"ar":["يتطلب رمز وصول إلى Instagram Graph API","محدود بالنسخة v21.0 من Instagram''s Graph API","يحتاج إلى معرف المستخدم و معرّف الوسائط للactions محددة"]},"version":4},"contentHash":"fe9adadbddc2273d13bf19b60a44614c7efce562884df0410e173832c632d012","qualityScore":42}');
