INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('olivenet-iot/olivenet-social-bot/instagram-api', 'instagram-api', 'olivenet-iot', 'olivenet-social-bot', 'community', 'instagram-api olivenet-iot olivenet-social-bot community The instagram-api skill enables developers to interact with Instagram''s Graph API, allowing them to create containers, publish media, and retrieve insights. This skill is ideal for developers building social media integrations. Instagram API 提供了媒体发布、状态检查和洞察获取的功能，帮助开发者提高效率 Instagram API はメディアの公開、ステータスの確認、インサイトの取得機能を提供し、開発者の効率を向上させます 인스타그램 API는 미디어 발행, 상태 확인 및 인사이트 가져오기 기능을 제공하여 개발자의 효율성을 향상시킵니다 La API de Instagram permite a los desarrolladores crear contenedores, publicar contenido y obtener información sobre el rendimiento de sus publicaciones L''API Instagram permet aux développeurs de créer des conteneurs, de publier du contenu et d''obtenir des informations sur les performances de leurs publications Die Instagram-API ermöglicht es Entwicklern, Container zu erstellen, Inhalte zu veröffentlichen und Informationen über die Leistung ihrer Veröffentlichungen zu erhalten A API do Instagram permite criar contêineres, publicar mídia e obter insights. Use o endpoint https://graph.instagram.com/v21.0 para criar contêineres e publicar mídia. Instagram API позволяет создавать контейнеры, публиковать медиа и получать аналитику. Используйте endpoint https://graph.instagram.com/v21.0 для создания контейнеров и публикации медиа. واجهة برمجة تطبيقات إنستغرام تسمح بإنشاء حاويات ونشر الوسائط والحصول على رؤى. استخدم نقطة النهاية https://graph.instagram.com/v21.0 لإنشاء حاويات ونشر الوسائط. how to use instagram-api instagram-api setup guide instagram-api alternative instagram-api vs facebook api instagram-api install instagram graph api tutorial instagram-api media publishing instagram-api insights retrieval instagram-api two-phase publishing Instagram API 图形 API 媒体发布 状态检查 洞察获取 两阶段发布 HTTPS 请求 AI エージェント 开发者指南 Creates containers using the `{user_id}/media` endpoint with a POST method Publishes media using the `{user_id}/media_publish` endpoint with a POST method Retrieves media status using the `{container_id}` endpoint with a GET method Gets insights using the `{media_id}/insights` endpoint with a GET method Supports two-phase publishing for video content Polls until FINISHED for video content instagram-api is a skill that provides access to Instagram''s Graph API, enabling developers to create, publish, and manage media, as well as retrieve engagement insights.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('maneeshanif/todo-spec-driven/dapr-integration', 'community', 'maneeshanif', 'todo-spec-driven', 'maneeshanif/todo-spec-driven', 'dapr-integration', 0, 0, 42, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:40.871Z', '4e955fec43534565828931d8348d50d0b839437de5fe0e18b2895aa8e2404566', '{"id":"maneeshanif/todo-spec-driven/dapr-integration","name":"dapr-integration","description":{"en":"The dapr-integration skill enables developers to integrate Dapr into their applications, providing a streamlined process for initialization, component creation, and sidecar configuration. This skill benefits developers working with Dapr and Kubernetes.","zh":"Dapr集成是一个强大的工具，用于构建分布式应用程序。它提供了一种简单的方式来管理应用程序的状态、配置和通信","ja":"Dapr統合は、分散アプリケーションを構築するための強力なツールです。状態、構成、通信の管理を簡単に行うことができます","ko":"Dapr 통합은 분산 애플리케이션을 구축하기 위한 강력한 도구입니다. 상태, 구성 및 통신 관리를 쉽게 수행할 수 있습니다","es":"Integra dapr en tus aplicaciones con facilidad. Aprende a configurar y utilizar dapr en tus proyectos de desarrollo.","fr":"Intégrez dapr dans vos applications avec facilité. Découvrez comment configurer et utiliser dapr dans vos projets de développement.","de":"Integrieren Sie dapr in Ihre Anwendungen mit Leichtigkeit. Erfahren Sie, wie Sie dapr in Ihren Entwicklungsprojekten konfigurieren und verwenden.","pt":"O Dapr é uma plataforma de aplicativos distribuídos que fornece uma camada de abstração para a comunicação entre serviços","ru":"Dapr — это платформа для распределенных приложений, которая предоставляет слой абстракции для обмена данными между сервисами","ar":"Dapr هو منصة لتطبيقات موزعة توفر طبقة من الاستخراج للاتصال بين الخدمات"},"seo":{"title":{"en":"dapr-integration: Setup Guide for AI Agents | AI Agent Skill","zh":"Dapr集成指南：快速开始和最佳实践","ja":"Dapr統合ガイド：クイックスタートとベストプラクティス","ko":"Dapr 통합 가이드: 빠른 시작과 모범 사례","es":"Guía de configuración de dapr-integration para desarrolla...","fr":"Guide d''intégration dapr pour les développeurs","de":"Dapr-Integration-Setup-Leitfaden für Entwickler","pt":"Guia de Integração Dapr: Configuração e Práticas Recomend...","ru":"ИИ Агенты: Руководство по Интеграции Dapr и Лучшие Практики","ar":"دليل تكامل Dapr: إعداد وافضل الممارسات"},"description":{"en":"Get started with dapr-integration and unlock seamless Dapr initialization, component creation, and sidecar configuration. Learn how to test locally and deplo...","zh":"学习Dapr集成的基础知识，包括初始化、组件文件创建和sidecar配置，快速开始您的Dapr项目","ja":"Dapr統合の基礎を学び、初期化、コンポーネントファイルの作成、サイドカーの設定などをマスターして、Daprプロジェクトを迅速に開始","ko":"Dapr 통합의 기본을 배우고 초기화, 구성 요소 파일 생성 및 사이드카 구성 등에 익숙해져 빠르게 Dapr 프로젝트를 시작","es":"Aprende a integrar dapr en tus proyectos con este tutorial paso a paso para desarrolladores","fr":"Découvrez comment intégrer dapr dans vos projets avec ce didacticiel étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie dapr in Ihre Projekte integrieren, mit diesem Schritt-für-Schritt-Tutorial für Entwickler","pt":"Aprenda a integrar o Dapr com o seu aplicativo, incluindo configuração, inicialização e testes locais","ru":"Изучите интеграцию Dapr с вашим приложением, включая настройку, инициализацию и локальные тесты","ar":"تعلم كيفية دمج Dapr مع تطبيقك، بما في ذلك الإعداد والت 初ية والاختبارات المحلية"},"definition":{"en":"dapr-integration is a skill that facilitates the integration of Dapr into applications, allowing for efficient initialization, component creation, and configuration.","zh":"Dapr集成是一种分布式应用程序运行时，提供了一组构建块来简化应用程序的开发和管理","ja":"Dapr統合は、分散アプリケーションのランタイムであり、開発と管理を簡素化するための構築ブロックのセットを提供します","ko":"Dapr 통합은 분산 애플리케이션 런타임으로, 개발 및 관리를 단순화하는 빌딩 블록 세트를 제공합니다","es":"Dapr-integration es una habilidad que permite a los desarrolladores integrar dapr en sus proyectos","fr":"Dapr-integration est une compétence qui permet aux développeurs d''intégrer dapr dans leurs projets","de":"Dapr-Integration ist eine Fähigkeit, die es Entwicklern ermöglicht, dapr in ihre Projekte zu integrieren","pt":"Dapr é uma plataforma de código aberto para construir aplicativos distribuídos","ru":"Dapr — это открытая платформа для построения распределенных приложений","ar":"Dapr هو منصة مفتوحة المصدر لبناء التطبيقات الموزعة"},"features":{"en":["Initializes Dapr using `dapr init` or `dapr init -k` for Kubernetes","Creates component files in the `dapr-components/` directory","Configures sidecar using annotations for Kubernetes deployments","Tests Dapr integration locally using `dapr run` commands","Checks Dapr installation version using `dapr --version`"],"zh":["支持快速开始和初始化","提供组件文件创建和管理","支持sidecar配置和注解","支持本地测试和调试","支持Kubernetes部署和管理"],"ja":["クイックスタートと初期化のサポート","コンポーネントファイルの作成と管理","サイドカーの設定と注釈のサポート","ローカルテストとデバッグのサポート","Kubernetesのデプロイと管理のサポート"],"ko":["빠른 시작 및 초기화 지원","구성 요소 파일 생성 및 관리","사이드카 구성 및 주석 지원","로컬 테스트 및 디버깅 지원","쿠버네티스 배포 및 관리 지원"],"es":["Inicialización de dapr con `dapr init`","Creación de archivos de componentes en `dapr-components/`","Configuración del sidecar con anotaciones para implementaciones de Kubernetes","Pruebas locales con comandos `dapr run`","Integración con Kubernetes mediante `dapr init -k`","Verificación de la instalación de dapr con `dapr --version`"],"fr":["Initialisation de dapr avec `dapr init`","Création de fichiers de composants dans `dapr-components/`","Configuration du sidecar avec des annotations pour les déploiements Kubernetes","Tests locaux avec des commandes `dapr run`","Intégration avec Kubernetes via `dapr init -k`","Vérification de l''installation de dapr avec `dapr --version`"],"de":["Initialisierung von dapr mit `dapr init`","Erstellung von Komponenten-Dateien in `dapr-components/`","Konfiguration des Sidecars mit Annotations für Kubernetes-Deployments","Lokale Tests mit `dapr run`-Befehlen","Integration mit Kubernetes über `dapr init -k`","Überprüfung der dapr-Installation mit `dapr --version`"],"pt":["Inicialização do Dapr com `dapr init`","Criação de arquivos de componentes em `dapr-components/`","Configuração do sidecar com anotações para implantações do Kubernetes","Testes locais com `dapr run`","Suporte à implantação em ambientes de nuvem e locais","Integração com outros serviços e aplicações"],"ru":["Инициализация Dapr с помощью `dapr init`","Создание файлов компонентов в `dapr-components/`","Настройка sidecar с помощью аннотаций для развертываний Kubernetes","Локальные тесты с помощью `dapr run`","Поддержка развертывания в облаке и локальных средах","Интеграция с другими сервисами и приложениями"],"ar":["تشغيل Dapr مع `dapr init`","إنشاء ملفات المكونات في `dapr-components/`","تكوين sidecar باستخدام التعليقات لتنصيب Kubernetes","اختبارات محلية مع `dapr run`","دعم التنصيب في بيئات السحابة والمحلية","التكامل مع خدمات وتطبيقات أخرى"]},"keywords":{"en":["how to use dapr-integration","dapr-integration setup guide","what is dapr-integration","dapr-integration vs service mesh","dapr-integration install","dapr-integration for Kubernetes","dapr-integration tutorial","dapr-integration alternative","dapr-integration documentation"],"zh":["Dapr集成","分布式应用程序","状态管理","配置管理","通信管理","Kubernetes","sidecar","AIエージェント","云原生应用程序"],"ja":["Dapr統合","分散アプリケーション","状態管理","構成管理","通信管理","Kubernetes","サイドカー","AIエージェント","クラウドネイティブアプリケーション"],"ko":["Dapr 통합","분산 애플리케이션","상태 관리","구성 관리","통신 관리","쿠버네티스","사이드카","AI 에이전트","클라우드 네이티브 애플리케이션"],"es":["dapr integration","integración de dapr","desarrollo de aplicaciones con dapr","configuración de dapr","herramientas de desarrollo dapr","dapr para desarrolladores","introducción a dapr","tutorial de dapr","guía de configuración de dapr"],"fr":["dapr integration","intégration de dapr","développement d''applications avec dapr","configuration de dapr","outils de développement dapr","dapr pour les développeurs","introduction à dapr","tutoriel de dapr","guide de configuration de dapr"],"de":["dapr integration","dapr-integration","entwicklung von anwendungen mit dapr","konfiguration von dapr","entwicklertools für dapr","dapr für entwickler","einführung in dapr","tutorial für dapr","leitfaden für die konfiguration von dapr"],"pt":["dapr","integração dapr","configuração dapr","inicialização dapr","testes locais dapr","kubernetes","sidecar","aplicativos distribuídos","desenvolvimento de software"],"ru":["dapr","интеграция dapr","настройка dapr","инициализация dapr","локальные тесты dapr","kubernetes","sidecar","распределенные приложения","разработка программного обеспечения"],"ar":["dapr","تكامل dapr","إعداد dapr","تشغيل dapr","اختبارات محلية dapr","kubernetes","sidecar","تطبيقات موزعة","تطوير البرمجيات"]}},"owner":"maneeshanif","repo":"todo-spec-driven","repoPath":"maneeshanif/todo-spec-driven","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"dapr-integration","description":"Integrate Dapr building blocks for event-driven microservices - Pub/Sub, State Management, Secrets, Service Invocation, and Jobs API. Use when implementing event-driven architecture for Phase 5. (project)","bodyPreview":"# Dapr Integration Skill\n\n## Quick Start\n\n1. **Read Phase 5 Constitution** - `constitution-prompt-phase-5.md`\n2. **Check Dapr installation** - `dapr --version`\n3. **Initialize Dapr** - `dapr init` or `dapr init -k` for Kubernetes\n4. **Create component files** - In `dapr-components/` directory\n5. **Configure sidecar** - Annotations for Kubernetes deployments\n6. **Test locally** - `dapr run` commands\n\n## Dapr Building Blocks Overview\n\n| Building Block | Purpose | Phase 5 Usage |\n|----------------|","body":"# Dapr Integration Skill\n\n## Quick Start\n\n1. **Read Phase 5 Constitution** - `constitution-prompt-phase-5.md`\n2. **Check Dapr installation** - `dapr --version`\n3. **Initialize Dapr** - `dapr init` or `dapr init -k` for Kubernetes\n4. **Create component files** - In `dapr-components/` directory\n5. **Configure sidecar** - Annotations for Kubernetes deployments\n6. **Test locally** - `dapr run` commands\n\n## Dapr Building Blocks Overview\n\n| Building Block | Purpose | Phase 5 Usage |\n|----------------|---------|---------------|\n| **Pub/Sub** | Event messaging | Task events, reminders, audit logs |\n| **State** | Key-value storage | Cache, session state |\n| **Secrets** | Secret management | API keys, DB credentials |\n| **Service Invocation** | Service-to-service calls | Microservice communication |\n| **Jobs API** | Scheduled tasks | Recurring task scheduling |\n\n## Component Configuration\n\n### Pub/Sub Component (Kafka)\n\nCreate `dapr-components/pubsub.yaml`:\n\n```yaml\napiVersion: dapr.io/v1alpha1\nkind: Component\nmetadata:\n  name: taskpubsub\n  namespace: todo-app\nspec:\n  type: pubsub.kafka\n  version: v1\n  metadata:\n    - name: brokers\n      value: \"kafka:9092\"\n    - name: consumerGroup\n      value: \"todo-consumer-group\"\n    - name: authType\n      value: \"none\"\n    - name: disableTls\n      value: \"true\"\nscopes:\n  - backend\n  - notification-service\n  - recurring-service\n  - audit-service\n```\n\n### State Store Component\n\nCreate `dapr-components/statestore.yaml`:\n\n```yaml\napiVersion: dapr.io/v1alpha1\nkind: Component\nmetadata:\n  name: statestore\n  namespace: todo-app\nspec:\n  type: state.redis\n  version: v1\n  metadata:\n    - name: redisHost\n      value: \"redis:6379\"\n    - name: redisPassword\n      value: \"\"\n    - name: actorStateStore\n      value: \"true\"\nscopes:\n  - backend\n```\n\n### Secrets Component\n\nCreate `dapr-components/secrets.yaml`:\n\n```yaml\napiVersion: dapr.io/v1alpha1\nkind: Component\nmetadata:\n  name: kubernetes-secrets\n  namespace: todo-app\nspec:\n  type: secretstores.kubernetes\n  version: v1\n  metadata: []\n```\n\n## Python SDK Integration\n\n### Installation\n\n```bash\nuv add dapr dapr-ext-fastapi\n```\n\n### Pub/Sub Publisher\n\n```python\nfrom dapr.clients import DaprClient\n\nasync def publish_task_event(event_type: str, task_data: dict):\n    \"\"\"Publish task event to Kafka via Dapr.\"\"\"\n    with DaprClient() as client:\n        client.publish_event(\n            pubsub_name=\"taskpubsub\",\n            topic_name=\"task-events\",\n            data=json.dumps({\n                \"event_type\": event_type,\n                \"task\": task_data,\n                \"timestamp\": datetime.utcnow().isoformat()\n            }),\n            data_content_type=\"application/json\"\n        )\n```\n\n### Pub/Sub Subscriber (FastAPI)\n\n```python\nfrom dapr.ext.fastapi import DaprApp\nfrom fastapi import FastAPI\n\napp = FastAPI()\ndapr_app = DaprApp(app)\n\n@dapr_app.subscribe(pubsub=\"taskpubsub\", topic=\"task-events\")\nasync def handle_task_event(event: dict):\n    \"\"\"Handle incoming task events.\"\"\"\n    event_type = event.get(\"event_type\")\n    task_data = event.get(\"task\")\n\n    if event_type == \"task.created\":\n        await process_new_task(task_data)\n    elif event_type == \"task.completed\":\n        await process_completed_task(task_data)\n```\n\n### State Management\n\n```python\nfrom dapr.clients import DaprClient\n\nasync def save_state(key: str, value: dict):\n    \"\"\"Save state to Dapr state store.\"\"\"\n    with DaprClient() as client:\n        client.save_state(\n            store_name=\"statestore\",\n            key=key,\n            value=json.dumps(value)\n        )\n\nasync def get_state(key: str) -> dict | None:\n    \"\"\"Get state from Dapr state store.\"\"\"\n    with DaprClient() as client:\n        state = client.get_state(store_name=\"statestore\", key=key)\n        return json.loads(state.data) if state.data else None\n```\n\n### Service Invocation\n\n```python\nfrom dapr.clients import DaprClient\n\nasync def invoke_notification_service(user_id: str, message: str):\n    \"\"\"Invoke notification service via Dapr.\"\"\"\n    with DaprClient() as client:\n        response = client.invoke_method(\n            app_id=\"notification-service\",\n            method_name=\"send\",\n            data=json.dumps({\n                \"user_id\": user_id,\n                \"message\": message\n            }),\n            http_verb=\"POST\"\n        )\n        return response.json()\n```\n\n### Jobs API (Scheduled Tasks)\n\n```python\nfrom dapr.clients import DaprClient\n\nasync def schedule_reminder(reminder_id: str, due_at: datetime):\n    \"\"\"Schedule a reminder using Dapr Jobs API.\"\"\"\n    with DaprClient() as client:\n        # Create a scheduled job\n        client.start_workflow(\n            workflow_component=\"dapr\",\n            workflow_name=\"reminder-workflow\",\n            input={\n                \"reminder_id\": reminder_id,\n                \"scheduled_time\": due_at.isoformat()\n            }\n        )\n```\n\n## Kubernetes Deployment Annotations\n\n```yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: backend\nspec:\n  template:\n    metadata:\n      annotations:\n        dapr.io/enabled: \"true\"\n        dapr.io/app-id: \"backend\"\n        dapr.io/app-port: \"8000\"\n        dapr.io/enable-api-logging: \"true\"\n        dapr.io/log-level: \"info\"\n        dapr.io/config: \"dapr-config\"\n    spec:\n      containers:\n        - name: backend\n          image: evolution-todo/backend:latest\n```\n\n## Local Development with Dapr\n\n### Run with Dapr Sidecar\n\n```bash\n# Run backend with Dapr\ndapr run --app-id backend \\\n         --app-port 8000 \\\n         --dapr-http-port 3500 \\\n         --components-path ./dapr-components \\\n         -- uv run uvicorn src.main:app --host 0.0.0.0 --port 8000\n\n# Run notification service with Dapr\ndapr run --app-id notification-service \\\n         --app-port 8002 \\\n         --dapr-http-port 3502 \\\n         --components-path ./dapr-components \\\n         -- uv run uvicorn services.notification.main:app --host 0.0.0.0 --port 8002\n```\n\n### Test Pub/Sub\n\n```bash\n# Publish test event\ndapr publish --publish-app-id backend \\\n             --pubsub taskpubsub \\\n             --topic task-events \\\n             --data ''{\"event_type\":\"task.created\",\"task\":{\"id\":\"123\",\"title\":\"Test\"}}''\n```\n\n## Verification Checklist\n\n- [ ] Dapr CLI installed (`dapr --version`)\n- [ ] Dapr initialized (`dapr init` or `dapr init -k`)\n- [ ] Component files created in `dapr-components/`\n- [ ] Python SDK installed (`dapr`, `dapr-ext-fastapi`)\n- [ ] Pub/Sub working (publish → subscribe)\n- [ ] State store working (save → get)\n- [ ] Service invocation working\n- [ ] Kubernetes annotations configured\n- [ ] All services have Dapr sidecars\n\n## Event Topics\n\n| Topic | Publisher | Subscribers | Purpose |\n|-------|-----------|-------------|---------|\n| `task-events` | Backend | Notification, Audit, WebSocket | Task CRUD events |\n| `reminder-events` | Recurring Service | Notification, Backend | Reminder triggers |\n| `audit-events` | All Services | Audit Service | Audit logging |\n\n## Troubleshooting\n\n| Issue | Cause | Solution |\n|-------|-------|----------|\n| Sidecar not starting | Missing annotations | Add `dapr.io/enabled: \"true\"` |\n| Pub/Sub not working | Component not loaded | Check component scope |\n| Connection refused | Wrong port | Verify `app-port` matches app |\n| State not persisting | Redis not running | Start Redis container |\n\n## References\n\n- [Dapr Documentation](https://docs.dapr.io/)\n- [Dapr Python SDK](https://github.com/dapr/python-sdk)\n- [Dapr Pub/Sub](https://docs.dapr.io/developing-applications/building-blocks/pubsub/)\n- [Dapr State Management](https://docs.dapr.io/developing-applications/building-blocks/state-management/)\n- [Phase 5 Constitution](../../../constitution-prompt-phase-5.md)\n"},"lastSynced":"2026-03-08T02:01:40.871Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Native Agents needing streamlined Dapr integration and Kubernetes deployment capabilities.","zh":"非常适合需要简化Dapr集成和Kubernetes部署能力的云原生代理。","ja":"Daprの統合とKubernetesのデプロイ能力をストリームライン化する必要があるクラウドネイティブエージェントに最適です。","ko":"Dapr 통합과 Kubernetes 배포 기능을 간소화하는 클라우드 네이티브 에이전트에 적합합니다.","es":"Perfecto para Agentes Nativos en la Nube que necesitan una integración de Dapr optimizada y capacidades de implementación de Kubernetes.","fr":"Parfait pour les agents Cloud Native nécessitant une intégration Dapr optimisée et des capacités de déploiement Kubernetes.","de":"Perfekt für Cloud-Native-Agents, die eine optimierte Dapr-Integration und Kubernetes-Bereitstellungsfunktionen benötigen.","pt":"Perfeito para agentes Cloud Native que necessitam de integração Dapr simplificada e capacidades de implantação Kubernetes.","ru":"Идеально для облачных агентов, которым необходима упрощенная интеграция Dapr и возможности развертывания Kubernetes.","ar":"مثالي لعميل الحوسبة السحابية الذي يحتاج إلى دمج Dapr المُبسط وقدرات النشر Kubernetes."},"recommendation":{"en":"Empowers agents to initialize Dapr, create component files, and configure sidecars using Kubernetes annotations and the `dapr init` command, streamlining the development process with Dapr and Kubernetes.","zh":"赋予代理初始化Dapr、创建组件文件和使用Kubernetes注释和`dapr init`命令配置sidecar的能力，简化了Dapr和Kubernetes的开发过程。","ja":"エージェントにDaprを初期化し、コンポーネントファイルを作成し、Kubernetesの注釈と`dapr init`コマンドを使用してサイドカーを構成する能力を与え、DaprとKubernetesの開発プロセスをストリームライン化します。","ko":"에이전트에 Dapr를 초기화하고, 컴포넌트 파일을 생성하고, Kubernetes 주석과 `dapr init` 명령을 사용하여 사이드카를 구성할 수 있는 능력을 부여하여 Dapr와 Kubernetes의 개발 과정을 간소화합니다.","es":"Habilita a los agentes a inicializar Dapr, crear archivos de componentes y configurar sidecars usando anotaciones de Kubernetes y el comando `dapr init`, optimizando el proceso de desarrollo con Dapr y Kubernetes.","fr":"Permet aux agents d''initialiser Dapr, de créer des fichiers de composants et de configurer des sidecars à l''aide d''annotations Kubernetes et de la commande `dapr init`, rationalisant le processus de développement avec Dapr et Kubernetes.","de":"Ermöglicht es Agenten, Dapr zu initialisieren, Komponentendateien zu erstellen und Sidecars mithilfe von Kubernetes-Anmerkungen und dem Befehl `dapr init` zu konfigurieren, wodurch der Entwicklungsprozess mit Dapr und Kubernetes optimiert wird.","pt":"Habilita os agentes a inicializar Dapr, criar arquivos de componentes e configurar sidecars usando anotações Kubernetes e o comando `dapr init`, simplificando o processo de desenvolvimento com Dapr e Kubernetes.","ru":"Позволяет агентам инициализировать Dapr, создавать файлы компонентов и настраивать sidecars с помощью аннотаций Kubernetes и команды `dapr init`, упрощая процесс разработки с Dapr и Kubernetes.","ar":"تمكين العملاء من初始化 Dapr وإنشاء ملفات المكونات وتكوين Sidecars باستخدام التعليقات Kubernetes وأمر `dapr init` ، وبذلك يُبسط عملية التطوير مع Dapr و Kubernetes."},"useCases":{"en":["Initializing Dapr for local development","Creating and configuring Dapr components for distributed applications","Deploying Dapr-enabled applications to Kubernetes clusters"],"zh":["为本地开发初始化Dapr","为分布式应用程序创建和配置Dapr组件","将Dapr启用的应用程序部署到Kubernetes集群"],"ja":["ローカル開発のためにDaprを初期化する","分散アプリケーションのためにDaprコンポーネントを作成して構成する","Daprを有効にしたアプリケーションをKubernetesクラスターにデプロイする"],"ko":["로컬 개발을 위한 Dapr 초기화","분산 애플리케이션을 위한 Dapr 컴포넌트 생성 및 구성","Dapr를 활성화한 애플리케이션을 Kubernetes 클러스터에 배포"],"es":["Inicializar Dapr para el desarrollo local","Crear y configurar componentes de Dapr para aplicaciones distribuidas","Implementar aplicaciones habilitadas para Dapr en clusters de Kubernetes"],"fr":["Initialiser Dapr pour le développement local","Créer et configurer des composants Dapr pour des applications distribuées","Déployer des applications Dapr activées sur des clusters Kubernetes"],"de":["Dapr für die lokale Entwicklung initialisieren","Dapr-Komponenten für verteilte Anwendungen erstellen und konfigurieren","Dapr-aktivierte Anwendungen in Kubernetes-Clustern bereitstellen"],"pt":["Inicializar Dapr para desenvolvimento local","Criar e configurar componentes Dapr para aplicações distribuídas","Implantar aplicações habilitadas para Dapr em clusters Kubernetes"],"ru":["Инициализировать Dapr для локальной разработки","Создать и настроить компоненты Dapr для распределенных приложений","Развернуть приложения с поддержкой Dapr в кластерах Kubernetes"],"ar":["ت 初始化 Dapr للتطوير المحلي","إنشاء وتكوين مكونات Dapr للتطبيقات الموزعة","نشر التطبيقات التي تعمل مع Dapr على مجموعات Kubernetes"]},"limitations":{"en":["Requires Dapr installation","Kubernetes environment needed for full functionality"],"zh":["需要Dapr安装","需要Kubernetes环境以实现全部功能"],"ja":["Daprのインストールが必要","完全な機能を実現するためにKubernetes環境が必要"],"ko":["Dapr 설치가 필요","전체 기능을 구현하기 위해 Kubernetes 환경이 필요"],"es":["Requiere la instalación de Dapr","Se necesita un entorno de Kubernetes para la funcionalidad completa"],"fr":["Nécessite l''installation de Dapr","Un environnement Kubernetes est nécessaire pour une fonctionnalité complète"],"de":["Benötigt die Installation von Dapr","Ein Kubernetes-Umgebung ist für die volle Funktionalität erforderlich"],"pt":["Requer instalação Dapr","Ambiente Kubernetes necessário para funcionalidade completa"],"ru":["Требуется установка Dapr","Среда Kubernetes необходима для полной функциональности"],"ar":["يتطلب تثبيت Dapr","بيئة Kubernetes مطلوبة للوظائف الكاملة"]},"version":4},"contentHash":"4e955fec43534565828931d8348d50d0b839437de5fe0e18b2895aa8e2404566","qualityScore":42}');
