INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maneeshanif/todo-spec-driven/dapr-integration', 'dapr-integration', 'maneeshanif', 'todo-spec-driven', 'community', 'dapr-integration maneeshanif todo-spec-driven community The dapr-integration skill enables developers to integrate Dapr into their applications, providing a streamlined process for initialization, component creation, and sidecar configuration. This skill benefits developers working with Dapr and Kubernetes. Dapr集成是一个强大的工具，用于构建分布式应用程序。它提供了一种简单的方式来管理应用程序的状态、配置和通信 Dapr統合は、分散アプリケーションを構築するための強力なツールです。状態、構成、通信の管理を簡単に行うことができます Dapr 통합은 분산 애플리케이션을 구축하기 위한 강력한 도구입니다. 상태, 구성 및 통신 관리를 쉽게 수행할 수 있습니다 Integra dapr en tus aplicaciones con facilidad. Aprende a configurar y utilizar dapr en tus proyectos de desarrollo. Intégrez dapr dans vos applications avec facilité. Découvrez comment configurer et utiliser dapr dans vos projets de développement. Integrieren Sie dapr in Ihre Anwendungen mit Leichtigkeit. Erfahren Sie, wie Sie dapr in Ihren Entwicklungsprojekten konfigurieren und verwenden. O Dapr é uma plataforma de aplicativos distribuídos que fornece uma camada de abstração para a comunicação entre serviços Dapr — это платформа для распределенных приложений, которая предоставляет слой абстракции для обмена данными между сервисами Dapr هو منصة لتطبيقات موزعة توفر طبقة من الاستخراج للاتصال بين الخدمات how to use dapr-integration dapr-integration setup guide what is dapr-integration dapr-integration vs service mesh dapr-integration install dapr-integration for Kubernetes dapr-integration tutorial dapr-integration alternative dapr-integration documentation Dapr集成 分布式应用程序 状态管理 配置管理 通信管理 Kubernetes sidecar AIエージェント 云原生应用程序 Initializes Dapr using `dapr init` or `dapr init -k` for Kubernetes Creates component files in the `dapr-components/` directory Configures sidecar using annotations for Kubernetes deployments Tests Dapr integration locally using `dapr run` commands Checks Dapr installation version using `dapr --version` dapr-integration is a skill that facilitates the integration of Dapr into applications, allowing for efficient initialization, component creation, and configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Deefunxion/pixel-flick-frenzy/game-development', 'community', 'Deefunxion', 'pixel-flick-frenzy', 'Deefunxion/pixel-flick-frenzy', 'game-development', 0, 0, 42, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:41.165Z', '419ea562dd8cfed0612d9a1dc8ad8ab821785e531b75b4e92c0599caf57c2c7f', '{"id":"Deefunxion/pixel-flick-frenzy/game-development","name":"game-development","description":{"en":"The game-development skill provides a comprehensive guide for building games across major engines and platforms, benefiting developers and indie game creators.","zh":"游戏开发综合指南，涵盖 Unity、Unreal 和 Godot 引擎的项目结构和脚本语言","ja":"ゲーム開発の総合ガイド - Unity、Unreal、Godot エンジンのプロジェクト構造とスクリプト言語","ko":"게임 개발을 위한 전체 가이드 - 유니티, 언리얼, 고도트 엔진의 프로젝트 구조 및 스크립트 언어","es":"Desarrolla juegos con Unity, Unreal y Godot. Guía técnica para principiantes y expertos.","fr":"Développez des jeux avec Unity, Unreal et Godot. Guide technique pour débutants et experts.","de":"Entwickeln Sie Spiele mit Unity, Unreal und Godot. Technischer Leitfaden für Anfänger und Experten.","pt":"Desenvolva jogos com Unity, Unreal e Godot, e aprenda a criar experiências de jogo imersivas","ru":"Разрабатывайте игры с помощью Unity, Unreal и Godot, и создавайте иммерсивные игровые trải nghiệm с помощью ИИ Агентов","ar":"برمج الألعاب باستخدام Unity و Unreal و Godot، وإنشاء تجارب اللعبة الغامرة مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Game Development: Comprehensive Setup Guide | AI Agent Skill","zh":"游戏开发设置指南 - Unity、Unreal 和 Godot","ja":"ゲーム開発ベストプラクティス - Unity、Unreal、Godot","ko":"게임 개발 가이드 - Unity, Unreal, Godot","es":"Guía de configuración para el desarrollo de juegos con Un...","fr":"Guide de mise en place pour le développement de jeux avec...","de":"Einrichtungsleitfaden für die Spieleentwicklung mit Unity...","pt":"Guia de Configuração de Desenvolvimento de Jogos","ru":"Настройка ИИ Агентов для Разработки Игр","ar":"دليل إعداد أدوات الذكاء الاصطناعي للبرمجة اللعبة"},"description":{"en":"Unlock game development potential with our AI agent skill, featuring Unity, Unreal, and Godot engine support - get started now!","zh":"了解游戏开发的技术细节，包括 Unity、Unreal 和 Godot 引擎的比较，项目结构和脚本语言","ja":"ゲーム開発のテクニカルな詳細を学ぶ - エンジンの比較、プロジェクト構造、スクリプト言語","ko":"게임 개발에 대한 기술 정보 - 유니티, 언리얼, 고도트 엔진 비교, 프로젝트 구조 및 스크립트 언어","es":"Aprende a desarrollar juegos con los principales motores y plataformas. Comparación de Unity, Unreal y Godot.","fr":"Apprenez à développer des jeux avec les principaux moteurs et plateformes. Comparaison de Unity, Unreal et Godot.","de":"Erfahren Sie, wie Sie Spiele mit den wichtigsten Spiel-Engines und Plattformen entwickeln. Vergleich von Unity, Unreal und Godot.","pt":"Aprenda a desenvolver jogos com Unity, Unreal e Godot, e descubra as melhores práticas para criar experiências de jogo imersivas","ru":"Узнайте, как разрабатывать игры с помощью Unity, Unreal и Godot, и откройте для себя лучшие практики для создания иммерсивных игровых trải nghiệm с помощью И...","ar":"تعلم كيفية برمجة الألعاب باستخدام Unity و Unreal و Godot، واكتشف أفضل الممارسات لإنشاء تجارب اللعبة الغامرة مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Game-development is a comprehensive process for creating games across Unity, Unreal, and Godot engines, supporting various platforms and languages.","zh":"游戏开发是指使用 Unity、Unreal 或 Godot 等游戏引擎创建游戏的过程","ja":"ゲーム開発とは、Unity、Unreal、Godot などのゲームエンジンを使用してゲームを作成するプロセス","ko":"게임 개발은 유니티, 언리얼, 고도트 등의 게임 엔진을 사용하여 게임을 만드는 과정","es":"El desarrollo de juegos es el proceso de creación de juegos electrónicos con herramientas como Unity y Unreal.","fr":"Le développement de jeux est le processus de création de jeux électroniques avec des outils tels que Unity et Unreal.","de":"Die Spieleentwicklung ist der Prozess der Erstellung von elektronischen Spielen mit Tools wie Unity und Unreal.","pt":"Desenvolvimento de jogos é o processo de criar jogos eletrônicos com tecnologias como Unity, Unreal e Godot","ru":"Разработка игр - это процесс создания электронных игр с помощью технологий như Unity, Unreal и Godot с использованием ИИ Агентов","ar":"برمجة الألعاب هي عملية إنشاء ألعاب إلكترونية باستخدام teknolojies مثل Unity و Unreal و Godot مع أدوات الذكاء الاصطناعي"},"features":{"en":["Supports Unity engine with C# scripting","Unreal engine integration with C++ and Blueprints","Godot engine development with GDScript and C#","Project structure organization with Assets and Scripts folders","Cross-platform support for mobile, PC, and VR/AR devices"],"zh":["支持 Unity、Unreal 和 Godot 引擎","使用 C#、C++ 和 GDScript 等脚本语言","适用于移动、独立、VR/AR 和 AAA 游戏开发","支持所有主要平台","提供项目结构和脚本语言的比较"],"ja":["Unity、Unreal、Godot エンジンのサポート","C#、C++、GDScript などのスクリプト言語の使用","モバイル、インディー、VR/AR、AAA ゲーム開発のサポート","すべての主要プラットフォームのサポート","プロジェクト構造とスクリプト言語の比較"],"ko":["유니티, 언리얼, 고도트 엔진 지원","C#、C++、GDScript 등의 스크립트 언어 사용","모바일, 인디, VR/AR, AAA 게임 개발 지원","모든 주요 플랫폼 지원","프로젝트 구조와 스크립트 언어 비교"],"es":["Compatibilidad con Unity y Unreal","Soporte para plataformas móviles y de escritorio","Uso de C#, C++ y GDScript","Creación de juegos 2D y 3D","Integración con VR/AR"],"fr":["Compatibilité avec Unity et Unreal","Prise en charge des plateformes mobiles et de bureau","Utilisation de C#, C++ et GDScript","Création de jeux 2D et 3D","Intégration avec la réalité virtuelle et augmentée"],"de":["Kompatibilität mit Unity und Unreal","Unterstützung für mobile und Desktop-Plattformen","Verwendung von C#, C++ und GDScript","Erstellung von 2D- und 3D-Spielen","Integration mit VR/AR"],"pt":["Suporte a Unity, Unreal e Godot","Criação de experiências de jogo imersivas","Desenvolvimento de jogos 2D e 3D","Uso de C#, C++ e GDScript","Compatibilidade com plataformas móveis e desktop"],"ru":["Поддержка Unity, Unreal и Godot","Создание иммерсивных игровых trải nghiệm","Разработка 2D и 3D игр","Использование C#, C++ и GDScript","Совместимость с мобильными и настольными платформами с помощью ИИ Агентов"],"ar":["دعم Unity و Unreal و Godot","إنشاء تجارب اللعبة الغامرة","برمجة الألعاب 2D و 3D","استخدام C# و C++ و GDScript","التوافق مع منصات الموبايل و سطح المكتب مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use game development","game development setup guide","unity vs unreal game engine","godot game development tutorial","game development with c#","game development install guide","what is game development","game development alternative","game development best practices"],"zh":["游戏开发","Unity","Unreal","Godot","游戏引擎","脚本语言","项目结构","游戏开发教程","游戏开发工具"],"ja":["ゲーム開発","Unity","Unreal","Godot","ゲームエンジン","スクリプト言語","プロジェクト構造","ゲーム開発チュートリアル","ゲーム開発ツール"],"ko":["게임 개발","유니티","언리얼","고도트","게임 엔진","스크립트 언어","프로젝트 구조","게임 개발 튜토리얼","게임 개발 도구"],"es":["desarrollo de juegos","Unity","Unreal","Godot","C#","C++","GDScript","juegos electrónicos","creación de juegos"],"fr":["développement de jeux","Unity","Unreal","Godot","C#","C++","GDScript","jeux électroniques","création de jeux"],"de":["Spieleentwicklung","Unity","Unreal","Godot","C#","C++","GDScript","elektronische Spiele","Erstellung von Spielen"],"pt":["desenvolvimento de jogos","Unity","Unreal","Godot","C#","C++","GDScript","jogos 2D","jogos 3D","experiências de jogo imersivas"],"ru":["разработка игр","Unity","Unreal","Godot","C#","C++","GDScript","2D игры","3D игры","иммерсивные игровые trải nghiệm","ИИ Агенты"],"ar":["برمجة الألعاب","Unity","Unreal","Godot","C#","C++","GDScript","ألعاب 2D","ألعاب 3D","تجارب اللعبة الغامرة","أدوات الذكاء الاصطناعي"]}},"owner":"Deefunxion","repo":"pixel-flick-frenzy","repoPath":"Deefunxion/pixel-flick-frenzy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"game-development","description":"Game development with Unity, Unreal Engine, and Godot. Use when building games, implementing game mechanics, physics, AI, or working with game engines.","bodyPreview":"# Game Development\n\nComprehensive guide for building games across major engines and platforms.\n\n## Engine Comparison\n\n| Engine | Language | Best For | Platforms |\n|--------|----------|----------|-----------|\n| **Unity** | C# | Mobile, indie, VR/AR | All |\n| **Unreal** | C++, Blueprints | AAA, realistic graphics | All |\n| **Godot** | GDScript, C# | 2D, indie, open source | All |\n\n---\n\n## Unity (C#)\n\n### Project Structure\n\n```\nAssets/\n├── Scripts/\n│   ├── Player/\n│   │   ├── PlayerController.cs\n│","body":"# Game Development\n\nComprehensive guide for building games across major engines and platforms.\n\n## Engine Comparison\n\n| Engine | Language | Best For | Platforms |\n|--------|----------|----------|-----------|\n| **Unity** | C# | Mobile, indie, VR/AR | All |\n| **Unreal** | C++, Blueprints | AAA, realistic graphics | All |\n| **Godot** | GDScript, C# | 2D, indie, open source | All |\n\n---\n\n## Unity (C#)\n\n### Project Structure\n\n```\nAssets/\n├── Scripts/\n│   ├── Player/\n│   │   ├── PlayerController.cs\n│   │   └── PlayerInput.cs\n│   ├── Enemies/\n│   ├── Systems/\n│   └── Utils/\n├── Prefabs/\n├── Scenes/\n├── Materials/\n├── Animations/\n└── Resources/\n```\n\n### Player Controller\n\n```csharp\nusing UnityEngine;\nusing UnityEngine.InputSystem;\n\n[RequireComponent(typeof(CharacterController))]\npublic class PlayerController : MonoBehaviour\n{\n    [Header(\"Movement\")]\n    [SerializeField] private float moveSpeed = 5f;\n    [SerializeField] private float sprintMultiplier = 1.5f;\n    [SerializeField] private float jumpHeight = 2f;\n    [SerializeField] private float gravity = -9.81f;\n\n    [Header(\"Look\")]\n    [SerializeField] private float lookSensitivity = 2f;\n    [SerializeField] private float maxLookAngle = 80f;\n\n    private CharacterController _controller;\n    private Vector2 _moveInput;\n    private Vector2 _lookInput;\n    private Vector3 _velocity;\n    private float _xRotation;\n    private bool _isSprinting;\n\n    private void Awake()\n    {\n        _controller = GetComponent<CharacterController>();\n        Cursor.lockState = CursorLockMode.Locked;\n    }\n\n    private void Update()\n    {\n        HandleMovement();\n        HandleLook();\n        ApplyGravity();\n    }\n\n    private void HandleMovement()\n    {\n        float speed = _isSprinting ? moveSpeed * sprintMultiplier : moveSpeed;\n        Vector3 move = transform.right * _moveInput.x + transform.forward * _moveInput.y;\n        _controller.Move(move * speed * Time.deltaTime);\n    }\n\n    private void HandleLook()\n    {\n        float mouseX = _lookInput.x * lookSensitivity * Time.deltaTime;\n        float mouseY = _lookInput.y * lookSensitivity * Time.deltaTime;\n\n        _xRotation -= mouseY;\n        _xRotation = Mathf.Clamp(_xRotation, -maxLookAngle, maxLookAngle);\n\n        Camera.main.transform.localRotation = Quaternion.Euler(_xRotation, 0f, 0f);\n        transform.Rotate(Vector3.up * mouseX);\n    }\n\n    private void ApplyGravity()\n    {\n        if (_controller.isGrounded && _velocity.y < 0)\n        {\n            _velocity.y = -2f;\n        }\n\n        _velocity.y += gravity * Time.deltaTime;\n        _controller.Move(_velocity * Time.deltaTime);\n    }\n\n    // Input System callbacks\n    public void OnMove(InputAction.CallbackContext context) =>\n        _moveInput = context.ReadValue<Vector2>();\n\n    public void OnLook(InputAction.CallbackContext context) =>\n        _lookInput = context.ReadValue<Vector2>();\n\n    public void OnJump(InputAction.CallbackContext context)\n    {\n        if (context.performed && _controller.isGrounded)\n        {\n            _velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);\n        }\n    }\n\n    public void OnSprint(InputAction.CallbackContext context) =>\n        _isSprinting = context.performed;\n}\n```\n\n### State Machine\n\n```csharp\npublic interface IState\n{\n    void Enter();\n    void Update();\n    void Exit();\n}\n\npublic class StateMachine\n{\n    private IState _currentState;\n\n    public void ChangeState(IState newState)\n    {\n        _currentState?.Exit();\n        _currentState = newState;\n        _currentState.Enter();\n    }\n\n    public void Update() => _currentState?.Update();\n}\n\n// Example: Enemy AI States\npublic class IdleState : IState\n{\n    private readonly EnemyAI _enemy;\n\n    public IdleState(EnemyAI enemy) => _enemy = enemy;\n\n    public void Enter() => _enemy.Animator.SetTrigger(\"Idle\");\n\n    public void Update()\n    {\n        if (_enemy.CanSeePlayer())\n        {\n            _enemy.StateMachine.ChangeState(new ChaseState(_enemy));\n        }\n    }\n\n    public void Exit() { }\n}\n\npublic class ChaseState : IState\n{\n    private readonly EnemyAI _enemy;\n\n    public ChaseState(EnemyAI enemy) => _enemy = enemy;\n\n    public void Enter() => _enemy.Animator.SetTrigger(\"Run\");\n\n    public void Update()\n    {\n        _enemy.NavAgent.SetDestination(_enemy.Player.position);\n\n        if (_enemy.InAttackRange())\n        {\n            _enemy.StateMachine.ChangeState(new AttackState(_enemy));\n        }\n        else if (!_enemy.CanSeePlayer())\n        {\n            _enemy.StateMachine.ChangeState(new IdleState(_enemy));\n        }\n    }\n\n    public void Exit() { }\n}\n```\n\n### Object Pooling\n\n```csharp\npublic class ObjectPool<T> where T : Component\n{\n    private readonly T _prefab;\n    private readonly Transform _parent;\n    private readonly Queue<T> _pool = new();\n\n    public ObjectPool(T prefab, int initialSize, Transform parent = null)\n    {\n        _prefab = prefab;\n        _parent = parent;\n\n        for (int i = 0; i < initialSize; i++)\n        {\n            CreateInstance();\n        }\n    }\n\n    public T Get()\n    {\n        if (_pool.Count == 0) CreateInstance();\n\n        T obj = _pool.Dequeue();\n        obj.gameObject.SetActive(true);\n        return obj;\n    }\n\n    public void Return(T obj)\n    {\n        obj.gameObject.SetActive(false);\n        _pool.Enqueue(obj);\n    }\n\n    private void CreateInstance()\n    {\n        T obj = Object.Instantiate(_prefab, _parent);\n        obj.gameObject.SetActive(false);\n        _pool.Enqueue(obj);\n    }\n}\n```\n\n---\n\n## Unreal Engine (C++)\n\n### Actor Component\n\n```cpp\n// PlayerMovementComponent.h\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"PlayerMovementComponent.generated.h\"\n\nUCLASS(ClassGroup=(Custom), meta=(BlueprintSpawnableComponent))\nclass MYGAME_API UPlayerMovementComponent : public UActorComponent\n{\n    GENERATED_BODY()\n\npublic:\n    UPlayerMovementComponent();\n\n    virtual void TickComponent(float DeltaTime, ELevelTick TickType,\n        FActorComponentTickFunction* ThisTickFunction) override;\n\n    UFUNCTION(BlueprintCallable, Category = \"Movement\")\n    void Move(FVector2D Input);\n\n    UFUNCTION(BlueprintCallable, Category = \"Movement\")\n    void Jump();\n\nprotected:\n    virtual void BeginPlay() override;\n\nprivate:\n    UPROPERTY(EditAnywhere, Category = \"Movement\")\n    float MoveSpeed = 600.0f;\n\n    UPROPERTY(EditAnywhere, Category = \"Movement\")\n    float JumpForce = 400.0f;\n\n    UPROPERTY()\n    class UCharacterMovementComponent* MovementComponent;\n};\n\n// PlayerMovementComponent.cpp\n#include \"PlayerMovementComponent.h\"\n#include \"GameFramework/CharacterMovementComponent.h\"\n\nUPlayerMovementComponent::UPlayerMovementComponent()\n{\n    PrimaryComponentTick.bCanEverTick = true;\n}\n\nvoid UPlayerMovementComponent::BeginPlay()\n{\n    Super::BeginPlay();\n\n    if (ACharacter* Owner = Cast<ACharacter>(GetOwner()))\n    {\n        MovementComponent = Owner->GetCharacterMovement();\n    }\n}\n\nvoid UPlayerMovementComponent::Move(FVector2D Input)\n{\n    if (!MovementComponent) return;\n\n    FVector Forward = GetOwner()->GetActorForwardVector();\n    FVector Right = GetOwner()->GetActorRightVector();\n\n    FVector Direction = (Forward * Input.Y + Right * Input.X).GetSafeNormal();\n    MovementComponent->AddInputVector(Direction * MoveSpeed);\n}\n\nvoid UPlayerMovementComponent::Jump()\n{\n    if (ACharacter* Character = Cast<ACharacter>(GetOwner()))\n    {\n        Character->Jump();\n    }\n}\n```\n\n### Gameplay Ability System (GAS)\n\n```cpp\n// MyGameplayAbility.h\n#pragma once\n\n#include \"Abilities/GameplayAbility.h\"\n#include \"MyGameplayAbility.generated.h\"\n\nUCLASS()\nclass MYGAME_API UMyGameplayAbility : public UGameplayAbility\n{\n    GENERATED_BODY()\n\npublic:\n    UMyGameplayAbility();\n\n    virtual void ActivateAbility(const FGameplayAbilitySpecHandle Handle,\n        const FGameplayAbilityActorInfo* ActorInfo,\n        const FGameplayAbilityActivationInfo ActivationInfo,\n        const FGameplayEventData* TriggerEventData) override;\n\n    virtual void EndAbility(const FGameplayAbilitySpecHandle Handle,\n        const FGameplayAbilityActorInfo* ActorInfo,\n        const FGameplayAbilityActivationInfo ActivationInfo,\n        bool bReplicateEndAbility, bool bWasCancelled) override;\n\nprotected:\n    UPROPERTY(EditDefaultsOnly, Category = \"Ability\")\n    float Damage = 50.0f;\n\n    UPROPERTY(EditDefaultsOnly, Category = \"Ability\")\n    TSubclassOf<UGameplayEffect> DamageEffect;\n};\n```\n\n---\n\n## Godot (GDScript)\n\n### Player Controller\n\n```gdscript\nextends CharacterBody3D\n\n@export var move_speed: float = 5.0\n@export var jump_velocity: float = 4.5\n@export var mouse_sensitivity: float = 0.002\n\nvar gravity: float = ProjectSettings.get_setting(\"physics/3d/default_gravity\")\n\n@onready var camera: Camera3D = $Camera3D\n\nfunc _ready() -> void:\n    Input.mouse_mode = Input.MOUSE_MODE_CAPTURED\n\nfunc _input(event: InputEvent) -> void:\n    if event is InputEventMouseMotion:\n        rotate_y(-event.relative.x * mouse_sensitivity)\n        camera.rotate_x(-event.relative.y * mouse_sensitivity)\n        camera.rotation.x = clamp(camera.rotation.x, -PI/2, PI/2)\n\nfunc _physics_process(delta: float) -> void:\n    # Gravity\n    if not is_on_floor():\n        velocity.y -= gravity * delta\n\n    # Jump\n    if Input.is_action_just_pressed(\"jump\") and is_on_floor():\n        velocity.y = jump_velocity\n\n    # Movement\n    var input_dir := Input.get_vector(\"move_left\", \"move_right\", \"move_forward\", \"move_back\")\n    var direction := (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()\n\n    if direction:\n        velocity.x = direction.x * move_speed\n        velocity.z = direction.z * move_speed\n    else:\n        velocity.x = move_toward(velocity.x, 0, move_speed)\n        velocity.z = move_toward(velocity.z, 0, move_speed)\n\n    move_and_slide()\n```\n\n### State Machine (GDScript)\n\n```gdscript\n# state_machine.gd\nclass_name StateMachine\nextends Node\n\n@export var initial_state: State\n\nvar current_state: State\nvar states: Dictionary = {}\n\nfunc _ready() -> void:\n    for child in get_children():\n        if child is State:\n            states[child.name.to_lower()] = child\n            child.transitioned.connect(_on_child_transitioned)\n\n    if initial_state:\n        initial_state.enter()\n        current_state = initial_state\n\nfunc _process(delta: float) -> void:\n    if current_state:\n        current_state.update(delta)\n\nfunc _physics_process(delta: float) -> void:\n    if current_state:\n        current_state.physics_update(delta)\n\nfunc _on_child_transitioned(state: State, new_state_name: String) -> void:\n    if state != current_state:\n        return\n\n    var new_state: State = states.get(new_state_name.to_lower())\n    if not new_state:\n        return\n\n    current_state.exit()\n    new_state.enter()\n    current_state = new_state\n\n# state.gd\nclass_name State\nextends Node\n\nsignal transitioned(state: State, new_state_name: String)\n\nfunc enter() -> void:\n    pass\n\nfunc exit() -> void:\n    pass\n\nfunc update(_delta: float) -> void:\n    pass\n\nfunc physics_update(_delta: float) -> void:\n    pass\n```\n\n---\n\n## Game Patterns\n\n### Entity Component System (ECS)\n\n```csharp\n// Unity DOTS example\nusing Unity.Entities;\nusing Unity.Mathematics;\nusing Unity.Transforms;\n\npublic struct MoveSpeed : IComponentData\n{\n    public float Value;\n}\n\npublic partial class MovementSystem : SystemBase\n{\n    protected override void OnUpdate()\n    {\n        float deltaTime = SystemAPI.Time.DeltaTime;\n\n        Entities.ForEach((ref LocalTransform transform, in MoveSpeed speed) =>\n        {\n            transform.Position += new float3(0, 0, speed.Value * deltaTime);\n        }).ScheduleParallel();\n    }\n}\n```\n\n### Event System\n\n```csharp\npublic static class GameEvents\n{\n    public static event Action<int> OnScoreChanged;\n    public static event Action<float> OnHealthChanged;\n    public static event Action OnGameOver;\n\n    public static void ScoreChanged(int newScore) => OnScoreChanged?.Invoke(newScore);\n    public static void HealthChanged(float newHealth) => OnHealthChanged?.Invoke(newHealth);\n    public static void GameOver() => OnGameOver?.Invoke();\n}\n\n// Usage\npublic class UIManager : MonoBehaviour\n{\n    private void OnEnable()\n    {\n        GameEvents.OnScoreChanged += UpdateScoreUI;\n        GameEvents.OnHealthChanged += UpdateHealthUI;\n    }\n\n    private void OnDisable()\n    {\n        GameEvents.OnScoreChanged -= UpdateScoreUI;\n        GameEvents.OnHealthChanged -= UpdateHealthUI;\n    }\n}\n```\n\n### Save System\n\n```csharp\n[Serializable]\npublic class SaveData\n{\n    public int Level;\n    public float PlayTime;\n    public Vector3Serializable PlayerPosition;\n    public List<string> UnlockedAchievements;\n}\n\npublic static class SaveSystem\n{\n    private static readonly string SavePath =\n        Path.Combine(Application.persistentDataPath, \"save.json\");\n\n    public static void Save(SaveData data)\n    {\n        string json = JsonUtility.ToJson(data, true);\n        File.WriteAllText(SavePath, json);\n    }\n\n    public static SaveData Load()\n    {\n        if (!File.Exists(SavePath)) return new SaveData();\n\n        string json = File.ReadAllText(SavePath);\n        return JsonUtility.FromJson<SaveData>(json);\n    }\n}\n```\n\n---\n\n## Performance Optimization\n\n### LOD (Level of Detail)\n\n```csharp\n// Unity LOD Group setup\n[RequireComponent(typeof(LODGroup))]\npublic class LODSetup : MonoBehaviour\n{\n    public Renderer[] lodRenderers;\n    public float[] screenRelativeTransitions = { 0.5f, 0.2f, 0.01f };\n\n    void Start()\n    {\n        LODGroup lodGroup = GetComponent<LODGroup>();\n        LOD[] lods = new LOD[lodRenderers.Length];\n\n        for (int i = 0; i < lodRenderers.Length; i++)\n        {\n            lods[i] = new LOD(screenRelativeTransitions[i], new[] { lodRenderers[i] });\n        }\n\n        lodGroup.SetLODs(lods);\n        lodGroup.RecalculateBounds();\n    }\n}\n```\n\n### Spatial Partitioning\n\n```csharp\npublic class QuadTree<T> where T : class\n{\n    private readonly int _maxObjects = 10;\n    private readonly int _maxLevels = 5;\n    private readonly int _level;\n    private readonly List<(Rect bounds, T obj)> _objects = new();\n    private readonly Rect _bounds;\n    private QuadTree<T>[] _nodes;\n\n    public QuadTree(int level, Rect bounds)\n    {\n        _level = level;\n        _bounds = bounds;\n    }\n\n    public void Insert(Rect objBounds, T obj)\n    {\n        if (_nodes != null)\n        {\n            int index = GetIndex(objBounds);\n            if (index != -1)\n            {\n                _nodes[index].Insert(objBounds, obj);\n                return;\n            }\n        }\n\n        _objects.Add((objBounds, obj));\n\n        if (_objects.Count > _maxObjects && _level < _maxLevels)\n        {\n            if (_nodes == null) Split();\n\n            int i = 0;\n            while (i < _objects.Count)\n            {\n                int index = GetIndex(_objects[i].bounds);\n                if (index != -1)\n                {\n                    var item = _objects[i];\n                    _objects.RemoveAt(i);\n                    _nodes[index].Insert(item.bounds, item.obj);\n                }\n                else i++;\n            }\n        }\n    }\n\n    public List<T> Retrieve(Rect area)\n    {\n        List<T> result = new();\n        RetrieveAll(area, result);\n        return result;\n    }\n}\n```\n\n---\n\n## Checklist\n\n### Pre-Production\n- [ ] Game Design Document (GDD)\n- [ ] Technical Design Document\n- [ ] Art style guide\n- [ ] Target platforms defined\n- [ ] Performance budgets set\n\n### Development\n- [ ] Version control setup\n- [ ] CI/CD for builds\n- [ ] Automated testing\n- [ ] Performance profiling regular\n- [ ] Memory leak checks\n\n### Release\n- [ ] Platform certification requirements\n- [ ] Localization complete\n- [ ] Accessibility options\n- [ ] Analytics integration\n- [ ] Crash reporting\n"},"lastSynced":"2026-03-08T02:01:41.165Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing cross-platform game building capabilities with Unity, Unreal, and Godot engines.","zh":"适合需要使用Unity、Unreal和Godot引擎进行跨平台游戏构建的游戏开发代理。","ja":"Unity、Unreal、Godotエンジンを使用したクロスプラットフォームゲームビルディング機能を持つゲーム開発エージェントに最適です。","ko":"Unity, Unreal, Godot 엔진을 사용한 크로스 플랫폼 게임 빌딩 기능을 필요로 하는 게임 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de juegos que necesitan capacidades de creación de juegos multiplataforma con Unity, Unreal y Godot.","fr":"Parfait pour les agents de développement de jeux nécessitant des capacités de création de jeux multiplateformes avec Unity, Unreal et Godot.","de":"Perfekt für Game-Development-Agents, die cross-plattformale Spielentwicklungsfähigkeiten mit Unity, Unreal und Godot Engines benötigen.","pt":"Perfeito para agentes de desenvolvimento de jogos que precisam de capacidades de construção de jogos cross-platform com Unity, Unreal e Godot engines.","ru":"Идеально для агентов разработки игр, которым необходимы возможности создания кроссплатформенных игр с Unity, Unreal и Godot engines.","ar":"مثالي لعميل تطوير الألعاب الذي يحتاج إلى قدرات إنشاء ألعاب متعددة المنصات مع محركات Unity و Unreal و Godot."},"recommendation":{"en":"Empowers agents to create immersive gaming experiences using C#, C++, and GDScript languages, deploying on multiple platforms including mobile, PC, and VR/AR devices, leveraging engine-specific features like Unity''s 2D and 3D rendering and Unreal''s realistic graphics capabilities.","zh":"赋予代理创建使用C#、C++和GDScript语言的沉浸式游戏体验的能力，部署在包括移动设备、PC和VR/AR设备在内的多个平台上，利用引擎特定的功能，如Unity的2D和3D渲染和Unreal的真实图形功能。","ja":"C#、C++、GDScript言語を使用した没入型ゲーム体験をエージェントが作成できるようにし、モバイル、PC、VR/ARデバイスなど複数のプラットフォームに展開し、Unityの2D/3DレンダリングやUnrealのリアルなグラフィックス機能などのエンジン固有の機能を利用します。","ko":"C#、C++ 및 GDScript 언어를 사용하여 몰입형 게임 경험을 생성할 수 있는 에이전트의 능력을 부여하며, 모바일, PC 및 VR/AR 디바이스를 포함한 여러 플랫폼에 배포하고, Unity의 2D 및 3D 렌더링 및 Unreal의 현실적인 그래픽 기능과 같은 엔진 특정 기능을 활용합니다.","es":"Habilita a los agentes a crear experiencias de juego inmersivas utilizando los lenguajes C#, C++ y GDScript, implementándolos en múltiples plataformas, incluidos dispositivos móviles, PC y VR/AR, aprovechando características específicas del motor como la renderización 2D y 3D de Unity y las capacidades gráficas realistas de Unreal.","fr":"Permet aux agents de créer des expériences de jeu immersives en utilisant les langages C#, C++ et GDScript, en les déployant sur plusieurs plateformes, y compris les appareils mobiles, PC et VR/AR, en exploitant les fonctionnalités spécifiques du moteur comme le rendu 2D et 3D d''Unity et les capacités graphiques réalistes d''Unreal.","de":"Ermächtigt Agenten, immersive Gaming-Erfahrungen mit den Sprachen C#, C++ und GDScript zu erstellen, auf mehreren Plattformen bereitzustellen, einschließlich mobiler Geräte, PC und VR/AR-Geräten, indem sie motor-spezifische Funktionen wie Unitys 2D- und 3D-Rendering und Unreals realistische Grafikfähigkeiten nutzen.","pt":"Habilita os agentes a criar experiências de jogos imersivas usando as linguagens C#, C++ e GDScript, implantando em múltiplas plataformas, incluindo dispositivos móveis, PC e VR/AR, aproveitando recursos específicos do motor, como a renderização 2D e 3D do Unity e as capacidades gráficas realistas do Unreal.","ru":"Наделяет агентов возможностью создавать иммерсивные игровые trải nghiệm с использованием языков C#, C++ и GDScript, развертывая на нескольких платформах, включая мобильные устройства, ПК и VR/AR-устройства, используя двигатель-специфические функции, такие как 2D- и 3D-рендеринг Unity и реалистичные графические возможности Unreal.","ar":"تمكّن العميل من إنشاء تجارب ألعاب غامرة باستخدام لغات C# و C++ و GDScript، و النشر على منصات متعددة بما في ذلك الأجهزة المحمولة وأجهزة الكمبيوتر وأجهزة VR/AR، واستخدام الميزات الخاصة بالمحرك مثل تحرير 2D و 3D في Unity والرسومات الواقعية في Unreal."},"useCases":{"en":["Building cross-platform 2D games with Godot","Developing AAA games with realistic graphics using Unreal Engine","Creating interactive VR/AR experiences with Unity"],"zh":["使用Godot构建跨平台2D游戏","使用Unreal Engine开发具有真实图形的AAA游戏","使用Unity创建交互式VR/AR体验"],"ja":["Godotを使用したクロスプラットフォーム2Dゲームの構築","Unreal Engineを使用したリアルなグラフィックスを持つAAAゲームの開発","Unityを使用したインタラクティブなVR/AR体験の作成"],"ko":["Godot을 사용한 크로스 플랫폼 2D 게임 빌드","Unreal Engine을 사용한 리얼한 그래픽의 AAA 게임 개발","Unity를 사용한 상호작용형 VR/AR 경험 생성"],"es":["Creación de juegos 2D multiplataforma con Godot","Desarrollo de juegos AAA con gráficos realistas utilizando Unreal Engine","Creación de experiencias interactivas VR/AR con Unity"],"fr":["Création de jeux 2D multiplateformes avec Godot","Développement de jeux AAA avec des graphiques réalistes utilisant Unreal Engine","Création d''expériences interactives VR/AR avec Unity"],"de":["Erstellung von cross-plattformalen 2D-Spielen mit Godot","Entwicklung von AAA-Spielen mit realistischen Grafiken mit Unreal Engine","Erstellung interaktiver VR/AR-Erfahrungen mit Unity"],"pt":["Construir jogos 2D cross-platform com Godot","Desenvolver jogos AAA com gráficos realistas usando Unreal Engine","Criar experiências interativas VR/AR com Unity"],"ru":["Создание кроссплатформенных 2D-игр с Godot","Разработка игр AAA с реалистичной графикой с использованием Unreal Engine","Создание интерактивных trải nghiệm VR/AR с Unity"],"ar":["بناء ألعاب 2D متعددة المنصات مع محرك Godot","تطوير ألعاب AAA ذات رسومات واقعية باستخدام محرك Unreal","إنشاء تجارب تفاعلية VR/AR مع Unity"]},"limitations":{"en":["Requires programming knowledge in C#, C++, or GDScript","Platform-dependent optimizations needed","Engine-specific limitations apply, such as Unity''s performance constraints on low-end devices"],"zh":["需要C#、C++或GDScript的编程知识","需要平台依赖的优化","引擎特定的限制适用，例如Unity在低端设备上的性能约束"],"ja":["C#、C++、またはGDScriptのプログラミング知識が必要","プラットフォーム依存の最適化が必要","エンジン固有の制限が適用され、Unityの低端デバイスでのパフォーマンス制約など"],"ko":["C#、C++ 또는 GDScript의 프로그래밍 지식 필요","플랫폼 종속 최적화 필요","엔진 특정 제한 사항이 적용됨. 예를 들어 Unity의 저사양 기기에서의 성능 제한"],"es":["Requiere conocimientos de programación en C#, C++ o GDScript","Se necesitan optimizaciones dependientes de la plataforma","Se aplican limitaciones específicas del motor, como las limitaciones de rendimiento de Unity en dispositivos de baja gama"],"fr":["Nécessite des connaissances en programmation en C#, C++ ou GDScript","Des optimisations dépendantes de la plateforme sont nécessaires","Des limitations spécifiques du moteur s''appliquent, telles que les contraintes de performance d''Unity sur les appareils bas de gamme"],"de":["Benötigt Programmierkenntnisse in C#, C++ oder GDScript","Plattform-abhängige Optimierungen sind erforderlich","Motor-spezifische Einschränkungen gelten, wie z.B. die Leistungsbeschränkungen von Unity auf Low-End-Geräten"],"pt":["Requer conhecimento de programação em C#, C++ ou GDScript","Otimizações dependente de plataforma necessárias","Limitações específicas do motor se aplicam, como as limitações de desempenho do Unity em dispositivos de baixo custo"],"ru":["Требуется знание программирования на C#, C++ или GDScript","Необходимы оптимизации, зависящие от платформы","Применяются ограничения, специфичные для двигателя, такие как ограничения производительности Unity на устройствах с низкой производительностью"],"ar":["يتطلب معرفة بالبرمجة بلغات C# أو C++ أو GDScript","تحسينات تعتمد على المنصة ضرورية","تطبق قيود محددة للمحرك، مثل قيود أداء Unity على الأجهزة منخفضة التكلفة"]},"version":4},"contentHash":"419ea562dd8cfed0612d9a1dc8ad8ab821785e531b75b4e92c0599caf57c2c7f","qualityScore":42}');
