INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Deefunxion/pixel-flick-frenzy/game-development', 'game-development', 'Deefunxion', 'pixel-flick-frenzy', 'community', 'game-development Deefunxion pixel-flick-frenzy community The game-development skill provides a comprehensive guide for building games across major engines and platforms, benefiting developers and indie game creators. 游戏开发综合指南，涵盖 Unity、Unreal 和 Godot 引擎的项目结构和脚本语言 ゲーム開発の総合ガイド - Unity、Unreal、Godot エンジンのプロジェクト構造とスクリプト言語 게임 개발을 위한 전체 가이드 - 유니티, 언리얼, 고도트 엔진의 프로젝트 구조 및 스크립트 언어 Desarrolla juegos con Unity, Unreal y Godot. Guía técnica para principiantes y expertos. Développez des jeux avec Unity, Unreal et Godot. Guide technique pour débutants et experts. Entwickeln Sie Spiele mit Unity, Unreal und Godot. Technischer Leitfaden für Anfänger und Experten. Desenvolva jogos com Unity, Unreal e Godot, e aprenda a criar experiências de jogo imersivas Разрабатывайте игры с помощью Unity, Unreal и Godot, и создавайте иммерсивные игровые trải nghiệm с помощью ИИ Агентов برمج الألعاب باستخدام Unity و Unreal و Godot، وإنشاء تجارب اللعبة الغامرة مع أدوات الذكاء الاصطناعي how to use game development game development setup guide unity vs unreal game engine godot game development tutorial game development with c# game development install guide what is game development game development alternative game development best practices 游戏开发 Unity Unreal Godot 游戏引擎 脚本语言 项目结构 游戏开发教程 游戏开发工具 Supports Unity engine with C# scripting Unreal engine integration with C++ and Blueprints Godot engine development with GDScript and C# Project structure organization with Assets and Scripts folders Cross-platform support for mobile, PC, and VR/AR devices Game-development is a comprehensive process for creating games across Unity, Unreal, and Godot engines, supporting various platforms and languages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mariotoffia/gobridge/deployment-aws-canary-setup', 'community', 'mariotoffia', 'gobridge', 'mariotoffia/gobridge', 'deployment-aws-canary-setup', 0, 0, 42, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:43.612Z', 'bf13ba527ac817430840b0c5588dc5da775c8b352f11c3eedea70def1c1fdc7a', '{"id":"mariotoffia/gobridge/deployment-aws-canary-setup","name":"deployment-aws-canary-setup","description":{"en":"The deployment-aws-canary-setup skill enables developers to set up progressive canary deployments for AWS Lambda using CDK TypeScript, reducing deployment risk by routing a small percentage of traffic to new code first.","zh":"本技能教您如何设置AWS Lambda的进阶金丝雀部署，使用CDK TypeScript配置Lambda版本和别名，CloudWatch报警和CodeDeploy部署组","ja":"このスキルでは、AWS Lambdaのカナリアデプロイを設定する方法を学び、CDK TypeScriptを使用してLambdaバージョンとエイリアス、CloudWatchアラーム、CodeDeployデプロイグループを構成する","ko":"본 스킬은 AWS Lambda의 카나리 배포를 설정하는 방법을 가르쳐주며, CDK TypeScript를 사용하여 Lambda 버전 및 별칭, CloudWatch 알림 및 CodeDeploy 배포 그룹을 구성","es":"Esta habilidad enseña a configurar implementaciones de canary progresivas para AWS Lambda. Aprende a configurar versiones y alias de Lambda, alarmas de CloudWatch y grupos de implementación de CodeDeploy","fr":"Cette compétence vous enseigne à configurer des déploiements canary progressifs pour AWS Lambda. Découvrez comment configurer des versions et des alias Lambda, des alarmes CloudWatch et des groupes de déploiement CodeDeploy","de":"Diese Fähigkeit lehrt die Einrichtung von progressiven Canary-Deployments für AWS Lambda. Erfahren Sie, wie Sie Lambda-Versionen und -Alias, CloudWatch-Alarme und CodeDeploy-Deployments-Gruppen konfigurieren","pt":"Configuração de implantação de canary para AWS Lambda usando CDK TypeScript, reduzindo o risco de implantação com entregas progressivas","ru":"Настройка прогрессивной канареечной доставки для AWS Lambda с помощью CDK TypeScript, снижающая риск доставки","ar":"إعداد توزيع Canary التقدمي لبرنامج AWS Lambda باستخدام CDK TypeScript، لتقليل مخاطر التوزيع"},"seo":{"title":{"en":"deployment-aws-canary-setup: Progressive Deployment Setup...","zh":"AWS 金丝雀部署设置指南 - AIエージェント","ja":"AWSカナリアデプロイセットアップガイド - AIエージェント","ko":"AWS 카나리 배포 설정 가이드 - AI 에이전트","es":"Configuración de implementación de canary en AWS: Guía de...","fr":"Déploiement canary AWS : Meilleures pratiques de configur...","de":"AWS-Canary-Deployments-Setup: Anleitung für eine sichere ...","pt":"Guia de Configuração de Implantação de Canary no AWS","ru":"Настройка прогрессивной канареечной доставки в AWS","ar":"إعداد توزيع Canary على منصة أمازون ويب سيرفيس"},"description":{"en":"Learn how to reduce deployment risk with canary deployments on AWS Lambda. Get started with our step-by-step setup guide and master traffic shifting with Cod...","zh":"了解如何使用CDK TypeScript设置AWS Lambda的进阶金丝雀部署，减少部署风险","ja":"CDK TypeScriptを使用してAWS Lambdaのカナリアデプロイを設定する方法を学び、デプロイリスクを軽減する","ko":"CDK TypeScript를 사용하여 AWS Lambda의 카나리 배포를 설정하는 방법을 배우고 배포 위험을 감소시키는 방법","es":"Aprende a configurar implementaciones de canary progresivas para AWS Lambda con CDK TypeScript y reduce el riesgo de despliegue","fr":"Découvrez comment configurer des déploiements canary progressifs pour AWS Lambda avec CDK TypeScript et réduisez les risques de déploiement","de":"Erfahren Sie, wie Sie progressive Canary-Deployments für AWS Lambda mit CDK TypeScript einrichten und das Deploy-Risiko minimieren","pt":"Aprenda a configurar implantações de canary progressivas para AWS Lambda usando CDK TypeScript e reduza o risco de implantação","ru":"Узнайте, как настроить прогрессивную канареечную доставку для AWS Lambda с помощью CDK TypeScript и снизьте риск доставки","ar":"تعلم كيفية إعداد توزيع Canary التقدمي لبرنامج AWS Lambda باستخدام CDK TypeScript وتقليل مخاطر التوزيع"},"definition":{"en":"deployment-aws-canary-setup is a skill that teaches you how to configure Lambda versions and aliases, CloudWatch alarms, and CodeDeploy deployment groups for traffic shifting on AWS Lambda.","zh":"AWS金丝雀部署是指使用CDK TypeScript设置进阶的Lambda部署，通过逐渐增加新版本流量来减少部署风险","ja":"AWSカナリアデプロイとは、CDK TypeScriptを使用してAWS Lambdaの進歩的なデプロイを設定し、新しいバージョンのトラフィックを徐々に増加させることでデプロイリスクを軽減すること","ko":"AWS 카나리 배포는 CDK TypeScript를 사용하여 진행적인 Lambda 배포를 설정하여 새로운 버전의 트래픽을 점진적으로 증가시키는 것으로 배포 위험을 감소시키는 것","es":"Un despliegue de canary en AWS es una técnica de despliegue que reduce el riesgo al dirigir un pequeño porcentaje de tráfico a nuevo código","fr":"Un déploiement canary sur AWS est une technique de déploiement qui réduit les risques en dirigeant un petit pourcentage de trafic vers le nouveau code","de":"Ein Canary-Deployments in AWS ist eine Deploy-Technik, die das Risiko reduziert, indem sie einen kleinen Prozentsatz des Traffics auf neuen Code umleitet","pt":"Implantação de canary é uma técnica de entrega progressiva que reduz o risco de implantação","ru":"Канареечная доставка - это техника прогрессивной доставки, снижающая риск доставки","ar":"توزيع Canary هو تقنية للتسليم التدريجي لتقليل مخاطر التوزيع"},"features":{"en":["Configures Lambda versions and aliases for canary deployments","Sets up CloudWatch alarms for automated rollback","Creates CodeDeploy deployment groups for traffic shifting","Routes a small percentage of traffic to new code first","Gradually shifts traffic to new version based on performance","Supports CDK TypeScript for infrastructure as code"],"zh":["使用CDK TypeScript配置Lambda版本和别名","设置CloudWatch报警用于自动回滚","配置CodeDeploy部署组用于流量转移","逐渐增加新版本流量以减少部署风险","支持AWS Lambda函数的进阶部署"],"ja":["CDK TypeScriptを使用してLambdaバージョンとエイリアスを構成する","CloudWatchアラームを設定して自動ロールバックする","CodeDeployデプロイグループを構成してトラフィックをシフトする","新しいバージョンのトラフィックを徐々に増加させることでデプロイリスクを軽減する","AWS Lambda関数の進歩的なデプロイをサポートする"],"ko":["CDK TypeScript를 사용하여 Lambda 버전 및 별칭을 구성","CloudWatch 알림을 설정하여 자동 롤백","CodeDeploy 배포 그룹을 구성하여 트래픽을 전환","새로운 버전의 트래픽을 점진적으로 증가시키는 것으로 배포 위험을 감소시키는","AWS Lambda 함수의 진행적인 배포를 지원"],"es":["Configuración de versiones y alias de Lambda","Creación de alarmas de CloudWatch para rollback automático","Configuración de grupos de implementación de CodeDeploy para cambio de tráfico","Implementación progresiva de canary para reducir el riesgo de despliegue","Uso de CDK TypeScript para la implementación"],"fr":["Configuration de versions et d''alias Lambda","Création d''alarmes CloudWatch pour rollback automatique","Configuration de groupes de déploiement CodeDeploy pour changement de trafic","Déploiement canary progressif pour réduire les risques de déploiement","Utilisation de CDK TypeScript pour le déploiement"],"de":["Konfiguration von Lambda-Versionen und -Alias","Erstellung von CloudWatch-Alarmen für automatischen Rollback","Konfiguration von CodeDeploy-Deployments-Gruppen für Traffic-Wechsel","Progressives Canary-Deployments für minimiertes Deploy-Risiko","Verwendung von CDK TypeScript für die Implementierung"],"pt":["Configuração de versões e aliases do Lambda","Alarmes do CloudWatch para reversão automática","Grupos de implantação do CodeDeploy para controle de tráfego","Entregas progressivas para reduzir o risco de implantação","Uso de CDK TypeScript para automação de implantação","Integração com AWS Lambda para entrega de funções"],"ru":["Настройка версий и псевдонимов Lambda","Сигналы CloudWatch для автоматического откат","Группы доставки CodeDeploy для контроля трафика","Прогрессивная доставка для снижения риска доставки","Использование CDK TypeScript для автоматизации доставки","Интеграция с AWS Lambda для доставки функций"],"ar":["إعداد إصدارات وأسماء مستعارة لبرنامج Lambda","إشارات CloudWatch للتراجع التلقائي","مجموعات التوزيع الخاصة ببرنامج CodeDeploy للتحكم في حركة المرور","التسليم التدريجي لتقليل مخاطر التوزيع","استخدام CDK TypeScript للautomatização التوزيع","التكامل مع برنامج AWS Lambda لتسليم الوظائف"]},"keywords":{"en":["how to use deployment-aws-canary-setup","what is deployment-aws-canary-setup","deployment-aws-canary-setup vs AWS CodePipeline","deployment-aws-canary-setup setup guide","deployment-aws-canary-setup install","AWS Lambda canary deployment best practices","CDK TypeScript deployment-aws-canary-setup","CodeDeploy traffic shifting tutorial","CloudWatch alarms for automated rollback","progressive deployment on AWS Lambda"],"zh":["AWS金丝雀部署","CDK TypeScript","Lambda版本","CloudWatch报警","CodeDeploy部署组","金丝雀部署设置","AWS Lambda函数","进阶部署","AIエージェント"],"ja":["AWSカナリアデプロイ","CDK TypeScript","Lambdaバージョン","CloudWatchアラーム","CodeDeployデプロイグループ","カナリアデプロイ設定","AWS Lambda関数","進歩的なデプロイ","AIエージェント"],"ko":["AWS 카나리 배포","CDK TypeScript","Lambda 버전","CloudWatch 알림","CodeDeploy 배포 그룹","카나리 배포 설정","AWS Lambda 함수","진행적인 배포","AI 에이전트"],"es":["despliegue de canary en AWS","implementación progresiva de canary","AWS Lambda","CDK TypeScript","CloudWatch","CodeDeploy","reducción de riesgo de despliegue","despliegue de aplicaciones en la nube","herramientas de despliegue de AWS"],"fr":["déploiement canary sur AWS","déploiement canary progressif","AWS Lambda","CDK TypeScript","CloudWatch","CodeDeploy","réduction des risques de déploiement","déploiement d''applications dans le cloud","outils de déploiement AWS"],"de":["Canary-Deployments in AWS","progressives Canary-Deployments","AWS Lambda","CDK TypeScript","CloudWatch","CodeDeploy","Minimierung des Deploy-Risikos","Deploy von Cloud-Anwendungen","AWS-Deploy-Tools"],"pt":["implantação de canary","AWS Lambda","CDK TypeScript","entrega progressiva","redução de risco de implantação","CloudWatch","CodeDeploy","automatização de implantação","entrega de funções","técnicas de entrega de software"],"ru":["канареечная доставка","AWS Lambda","CDK TypeScript","прогрессивная доставка","снижение риска доставки","CloudWatch","CodeDeploy","автоматизация доставки","доставка функций","техники доставки программного обеспечения"],"ar":["توزيع Canary","AWS Lambda","CDK TypeScript","التسليم التدريجي","تقليل مخاطر التوزيع","CloudWatch","CodeDeploy","automatización التوزيع","تسليم الوظائف","تقنيات التسليم البرمجية"]}},"owner":"mariotoffia","repo":"gobridge","repoPath":"mariotoffia/gobridge","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"deployment-aws-canary-setup","description":"Step-by-step guide for setting up AWS Lambda canary deployments with CDK, CloudWatch alarms, and automated rollback.","bodyPreview":"# Skill: AWS Canary Deployment Setup\n\nThis skill teaches you how to set up progressive canary deployments for AWS Lambda using CDK TypeScript. You''ll configure Lambda versions and aliases, CloudWatch alarms for automated rollback, and CodeDeploy deployment groups for traffic shifting.\n\nCanary deployments reduce deployment risk by routing a small percentage of traffic to new code first. If the new version performs well (low errors, acceptable latency), traffic gradually shifts until 100% reaches","body":"# Skill: AWS Canary Deployment Setup\n\nThis skill teaches you how to set up progressive canary deployments for AWS Lambda using CDK TypeScript. You''ll configure Lambda versions and aliases, CloudWatch alarms for automated rollback, and CodeDeploy deployment groups for traffic shifting.\n\nCanary deployments reduce deployment risk by routing a small percentage of traffic to new code first. If the new version performs well (low errors, acceptable latency), traffic gradually shifts until 100% reaches the new version. If metrics fail, traffic automatically rolls back to the stable version.\n\nThis approach is essential for production workloads where zero-downtime deployments and automatic failure recovery are critical requirements.\n\n## Prerequisites\n\n- AWS CDK v2 installed (`npm install -g aws-cdk`)\n- TypeScript project with CDK configured\n- Lambda function deployed with proper IAM roles\n- CloudWatch configured for Lambda metrics\n- Understanding of Lambda versions and aliases\n\n## Overview\n\nIn this skill, you will:\n1. Create Lambda function with versioning and alias\n2. Configure CloudWatch alarms for error rate and latency\n3. Set up CodeDeploy deployment group with canary config\n4. Create CDK stack with all deployment infrastructure\n5. Implement rollback procedures\n6. Add monitoring dashboard for canary metrics\n\n## Step 1: Create Lambda with Versioning and Alias\n\nLambda versions are immutable snapshots of your function code and configuration. Aliases are mutable pointers that can route traffic between versions.\n\n### CDK Lambda Construct with Versioning\n\n```typescript\n// lib/constructs/versioned-lambda.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport * as codedeploy from ''aws-cdk-lib/aws-codedeploy'';\nimport { Construct } from ''constructs'';\n\nexport interface VersionedLambdaProps {\n  functionName: string;\n  description: string;\n  codePath: string;\n  handler: string;\n  runtime: lambda.Runtime;\n  memorySize?: number;\n  timeout?: cdk.Duration;\n  environment?: { [key: string]: string };\n  reservedConcurrentExecutions?: number;\n}\n\nexport class VersionedLambda extends Construct {\n  public readonly function: lambda.Function;\n  public readonly alias: lambda.Alias;\n  public readonly currentVersion: lambda.Version;\n\n  constructor(scope: Construct, id: string, props: VersionedLambdaProps) {\n    super(scope, id);\n\n    // Create Lambda function with tracing enabled\n    this.function = new lambda.Function(this, ''Function'', {\n      functionName: props.functionName,\n      description: props.description,\n      runtime: props.runtime,\n      handler: props.handler,\n      code: lambda.Code.fromAsset(props.codePath),\n      memorySize: props.memorySize ?? 256,\n      timeout: props.timeout ?? cdk.Duration.seconds(30),\n      environment: props.environment,\n      tracing: lambda.Tracing.ACTIVE,\n      reservedConcurrentExecutions: props.reservedConcurrentExecutions,\n      // Enable versioning by setting currentVersionOptions\n      currentVersionOptions: {\n        removalPolicy: cdk.RemovalPolicy.RETAIN,\n        description: `Version deployed at ${new Date().toISOString()}`,\n      },\n    });\n\n    // Get the current version (creates new version on each deployment)\n    this.currentVersion = this.function.currentVersion;\n\n    // Create alias pointing to current version\n    // The alias is what API Gateway or other services invoke\n    this.alias = new lambda.Alias(this, ''LiveAlias'', {\n      aliasName: ''live'',\n      version: this.currentVersion,\n      description: ''Production traffic alias'',\n    });\n  }\n}\n```\n\nThe key concepts here:\n- **Versions**: Each deployment creates an immutable version snapshot\n- **Alias**: The \"live\" alias is what clients invoke, not a specific version\n- **Traffic routing**: The alias can split traffic between two versions\n\n### Using the Construct\n\n```typescript\n// lib/stacks/api-stack.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport { Construct } from ''constructs'';\nimport { VersionedLambda } from ''../constructs/versioned-lambda'';\n\nexport class ApiStack extends cdk.Stack {\n  public readonly apiHandler: VersionedLambda;\n\n  constructor(scope: Construct, id: string, props?: cdk.StackProps) {\n    super(scope, id, props);\n\n    const stage = this.node.tryGetContext(''stage'') || ''dev'';\n\n    this.apiHandler = new VersionedLambda(this, ''ApiHandler'', {\n      functionName: `my-service-api-${stage}`,\n      description: ''API handler for my-service'',\n      codePath: ''../dist/api'',\n      handler: ''bootstrap'',\n      runtime: lambda.Runtime.PROVIDED_AL2023,\n      memorySize: 256,\n      timeout: cdk.Duration.seconds(30),\n      environment: {\n        STAGE: stage,\n        LOG_LEVEL: stage === ''prod'' ? ''INFO'' : ''DEBUG'',\n      },\n    });\n\n    // Export alias ARN for API Gateway integration\n    new cdk.CfnOutput(this, ''ApiAliasArn'', {\n      value: this.apiHandler.alias.functionArn,\n      description: ''Lambda alias ARN for API Gateway'',\n    });\n  }\n}\n```\n\n## Step 2: Configure CloudWatch Alarms\n\nCloudWatch alarms monitor your Lambda''s health during deployment. If metrics breach thresholds, CodeDeploy triggers automatic rollback.\n\n### Alarm Configuration Construct\n\n```typescript\n// lib/constructs/deployment-alarms.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport { Construct } from ''constructs'';\n\nexport interface DeploymentAlarmsProps {\n  lambdaFunction: lambda.Function;\n  alias: lambda.Alias;\n  alarmNamePrefix: string;\n  // Thresholds\n  errorRateThreshold?: number;      // Default: 1%\n  latencyP99Threshold?: number;     // Default: 5000ms\n  throttleThreshold?: number;       // Default: 10 per minute\n  evaluationPeriods?: number;       // Default: 2\n}\n\nexport class DeploymentAlarms extends Construct {\n  public readonly errorAlarm: cloudwatch.Alarm;\n  public readonly latencyAlarm: cloudwatch.Alarm;\n  public readonly throttleAlarm: cloudwatch.Alarm;\n  public readonly allAlarms: cloudwatch.Alarm[];\n\n  constructor(scope: Construct, id: string, props: DeploymentAlarmsProps) {\n    super(scope, id);\n\n    const evaluationPeriods = props.evaluationPeriods ?? 2;\n\n    // Error rate alarm - triggers rollback if errors exceed threshold\n    this.errorAlarm = new cloudwatch.Alarm(this, ''ErrorAlarm'', {\n      alarmName: `${props.alarmNamePrefix}-errors`,\n      alarmDescription: ''Lambda error rate exceeded threshold during deployment'',\n      metric: props.alias.metricErrors({\n        period: cdk.Duration.minutes(1),\n        statistic: ''Sum'',\n      }),\n      threshold: props.errorRateThreshold ?? 10,\n      evaluationPeriods: evaluationPeriods,\n      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,\n      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,\n    });\n\n    // P99 latency alarm - triggers rollback if latency too high\n    this.latencyAlarm = new cloudwatch.Alarm(this, ''LatencyAlarm'', {\n      alarmName: `${props.alarmNamePrefix}-latency-p99`,\n      alarmDescription: ''Lambda P99 latency exceeded threshold during deployment'',\n      metric: props.alias.metricDuration({\n        period: cdk.Duration.minutes(1),\n        statistic: ''p99'',\n      }),\n      threshold: props.latencyP99Threshold ?? 5000,\n      evaluationPeriods: evaluationPeriods,\n      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,\n      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,\n    });\n\n    // Throttle alarm - indicates capacity issues\n    this.throttleAlarm = new cloudwatch.Alarm(this, ''ThrottleAlarm'', {\n      alarmName: `${props.alarmNamePrefix}-throttles`,\n      alarmDescription: ''Lambda throttling detected during deployment'',\n      metric: props.alias.metricThrottles({\n        period: cdk.Duration.minutes(1),\n        statistic: ''Sum'',\n      }),\n      threshold: props.throttleThreshold ?? 10,\n      evaluationPeriods: evaluationPeriods,\n      comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,\n      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,\n    });\n\n    this.allAlarms = [this.errorAlarm, this.latencyAlarm, this.throttleAlarm];\n  }\n}\n```\n\nThese alarms monitor the alias (which receives production traffic), not the function directly. This ensures we''re measuring the actual user experience during canary deployment.\n\n## Step 3: Configure CodeDeploy Deployment Group\n\nCodeDeploy manages the traffic shifting between Lambda versions. It supports multiple deployment strategies.\n\n### Deployment Configuration Options\n\n```typescript\n// lib/constructs/canary-deployment.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport * as codedeploy from ''aws-cdk-lib/aws-codedeploy'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport { Construct } from ''constructs'';\n\n// Available deployment configurations\nexport enum CanaryDeploymentConfig {\n  // Canary: Deploy to small percentage, wait, then 100%\n  CANARY_10_PERCENT_5_MINUTES = ''CANARY_10PERCENT_5MINUTES'',\n  CANARY_10_PERCENT_10_MINUTES = ''CANARY_10PERCENT_10MINUTES'',\n  CANARY_10_PERCENT_15_MINUTES = ''CANARY_10PERCENT_15MINUTES'',\n  \n  // Linear: Gradually increase traffic at fixed intervals\n  LINEAR_10_PERCENT_EVERY_1_MINUTE = ''LINEAR_10PERCENT_EVERY_1MINUTE'',\n  LINEAR_10_PERCENT_EVERY_2_MINUTES = ''LINEAR_10PERCENT_EVERY_2MINUTES'',\n  LINEAR_10_PERCENT_EVERY_3_MINUTES = ''LINEAR_10PERCENT_EVERY_3MINUTES'',\n  LINEAR_10_PERCENT_EVERY_10_MINUTES = ''LINEAR_10PERCENT_EVERY_10MINUTES'',\n  \n  // All at once (not recommended for production)\n  ALL_AT_ONCE = ''ALL_AT_ONCE'',\n}\n\nexport interface CanaryDeploymentProps {\n  alias: lambda.Alias;\n  deploymentConfig: CanaryDeploymentConfig;\n  alarms: cloudwatch.Alarm[];\n  applicationName?: string;\n  deploymentGroupName?: string;\n}\n\nexport class CanaryDeployment extends Construct {\n  public readonly application: codedeploy.LambdaApplication;\n  public readonly deploymentGroup: codedeploy.LambdaDeploymentGroup;\n\n  constructor(scope: Construct, id: string, props: CanaryDeploymentProps) {\n    super(scope, id);\n\n    // Create CodeDeploy application\n    this.application = new codedeploy.LambdaApplication(this, ''Application'', {\n      applicationName: props.applicationName,\n    });\n\n    // Map deployment config enum to CDK deployment config\n    const deploymentConfig = this.getDeploymentConfig(props.deploymentConfig);\n\n    // Create deployment group with automatic rollback\n    this.deploymentGroup = new codedeploy.LambdaDeploymentGroup(this, ''DeploymentGroup'', {\n      application: this.application,\n      deploymentGroupName: props.deploymentGroupName,\n      alias: props.alias,\n      deploymentConfig: deploymentConfig,\n      \n      // Attach alarms for automatic rollback\n      alarms: props.alarms,\n      \n      // Auto-rollback on deployment failure or alarm breach\n      autoRollback: {\n        failedDeployment: true,\n        stoppedDeployment: true,\n        deploymentInAlarm: true,\n      },\n    });\n  }\n\n  private getDeploymentConfig(\n    config: CanaryDeploymentConfig\n  ): codedeploy.ILambdaDeploymentConfig {\n    switch (config) {\n      case CanaryDeploymentConfig.CANARY_10_PERCENT_5_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_5MINUTES;\n      case CanaryDeploymentConfig.CANARY_10_PERCENT_10_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_10MINUTES;\n      case CanaryDeploymentConfig.CANARY_10_PERCENT_15_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_15MINUTES;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_1_MINUTE:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_1MINUTE;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_2_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_2MINUTES;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_3_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_3MINUTES;\n      case CanaryDeploymentConfig.LINEAR_10_PERCENT_EVERY_10_MINUTES:\n        return codedeploy.LambdaDeploymentConfig.LINEAR_10PERCENT_EVERY_10MINUTES;\n      case CanaryDeploymentConfig.ALL_AT_ONCE:\n        return codedeploy.LambdaDeploymentConfig.ALL_AT_ONCE;\n      default:\n        return codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_5MINUTES;\n    }\n  }\n}\n```\n\n### Deployment Config Comparison\n\n| Config | Traffic Shift | Total Time | Use Case |\n|--------|---------------|------------|----------|\n| CANARY_10PERCENT_5MINUTES | 10% → 100% | 5 min | Quick validation |\n| CANARY_10PERCENT_10MINUTES | 10% → 100% | 10 min | Standard production |\n| LINEAR_10PERCENT_EVERY_1MINUTE | 10% increments | 10 min | Gradual rollout |\n| LINEAR_10PERCENT_EVERY_10MINUTES | 10% increments | 100 min | High-risk changes |\n\n## Step 4: Complete CDK Stack\n\nCombine all components into a production-ready deployment stack.\n\n```typescript\n// lib/stacks/canary-deployment-stack.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport * as codedeploy from ''aws-cdk-lib/aws-codedeploy'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport { Construct } from ''constructs'';\nimport { VersionedLambda } from ''../constructs/versioned-lambda'';\nimport { DeploymentAlarms } from ''../constructs/deployment-alarms'';\nimport { CanaryDeployment, CanaryDeploymentConfig } from ''../constructs/canary-deployment'';\n\nexport interface CanaryDeploymentStackProps extends cdk.StackProps {\n  stage: string;\n  serviceName: string;\n  codePath: string;\n  deploymentConfig?: CanaryDeploymentConfig;\n  errorRateThreshold?: number;\n  latencyP99Threshold?: number;\n}\n\nexport class CanaryDeploymentStack extends cdk.Stack {\n  public readonly lambdaFunction: lambda.Function;\n  public readonly alias: lambda.Alias;\n  public readonly deploymentGroup: codedeploy.LambdaDeploymentGroup;\n\n  constructor(scope: Construct, id: string, props: CanaryDeploymentStackProps) {\n    super(scope, id, props);\n\n    const alarmPrefix = `${props.serviceName}-${props.stage}`;\n\n    // Create versioned Lambda\n    const versionedLambda = new VersionedLambda(this, ''ApiHandler'', {\n      functionName: `${props.serviceName}-api-${props.stage}`,\n      description: `${props.serviceName} API handler`,\n      codePath: props.codePath,\n      handler: ''bootstrap'',\n      runtime: lambda.Runtime.PROVIDED_AL2023,\n      memorySize: 256,\n      timeout: cdk.Duration.seconds(30),\n      environment: {\n        STAGE: props.stage,\n        SERVICE_NAME: props.serviceName,\n      },\n    });\n\n    this.lambdaFunction = versionedLambda.function;\n    this.alias = versionedLambda.alias;\n\n    // Create deployment alarms\n    const alarms = new DeploymentAlarms(this, ''Alarms'', {\n      lambdaFunction: this.lambdaFunction,\n      alias: this.alias,\n      alarmNamePrefix: alarmPrefix,\n      errorRateThreshold: props.errorRateThreshold,\n      latencyP99Threshold: props.latencyP99Threshold,\n    });\n\n    // Determine deployment config based on stage\n    const deploymentConfig = props.deploymentConfig ?? \n      (props.stage === ''prod'' \n        ? CanaryDeploymentConfig.CANARY_10_PERCENT_10_MINUTES\n        : CanaryDeploymentConfig.ALL_AT_ONCE);\n\n    // Create canary deployment group\n    const canaryDeployment = new CanaryDeployment(this, ''CanaryDeploy'', {\n      alias: this.alias,\n      deploymentConfig: deploymentConfig,\n      alarms: alarms.allAlarms,\n      applicationName: `${props.serviceName}-${props.stage}`,\n      deploymentGroupName: `${props.serviceName}-${props.stage}-dg`,\n    });\n\n    this.deploymentGroup = canaryDeployment.deploymentGroup;\n\n    // Outputs\n    new cdk.CfnOutput(this, ''FunctionName'', {\n      value: this.lambdaFunction.functionName,\n    });\n\n    new cdk.CfnOutput(this, ''AliasArn'', {\n      value: this.alias.functionArn,\n    });\n\n    new cdk.CfnOutput(this, ''CurrentVersion'', {\n      value: versionedLambda.currentVersion.version,\n    });\n\n    new cdk.CfnOutput(this, ''DeploymentGroupName'', {\n      value: this.deploymentGroup.deploymentGroupName,\n    });\n  }\n}\n```\n\n### CDK App Entry Point\n\n```typescript\n// bin/app.ts\n#!/usr/bin/env node\nimport ''source-map-support/register'';\nimport * as cdk from ''aws-cdk-lib'';\nimport { CanaryDeploymentStack } from ''../lib/stacks/canary-deployment-stack'';\nimport { CanaryDeploymentConfig } from ''../lib/constructs/canary-deployment'';\n\nconst app = new cdk.App();\n\nconst stage = app.node.tryGetContext(''stage'') || ''dev'';\nconst serviceName = ''my-service'';\n\nnew CanaryDeploymentStack(app, `${serviceName}-${stage}`, {\n  stage: stage,\n  serviceName: serviceName,\n  codePath: ''../dist/api'',\n  deploymentConfig: stage === ''prod'' \n    ? CanaryDeploymentConfig.CANARY_10_PERCENT_10_MINUTES\n    : CanaryDeploymentConfig.ALL_AT_ONCE,\n  errorRateThreshold: 10,\n  latencyP99Threshold: 5000,\n  env: {\n    account: process.env.CDK_DEFAULT_ACCOUNT,\n    region: process.env.CDK_DEFAULT_REGION || ''eu-west-1'',\n  },\n});\n```\n\n## Step 5: Test Rollback Scenarios\n\nImplement scripts and procedures for testing rollback behavior.\n\n### Metrics Check Script\n\n```bash\n#!/bin/bash\n# scripts/check-metrics.sh\n# Validates Lambda metrics for canary deployment health\n\nset -euo pipefail\n\nSERVICE=$1\nSTAGE=$2\nFUNCTION_NAME=\"${SERVICE}-api-${STAGE}\"\nALIAS_NAME=\"live\"\n\necho \"Checking metrics for ${FUNCTION_NAME}:${ALIAS_NAME}...\"\n\n# Time range: last 5 minutes\nEND_TIME=$(date -u +\"%Y-%m-%dT%H:%M:%SZ\")\nSTART_TIME=$(date -u -v-5M +\"%Y-%m-%dT%H:%M:%SZ\" 2>/dev/null || \\\n             date -u -d \"5 minutes ago\" +\"%Y-%m-%dT%H:%M:%SZ\")\n\n# Get error count\nERRORS=$(aws cloudwatch get-metric-statistics \\\n  --namespace AWS/Lambda \\\n  --metric-name Errors \\\n  --dimensions Name=FunctionName,Value=$FUNCTION_NAME Name=Resource,Value=\"${FUNCTION_NAME}:${ALIAS_NAME}\" \\\n  --start-time \"$START_TIME\" \\\n  --end-time \"$END_TIME\" \\\n  --period 300 \\\n  --statistics Sum \\\n  --query ''Datapoints[0].Sum'' \\\n  --output text 2>/dev/null || echo \"0\")\n\n# Get invocation count  \nINVOCATIONS=$(aws cloudwatch get-metric-statistics \\\n  --namespace AWS/Lambda \\\n  --metric-name Invocations \\\n  --dimensions Name=FunctionName,Value=$FUNCTION_NAME Name=Resource,Value=\"${FUNCTION_NAME}:${ALIAS_NAME}\" \\\n  --start-time \"$START_TIME\" \\\n  --end-time \"$END_TIME\" \\\n  --period 300 \\\n  --statistics Sum \\\n  --query ''Datapoints[0].Sum'' \\\n  --output text 2>/dev/null || echo \"1\")\n\n# Get P99 duration\nDURATION_P99=$(aws cloudwatch get-metric-statistics \\\n  --namespace AWS/Lambda \\\n  --metric-name Duration \\\n  --dimensions Name=FunctionName,Value=$FUNCTION_NAME Name=Resource,Value=\"${FUNCTION_NAME}:${ALIAS_NAME}\" \\\n  --start-time \"$START_TIME\" \\\n  --end-time \"$END_TIME\" \\\n  --period 300 \\\n  --extended-statistics p99 \\\n  --query ''Datapoints[0].ExtendedStatistics.p99'' \\\n  --output text 2>/dev/null || echo \"0\")\n\n# Handle None values\nERRORS=${ERRORS//None/0}\nINVOCATIONS=${INVOCATIONS//None/1}\nDURATION_P99=${DURATION_P99//None/0}\n\n# Calculate error rate\nif [[ \"$INVOCATIONS\" != \"0\" ]]; then\n  ERROR_RATE=$(echo \"scale=4; $ERRORS / $INVOCATIONS\" | bc)\nelse\n  ERROR_RATE=\"0\"\nfi\n\necho \"==========================================\"\necho \"Errors:       $ERRORS\"\necho \"Invocations:  $INVOCATIONS\"\necho \"Error Rate:   $ERROR_RATE\"\necho \"P99 Duration: ${DURATION_P99}ms\"\necho \"==========================================\"\n\n# Validate against thresholds\nFAILED=0\n\nif (( $(echo \"$ERROR_RATE > 0.01\" | bc -l) )); then\n  echo \"❌ FAIL: Error rate $ERROR_RATE > 1%\"\n  FAILED=1\nfi\n\nif (( $(echo \"$DURATION_P99 > 5000\" | bc -l) )); then\n  echo \"❌ FAIL: P99 latency ${DURATION_P99}ms > 5000ms\"\n  FAILED=1\nfi\n\nif [[ $FAILED -eq 1 ]]; then\n  echo \"\"\n  echo \"Metrics validation FAILED - rollback recommended\"\n  exit 1\nfi\n\necho \"✅ PASS: All metrics within thresholds\"\nexit 0\n```\n\n### Manual Rollback Commands\n\n```bash\n#!/bin/bash\n# scripts/rollback.sh\n# Manually rollback to previous Lambda version\n\nset -euo pipefail\n\nSERVICE=$1\nSTAGE=$2\nFUNCTION_NAME=\"${SERVICE}-api-${STAGE}\"\nALIAS_NAME=\"live\"\n\necho \"Rolling back ${FUNCTION_NAME}...\"\n\n# Get previous version (second to last)\nPREVIOUS_VERSION=$(aws lambda list-versions-by-function \\\n  --function-name \"$FUNCTION_NAME\" \\\n  --query ''Versions[-2].Version'' \\\n  --output text)\n\nif [[ \"$PREVIOUS_VERSION\" == \"None\" || \"$PREVIOUS_VERSION\" == \"\\$LATEST\" ]]; then\n  echo \"Error: No previous version found to rollback to\"\n  exit 1\nfi\n\necho \"Rolling back to version: $PREVIOUS_VERSION\"\n\n# Update alias to point to previous version (100% traffic)\naws lambda update-alias \\\n  --function-name \"$FUNCTION_NAME\" \\\n  --name \"$ALIAS_NAME\" \\\n  --function-version \"$PREVIOUS_VERSION\" \\\n  --routing-config ''AdditionalVersionWeights={}''\n\necho \"✅ Rollback complete. Alias now points to version $PREVIOUS_VERSION\"\n\n# Verify\nCURRENT=$(aws lambda get-alias \\\n  --function-name \"$FUNCTION_NAME\" \\\n  --name \"$ALIAS_NAME\" \\\n  --query ''FunctionVersion'' \\\n  --output text)\n\necho \"Current alias version: $CURRENT\"\n```\n\n### Stop In-Progress Deployment\n\n```bash\n#!/bin/bash\n# scripts/stop-deployment.sh\n# Stop an in-progress CodeDeploy deployment\n\nset -euo pipefail\n\nSERVICE=$1\nSTAGE=$2\nAPPLICATION_NAME=\"${SERVICE}-${STAGE}\"\nDEPLOYMENT_GROUP=\"${SERVICE}-${STAGE}-dg\"\n\n# Get current deployment ID\nDEPLOYMENT_ID=$(aws deploy list-deployments \\\n  --application-name \"$APPLICATION_NAME\" \\\n  --deployment-group-name \"$DEPLOYMENT_GROUP\" \\\n  --include-only-statuses \"InProgress\" \\\n  --query ''deployments[0]'' \\\n  --output text)\n\nif [[ \"$DEPLOYMENT_ID\" == \"None\" ]]; then\n  echo \"No in-progress deployment found\"\n  exit 0\nfi\n\necho \"Stopping deployment: $DEPLOYMENT_ID\"\n\naws deploy stop-deployment \\\n  --deployment-id \"$DEPLOYMENT_ID\" \\\n  --auto-rollback-enabled\n\necho \"✅ Deployment stopped and rollback initiated\"\n```\n\n## Step 6: Monitor Canary Metrics\n\nCreate a CloudWatch dashboard for monitoring canary deployments in real-time.\n\n```typescript\n// lib/constructs/canary-dashboard.ts\nimport * as cdk from ''aws-cdk-lib'';\nimport * as cloudwatch from ''aws-cdk-lib/aws-cloudwatch'';\nimport * as lambda from ''aws-cdk-lib/aws-lambda'';\nimport { Construct } from ''constructs'';\n\nexport interface CanaryDashboardProps {\n  dashboardName: string;\n  lambdaFunction: lambda.Function;\n  alias: lambda.Alias;\n}\n\nexport class CanaryDashboard extends Construct {\n  public readonly dashboard: cloudwatch.Dashboard;\n\n  constructor(scope: Construct, id: string, props: CanaryDashboardProps) {\n    super(scope, id);\n\n    this.dashboard = new cloudwatch.Dashboard(this, ''Dashboard'', {\n      dashboardName: props.dashboardName,\n    });\n\n    // Error rate widget\n    this.dashboard.addWidgets(\n      new cloudwatch.GraphWidget({\n        title: ''Error Rate'',\n        left: [\n          props.alias.metricErrors({\n            period: cdk.Duration.minutes(1),\n            statistic: ''Sum'',\n            label: ''Errors'',\n          }),\n        ],\n        right: [\n          props.alias.metricInvocations({\n            period: cdk.Duration.minutes(1),\n            statistic: ''Sum'',\n            label: ''Invocations'',\n          }),\n        ],\n        width: 12,\n      }),\n      new cloudwatch.GraphWidget({\n        title: ''Latency (P50, P90, P99)'',\n        left: [\n          props.alias.metricDuration({\n            period: cdk.Duration.minutes(1),\n            statistic: ''p50'',\n            label: ''P50'',\n          }),\n          props.alias.metricDuration({\n            period: cdk.Duration.minutes(1),\n            statistic: ''p90'',\n            label: ''P90'',\n          }),\n          props.alias.metricDuration({\n            period: cdk.Duration.minutes(1),\n            statistic: ''p99'',\n            label: ''P99'',\n          }),\n        ],\n        width: 12,\n      })\n    );\n\n    // Throttles and concurrent executions\n    this.dashboard.addWidgets(\n      new cloudwatch.GraphWidget({\n        title: ''Throttles'',\n        left: [\n          props.alias.metricThrottles({\n            period: cdk.Duration.minutes(1),\n            statistic: ''Sum'',\n          }),\n        ],\n        width: 8,\n      }),\n      new cloudwatch.GraphWidget({\n        title: ''Concurrent Executions'',\n        left: [\n          props.lambdaFunction.metric(''ConcurrentExecutions'', {\n            period: cdk.Duration.minutes(1),\n            statistic: ''Maximum'',\n          }),\n        ],\n        width: 8,\n      }),\n      new cloudwatch.SingleValueWidget({\n        title: ''Current Error Rate'',\n        metrics: [\n          props.alias.metricErrors({\n            period: cdk.Duration.minutes(5),\n            statistic: ''Sum'',\n          }),\n        ],\n        width: 8,\n      })\n    );\n  }\n}\n```\n\n## Makefile Targets\n\nAdd deployment targets to your Makefile for easy canary operations.\n\n```makefile\n# Makefile for canary deployment operations\n\nSERVICE_NAME := my-service\nSTAGE ?= dev\nCDK_DIR := deploy/cdk\nVERSION ?= $(shell git describe --tags --always)\n\n.PHONY: deploy deploy-canary promote rollback check-metrics stop-deployment\n\n# Standard deployment (uses stage-appropriate config)\ndeploy: build\n\t@echo \"Deploying $(SERVICE_NAME) to $(STAGE)...\"\n\tcd $(CDK_DIR) && cdk deploy --context stage=$(STAGE) --require-approval never\n\n# Deploy with specific canary weight (0.1 = 10%, 0.5 = 50%)\ndeploy-canary: build\nifndef WEIGHT\n\t$(error WEIGHT is required, e.g., make deploy-canary WEIGHT=0.1)\nendif\n\t@echo \"Deploying canary at $(WEIGHT) weight...\"\n\tcd $(CDK_DIR) && CANARY_WEIGHT=$(WEIGHT) cdk deploy --context stage=$(STAGE)\n\n# Promote canary to 100%\npromote:\n\t@echo \"Promoting $(SERVICE_NAME) to 100% in $(STAGE)...\"\n\t./scripts/promote.sh $(SERVICE_NAME) $(STAGE)\n\n# Rollback to previous version\nrollback:\n\t@echo \"Rolling back $(SERVICE_NAME) in $(STAGE)...\"\n\t./scripts/rollback.sh $(SERVICE_NAME) $(STAGE)\n\n# Check deployment metrics\ncheck-metrics:\n\t@./scripts/check-metrics.sh $(SERVICE_NAME) $(STAGE)\n\n# Stop in-progress deployment\nstop-deployment:\n\t@./scripts/stop-deployment.sh $(SERVICE_NAME) $(STAGE)\n\n# Build Lambda binary\nbuild:\n\tGOOS=linux GOARCH=arm64 CGO_ENABLED=0 go build -o bootstrap ./cmd/api\n\tzip -j dist/api.zip bootstrap\n\trm bootstrap\n```\n\n## Verification Checklist\n\nAfter setting up canary deployments, verify:\n\n- [ ] Lambda function publishes new version on each deployment\n- [ ] Alias \"live\" exists and points to current version\n- [ ] CloudWatch alarms configured for errors, latency, and throttles\n- [ ] CodeDeploy deployment group created with correct config\n- [ ] Alarms attached to deployment group for auto-rollback\n- [ ] autoRollback enabled for failedDeployment and deploymentInAlarm\n- [ ] Metrics check script validates error rate < 1%\n- [ ] Metrics check script validates P99 latency < 5000ms\n- [ ] Manual rollback script updates alias to previous version\n- [ ] Stop deployment script halts in-progress deployments\n- [ ] Dashboard shows real-time canary metrics\n- [ ] Makefile has deploy, rollback, and check-metrics targets\n- [ ] Different deployment configs used per environment (ALL_AT_ONCE for dev, CANARY for prod)\n"},"lastSynced":"2026-03-08T02:01:43.612Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Agents needing automated AWS Lambda deployment management with CDK TypeScript.","zh":"适用于需要使用 CDK TypeScript 自动化 AWS Lambda 部署管理的 Cloud Agents。","ja":"CDK TypeScript を使用して AWS Lambda のデプロイメント管理を自動化する必要がある Cloud Agents に適しています。","ko":"CDK TypeScript를 사용하여 AWS Lambda 배포 관리를 자동화해야 하는 Cloud Agents에 적합합니다.","es":"Perfecto para agentes en la nube que necesitan una gestión de implementación automatizada de AWS Lambda con CDK TypeScript.","fr":"Parfait pour les agents Cloud nécessitant une gestion de déploiement automatique d''AWS Lambda avec CDK TypeScript.","de":"Perfekt für Cloud-Agents, die eine automatisierte AWS Lambda-Bereitstellungsverwaltung mit CDK TypeScript benötigen.","pt":"Perfeito para Agentes de Nuvem que necessitam de gerenciamento de implantação automatizada do AWS Lambda com CDK TypeScript.","ru":"Идеально подходит для облачных агентов, которым требуется автоматизированное управление развертыванием AWS Lambda с помощью CDK TypeScript.","ar":"مثالي لعمليات الوكيل السحابي التي تحتاج إلى إدارة تثبيت أتمتية لخدمة AWS Lambda مع CDK TypeScript."},"recommendation":{"en":"Empowers agents to configure Lambda versions and aliases, set up CloudWatch alarms for automated rollback, and create CodeDeploy deployment groups for traffic shifting, reducing deployment risk with progressive canary deployments using AWS Lambda and CDK TypeScript.","zh":"赋予代理配置 Lambda 版本和别名、设置 CloudWatch 报警以实现自动回滚，并创建 CodeDeploy 部署组以进行流量转移，使用 AWS Lambda 和 CDK TypeScript 实现渐进式金丝雀部署，减少部署风险。","ja":"エージェントに Lambda バージョンとエイリアスを構成し、自動ロールバックのための CloudWatch アラームを設定し、CodeDeploy デプロイ グループを作成してトラフィック シフトを行うことを可能にし、AWS Lambda と CDK TypeScript を使用してプログレッシブ カナリア デプロイメントを実行し、デプロイメント リスクを軽減します。","ko":"에이전트가 Lambda 버전 및 별칭을 구성하고 자동 롤백을 위한 CloudWatch 알람을 설정하며 CodeDeploy 배포 그룹을 생성하여 트래픽 시프트를 수행할 수 있도록 하여 AWS Lambda 및 CDK TypeScript를 사용하여 점진적인 카나리 배포를 구현하고 배포 위험을 줄입니다.","es":"Habilita a los agentes a configurar versiones y alias de Lambda, configurar alarmas de CloudWatch para reversión automatizada y crear grupos de implementación de CodeDeploy para cambio de tráfico, reduciendo el riesgo de implementación con implementaciones canarias progresivas que utilizan AWS Lambda y CDK TypeScript.","fr":"Permet aux agents de configurer les versions et les alias Lambda, de configurer des alarmes CloudWatch pour une réversibilité automatique et de créer des groupes de déploiement CodeDeploy pour le changement de trafic, en réduisant le risque de déploiement avec des déploiements canaris progressifs utilisant AWS Lambda et CDK TypeScript.","de":"Ermöglicht es Agenten, Lambda-Versionen und -Aliase zu konfigurieren, CloudWatch-Alarmanlagen für eine automatische Rückkehr zu konfigurieren und CodeDeploy-Deploy-Gruppen für den Traffikumschalter zu erstellen, wodurch das Bereitstellungsrisiko mit fortschreitenden Kanarien-Bereitstellungen, die AWS Lambda und CDK TypeScript verwenden, reduziert wird.","pt":"Permite que os agentes configurem versões e alias do Lambda, configurem alarmes do CloudWatch para rollback automatizado e criem grupos de implantação do CodeDeploy para mudança de tráfego, reduzindo o risco de implantação com implantações canary progressivas usando AWS Lambda e CDK TypeScript.","ru":"Позволяет агентам настраивать версии и псевдонимы Lambda, устанавливать сигналы тревоги CloudWatch для автоматического отката, а также создавать группы развертывания CodeDeploy для переадресации трафика, снижая риск развертывания с помощью постепенных канареечных развертываний, использующих AWS Lambda и CDK TypeScript.","ar":"تمكّن الوكلاء من تكوين إصدارات وكنية Lambda، وتكوين إشعارات CloudWatch للتراجع التلقائي، وإنشاء مجموعات تثبيت CodeDeploy لتحويل حركة المرور، مما يقلل من خطر التثبيت باستخدام تثبيتات كاناري تدريجية باستخدام AWS Lambda و CDK TypeScript."},"useCases":{"en":["Automating canary deployments for AWS Lambda functions","Configuring CloudWatch alarms for automated rollback","Setting up CodeDeploy deployment groups for traffic shifting"],"zh":["自动化 AWS Lambda 函数的金丝雀部署","配置 CloudWatch 报警以实现自动回滚","设置 CodeDeploy 部署组以进行流量转移"],"ja":["AWS Lambda 関数のカナリア デプロイメントを自動化する","自動ロールバックのための CloudWatch アラームを構成する","CodeDeploy デプロイ グループを作成してトラフィック シフトを行う"],"ko":["AWS Lambda 함수의 카나리 배포를 자동화하는 것","자동 롤백을 위한 CloudWatch 알람을 구성하는 것","CodeDeploy 배포 그룹을 생성하여 트래픽 시프트를 수행하는 것"],"es":["Automatizar implementaciones canarias para funciones de AWS Lambda","Configurar alarmas de CloudWatch para reversión automatizada","Configurar grupos de implementación de CodeDeploy para cambio de tráfico"],"fr":["Automatiser les déploiements canaris pour les fonctions AWS Lambda","Configurer des alarmes CloudWatch pour une réversibilité automatique","Configurer des groupes de déploiement CodeDeploy pour le changement de trafic"],"de":["Automatisieren von Kanarien-Bereitstellungen für AWS Lambda-Funktionen","Konfigurieren von CloudWatch-Alarmanlagen für eine automatische Rückkehr","Konfigurieren von CodeDeploy-Deploy-Gruppen für den Traffikumschalter"],"pt":["Automatizar implantações canary para funções AWS Lambda","Configurar alarmes do CloudWatch para rollback automatizado","Configurar grupos de implantação do CodeDeploy para mudança de tráfego"],"ru":["Автоматизировать канареечные развертывания для функций AWS Lambda","Настроить сигналы тревоги CloudWatch для автоматического отката","Настроить группы развертывания CodeDeploy для переадресации трафика"],"ar":["تأتمتة تثبيتات كاناري لدوال AWS Lambda","تكوين إشعارات CloudWatch للتراجع التلقائي","تكوين مجموعات تثبيت CodeDeploy لتحويل حركة المرور"]},"limitations":{"en":["Requires AWS account and CDK TypeScript setup","Limited to AWS Lambda deployments","Needs CloudWatch and CodeDeploy configuration"],"zh":["需要 AWS 账户和 CDK TypeScript 设置","仅限 AWS Lambda 部署","需要 CloudWatch 和 CodeDeploy 配置"],"ja":["AWS アカウントと CDK TypeScript の設定が必要","AWS Lambda デプロイメントのみに限定される","CloudWatch と CodeDeploy の構成が必要"],"ko":["AWS 계정 및 CDK TypeScript 설정이 필요함","AWS Lambda 배포만 가능","CloudWatch 및 CodeDeploy 구성이 필요함"],"es":["Requiere una cuenta de AWS y una configuración de CDK TypeScript","Limitado a implementaciones de AWS Lambda","Requiere configuración de CloudWatch y CodeDeploy"],"fr":["Nécessite un compte AWS et une configuration CDK TypeScript","Limité aux déploiements AWS Lambda","Nécessite une configuration CloudWatch et CodeDeploy"],"de":["Benötigt ein AWS-Konto und eine CDK TypeScript-Konfiguration","Begrenzt auf AWS Lambda-Bereitstellungen","Benötigt eine CloudWatch- und CodeDeploy-Konfiguration"],"pt":["Requer conta da AWS e configuração do CDK TypeScript","Limitado a implantações do AWS Lambda","Necessita de configuração do CloudWatch e CodeDeploy"],"ru":["Требуется учетная запись AWS и настройка CDK TypeScript","Ограничен развертыванием AWS Lambda","Требуется настройка CloudWatch и CodeDeploy"],"ar":["يتطلب حساب AWS و إعداد CDK TypeScript","محدود بتثبيتات AWS Lambda","يحتاج إلى إعداد CloudWatch و CodeDeploy"]},"version":4},"contentHash":"bf13ba527ac817430840b0c5588dc5da775c8b352f11c3eedea70def1c1fdc7a","qualityScore":42}');
