INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mariotoffia/gobridge/deployment-aws-canary-setup', 'deployment-aws-canary-setup', 'mariotoffia', 'gobridge', 'community', 'deployment-aws-canary-setup mariotoffia gobridge community The deployment-aws-canary-setup skill enables developers to set up progressive canary deployments for AWS Lambda using CDK TypeScript, reducing deployment risk by routing a small percentage of traffic to new code first. 本技能教您如何设置AWS Lambda的进阶金丝雀部署，使用CDK TypeScript配置Lambda版本和别名，CloudWatch报警和CodeDeploy部署组 このスキルでは、AWS Lambdaのカナリアデプロイを設定する方法を学び、CDK TypeScriptを使用してLambdaバージョンとエイリアス、CloudWatchアラーム、CodeDeployデプロイグループを構成する 본 스킬은 AWS Lambda의 카나리 배포를 설정하는 방법을 가르쳐주며, CDK TypeScript를 사용하여 Lambda 버전 및 별칭, CloudWatch 알림 및 CodeDeploy 배포 그룹을 구성 Esta habilidad enseña a configurar implementaciones de canary progresivas para AWS Lambda. Aprende a configurar versiones y alias de Lambda, alarmas de CloudWatch y grupos de implementación de CodeDeploy Cette compétence vous enseigne à configurer des déploiements canary progressifs pour AWS Lambda. Découvrez comment configurer des versions et des alias Lambda, des alarmes CloudWatch et des groupes de déploiement CodeDeploy Diese Fähigkeit lehrt die Einrichtung von progressiven Canary-Deployments für AWS Lambda. Erfahren Sie, wie Sie Lambda-Versionen und -Alias, CloudWatch-Alarme und CodeDeploy-Deployments-Gruppen konfigurieren Configuração de implantação de canary para AWS Lambda usando CDK TypeScript, reduzindo o risco de implantação com entregas progressivas Настройка прогрессивной канареечной доставки для AWS Lambda с помощью CDK TypeScript, снижающая риск доставки إعداد توزيع Canary التقدمي لبرنامج AWS Lambda باستخدام CDK TypeScript، لتقليل مخاطر التوزيع how to use deployment-aws-canary-setup what is deployment-aws-canary-setup deployment-aws-canary-setup vs AWS CodePipeline deployment-aws-canary-setup setup guide deployment-aws-canary-setup install AWS Lambda canary deployment best practices CDK TypeScript deployment-aws-canary-setup CodeDeploy traffic shifting tutorial CloudWatch alarms for automated rollback progressive deployment on AWS Lambda AWS金丝雀部署 CDK TypeScript Lambda版本 CloudWatch报警 CodeDeploy部署组 金丝雀部署设置 AWS Lambda函数 进阶部署 AIエージェント Configures Lambda versions and aliases for canary deployments Sets up CloudWatch alarms for automated rollback Creates CodeDeploy deployment groups for traffic shifting Routes a small percentage of traffic to new code first Gradually shifts traffic to new version based on performance Supports CDK TypeScript for infrastructure as code deployment-aws-canary-setup is a skill that teaches you how to configure Lambda versions and aliases, CloudWatch alarms, and CodeDeploy deployment groups for traffic shifting on AWS Lambda.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openjavis/clawdbot-python/gog', 'community', 'openjavis', 'clawdbot-python', 'openjavis/clawdbot-python', 'gog', 0, 0, 42, '2026-03-08T01:57:15.273Z', '2026-03-08T02:02:06.905Z', 'ceb5ee5bb4f0b9016694ed709180399fc75214b7b91a958e1aae1e1a351cb0b6', '{"id":"openjavis/clawdbot-python/gog","name":"gog","description":{"en":"The gog skill enables developers to integrate Gmail, Calendar, Drive, and other Google services into their applications using OAuth authentication. It benefits developers who need to automate tasks or build custom workflows.","zh":"gog是一种命令行工具，用于集成Gmail、Calendar、Drive等Google服务，支持OAuth认证和多账户管理","ja":"gogは、Gmail、Calendar、DriveなどのGoogleサービスを統合するコマンドラインツールで、OAuth認証と複数アカウント管理をサポートしています","ko":"gog는 Gmail, Calendar, Drive 등의 Google 서비스를 통합하는 명령어 인터페이스 도구로서 OAuth 인증 및 다중 계정 관리를 지원합니다","es":"gog es una herramienta de línea de comandos que permite interactuar con Gmail, Calendar, Drive y más. Requiere configuración de OAuth","fr":"gog est un outil en ligne de commande qui permet d''interagir avec Gmail, Calendar, Drive et plus. Il nécessite une configuration OAuth","de":"gog ist ein Kommandozeilen-Tool, das die Interaktion mit Gmail, Calendar, Drive und mehr ermöglicht. Es erfordert eine OAuth-Konfiguration","pt":"O gog é uma ferramenta de linha de comando para gerenciar serviços do Google. Configure-o para usar com Gmail, Calendar e mais.","ru":"gog - это инструмент командной строки для управления сервисами Google. Настройте его для работы с Gmail, Calendar и другими.","ar":"gog هو أداة سطر أوامر لتنظيم خدمات جوجل. ثبته لاستخدام جيميل وكالندر وغيرها."},"seo":{"title":{"en":"gog: OAuth Setup Guide for AI Agents","zh":"gog AI工具：Gmail/Calendar/Drive集成设置指南","ja":"gog AIエージェント：Gmail/Calendar/Drive統合セットアップガイド","ko":"gog AI 에이전트: Gmail/Calendar/Drive 통합 설정 가이드","es":"Guía de Configuración de gog para Gmail y Google Drive","fr":"Guide de Configuration de gog pour Gmail et Google Drive","de":"Konfigurationsleitfaden für gog mit Gmail und Google Drive","pt":"Guia de Configuração do gog para Desenvolvedores","ru":"Настройка gog для ИИ Агентов: Руководство","ar":"دليل تثبيت gog لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock gog''s full potential with our expert OAuth setup guide. Learn how to authenticate and use gog for Gmail, Calendar, and Drive integration today!","zh":"了解gog AI工具的技术细节，实现Gmail、Calendar、Drive等服务的集成和自动化","ja":"gog AIエージェントのテクニカルな詳細を学び、Gmail、Calendar、Driveなどのサービスを統合して自動化する","ko":"gog AI 에이전트의 기술적인 세부 사항을 알아보고 Gmail, Calendar, Drive 등의 서비스를 통합하여 자동화하십시오","es":"Aprende a configurar gog para interactuar con Gmail, Calendar, Drive y más con OAuth. Descubre los comandos comunes y la autenticación","fr":"Découvrez comment configurer gog pour interagir avec Gmail, Calendar, Drive et plus avec OAuth. Explorez les commandes communes et l''authentification","de":"Erfahren Sie, wie Sie gog für die Interaktion mit Gmail, Calendar, Drive und mehr mit OAuth konfigurieren. Entdecken Sie die gängigen Befehle und die Authent...","pt":"Aprenda a configurar o gog para Gmail, Calendar, Drive e mais. Descubra como usar comandos para gerenciar serviços do Google.","ru":"Узнайте, как настроить gog для работы с Gmail, Calendar, Drive и другими сервисами Google. Используйте команды для управления.","ar":"تعرف على كيفية تثبيت gog لجيميل وكالندر ودرايف وغيرها. استخدم أوامر لتنظيم خدمات جوجل."},"definition":{"en":"gog is a command-line tool that utilizes OAuth for authentication and interaction with Google services such as Gmail, Calendar, and Drive.","zh":"gog是一种AI工具，提供Gmail、Calendar、Drive等Google服务的命令行接口","ja":"gogは、Gmail、Calendar、DriveなどのGoogleサービスを提供するAIエージェントです","ko":"gog는 Gmail, Calendar, Drive 등의 Google 서비스를 제공하는 AI 에이전트입니다","es":"gog es un agente de inteligencia artificial que permite la interacción con servicios de Google","fr":"gog est un agent d''intelligence artificielle qui permet l''interaction avec les services Google","de":"gog ist ein KI-Agent, der die Interaktion mit Google-Diensten ermöglicht","pt":"gog é uma ferramenta de CLI para interagir com serviços do Google, como Gmail e Calendar.","ru":"gog - это инструмент командной строки для взаимодействия с сервисами Google, такими как Gmail и Calendar.","ar":"gog هو أداة سطر أوامر للتفاعل مع خدمات جوجل مثل جيميل وكالندر."},"features":{"en":["Supports OAuth setup using client_secret.json files","Enables authentication for multiple Google services including Gmail, Calendar, and Drive","Allows for Gmail search using custom queries like ''newer_than:7d''","Performs Gmail messages search with options to ignore threading and specify accounts","Sends plain text emails using the Gmail service"],"zh":["支持Gmail、Calendar、Drive、Contacts、Sheets、Docs等Google服务","OAuth认证支持，确保账户安全","多账户管理，方便切换和管理不同账户","命令行接口，灵活方便的操作体验","支持自定义搜索和过滤，快速找到所需信息"],"ja":["Gmail、Calendar、Drive、Contacts、Sheets、DocsなどのGoogleサービスをサポート","OAuth認証をサポートし、 アカウントのセキュリティを確保","複数アカウント管理をサポートし、異なるアカウントの切り替えと管理を容易に","コマンドラインインターフェイスを提供し、柔軟で便利な操作体験を実現","カスタム検索とフィルタリングをサポートし、必要な情報を迅速に見つける"],"ko":["Gmail, Calendar, Drive, Contacts, Sheets, Docs 등의 Google 서비스를 지원","OAuth 인증을 지원하여 계정 보안을 보장","다중 계정 관리를 지원하여 다른 계정의 전환 및 관리를 쉽게 함","명령어 인터페이스를 제공하여 유연하고 편리한操作 경험을 제공","사용자 지정 검색 및 필터링을 지원하여 필요한 정보를 신속하게 찾을 수 있음"],"es":["Autenticación con OAuth","Compatibilidad con Gmail, Calendar, Drive y más","Búsqueda de correos electrónicos y mensajes","Envío de correos electrónicos","Compatibilidad con múltiples cuentas"],"fr":["Authentification avec OAuth","Compatibilité avec Gmail, Calendar, Drive et plus","Recherche de courriels et de messages","Envoi de courriels","Compatibilité avec plusieurs comptes"],"de":["Authentifizierung mit OAuth","Kompatibilität mit Gmail, Calendar, Drive und mehr","Suche nach E-Mails und Nachrichten","Versand von E-Mails","Kompatibilität mit mehreren Konten"],"pt":["Autenticação OAuth para serviços do Google","Comandos para gerenciar Gmail, Calendar e Drive","Suporte a múltiplos serviços do Google","Filtragem de emails com comandos personalizados","Envio de emails com opções de formatação"],"ru":["Аутентификация OAuth для сервисов Google","Команды для управления Gmail, Calendar и Drive","Поддержка нескольких сервисов Google","Фильтрация писем с помощью пользовательских команд","Отправка писем с опциями форматирования"],"ar":["التحقق من OAuth لخدمات جوجل","أوامر لتنظيم جيميل وكالندر ودرايف","دعم لعدة خدمات جوجل","تصفية رسائل البريد الإلكتروني باستخدام أوامر مخصصة","إرسال رسائل البريد الإلكتروني مع خيارات تنسيق"]},"keywords":{"en":["how to use gog","gog oauth setup","gog alternative to Zapier","gog vs IFTTT","gog install guide","gog setup for developers","what is gog","gog for Gmail automation","gog Calendar integration"],"zh":["gog AI工具","Gmail命令行工具","Calendar命令行工具","Drive命令行工具","Google服务集成","OAuth认证","多账户管理","命令行接口"],"ja":["gog AIエージェント","Gmailコマンドラインツール","Calendarコマンドラインツール","Driveコマンドラインツール","Googleサービス統合","OAuth認証","複数アカウント管理","コマンドラインインターフェイス"],"ko":["gog AI 에이전트","Gmail 명령어 인터페이스 도구","Calendar 명령어 인터페이스 도구","Drive 명령어 인터페이스 도구","Google 서비스 통합","OAuth 인증","다중 계정 관리","명령어 인터페이스"],"es":["gog","agente de inteligencia artificial","herramienta de línea de comandos","Gmail","Google Drive","OAuth","autenticación","búsqueda de correos electrónicos"],"fr":["gog","agent d''intelligence artificielle","outil en ligne de commande","Gmail","Google Drive","OAuth","authentification","recherche de courriels"],"de":["gog","KI-Agent","Kommandozeilen-Tool","Gmail","Google Drive","OAuth","Authentifizierung","Suche nach E-Mails"],"pt":["gog cli","gog oauth","gog gmail","gog calendar","gog drive","ferramenta de linha de comando","gerenciamento de serviços do google"],"ru":["gog cli","gog oauth","gog gmail","gog calendar","gog drive","инструмент командной строки","управление сервисами google"],"ar":["gog cli","gog oauth","gog جيميل","gog كالندر","gog درايف","أداة سطر أوامر","تنظيم خدمات جوجل"]}},"owner":"openjavis","repo":"clawdbot-python","repoPath":"openjavis/clawdbot-python","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"gog","description":"Google Workspace CLI for Gmail, Calendar, Drive, Contacts, Sheets, and Docs.","bodyPreview":"# gog\n\nUse `gog` for Gmail/Calendar/Drive/Contacts/Sheets/Docs. Requires OAuth setup.\n\nSetup (once)\n\n- `gog auth credentials /path/to/client_secret.json`\n- `gog auth add you@gmail.com --services gmail,calendar,drive,contacts,docs,sheets`\n- `gog auth list`\n\nCommon commands\n\n- Gmail search: `gog gmail search ''newer_than:7d'' --max 10`\n- Gmail messages search (per email, ignores threading): `gog gmail messages search \"in:inbox from:ryanair.com\" --max 20 --account you@example.com`\n- Gmail send (plain","body":"# gog\n\nUse `gog` for Gmail/Calendar/Drive/Contacts/Sheets/Docs. Requires OAuth setup.\n\nSetup (once)\n\n- `gog auth credentials /path/to/client_secret.json`\n- `gog auth add you@gmail.com --services gmail,calendar,drive,contacts,docs,sheets`\n- `gog auth list`\n\nCommon commands\n\n- Gmail search: `gog gmail search ''newer_than:7d'' --max 10`\n- Gmail messages search (per email, ignores threading): `gog gmail messages search \"in:inbox from:ryanair.com\" --max 20 --account you@example.com`\n- Gmail send (plain): `gog gmail send --to a@b.com --subject \"Hi\" --body \"Hello\"`\n- Gmail send (multi-line): `gog gmail send --to a@b.com --subject \"Hi\" --body-file ./message.txt`\n- Gmail send (stdin): `gog gmail send --to a@b.com --subject \"Hi\" --body-file -`\n- Gmail send (HTML): `gog gmail send --to a@b.com --subject \"Hi\" --body-html \"<p>Hello</p>\"`\n- Gmail draft: `gog gmail drafts create --to a@b.com --subject \"Hi\" --body-file ./message.txt`\n- Gmail send draft: `gog gmail drafts send <draftId>`\n- Gmail reply: `gog gmail send --to a@b.com --subject \"Re: Hi\" --body \"Reply\" --reply-to-message-id <msgId>`\n- Calendar list events: `gog calendar events <calendarId> --from <iso> --to <iso>`\n- Calendar create event: `gog calendar create <calendarId> --summary \"Title\" --from <iso> --to <iso>`\n- Calendar create with color: `gog calendar create <calendarId> --summary \"Title\" --from <iso> --to <iso> --event-color 7`\n- Calendar update event: `gog calendar update <calendarId> <eventId> --summary \"New Title\" --event-color 4`\n- Calendar show colors: `gog calendar colors`\n- Drive search: `gog drive search \"query\" --max 10`\n- Contacts: `gog contacts list --max 20`\n- Sheets get: `gog sheets get <sheetId> \"Tab!A1:D10\" --json`\n- Sheets update: `gog sheets update <sheetId> \"Tab!A1:B2\" --values-json ''[[\"A\",\"B\"],[\"1\",\"2\"]]'' --input USER_ENTERED`\n- Sheets append: `gog sheets append <sheetId> \"Tab!A:C\" --values-json ''[[\"x\",\"y\",\"z\"]]'' --insert INSERT_ROWS`\n- Sheets clear: `gog sheets clear <sheetId> \"Tab!A2:Z\"`\n- Sheets metadata: `gog sheets metadata <sheetId> --json`\n- Docs export: `gog docs export <docId> --format txt --out /tmp/doc.txt`\n- Docs cat: `gog docs cat <docId>`\n\nCalendar Colors\n\n- Use `gog calendar colors` to see all available event colors (IDs 1-11)\n- Add colors to events with `--event-color <id>` flag\n- Event color IDs (from `gog calendar colors` output):\n  - 1: #a4bdfc\n  - 2: #7ae7bf\n  - 3: #dbadff\n  - 4: #ff887c\n  - 5: #fbd75b\n  - 6: #ffb878\n  - 7: #46d6db\n  - 8: #e1e1e1\n  - 9: #5484ed\n  - 10: #51b749\n  - 11: #dc2127\n\nEmail Formatting\n\n- Prefer plain text. Use `--body-file` for multi-paragraph messages (or `--body-file -` for stdin).\n- Same `--body-file` pattern works for drafts and replies.\n- `--body` does not unescape `\\n`. If you need inline newlines, use a heredoc or `$''Line 1\\n\\nLine 2''`.\n- Use `--body-html` only when you need rich formatting.\n- HTML tags: `<p>` for paragraphs, `<br>` for line breaks, `<strong>` for bold, `<em>` for italic, `<a href=\"url\">` for links, `<ul>`/`<li>` for lists.\n- Example (plain text via stdin):\n\n  ```bash\n  gog gmail send --to recipient@example.com \\\n    --subject \"Meeting Follow-up\" \\\n    --body-file - <<''EOF''\n  Hi Name,\n\n  Thanks for meeting today. Next steps:\n  - Item one\n  - Item two\n\n  Best regards,\n  Your Name\n  EOF\n  ```\n\n- Example (HTML list):\n  ```bash\n  gog gmail send --to recipient@example.com \\\n    --subject \"Meeting Follow-up\" \\\n    --body-html \"<p>Hi Name,</p><p>Thanks for meeting today. Here are the next steps:</p><ul><li>Item one</li><li>Item two</li></ul><p>Best regards,<br>Your Name</p>\"\n  ```\n\nNotes\n\n- Set `GOG_ACCOUNT=you@gmail.com` to avoid repeating `--account`.\n- For scripting, prefer `--json` plus `--no-input`.\n- Sheets values can be passed via `--values-json` (recommended) or as inline rows.\n- Docs supports export/cat/copy. In-place edits require a Docs API client (not in gog).\n- Confirm before sending mail or creating events.\n- `gog gmail search` returns one row per thread; use `gog gmail messages search` when you need every individual email returned separately.\n"},"lastSynced":"2026-03-08T02:02:06.905Z","agentAnalysis":{"suitability":{"en":"Ideal for Automation Agents requiring comprehensive Google Workspace integration via OAuth.","zh":"适用于需要通过OAuth进行全面Google Workspace集成的自动化代理。","ja":"OAuthを介したGoogle Workspaceの包括的な統合を必要とする自動化エージェントに適しています。","ko":"OAuth를 통해 전체 Google Workspace 통합이 필요한 자동화 에이전트에 적합합니다.","es":"Ideal para Automation Agents que requieren una integración completa de Google Workspace mediante OAuth.","fr":"Idéal pour les Automation Agents nécessitant une intégration complète de Google Workspace via OAuth.","de":"Ideal für Automation Agents, die eine umfassende Google Workspace-Integration über OAuth benötigen.","pt":"Ideal para Agentes de Automação que exigem integração abrangente do Google Workspace via OAuth.","ru":"Идеально для агентов автоматизации, требующих полной интеграции с Google Workspace через OAuth.","ar":"مثالي للوكلاء الآليين الذين يتطلبون تكاملًا شاملاً مع مساحة عمل جوجل عبر OAuth."},"recommendation":{"en":"Enables direct access to Gmail, Calendar, Drive, Contacts, Sheets, and Docs through OAuth authentication. Provides programmatic control for automating email workflows, scheduling, and document management without manual API setup.","zh":"通过OAuth身份验证，实现直接访问Gmail、日历、Drive、联系人、Sheets和Docs。提供程序化控制，用于自动执行电子邮件工作流、调度和文档管理，无需手动设置API。","ja":"OAuth認証を介して、Gmail、カレンダー、Drive、連絡先、Sheets、Docsへの直接アクセスを可能にします。電子メールのワークフロー、スケジューリング、ドキュメント管理の自動化のためのプログラム制御を提供し、手動でのAPI設定は不要です。","ko":"OAuth 인증을 통해 Gmail, 달력, Drive, 연락처, 시트, 다큐먼트에 직접 액세스할 수 있습니다. 이메일 워크플로, 스케줄링, 문서 관리를 자동화하기 위한 프로그램 제어를 제공하며 수동 API 설정은 필요하지 않습니다.","es":"Permite el acceso directo a Gmail, Calendar, Drive, Contacts, Sheets y Docs mediante autenticación OAuth. Proporciona control programático para automatizar flujos de trabajo de correo electrónico, programación y gestión de documentos sin configuración manual de API.","fr":"Permet un accès direct à Gmail, Calendar, Drive, Contacts, Sheets et Docs via l''authentification OAuth. Fournit un contrôle programmatique pour automatiser les workflows d''e-mail, la planification et la gestion de documents sans configuration manuelle des API.","de":"Ermöglicht direkten Zugriff auf Gmail, Calendar, Drive, Contacts, Sheets und Docs über OAuth-Authentifizierung. Bietet programmatische Steuerung zur Automatisierung von E-Mail-Workflows, Terminplanung und Dokumentenverwaltung ohne manuelle API-Einrichtung.","pt":"Habilita acesso direto ao Gmail, Calendário, Drive, Contatos, Planilhas e Docs por meio da autenticação OAuth. Fornece controle programático para automatizar fluxos de trabalho de e-mail, agendamento e gerenciamento de documentos sem configuração manual de API.","ru":"Предоставляет прямой доступ к Gmail, Календарю, Диску, Контактам, Таблицам и Документам через аутентификацию OAuth. Предоставляет программный контроль для автоматизации рабочих процессов электронной почты, планирования и управления документами без ручной настройки API.","ar":"يمكن الوصول المباشر إلى جيميل، التقويم، درايف، جهات الاتصال، الأوراق والوثائق من خلال المصادقة OAuth. يوفر التحكم البرمجي لتحسين سير عمل البريد الإلكتروني والتخطيط وإدارة الوثائق بدون إعداد يدوي ل API."},"useCases":{"en":["Automating Gmail message searches with advanced query filters","Scheduling calendar events programmatically","Managing Google Drive files and documents through automated workflows"],"zh":["使用高级查询过滤器自动执行Gmail消息搜索","程序化地安排日历事件","通过自动化工作流管理Google Drive文件和文档"],"ja":["高度なクエリフィルタを使用してGmailメッセージの検索を自動化する","カレンダーイベントをプログラム的にスケジュールする","自動化されたワークフローを介してGoogle Driveのファイルとドキュメントを管理する"],"ko":["고급 쿼리 필터를 사용하여 Gmail 메시지 검색을 자동화하기","프로그램으로 일정 이벤트를 예약하기","자동화된 워크플로우를 통해 Google Drive 파일 및 문서 관리하기"],"es":["Automatización de búsquedas de mensajes de Gmail con filtros de consulta avanzados","Programación de eventos de calendario de forma programática","Gestión de archivos y documentos de Google Drive mediante flujos de trabajo automatizados"],"fr":["Automatisation des recherches de messages Gmail avec des filtres de requête avancés","Planification d''événements de calendrier de manière programmatique","Gestion des fichiers et documents Google Drive via des workflows automatisés"],"de":["Automatisierung von Gmail-Nachrichtensuchen mit erweiterten Abfragefiltern","Programmatische Planung von Kalenderereignissen","Verwaltung von Google Drive-Dateien und -Dokumenten durch automatisierte Workflows"],"pt":["Automating Gmail message searches with advanced query filters","Agendamento de eventos de calendário de forma programática","Gerenciamento de arquivos e documentos do Google Drive por meio de fluxos de trabalho automatizados"],"ru":["Автоматизация поиска сообщений Gmail с расширенными фильтрами запросов","Программное планирование событий календаря","Управление файлами и документами Google Диска через автоматизированные рабочие процессы"],"ar":["تحسين عمليات البحث عن الرسائل في جيميل باستخدام مرشحات استعلام متقدمة","جدولة أحداث التقويم بطريقة برمجية","إدارة الملفات والوثائق في جوجل درايف من خلال سير العمل الآلي"]},"limitations":{"en":["Requires OAuth setup with client_secret.json","Needs per-account service authorization (gmail,calendar,etc.)","Limited to Google Workspace services only"],"zh":["需要使用client_secret.json进行OAuth设置","需要每个帐户的服务授权（gmail、calendar等）","仅限Google Workspace服务"],"ja":["client_secret.jsonを使用したOAuthの設定が必要","各アカウントごとのサービス認証（gmail、calendarなど）が必要","Google Workspaceサービスのみに限定される"],"ko":["client_secret.json을 사용한 OAuth 설정이 필요합니다.","각 계정별 서비스 인증(gmail, 달력 등) 필요","Google Workspace 서비스에만 제한됨"],"es":["Requiere configuración de OAuth con client_secret.json","Necesita autorización de servicio por cuenta (gmail, calendar, etc.)","Limitado solo a servicios de Google Workspace"],"fr":["Nécessite une configuration OAuth avec client_secret.json","Nécessite une autorisation de service par compte (gmail, calendar, etc.)","Limité aux services Google Workspace uniquement"],"de":["Erfordert OAuth-Einrichtung mit client_secret.json","Benötigt Service-Autorisierung pro Konto (gmail, calendar, etc.)","Beschränkt auf Google Workspace-Dienste"],"pt":["Exige configuração OAuth com client_secret.json","Necessita de autorização de serviço por conta (gmail,calendar,etc.)","Limitado aos serviços do Google Workspace apenas"],"ru":["Требует настройки OAuth с client_secret.json","Требует авторизации службы для каждой учетной записи (gmail,calendar и т. д.)","Ограничен только сервисами Google Workspace"],"ar":["يتطلب إعداد OAuth مع client_secret.json","يحتاج إلى تفويض خدمة لكل حساب (جيميل، تقويم، إلخ)","محدود بخدمات مساحة عمل جوجل فقط"]},"version":4},"contentHash":"ceb5ee5bb4f0b9016694ed709180399fc75214b7b91a958e1aae1e1a351cb0b6","qualityScore":42}');
