INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openjavis/clawdbot-python/gog', 'gog', 'openjavis', 'clawdbot-python', 'community', 'gog openjavis clawdbot-python community The gog skill enables developers to integrate Gmail, Calendar, Drive, and other Google services into their applications using OAuth authentication. It benefits developers who need to automate tasks or build custom workflows. gog是一种命令行工具，用于集成Gmail、Calendar、Drive等Google服务，支持OAuth认证和多账户管理 gogは、Gmail、Calendar、DriveなどのGoogleサービスを統合するコマンドラインツールで、OAuth認証と複数アカウント管理をサポートしています gog는 Gmail, Calendar, Drive 등의 Google 서비스를 통합하는 명령어 인터페이스 도구로서 OAuth 인증 및 다중 계정 관리를 지원합니다 gog es una herramienta de línea de comandos que permite interactuar con Gmail, Calendar, Drive y más. Requiere configuración de OAuth gog est un outil en ligne de commande qui permet d''interagir avec Gmail, Calendar, Drive et plus. Il nécessite une configuration OAuth gog ist ein Kommandozeilen-Tool, das die Interaktion mit Gmail, Calendar, Drive und mehr ermöglicht. Es erfordert eine OAuth-Konfiguration O gog é uma ferramenta de linha de comando para gerenciar serviços do Google. Configure-o para usar com Gmail, Calendar e mais. gog - это инструмент командной строки для управления сервисами Google. Настройте его для работы с Gmail, Calendar и другими. gog هو أداة سطر أوامر لتنظيم خدمات جوجل. ثبته لاستخدام جيميل وكالندر وغيرها. how to use gog gog oauth setup gog alternative to Zapier gog vs IFTTT gog install guide gog setup for developers what is gog gog for Gmail automation gog Calendar integration gog AI工具 Gmail命令行工具 Calendar命令行工具 Drive命令行工具 Google服务集成 OAuth认证 多账户管理 命令行接口 Supports OAuth setup using client_secret.json files Enables authentication for multiple Google services including Gmail, Calendar, and Drive Allows for Gmail search using custom queries like ''newer_than:7d'' Performs Gmail messages search with options to ignore threading and specify accounts Sends plain text emails using the Gmail service gog is a command-line tool that utilizes OAuth for authentication and interaction with Google services such as Gmail, Calendar, and Drive.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EvanBacon/apple-health/expo-modules', 'community', 'EvanBacon', 'apple-health', 'EvanBacon/apple-health', 'expo-modules', 0, 0, 42, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:30.239Z', '778c219951b45d3f454b9fe5f2e255380db39a3fa47dc1cd0e1aa7cbf6ef8d62', '{"id":"EvanBacon/apple-health/expo-modules","name":"expo-modules","description":{"en":"expo-modules provides Apple HealthKit bindings for Expo, enabling developers to access native health and fitness data. It benefits developers building health-related applications.","zh":"expo-modules 为 Expo 提供 Apple HealthKit 绑定，遵循现代 Web 模块设计原则，实现 100% 向后兼容性","ja":"expo-modules は Expo に Apple HealthKit バインディングを提供し、モダン Web モジュール設計原則に従い、100% の後方互換性を実現します","ko":"expo-modules는 Expo에 Apple HealthKit 바인딩을 제공하며, 현대적인 웹 모듈 디자인 원칙을 따르며 100%의 이전 버전과 호환됩니다","es":"expo-modules proporciona enlaces de Apple HealthKit para Expo, permitiendo diseñar APIs nativas con estándares modernos","fr":"Les modules expo offrent des liaisons Apple HealthKit pour Expo, permettant de concevoir des API natives avec des standards modernes","de":"expo-modules bietet Apple HealthKit-Bindings für Expo, um native APIs mit modernen Standards zu entwerfen","pt":"O expo-modules fornece bindings do Apple HealthKit para o Expo, permitindo que os desenvolvedores criem aplicativos móveis com funcionalidades de saúde","ru":"expo-modules предоставляет биндинги Apple HealthKit для Expo, позволяя разработчикам создавать мобильные приложения со здоровьем","ar":"expo-modules يوفر ربطات Apple HealthKit لمنصة Expo، مما يسمح للمطورين بإنشاء تطبيقات الجوال مع ميزات الصحة"},"seo":{"title":{"en":"expo-modules: Apple HealthKit Bindings Setup Guide | AI A...","zh":"expo-modules 设置指南：Apple HealthKit 绑定","ja":"expo-modules セットアップガイド：Apple HealthKit バインディング","ko":"expo-modules 설정 가이드: Apple HealthKit 바인딩","es":"Guía de configuración de expo-modules para Apple HealthKit","fr":"Configurer les modules expo pour Apple HealthKit","de":"Einrichtungsleitfaden für expo-modules mit Apple HealthKit","pt":"Guia de Configuração do expo-modules para Desenvolvedores","ru":"ИИ Агенты: expo-modules Настройка для Разработчиков","ar":"دليل إعداد expo-modules لمنصة Expo"},"description":{"en":"Unlock native Apple HealthKit functionality in Expo with expo-modules. Learn how to integrate seamless health and fitness tracking into your apps today!","zh":"了解 expo-modules 的技术细节，包括设计原则、API 设计和最佳实践，用于 Apple HealthKit 的集成","ja":"expo-modules のテクニカル詳細を学ぶ、設計原則、API デザイン、ベストプラクティスなど、Apple HealthKit の統合に役立ちます","ko":"expo-modules의 기술 세부 사항을 알아보세요. Apple HealthKit 통합을 위한 설계 원칙, API 디자인 및 최선의 실践","es":"Aprende a utilizar expo-modules para integrar Apple HealthKit en tus aplicaciones móviles con estándares de módulos nativos","fr":"Découvrez comment utiliser les modules expo pour intégrer Apple HealthKit dans vos applications mobiles avec des standards de modules natifs","de":"Erfahren Sie, wie Sie expo-modules verwenden, um Apple HealthKit in Ihre mobilen Anwendungen mit nativen Modulstandards zu integrieren","pt":"Aprenda a configurar o expo-modules para criar aplicativos móveis com Apple HealthKit bindings","ru":"ИИ Агенты: узнайте, как настроить expo-modules для создания мобильных приложений с Apple HealthKit","ar":"تعرف على كيفية إعداد expo-modules لإنشاء تطبيقات الجوال مع روابط Apple HealthKit"},"definition":{"en":"expo-modules is a set of Apple HealthKit bindings for Expo, designed to provide native API access for seamless health and fitness tracking integration.","zh":"expo-modules 是 Expo 的一个模块，提供 Apple HealthKit 的绑定，用于移动应用开发","ja":"expo-modules は Expo のモジュールの一つで、Apple HealthKit のバインディングを提供し、モバイルアプリ開発に役立ちます","ko":"expo-modules는 Expo의 모듈 중 하나로, Apple HealthKit 바인딩을 제공하여 모바일 애플리케이션 개발에 도움이 됩니다","es":"expo-modules es un conjunto de enlaces de Apple HealthKit para Expo que permiten el diseño de APIs nativas","fr":"Les modules expo sont un ensemble de liaisons Apple HealthKit pour Expo qui permettent la conception d''API natives","de":"expo-modules ist eine Sammlung von Apple HealthKit-Bindings für Expo, die das Entwerfen von nativen APIs ermöglichen","pt":"O que é expo-modules? É um módulo que fornece bindings do Apple HealthKit para o Expo","ru":"Что такое expo-modules? Это модуль, предоставляющий биндинги Apple HealthKit для Expo","ar":"ما هو expo-modules؟ هو وحدة توفر ربطات Apple HealthKit لمنصة Expo"},"features":{"en":["Designs native APIs inspired by modern web modules like std:kv-storage and clipboard","Aims for 100% backwards compatibility like the web","Creates escape hatches for single-platform functionality","Exposes native functionality directly, avoiding extraneous abstractions","Prefers string union types for API options instead of boolean flags or enums","Uses sync methods when possible, avoiding unnecessary async methods"],"zh":["设计原则：遵循现代 Web 模块设计原则","API 设计：直接暴露原生功能，避免多余抽象","后向兼容性：实现 100% 的后向兼容性","同步方法：使用同步方法代替异步方法","字符串联合类型：使用字符串联合类型代替布尔标志"],"ja":["設計原則：モダン Web モジュール設計原則に従う","API デザイン：直接ネイティブ機能を公開し、余分な抽象を避ける","後方互換性：100% の後方互換性を実現","同期方法：同期方法を使用して非同期方法を置き換える","文字列ユニオン型：文字列ユニオン型を使用してブールフラグを置き換える"],"ko":["설계 원칙: 현대적인 웹 모듈 디자인 원칙을 따름","API 디자인: 직접 네이티브 기능을公开하며, 불필요한 추상을 피함","이전 버전과 호환성: 100%의 이전 버전과 호환성을 구현","동기화 방법: 동기화 방법을 사용하여 비동기 방법을 대체","문자열 유니온 타입: 문자열 유니온 타입을 사용하여 불린 플래그를 대체"],"es":["Diseño de APIs nativas con estándares modernos","Compatibilidad hacia atrás del 100% como la web","Escape hatches para funcionalidad de una sola plataforma","Exposición directa de funcionalidad nativa","Métodos síncronos en lugar de asíncronos cuando sea posible"],"fr":["Conception d''API natives avec des standards modernes","Compatibilité vers l''arrière de 100% comme le web","Échappatoires pour la fonctionnalité d''une seule plate-forme","Exposition directe de la fonctionnalité native","Méthodes synchrones au lieu d''asynchrones lorsque cela est possible"],"de":["Entwurf von nativen APIs mit modernen Standards","100% rückwärts kompatibel wie das Web","Fluchtwege für Single-Platform-Funktionalität","Direkte Exposition von nativer Funktionalität","Synchrone Methoden anstelle von asynchronen, wenn möglich"],"pt":["Design de APIs nativas inspiradas em especificações W3C","Compatibilidade de 100% para trás como a web","Criação de escape hatches para funcionalidades de plataforma única","Exposição direta de funcionalidades nativas","Métodos síncronos em vez de assíncronos quando possível"],"ru":["Дизайн родных API, вдохновлённый спецификациями W3C","100% обратная совместимость, как и веб","Создание побега для функциональности одной платформы","Прямое暴露 родных функциональностей","Синхронные методы вместо асинхронных, когда это возможно"],"ar":["تصميم واجهات برمجة التطبيقات الأصلية مستوحاة من مواصفات W3C","متوافق مع 100% للخلف مثل الويب","إنشاء ملاذ للوظائف منصة واحدة","التعرض المباشر للوظائف الأصلية","أساليب متزامنة بدلاً من غير المتزامنة عندما يكون ذلك ممكنًا"]},"keywords":{"en":["how to use expo-modules","expo-modules alternative","expo-modules install","what is expo-modules","expo-modules vs react-native","expo-modules setup guide","expo-modules documentation","expo-modules HealthKit integration"],"zh":["expo-modules","Apple HealthKit","Expo","移动应用开发","现代 Web 模块","API 设计","后向兼容性","AIエージェント"],"ja":["expo-modules","Apple HealthKit","Expo","モバイルアプリ開発","モダン Web モジュール","API デザイン","後方互換性","AIエージェント"],"ko":["expo-modules","Apple HealthKit","Expo","모바일 애플리케이션 개발","현대적인 웹 모듈","API 디자인","이전 버전과 호환성","AI 에이전트"],"es":["expo-modules","Apple HealthKit","APIs nativas","estándares modernos","compatibilidad hacia atrás","funcionalidad de una sola plataforma","exposición de funcionalidad nativa","métodos síncronos","desarrollo de aplicaciones móviles"],"fr":["modules expo","Apple HealthKit","API natives","standards modernes","compatibilité vers l''arrière","fonctionnalité d''une seule plate-forme","exposition de fonctionnalité native","méthodes synchrones","développement d''applications mobiles"],"de":["expo-modules","Apple HealthKit","native APIs","moderne Standards","Rückwärtskompatibilität","Single-Platform-Funktionalität","Exposition von nativer Funktionalität","synchrone Methoden","Entwicklung von mobilen Anwendungen"],"pt":["expo-modules","Apple HealthKit","Expo","desenvolvimento móvel","APIs nativas","compatibilidade para trás","funcionalidades de saúde"],"ru":["expo-modules","Apple HealthKit","Expo","мобильное развитие","родные API","обратная совместимость","функциональности здоровья"],"ar":["expo-modules","Apple HealthKit","Expo","تطوير الجوال","واجهات برمجة التطبيقات الأصلية","التوافق للخلف","ميزات الصحة"]}},"owner":"EvanBacon","repo":"apple-health","repoPath":"EvanBacon/apple-health","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"expo-modules","description":"Building great Expo native modules for iOS and Android. Views, APIs, Marshalling, Shared Objects, Expo Documentation, Verifying Expo modules.","bodyPreview":"## Great module standards\n\n- Design native APIs as if you contributing W3C specs for the browser, take inspiration from modern web modules. eg `std:kv-storage`, `clipboard`.\n- Aim for 100% backwards compatibility like the web.\n- Create escape hatches for single-platform functionality.\n- Avoid extraneous abstractions. Directly expose native functionality.\n- Avoid unnecessary async methods. Use sync methods when possible.\n- Prefer string union types for API options instead of boolean flags, enums,","body":"## Great module standards\n\n- Design native APIs as if you contributing W3C specs for the browser, take inspiration from modern web modules. eg `std:kv-storage`, `clipboard`.\n- Aim for 100% backwards compatibility like the web.\n- Create escape hatches for single-platform functionality.\n- Avoid extraneous abstractions. Directly expose native functionality.\n- Avoid unnecessary async methods. Use sync methods when possible.\n- Prefer string union types for API options instead of boolean flags, enums, or multiple parameters. eg instead of `capture(options: { isHighQuality: boolean })`, use `capture(options: { quality: ''high'' | ''medium'' | ''low'' })`.\n- Marshalling is awesome for platform-specific APIs.\n- New Architecture only. NEVER support legacy React Native architecture.\n- ALWAYS use only Expo modules API.\n- Prefer Swift and Kotlin.\n- Use optionality for availability checks as opposed to extraneous `isAvailable` functions or constants. eg `snapshot.capture?.()` instead of `snapshot.isAvailable && snapshot.capture()`.\n- ALWAYS support the latest and greatest API features.\n\nExample of a GREAT Expo module:\n\n```ts\nimport { NativeModule } from \"expo\";\n\ndeclare class AppClipModule extends NativeModule<{}> {\n  prompt(): void;\n  isAppClip?: boolean;\n}\n\n// This call loads the native module object from the JSI.\nconst AppClipNative =\n  typeof expo !== \"undefined\"\n    ? (expo.modules.AppClip as AppClipModule) ?? {}\n    : {};\n\nif (AppClipNative?.isAppClip) {\n  navigator.appClip = {\n    prompt: AppClipNative.prompt,\n  };\n}\n\n// Add types for the global `navigator.appClip` object.\ndeclare global {\n  interface Navigator {\n    /**\n     * Only available in an App Clip context.\n     * @expo\n     */\n    appClip?: {\n      /** Open the SKOverlay */\n      prompt: () => void;\n    };\n  }\n}\n\nexport {};\n```\n\n- Simple web-style interface.\n- Global type augmentation for easy access.\n- Docs in the type definitions.\n- Optional availability checks instead of extraneous `isAvailable` methods.\n\nExample of a POOR Expo module:\n\n```ts\nimport { NativeModulesProxy } from \"expo-modules-core\";\nconst { ExpoAppClip } = NativeModulesProxy;\nexport default {\n  promptAppClip() {\n    return ExpoAppClip.promptAppClip();\n  },\n  isAppClipAvailable() {\n    return ExpoAppClip.isAppClipAvailable();\n  },\n};\n```\n\n## Great documentation\n\n- If you have a function like `isAvailable()`, explain why it exists in the docs. Research cases where it may return false such as in a simulator or particular OS version.\n- Document OS version availability for functions and constants in the type definitions.\n\n## BAD module standards\n\n- APIs that are hard to import, e.g. `import * as MediaLibrary from ''expo-media-library'';` instead of `import { MediaLibrary } from ''expo/media'';`\n- Extraneous abstractions over native functionality. The native module is installing on the global, do not wrap it in another layer for no reason.\n- Extraneous async methods when sync methods are possible.\n- Boolean flags instead of string union types for options.\n- Supporting legacy React Native architecture.\n\n## Views\n\nTake API inspiration from great web component libraries like BaseUI and Radix.\n\n- https://base-ui.com/react/components/progress\n- https://www.radix-ui.com/primitives/docs/components/progress\n\nConsider if you''re building a control or a display component. Controls should have more interactive APIs, while display components should be more declarative.\n\nPrefer functions on views instead of `useImperativeHandle` + `findNodeHandle`.\n\n```swift\nAsyncFunction(\"capture\") { (view, options: Options) -> Ref in\n  return try capture(self.appContext, view)\n}\n```\n\nRemember to export views in the module:\n\n```swift\nimport ExpoModulesCore\n\npublic class ExpoWebViewModule: Module {\n  public func definition() -> ModuleDefinition {\n    Name(\"ExpoWebView\")\n\n    View(ExpoWebView.self) {}\n  }\n}\n```\n\n## Marshalling-style API\n\nConsider this example https://github.com/EvanBacon/expo-shared-objects-haptics-example/blob/be90e92f8dba9b0807009502ab25c423c57e640d/modules/my-module/ios/MyModule.swift#L1C1-L178C2\n\nUsing `@retroactive Convertible` and `AnyArgument` to convert between Swift types and dictionaries enables passing complex data structures across the boundary without writing custom serialization code for each type.\n\n```swift\nextension CHHapticEventParameter: @retroactive Convertible, AnyArgument {\n    public static func convert(from value: Any?, appContext: AppContext) throws -> Self {\n        guard let dict = value as? [String: Any],\n              let parameterIDRaw = dict[\"parameterID\"] as? String,\n              let value = dict[\"value\"] as? Double else {\n            throw NotADictionaryException()\n        }\n        return Self(parameterID: CHHapticEvent.ParameterID(rawValue: parameterIDRaw), value: Float(value))\n    }\n}\n\nextension CHHapticEvent: @retroactive Convertible, AnyArgument {\n    public static func convert(from value: Any?, appContext: AppContext) throws -> Self {\n        guard let dict = value as? [String: Any],\n              let eventTypeRaw = dict[\"eventType\"] as? String,\n              let relativeTime = dict[\"relativeTime\"] as? Double else {\n            throw NotADictionaryException()\n        }\n        let eventType = CHHapticEvent.EventType(rawValue: eventTypeRaw)\n        let parameters = (dict[\"parameters\"] as? [[String: Any]])?.compactMap { paramDict -> CHHapticEventParameter? in\n            try? CHHapticEventParameter.convert(from: paramDict, appContext: appContext)\n        } ?? []\n        return Self(eventType: eventType, parameters: parameters, relativeTime: relativeTime)\n    }\n}\n\nextension CHHapticDynamicParameter: @retroactive Convertible, AnyArgument {\n    public static func convert(from value: Any?, appContext: AppContext) throws -> Self {\n        guard let dict = value as? [String: Any],\n              let parameterIDRaw = dict[\"parameterID\"] as? String,\n              let value = dict[\"value\"] as? Double,\n              let relativeTime = dict[\"relativeTime\"] as? Double else {\n            throw NotADictionaryException()\n        }\n\n        return Self(parameterID: CHHapticDynamicParameter.ID(rawValue: parameterIDRaw), value: Float(value), relativeTime: relativeTime)\n    }\n}\n\nextension CHHapticPattern: @retroactive Convertible, AnyArgument {\n    public static func convert(from value: Any?, appContext: AppContext) throws -> Self {\n        guard let dict = value as? [String: Any],\n              let eventsArray = dict[\"events\"] as? [[String: Any]] else {\n            throw NotADictionaryException()\n        }\n        let events = try eventsArray.map { eventDict -> CHHapticEvent in\n            try CHHapticEvent.convert(from: eventDict, appContext: appContext)\n        }\n        let parameters = (dict[\"parameters\"] as? [[String: Any]])?.compactMap { paramDict -> CHHapticDynamicParameter? in\n            return try? CHHapticDynamicParameter.convert(from: paramDict, appContext: appContext)\n        } ?? []\n        return try Self(events: events, parameters: parameters)\n    }\n}\n\ninternal final class NotAnArrayException: Exception {\n    override var reason: String {\n        \"Given value is not an array\"\n    }\n}\n\ninternal final class IncorrectArraySizeException: GenericException<(expected: Int, actual: Int)> {\n    override var reason: String {\n        \"Given array has unexpected number of elements: \\(param.actual), expected: \\(param.expected)\"\n    }\n}\n\ninternal final class NotADictionaryException: Exception {\n    override var reason: String {\n        \"Given value is not a dictionary\"\n    }\n}\n\n```\n\nLater this can be used to implement methods that accept complex data structures as arguments.\n\n```swift\nFunction(\"playPattern\") { (pattern: CHHapticPattern) in\n    let player = try hapticEngine.makePlayer(with: pattern)\n    try player.start(atTime: 0)\n}\n```\n\nUse shorthand where possible, especially when the JS value matches the Swift value:\n\n```swift\nProperty(\"__typename\") { $0.__typename }\n```\n\n## Shared objects\n\nShared objects are long-lived native instances that are shared to JS. They can be used to keep heavy state objects, such as a decoded bitmap, alive across React components, rather than spinning up a new native instance every time a component mounts.\n\n- https://docs.expo.dev/modules/shared-objects/\n- https://expo.dev/blog/the-real-world-impact-of-shared-objects\n\n## Interacting with AppDelegate\n\nTo interact with HealthKit, the module may need to respond to app lifecycle events. This can be done by implementing the `ExpoAppDelegateSubscriber` protocol.\n\n```swift\nimport ExpoModulesCore\n\npublic class ExpoHeadAppDelegateSubscriber: ExpoAppDelegateSubscriber {\n\n// Any AppDelegate methods you want to implement\n  public func application(\n    _ application: UIApplication,\n    continue userActivity: NSUserActivity,\n    restorationHandler: @escaping ([UIUserActivityRestoring]?) -> Void\n  ) -> Bool {\n    launchedActivity = userActivity\n\n   // ...\n\n    return false\n  }\n}\n```\n\nThen add the subscriber to the `expo-module.config.json`:\n\n```json\n{\n  \"platforms\": [\"apple\", \"android\", \"web\"],\n  \"apple\": {\n    \"modules\": [\"ExpoHeadModule\", ...],\n    \"appDelegateSubscribers\": [\"ExpoHeadAppDelegateSubscriber\"]\n  }\n}\n```\n\n## Expo ecosystem integration\n\n- Create a Config Plugin for setting up all permissions and entitlements.\n- Permissions APIs should follow Expo''s permission model and implement hooks.\n  - Ref: https://github.com/expo/expo/blob/843d5e108ff70539ac353721d3a7765a5d08d502/packages/expo-media-library/src/MediaLibrary.ts#L502-L519\n- Document when things don''t work in Expo Go and link to dev client instructions.\n- Consider creating Expo devtools plugins for interacting with native APIs. Optimize for Claude Code usage, e.g. a Bun CLI before a UI.\n  - Ref: https://docs.expo.dev/debugging/devtools-plugins\n- If any feature launches the app or could benefit from deep linking, add an Expo Router integration. A good example is `expo-quick-actions` which has a `expo-quick-actions/router` import for automatic deep linking. Other good examples are Expo notifications (open settings, redirect notifications), widgets, siri shortcuts.\n  - Ref: https://github.com/EvanBacon/expo-quick-actions\n\n## Verification\n\n- Run `yarn expo run:ios --no-bundler` in an Expo app to headlessly compile the module and verify there are no compilation errors.\n"},"lastSynced":"2026-03-08T02:02:30.239Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile Health Application Agents needing native Apple HealthKit bindings for Expo","zh":"非常适合需要 Expo 中原生 Apple HealthKit 绑定的移动健康应用代理","ja":"Expo でネイティブの Apple HealthKit バインディングが必要なモバイルヘルスアプリケーションエージェントに最適","ko":"Expo에서 네이티브 Apple HealthKit 바인딩이 필요한 모바일 헬스 애플리케이션 에이전트에 적합","es":"Perfecto para Agentes de Aplicaciones de Salud Móviles que necesitan enlaces nativos de Apple HealthKit para Expo","fr":"Parfait pour les Agents d''Applications de Santé Mobiles ayant besoin de liens natifs Apple HealthKit pour Expo","de":"Perfekt für Mobile Gesundheitsanwendungsagenten, die native Apple HealthKit-Bindings für Expo benötigen","pt":"Perfeito para Agentes de Aplicativos de Saúde Móvel que precisam de vinculações nativas do Apple HealthKit para Expo","ru":"Идеально для Мобильных Приложений Здравоохранения, которым необходимы родные привязки Apple HealthKit для Expo","ar":"مثالي للوكلاء التطبيقات الصحية المحمولة الذين بحاجة إلى ربطات أصلية من Apple HealthKit ل Expo"},"recommendation":{"en":"Empowers agents to access native health and fitness data using Apple HealthKit bindings, providing direct exposure to native functionality through standards like W3C specs, and enabling 100% backwards compatibility like the web, with escape hatches for single-platform functionality","zh":"赋予代理访问本地健康和健身数据的能力，使用 Apple HealthKit 绑定，通过 W3C 规范等标准提供对本地功能的直接访问，并实现与 web 一样的 100% 向后兼容性，同时提供单平台功能的逃生舱","ja":"エージェントにネイティブの健康およびフィットネスデータへのアクセスを可能にし、Apple HealthKit バインディングを使用し、W3C 標準などの規格を通じてネイティブ機能への直接アクセスを提供し、Web と同等の 100% の下位互換性を実現し、シングルプラットフォーム機能のための逃げ道を提供する","ko":"에이전트가 Apple HealthKit 바인딩을 사용하여 네이티브 건강 및 피트니스 데이터에 액세스 할 수 있도록 하며 W3C 사양과 같은 표준을 통해 네이티브 기능에 직접 노출되며 웹과 동일한 100%의 하위 호환성을 제공하고 단일 플랫폼 기능을 위한 탈출구를 제공함","es":"Habilita a los agentes para acceder a datos de salud y fitness nativos mediante enlaces de Apple HealthKit, proporcionando una exposición directa a la funcionalidad nativa a través de estándares como las especificaciones de W3C, y permitiendo la compatibilidad hacia atrás del 100% como la web, con escotillas de escape para la funcionalidad de una sola plataforma","fr":"Permet aux agents d''accéder à des données de santé et de fitness natives en utilisant des liens Apple HealthKit, offrant une exposition directe à la fonctionnalité native à travers des normes comme les spécifications W3C, et permettant une compatibilité descendante de 100% comme le web, avec des échappatoires pour la fonctionnalité d''une seule plate-forme","de":"Ermöglicht es Agents, auf native Gesundheits- und Fitnessdaten zuzugreifen, indem sie Apple HealthKit-Bindings verwenden, und bietet direkten Zugriff auf native Funktionalität durch Standards wie W3C-Spezifikationen, und ermöglicht 100% rückwärtskompatible wie das Web, mit Ausgabemöglichkeiten für Single-Plattform-Funktionalität","pt":"Habilita os agentes a acessar dados nativos de saúde e fitness usando as vinculações do Apple HealthKit, fornecendo exposição direta à funcionalidade nativa por meio de padrões como as especificações da W3C, e permitindo 100% de compatibilidade para trás como a web, com escotilhas para funcionalidade de plataforma única","ru":"Наделяет агентов возможностью доступа к родным данным о здоровье и фитнесе с помощью привязок Apple HealthKit, предоставляя прямой доступ к родной функциональности через стандарты, такие как спецификации W3C, и обеспечивающая 100% обратную совместимость, как веб, с возможностью использования функциональности единичной платформы","ar":"تمكين الوكلاء من الوصول إلى بيانات الصحة واللياقة البدنية الأصلية باستخدام ربطات Apple HealthKit، وتوفير التعرض المباشر للوظائف الأصلية من خلال المعايير مثل مواصفات W3C، وتمكين 100٪ من التوافق العكسي مثل الويب، مع ملاجئ للوظائف الخاصة بالمنصة الواحدة"},"useCases":{"en":["Accessing native health data for fitness tracking","Building health-related applications with native API integration","Utilizing std:kv-storage and clipboard for seamless data exchange"],"zh":["访问本地健康数据进行健身追踪","使用本地 API 集成构建与健康相关的应用程序","利用 std:kv-storage 和剪贴板实现无缝数据交换"],"ja":["ネイティブの健康データへのアクセスによるフィットネストラッキング","ネイティブ API 統合を使用したヘルス関連アプリケーションの構築","std:kv-storage およびクリップボードを使用したシームレスなデータ交換"],"ko":["네이티브 건강 데이터에 액세스하여 피트니스 추적","네이티브 API 통합을 사용하여 건강 관련 애플리케이션 구축","std:kv-storage 및 클립보드를 사용한 무결점 데이터 교환"],"es":["Acceder a datos de salud nativos para el seguimiento de la condición física","Construir aplicaciones relacionadas con la salud con integración de API nativa","Utilizar std:kv-almacenamiento y portapapeles para un intercambio de datos sin problemas"],"fr":["Accéder à des données de santé natives pour le suivi de la condition physique","Construire des applications liées à la santé avec une intégration d''API native","Utiliser std:kv-stockage et presse-papiers pour un échange de données sans problème"],"de":["Auf native Gesundheitsdaten für die Fitnessverfolgung zugreifen","Gesundheitsbezogene Anwendungen mit nativer API-Integration aufbauen","Verwenden von std:kv-Speicher und Zwischenablage für einen nahtlosen Datenaustausch"],"pt":["Acessar dados de saúde nativos para acompanhamento de condicionamento físico","Construir aplicações relacionadas à saúde com integração de API nativa","Utilizar std:kv-storage e clipboard para troca de dados sem interrupção"],"ru":["Доступ к родным данным о здоровье для отслеживания фитнеса","Построение приложений, связанных со здоровьем, с интеграцией родной API","Использование std:kv-storage и clipboard для беспрепятственной передачи данных"],"ar":["الوصول إلى بيانات الصحة الأصلية لتعقب اللياقة البدنية","بناء التطبيقات الصحية ذات الصلة بintegration API الأصلية","استخدام std:kv-storage و clipboard لنقل البيانات دون انقطاع"]},"limitations":{"en":["Requires Expo environment","Limited to Apple HealthKit functionality","Native functionality exposure may require platform-specific knowledge"],"zh":["需要 Expo 环境","仅限 Apple HealthKit 功能","本地功能曝露可能需要特定于平台的知识"],"ja":["Expo 環境を必要とする","Apple HealthKit 機能のみ","ネイティブ機能の公開にはプラットフォーム固有の知識が必要になる可能性がある"],"ko":["Expo 환경이 필요","Apple HealthKit 기능만","네이티브 기능公开에는 플랫폼별 지식이 필요할 수 있음"],"es":["Requiere entorno de Expo","Limitado a la funcionalidad de Apple HealthKit","La exposición a la funcionalidad nativa puede requerir conocimientos específicos de la plataforma"],"fr":["Nécessite un environnement Expo","Limité à la fonctionnalité Apple HealthKit","L''exposition à la fonctionnalité native peut nécessiter des connaissances spécifiques à la plate-forme"],"de":["Benötigt Expo-Umgebung","Begrenzt auf Apple HealthKit-Funktionalität","Die Exposition gegenüber der nativen Funktionalität kann plattformspezifische Kenntnisse erfordern"],"pt":["Requer ambiente Expo","Limitado à funcionalidade do Apple HealthKit","A exposição da funcionalidade nativa pode exigir conhecimento específico da plataforma"],"ru":["Требует среды Expo","Ограничен функциональностью Apple HealthKit","Возможность доступа к родной функциональности может требовать знаний, специфичных для платформы"],"ar":["يتطلب بيئة Expo","محدود بالوظائف Apple HealthKit","يمكن أن تتطلب التعرض للوظائف الأصلية معرفة محددة بالمنصة"]},"version":4},"contentHash":"778c219951b45d3f454b9fe5f2e255380db39a3fa47dc1cd0e1aa7cbf6ef8d62","qualityScore":42}');
