INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EvanBacon/apple-health/expo-modules', 'expo-modules', 'EvanBacon', 'apple-health', 'community', 'expo-modules EvanBacon apple-health community expo-modules provides Apple HealthKit bindings for Expo, enabling developers to access native health and fitness data. It benefits developers building health-related applications. expo-modules 为 Expo 提供 Apple HealthKit 绑定，遵循现代 Web 模块设计原则，实现 100% 向后兼容性 expo-modules は Expo に Apple HealthKit バインディングを提供し、モダン Web モジュール設計原則に従い、100% の後方互換性を実現します expo-modules는 Expo에 Apple HealthKit 바인딩을 제공하며, 현대적인 웹 모듈 디자인 원칙을 따르며 100%의 이전 버전과 호환됩니다 expo-modules proporciona enlaces de Apple HealthKit para Expo, permitiendo diseñar APIs nativas con estándares modernos Les modules expo offrent des liaisons Apple HealthKit pour Expo, permettant de concevoir des API natives avec des standards modernes expo-modules bietet Apple HealthKit-Bindings für Expo, um native APIs mit modernen Standards zu entwerfen O expo-modules fornece bindings do Apple HealthKit para o Expo, permitindo que os desenvolvedores criem aplicativos móveis com funcionalidades de saúde expo-modules предоставляет биндинги Apple HealthKit для Expo, позволяя разработчикам создавать мобильные приложения со здоровьем expo-modules يوفر ربطات Apple HealthKit لمنصة Expo، مما يسمح للمطورين بإنشاء تطبيقات الجوال مع ميزات الصحة how to use expo-modules expo-modules alternative expo-modules install what is expo-modules expo-modules vs react-native expo-modules setup guide expo-modules documentation expo-modules HealthKit integration expo-modules Apple HealthKit Expo 移动应用开发 现代 Web 模块 API 设计 后向兼容性 AIエージェント Designs native APIs inspired by modern web modules like std:kv-storage and clipboard Aims for 100% backwards compatibility like the web Creates escape hatches for single-platform functionality Exposes native functionality directly, avoiding extraneous abstractions Prefers string union types for API options instead of boolean flags or enums Uses sync methods when possible, avoiding unnecessary async methods expo-modules is a set of Apple HealthKit bindings for Expo, designed to provide native API access for seamless health and fitness tracking integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bendrucker/route-agent/promptfoo', 'community', 'bendrucker', 'route-agent', 'bendrucker/route-agent', 'promptfoo', 0, 0, 42, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:35.774Z', 'e1b1d448b580a2c0ce760402bcec98a68ab3b3cd1c1183e7df03edda91d572b5', '{"id":"bendrucker/route-agent/promptfoo","name":"promptfoo","description":{"en":"promptfoo is a CLI tool for testing and comparing LLM outputs, ideal for AI agent developers. It auto-discovers config files and supports various extensions","zh":"Promptfoo是一个CLI工具，用于测试和比较LLM输出。支持配置文件和变量替换","ja":"PromptfooはCLIツールで、LLM出力をテストして比較します。設定ファイルと変数置換をサポートしています","ko":"Promptfoo는 CLI 도구로, LLM 출력을 테스트하고 비교합니다. 설정 파일과 변수 치환을 지원합니다","es":"Promptfoo es una herramienta de línea de comandos para testing y comparación de salidas de LLM. Soporta extensiones como .yaml, .json y .js","fr":"Promptfoo est un outil en ligne de commande pour tester et comparer les sorties de LLM. Il prend en charge les extensions comme .yaml, .json et .js","de":"Promptfoo ist ein CLI-Tool für Testing und Vergleich von LLM-Ausgaben. Es unterstützt Erweiterungen wie .yaml, .json und .js","pt":"O Promptfoo é uma ferramenta de linha de comando para testar e comparar saídas de LLM. Ele suporta arquivos de configuração em YAML, JSON e JS","ru":"Promptfoo - это инструмент командной строки для тестирования и сравнения вывода ИИ Агентов. Он поддерживает файлы конфигурации в форматах YAML, JSON и JS","ar":"Promptfoo هو أداة سطر الأوامر لاختبار وحدات اللغة الإصطناعية. يدعم ملفات التهيئة بالصيغ YAML و JSON و JS"},"seo":{"title":{"en":"promptfoo: CLI Tool Setup Guide for AI Agents","zh":"Promptfoo中文指南：AI智能工具配置与优化","ja":"Promptfoo日本語ガイド：AIエージェントの設定と最適化","ko":"Promptfoo 한국어 가이드: AI 에이전트 설정 및 최적화","es":"Guía de configuración de Promptfoo para desarrolladores","fr":"Configurer Promptfoo pour les développeurs : Guide étape ...","de":"Promptfoo-Setup-Anleitung für Entwickler: CLI-Tool und Ko...","pt":"Guia de Configuração do Promptfoo: Ferramenta de Teste de...","ru":"Настройка Promptfoo: Инструмент для тестирования ИИ Агентов","ar":"دليل إعداد Promptfoo: أداة اختبار وحدات اللغة الإصطناعية"},"description":{"en":"Discover how to test and compare LLM outputs with promptfoo. Learn to configure and use this CLI tool for AI agent development","zh":"了解Promptfoo的功能和特点，包括CLI工具、配置文件和变量替换。优化您的AI智能工具体验","ja":"Promptfooの機能と特徴を紹介します。CLIツール、設定ファイル、変数置換などを含みます。AIエージェントの使い方を最適化しましょう","ko":"Promptfoo의 기능과 특징을 알아보세요. CLI 도구, 설정 파일, 변수 치환 등이 포함되어 있습니다. AI 에이전트 사용을 최적화하세요","es":"Aprende a configurar Promptfoo, una herramienta de línea de comandos para testing y comparación de salidas de LLM, y mejora tus habilidades de desarrollo","fr":"Découvrez comment configurer Promptfoo, un outil en ligne de commande pour tester et comparer les sorties de LLM, et améliorez vos compétences de développement","de":"Erfahren Sie, wie Sie Promptfoo konfigurieren, ein CLI-Tool für Testing und Vergleich von LLM-Ausgaben, und verbessern Sie Ihre Entwicklerfähigkeiten","pt":"Aprenda a configurar o Promptfoo, uma ferramenta de linha de comando para testar e comparar saídas de LLM. Descubra como usar arquivos de configuração e subs...","ru":"Узнайте, как настроить Promptfoo, инструмент командной строки для тестирования и сравнения вывода ИИ Агентов. Откройте для себя, как использовать файлы конфи...","ar":"تعرف على كيفية إعداد Promptfoo، أداة سطر الأوامر لاختبار وحدات اللغة الإصطناعية. اكتشف كيفية استخدام ملفات التهيئة وتبديل المتغيرات"},"definition":{"en":"promptfoo is a command-line interface tool for testing and comparing large language model outputs","zh":"Promptfoo是AI智能工具，用于构建和优化LLM输出","ja":"PromptfooはAIエージェントの一種で、LLM出力を構築して最適化するために使用されます","ko":"Promptfoo는 AI 에이전트의 일종으로, LLM 출력을 구축하고 최적화하는 데 사용됩니다","es":"Promptfoo es una herramienta de línea de comandos para testing y comparación de salidas de LLM","fr":"Promptfoo est un outil en ligne de commande pour tester et comparer les sorties de LLM","de":"Promptfoo ist ein CLI-Tool für Testing und Vergleich von LLM-Ausgaben","pt":"O Promptfoo é uma ferramenta de teste de LLM que permite a configuração de arquivos e substituição de variáveis","ru":"Promptfoo - это инструмент для тестирования ИИ Агентов, который позволяет конфигурировать файлы и заменять переменные","ar":"Promptfoo هو أداة اختبار وحدات اللغة الإصطناعية التي تمكن من تهيئة الملفات وتبديل المتغيرات"},"features":{"en":["Auto-discovers promptfooconfig.yaml in the current directory","Supports config file extensions: .yaml, .json, .js","Allows inline prompt with variable substitution","Uses -c path for custom config file locations","Supports file://prompt.txt for external prompt files"],"zh":["支持配置文件（.yaml、.json、.js）","变量替换功能","CLI工具用于测试和比较LLM输出","自动发现配置文件","支持内联提示和文件提示"],"ja":["設定ファイル（.yaml、.json、.js）をサポート","変数置換機能","CLIツールを使用してLLM出力をテストして比較","設定ファイルを自動で検出","インラインプロンプトとファイルプロンプトをサポート"],"ko":["설정 파일(.yaml, .json, .js) 지원","변수 치환 기능","CLI 도구를 사용하여 LLM 출력을 테스트하고 비교","설정 파일 자동 검색","인라인 프롬프트와 파일 프롬프트 지원"],"es":["Soporte para extensiones .yaml, .json y .js","Configuración a través de un archivo de configuración","Compatibilidad con variables y sustitución en los prompts","Descubrimiento automático de la configuración en el directorio actual","Opción para especificar la ruta de la configuración mediante la bandera -c"],"fr":["Prise en charge des extensions .yaml, .json et .js","Configuration via un fichier de configuration","Compatibilité avec les variables et la substitution dans les prompts","Découverte automatique de la configuration dans le répertoire courant","Option pour spécifier le chemin de la configuration via la balise -c"],"de":["Unterstützung für Erweiterungen .yaml, .json und .js","Konfiguration über eine Konfigurationsdatei","Kompatibilität mit Variablen und Ersetzung in den Prompts","Automatische Erkennung der Konfiguration im aktuellen Verzeichnis","Option zum Festlegen des Konfigurationspfads mit der Flagge -c"],"pt":["Suporte a arquivos de configuração em YAML, JSON e JS","Substituição de variáveis em prompts","Uso de arquivos de configuração personalizados","Teste e comparação de saídas de LLM","Interface de linha de comando fácil de usar"],"ru":["Поддержка файлов конфигурации в форматах YAML, JSON и JS","Замена переменных в промптах","Использование пользовательских файлов конфигурации","Тестирование и сравнение вывода ИИ Агентов","Простой интерфейс командной строки"],"ar":["دعم ملفات التهيئة بالصيغ YAML و JSON و JS","تبديل المتغيرات في الدوائر","استخدام ملفات التهيئة المخصصة","اختبار ومقارنة مخرجات وحدات اللغة الإصطناعية","واجهة سطر الأوامر سهلة الاستخدام"]},"keywords":{"en":["how to use promptfoo","promptfoo alternative","promptfoo config file","promptfoo setup guide","LLM output testing","CLI tool for AI agents","promptfoo vs other LLM tools","install promptfoo","promptfoo documentation"],"zh":["Promptfoo","AI智能工具","CLI工具","配置文件","变量替换","LLM输出","AIエージェント","智能工具配置"],"ja":["Promptfoo","AIエージェント","CLIツール","設定ファイル","変数置換","LLM出力","AIツール","エージェントの設定"],"ko":["Promptfoo","AI 에이전트","CLI 도구","설정 파일","변수 치환","LLM 출력","AI 도구","에이전트 설정"],"es":["Promptfoo","herramienta de línea de comandos","testing de LLM","comparación de salidas de LLM","configuración de Promptfoo","desarrollo de software","herramientas de desarrollo","CLI","yaml","json","js"],"fr":["Promptfoo","outil en ligne de commande","testing de LLM","comparaison de sorties de LLM","configuration de Promptfoo","développement de logiciels","outils de développement","CLI","yaml","json","js","Agent IA"],"de":["Promptfoo","CLI-Tool","Testing von LLM","Vergleich von LLM-Ausgaben","Konfiguration von Promptfoo","Software-Entwicklung","Entwickler-Tools","CLI","yaml","json","js","KI-Tool","KI-Agent"],"pt":["Promptfoo","Ferramenta de teste de LLM","Configuração de arquivos","Substituição de variáveis","Teste de saídas de LLM","Interface de linha de comando","Desenvolvimento de software","Ferramentas de desenvolvimento"],"ru":["Promptfoo","Инструмент для тестирования ИИ Агентов","Конфигурация файлов","Замена переменных","Тестирование вывода ИИ Агентов","Интерфейс командной строки","Разработка программного обеспечения","Инструменты для разработки"],"ar":["Promptfoo","أداة اختبار وحدات اللغة الإصطناعية","تهيئة الملفات","تبديل المتغيرات","اختبار مخرجات وحدات اللغة الإصطناعية","واجهة سطر الأوامر","تطوير البرمجيات","أدوات التطوير"]}},"owner":"bendrucker","repo":"route-agent","repoPath":"bendrucker/route-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"promptfoo","description":"|","bodyPreview":"# Promptfoo\n\n[Promptfoo](https://www.promptfoo.dev/) is a CLI tool for testing and comparing LLM outputs.\n\n## Config File\n\nThe CLI auto-discovers `promptfooconfig.yaml` in the current directory. Use `-c path` for other locations.\n\nSupported extensions: `.yaml`, `.json`, `.js`\n\n## Configuration\n\n```yaml\n# yaml-language-server: $schema=https://promptfoo.dev/config-schema.json\ndescription: \"What this eval tests\"\n\nprompts:\n  - file://prompt.txt\n  - |\n    Inline prompt with {{variable}} substitution","body":"# Promptfoo\n\n[Promptfoo](https://www.promptfoo.dev/) is a CLI tool for testing and comparing LLM outputs.\n\n## Config File\n\nThe CLI auto-discovers `promptfooconfig.yaml` in the current directory. Use `-c path` for other locations.\n\nSupported extensions: `.yaml`, `.json`, `.js`\n\n## Configuration\n\n```yaml\n# yaml-language-server: $schema=https://promptfoo.dev/config-schema.json\ndescription: \"What this eval tests\"\n\nprompts:\n  - file://prompt.txt\n  - |\n    Inline prompt with {{variable}} substitution\n\nproviders:\n  - anthropic:messages:claude-sonnet-4-5-20250929\n\ndefaultTest:\n  options:\n    provider:\n      config:\n        temperature: 0.0\n        max_tokens: 4096\n\ntests:\n  - description: \"What this case tests\"\n    vars:\n      variable: \"value\"\n      from_file: file://data/input.txt\n    assert:\n      - type: contains\n        value: \"expected substring\"\n\n# Or load tests from files\ntests: file://cases/all.yaml\n\noutputPath: ./results.json\n\nevaluateOptions:\n  maxConcurrency: 4\n```\n\n## Provider IDs\n\n| Model | ID |\n|-------|----|\n| Opus 4.5 | `anthropic:messages:claude-opus-4-5-20251101` |\n| Sonnet 4.5 | `anthropic:messages:claude-sonnet-4-5-20250929` |\n| Haiku 4.5 | `anthropic:messages:claude-haiku-4-5-20251001` |\n\nProvider config: `temperature`, `max_tokens`, `top_p`, `top_k`, `tools`, `tool_choice`\n\n## Prompts\n\n- `file://path.txt` — load from file (path relative to config)\n- Inline string with `{{variable}}` Nunjucks substitution\n- Chat format via JSON: `[{\"role\": \"system\", \"content\": \"...\"}, {\"role\": \"user\", \"content\": \"{{input}}\"}]`\n\n## Assertion Types\n\n| Type | Use | Value |\n|------|-----|-------|\n| `contains` | Substring match | `\"expected text\"` |\n| `icontains` | Case-insensitive substring | `\"expected text\"` |\n| `equals` | Exact match | `\"exact value\"` |\n| `regex` | Pattern match | `\"\\\\d{4}-\\\\d{2}-\\\\d{2}\"` |\n| `is-json` | Valid JSON output | — |\n| `contains-json` | Output contains JSON | — |\n| `starts-with` | Prefix match | `\"prefix\"` |\n| `cost` | Max cost | `threshold: 0.01` |\n| `latency` | Max response time (ms) | `threshold: 5000` |\n| `javascript` | Custom JS expression | `output.includes(''x'')` |\n| `python` | Custom Python | `file://check.py:fn_name` |\n| `llm-rubric` | LLM-as-judge | rubric text |\n| `similar` | Semantic similarity | `value: \"text\"`, `threshold: 0.8` |\n| `model-graded-factuality` | Fact checking | — |\n\nPrefix any assertion with `not-` to negate (e.g., `not-contains`).\n\n### llm-rubric\n\nUses an LLM to grade output against a rubric:\n\n```yaml\nassert:\n  - type: llm-rubric\n    value: |\n      The response should:\n      - Mention at least 3 factors\n      - Include specific examples\n    threshold: 0.7\n    provider: anthropic:messages:claude-sonnet-4-5-20250929\n```\n\n### javascript\n\nInline expressions or functions. Access `output` (string) and `context` (with `vars`, `prompt`):\n\n```yaml\nassert:\n  - type: javascript\n    value: output.length > 100 && output.includes(''route'')\n  - type: javascript\n    value: |\n      const data = JSON.parse(output);\n      return data.calories >= 200 && data.calories <= 300;\n```\n\n## Test Organization\n\nSplit cases into separate files and reference them:\n\n```yaml\ntests:\n  - file://cases/basic.yaml\n  - file://cases/edge-cases.yaml\n```\n\nEach case file contains a YAML array of test objects.\n\n## CLI\n\n```bash\nnpx promptfoo eval                         # Run with auto-discovered config\nnpx promptfoo eval -c path/to/config.yaml  # Specific config\nnpx promptfoo eval --filter-metadata key=v # Filter tests\nnpx promptfoo view                         # Web UI for results\nnpx promptfoo cache clear                  # Clear result cache\n```\n\n## References\n\nConsult the [configuration reference](https://www.promptfoo.dev/docs/configuration/reference/) and [Anthropic provider docs](https://www.promptfoo.dev/docs/providers/anthropic/) for full details.\n"},"lastSynced":"2026-03-08T02:02:35.774Z","agentAnalysis":{"suitability":{"en":"Perfect for LLM Agent Developers needing comprehensive content analysis and comparison of model outputs.","zh":"非常适合需要对模型输出进行全面内容分析和比较的 LLM Agent 开发者。","ja":"LLM エージェント開発者が包括的なコンテンツ分析とモデル出力の比較を必要とする場合に最適です。","ko":"모델 출력에 대한 종합적인 내용 분석 및 비교가 필요한 LLM 에이전트 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de Agentes LLM que necesitan un análisis y comparación de contenido integral de los resultados del modelo.","fr":"Parfait pour les développeurs d''agents LLM ayant besoin d''une analyse et d''une comparaison de contenu complètes des sorties de modèle.","de":"Perfekt für LLM-Agent-Entwickler, die eine umfassende Inhaltsanalyse und -vergleich der Modellergebnisse benötigen.","pt":"Perfeito para desenvolvedores de Agentes LLM que precisam de análise e comparação abrangentes de conteúdo.","ru":"Идеально подходит для разработчиков агентов LLM, которым необходим комплексный анализ и сравнение содержимого.","ar":"مثالي لمنطقي التطوير ال llm الذين يحتاجون إلى تحليل ومقارنة كاملة للمحتوى."},"recommendation":{"en":"Empowers agents to test and compare LLM outputs using YAML, JSON, or JS config files, supporting extensions like .yaml, .json, and .js, and auto-discovering promptfooconfig.yaml for streamlined evaluation.","zh":"赋予代理测试和比较 LLM 输出的能力，使用 YAML、JSON 或 JS 配置文件，支持扩展名为 .yaml、.json 和 .js 的文件，并自动发现 promptfooconfig.yaml 以实现流畅的评估，支持通过 CLI 进行设置。","ja":"エージェントに LLM 出力をテストし、比較する機能を提供します。YAML、JSON、または JS 構成ファイルを使用し、.yaml、.json、.js などの拡張子をサポートし、promptfooconfig.yaml を自動的に検出して評価を簡素化します。","ko":"에이전트가 LLM 출력을 테스트하고 비교할 수 있도록 하는 기능을 제공하며, YAML, JSON 또는 JS 구성 파일을 사용하고, .yaml, .json 및 .js와 같은 확장자를 지원하며, promptfooconfig.yaml를 자동으로 검색하여 평가를 간소화합니다.","es":"Habilita a los agentes a probar y comparar las salidas de LLM utilizando archivos de configuración YAML, JSON o JS, que admiten extensiones como .yaml, .json y .js, y que auto-detectan promptfooconfig.yaml para una evaluación optimizada.","fr":"Permet aux agents de tester et de comparer les sorties de LLM en utilisant des fichiers de configuration YAML, JSON ou JS, qui prennent en charge des extensions comme .yaml, .json et .js, et qui détectent automatiquement promptfooconfig.yaml pour une évaluation rationalisée.","de":"Ermächtigt Agenten, LLM-Ausgaben mithilfe von YAML-, JSON- oder JS-Konfigurationsdateien zu testen und zu vergleichen, die Erweiterungen wie .yaml, .json und .js unterstützen und promptfooconfig.yaml automatisch erkennen, um eine optimierte Bewertung zu ermöglichen.","pt":"Habilita os agentes a testar e comparar saídas LLM usando arquivos de configuração YAML, JSON ou JS, suportando extensões como .yaml, .json e .js, e auto-descobrindo promptfooconfig.yaml para avaliação otimizada.","ru":"Наделяет агентов возможностью тестировать и сравнивать выходные данные LLM с помощью файлов конфигурации YAML, JSON или JS, поддерживая расширения như .yaml, .json и .js, и автоматически обнаруживая promptfooconfig.yaml для оптимизированной оценки.","ar":"يمنح الوكلاء khảية اختبار ومقارنة مخرجات LLM باستخدام ملفات التكوين YAML و JSON و JS ، ودعم الامتدادات مثل .yaml و .json و .js ، واكتشاف خودي لملف promptfooconfig.yaml لتقييم مبسط."},"useCases":{"en":["Automating LLM output comparisons","Generating config files for custom evaluations","Debugging model performance with inline prompt substitution"],"zh":["自动化 LLM 输出比较","生成自定义评估的配置文件","使用内联提示替换调试模型性能"],"ja":["LLM 出力の比較を自動化する","カスタム評価用の構成ファイルを生成する","インラインプロンプトの置換を使用してモデル性能をデバッグする"],"ko":["LLM 출력 비교 자동화","사용자 정의 평가를 위한 구성 파일 생성","인라인 프롬프트 대체를 통한 모델 성능 디버깅"],"es":["Automatizar comparaciones de salidas de LLM","Generar archivos de configuración para evaluaciones personalizadas","Depurar el rendimiento del modelo con sustitución de instrucciones en línea"],"fr":["Automatiser les comparaisons de sorties de LLM","Générer des fichiers de configuration pour des évaluations personnalisées","Déboguer les performances du modèle avec substitution d''instructions en ligne"],"de":["Automatisieren von LLM-Ausgabevergleichen","Erstellen von Konfigurationsdateien für benutzerdefinierte Bewertungen","Fehlersuche der Modellleistung mit Inline-Anweisungsersetzung"],"pt":["Automatizar comparações de saídas LLM","Gerar arquivos de configuração para avaliações personalizadas","Depurar o desempenho do modelo com substituição de prompt em linha"],"ru":["Автоматизировать сравнения выходных данных LLM","Генерировать файлы конфигурации для индивидуальных оценок","Отлаживать производительность модели с помощью подстановки запроса в строке"],"ar":["أتمتة مقارنة مخرجات LLM","توليد ملفات التكوين لتقييمات مخصصة","تصحيح أخطاء أداء الموديل باستخدام استبدال البرومت في السطر"]},"limitations":{"en":["Requires CLI setup","Limited to specific file formats (.yaml, .json, .js)"],"zh":["需要 CLI 设置","仅限于特定的文件格式 (.yaml, .json, .js)"],"ja":["CLI の設定が必要","特定のファイル形式 (.yaml, .json, .js) しかサポートされません"],"ko":["CLI 설정이 필요함","특정 파일 형식(.yaml, .json, .js)만 지원"],"es":["Requiere configuración de CLI","Limitado a formatos de archivo específicos (.yaml, .json, .js)"],"fr":["Nécessite une configuration de CLI","Limité à des formats de fichiers spécifiques (.yaml, .json, .js)"],"de":["Benötigt CLI-Einrichtung","Begrenzt auf bestimmte Dateiformate (.yaml, .json, .js)"],"pt":["Requer configuração CLI","Limitado a formatos de arquivo específicos (.yaml, .json, .js)"],"ru":["Требует настройки CLI","Ограничен конкретными форматами файлов (.yaml, .json, .js)"],"ar":["يتطلب إعداد CLI","محدود بالتنسيقات المحددة لملفات (.yaml، .json، .js)"]},"version":4},"contentHash":"e1b1d448b580a2c0ce760402bcec98a68ab3b3cd1c1183e7df03edda91d572b5","qualityScore":42}');
