INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bendrucker/route-agent/promptfoo', 'promptfoo', 'bendrucker', 'route-agent', 'community', 'promptfoo bendrucker route-agent community promptfoo is a CLI tool for testing and comparing LLM outputs, ideal for AI agent developers. It auto-discovers config files and supports various extensions Promptfoo是一个CLI工具，用于测试和比较LLM输出。支持配置文件和变量替换 PromptfooはCLIツールで、LLM出力をテストして比較します。設定ファイルと変数置換をサポートしています Promptfoo는 CLI 도구로, LLM 출력을 테스트하고 비교합니다. 설정 파일과 변수 치환을 지원합니다 Promptfoo es una herramienta de línea de comandos para testing y comparación de salidas de LLM. Soporta extensiones como .yaml, .json y .js Promptfoo est un outil en ligne de commande pour tester et comparer les sorties de LLM. Il prend en charge les extensions comme .yaml, .json et .js Promptfoo ist ein CLI-Tool für Testing und Vergleich von LLM-Ausgaben. Es unterstützt Erweiterungen wie .yaml, .json und .js O Promptfoo é uma ferramenta de linha de comando para testar e comparar saídas de LLM. Ele suporta arquivos de configuração em YAML, JSON e JS Promptfoo - это инструмент командной строки для тестирования и сравнения вывода ИИ Агентов. Он поддерживает файлы конфигурации в форматах YAML, JSON и JS Promptfoo هو أداة سطر الأوامر لاختبار وحدات اللغة الإصطناعية. يدعم ملفات التهيئة بالصيغ YAML و JSON و JS how to use promptfoo promptfoo alternative promptfoo config file promptfoo setup guide LLM output testing CLI tool for AI agents promptfoo vs other LLM tools install promptfoo promptfoo documentation Promptfoo AI智能工具 CLI工具 配置文件 变量替换 LLM输出 AIエージェント 智能工具配置 Auto-discovers promptfooconfig.yaml in the current directory Supports config file extensions: .yaml, .json, .js Allows inline prompt with variable substitution Uses -c path for custom config file locations Supports file://prompt.txt for external prompt files promptfoo is a command-line interface tool for testing and comparing large language model outputs');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hippocampus-dev/hippocampus/kubernetes-operations', 'community', 'hippocampus-dev', 'hippocampus', 'hippocampus-dev/hippocampus', 'kubernetes-operations', 0, 0, 42, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:36.319Z', '4c446f154c8ce1582ad6fff59075a6b441ca2cccc8f21320426bcd1d1db45473', '{"id":"hippocampus-dev/hippocampus/kubernetes-operations","name":"kubernetes-operations","description":{"en":"The kubernetes-operations skill provides developers with a robust toolset for debugging and investigating Kubernetes issues, leveraging Grafana and kubectl for efficient troubleshooting.","zh":"Kubernetes操作技能提供了访问Grafana、配置ArgoCD和使用kubectl进行调试的能力","ja":"KubernetesオペレーションスキルはGrafanaへのアクセス、ArgoCDの設定、kubectlによるデバッグを提供する","ko":"Kubernetes 운영 스킬은 Grafana 접근, ArgoCD 설정, kubectl 디버깅을 제공합니다","es":"La guía de operaciones de Kubernetes te permite configurar y depurar clústeres de manera eficiente. Accede a herramientas como Grafana y kubectl","fr":"Le guide des opérations Kubernetes vous permet de configurer et de déboguer les clusters de manière efficace. Accédez aux outils tels que Grafana et kubectl","de":"Der Kubernetes-Betriebsleitfaden ermöglicht es Ihnen, Cluster effizient zu konfigurieren und zu debuggen. Zugriff auf Tools wie Grafana und kubectl","pt":"O Kubernetes-Operations é uma ferramenta para gerenciar e monitorar clusters Kubernetes. Aprenda a configurá-lo com nosso guia.","ru":"Kubernetes-Operations - это инструмент для управления и мониторинга кластеров Kubernetes. Узнайте, как его настроить.","ar":"كوبيرنتس-أوبريشنز هي أداة لادارة وتحكم مجموعات كوبيرنتس. تعلم كيفية إعدادها مع دليلنا."},"seo":{"title":{"en":"kubernetes-operations: Expert Debugging Setup Guide | AI ...","zh":"Kubernetes 操作最佳实践 - AIエージェント","ja":"Kubernetes オペレーションセットアップガイド - AIエージェント","ko":"Kubernetes 운영 가이드 - AI 에이전트","es":"Guía de Operaciones de Kubernetes: Configuración y Depura...","fr":"Guide des Opérations Kubernetes: Configuration et Débogage","de":"Kubernetes-Betriebsleitfaden: Einrichtung und Fehlerbehebung","pt":"Guia de Configuração do Kubernetes-Operations","ru":"Настройка ИИ Агентов для Kubernetes-Operations","ar":"دليل إعداد كوبيرنتس-أوبريشنز"},"description":{"en":"Unlock efficient Kubernetes troubleshooting with our AI agent skill, featuring Grafana and kubectl integration - get started now!","zh":"了解Kubernetes操作的关键技术，包括Grafana和ArgoCD配置，kubectl调试等","ja":"Kubernetesオペレーションの重要な機能を学ぶ：Grafana、ArgoCD、kubectlデバッグなど","ko":"Kubernetes 운영의 핵심 기술을 알아보세요: Grafana, ArgoCD, kubectl 디버깅 등","es":"Aprende a configurar y depurar operaciones de Kubernetes con nuestra guía. Incluye acceso a Grafana y kubectl para una gestión eficiente","fr":"Découvrez comment configurer et déboguer les opérations Kubernetes avec notre guide. Accédez à Grafana et kubectl pour une gestion efficace","de":"Erfahren Sie, wie Sie Kubernetes-Betriebsabläufe konfigurieren und debuggen. Enthalten sind Zugriff auf Grafana und kubectl für eine effiziente Verwaltung","pt":"Aprenda a configurar e otimizar o Kubernetes-Operations com nosso guia passo a passo","ru":"Узнайте, как настроить и оптимизировать Kubernetes-Operations с помощью нашего пошагового руководства","ar":"تعلم كيفية إعداد وتحسين كوبيرنتس-أوبريشنز باستخدام دليلنا الخطوة بخطوة"},"definition":{"en":"kubernetes-operations is a specialized AI agent skill for streamlining Kubernetes debugging and operations, utilizing key technologies like Grafana and kubectl.","zh":"Kubernetes操作是指在Kubernetes环境中进行的运维和管理工作","ja":"KubernetesオペレーションとはKubernetes環境での運用と管理作業のこと","ko":"Kubernetes 운영은 Kubernetes 환경에서 수행되는 운용 및 관리 작업입니다","es":"Las operaciones de Kubernetes son el conjunto de procesos para gestionar y mantener clústeres de contenedores","fr":"Les opérations Kubernetes sont l''ensemble des processus pour gérer et maintenir les clusters de conteneurs","de":"Die Kubernetes-Betriebsabläufe sind die Gesamtheit der Prozesse zur Verwaltung und Wartung von Containern-Clustern","pt":"O que é Kubernetes-Operations? É uma ferramenta para gerenciar e monitorar clusters Kubernetes.","ru":"Что такое Kubernetes-Operations? Это инструмент для управления и мониторинга кластеров Kubernetes.","ar":"ما هي كوبيرنتس-أوبريشنز؟ هي أداة لادارة وتحكم مجموعات كوبيرنتس."},"features":{"en":["Access to Grafana at https://grafana.minikube.127.0.0.1.nip.io for comprehensive metrics and logging","Disable and re-enable ArgoCD self-healing for manual changes","Utilize kubectl for pod startup failure investigation and event analysis","Leverage Grafana for tracing, metrics, logs, and profiles","Investigate in-container process and network issues"],"zh":["访问Grafana进行监控和分析","配置ArgoCD进行自动化部署","使用kubectl进行Pod调试和故障排除","查看事件和日志进行问题诊断","使用Traces和metrics进行性能优化"],"ja":["Grafanaへのアクセスによる監視と分析","ArgoCDの設定による自動化デプロイ","kubectlによるPodのデバッグと障害対応","イベントとログの確認による問題診断","Tracesとmetricsによるパフォーマンス最適化"],"ko":["Grafana 접근을 통한 모니터링 및 분석","ArgoCD 설정을 통한 자동화 배포","kubectl을 통한 Pod 디버깅 및 故障 처리","이벤트 및 로그 확인을 통한 문제 진단","Traces 및 metrics를 통한 성능 최적화"],"es":["Acceso a Grafana para monitorear métricas y registros","Uso de kubectl para depurar y gestionar clústeres","Desactivación de ArgoCD selfHeal para cambios manuales","Análisis de eventos y perfiles de clústeres","Monitoreo de procesos y redes en contenedores"],"fr":["Accès à Grafana pour surveiller les métriques et les journaux","Utilisation de kubectl pour déboguer et gérer les clusters","Désactivation de ArgoCD selfHeal pour les modifications manuelles","Analyse des événements et des profils de cluster","Surveillance des processus et des réseaux dans les conteneurs"],"de":["Zugriff auf Grafana zur Überwachung von Metriken und Protokollen","Verwendung von kubectl zur Fehlersuche und Cluster-Verwaltung","Deaktivierung von ArgoCD selfHeal für manuelle Änderungen","Analyse von Ereignissen und Cluster-Profilen","Überwachung von Prozessen und Netzwerken in Containern"],"pt":["Acesso ao Grafana em https://grafana.minikube.127.0.0.1.nip.io","Desabilitar o ArgoCD selfHeal antes de alterações manuais","Utilizar kubectl para verificar eventos em namespaces específicos","Análise de trazas, métricas, logs e perfis com o Grafana","Depuração de falhas de inicialização de pods e eventos com kubectl"],"ru":["Доступ к Grafana по адресу https://grafana.minikube.127.0.0.1.nip.io","Отключение ArgoCD selfHeal перед ручными изменениями","Использование kubectl для проверки событий в определенных namespaces","Анализ трассировок, метрик, логов и профилей с помощью Grafana","Отладка ошибок запуска pods и событий с помощью kubectl"],"ar":["الدخول إلى Grafana على https://grafana.minikube.127.0.0.1.nip.io","تعطيل ArgoCD selfHeal قبل التغييرات اليدوية","استخدام kubectl لتحقق من الأحداث في مساحات الأسماء المحددة","تحليل التتبعات والبيانات والمسجل والملفات الشخصية مع Grafana","تصحيح أخطاء بدء تشغيل pods والأحداث مع kubectl"]},"keywords":{"en":["how to use kubernetes-operations","kubernetes-operations setup guide","kubernetes debugging tools","Grafana integration with Kubernetes","kubectl commands for troubleshooting","kubernetes-operations vs other debugging tools","install kubernetes-operations","kubernetes-operations alternative solutions","what is kubernetes-operations"],"zh":["Kubernetes操作","Grafana监控","ArgoCD自动化","kubectl调试","Kubernetes运维","Kubernetes管理","AIエージェント","Kubernetes最佳实践"],"ja":["Kubernetesオペレーション","Grafanaモニタリング","ArgoCD自動化","kubectlデバッグ","Kubernetes運用","Kubernetes管理","AIエージェント","Kubernetesベストプラクティス"],"ko":["Kubernetes 운영","Grafana 모니터링","ArgoCD 자동화","kubectl 디버깅","Kubernetes 운용","Kubernetes 관리","AI 에이전트","Kubernetes 가이드"],"es":["operaciones de kubernetes","configuración de kubernetes","depuración de kubernetes","Grafana kubernetes","kubectl tutorial","ArgoCD selfHeal","monitoreo de clústeres","gestión de contenedores"],"fr":["opérations kubernetes","configuration kubernetes","débogage kubernetes","Grafana kubernetes","tutoriel kubectl","ArgoCD selfHeal","surveillance de clusters","gestion de conteneurs"],"de":["Kubernetes-Betriebsabläufe","Kubernetes-Konfiguration","Kubernetes-Fehlersuche","Grafana Kubernetes","kubectl-Tutorial","ArgoCD selfHeal","Überwachung von Clustern","Container-Verwaltung"],"pt":["kubernetes-operations","guia de configuração","gerenciamento de clusters","monitoramento de kubernetes","argoCD","grafana","kubectl","depuração de pods","análise de trazas"],"ru":["kubernetes-operations","настройка ИИ Агентов","управление кластерами","мониторинг kubernetes","argoCD","grafana","kubectl","отладка pods","анализ трассировок"],"ar":["كوبيرنتس-أوبريشنز","دليل إعداد","إدارة مجموعات","مراقبة كوبيرنتس","argoCD","grafana","kubectl","تصحيح أخطاء pods","تحليل التتبعات"]}},"owner":"hippocampus-dev","repo":"hippocampus","repoPath":"hippocampus-dev/hippocampus","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"kubernetes-operations","description":"Kubernetes cluster operations on minikube including observability (Grafana, Prometheus, Alertmanager, Loki, Tempo), debugging (kubectl debug, ephemeral containers), and cluster management (ArgoCD). Use when working with cluster/manifests/, Kubernetes workloads, pods, deployments, operators, controllers, or cluster components.","bodyPreview":"* Access Grafana at `https://grafana.minikube.127.0.0.1.nip.io`\n* Disable ArgoCD selfHeal before manual changes, re-enable after\n\n## Debugging\n\n| Investigating | Tool | Entry Point                                 |\n|---------------|------|---------------------------------------------|\n| Traces, metrics, logs, profiles | Grafana | `https://grafana.minikube.127.0.0.1.nip.io` |\n| Pod startup failures, events | kubectl | `kubectl get events -n <namespace>`         |\n| In-container process/network |","body":"* Access Grafana at `https://grafana.minikube.127.0.0.1.nip.io`\n* Disable ArgoCD selfHeal before manual changes, re-enable after\n\n## Debugging\n\n| Investigating | Tool | Entry Point                                 |\n|---------------|------|---------------------------------------------|\n| Traces, metrics, logs, profiles | Grafana | `https://grafana.minikube.127.0.0.1.nip.io` |\n| Pod startup failures, events | kubectl | `kubectl get events -n <namespace>`         |\n| In-container process/network | kubectl debug | Ephemeral container                         |\n\n### Observability Investigation (via Grafana)\n\nUse Grafana for all observability signals. Do NOT query backends (Tempo, Mimir, Loki) directly.\n\n1. **Get query parameters** - Check `cluster/manifests/<app>/` for namespace, labels, `OTEL_SERVICE_NAME` (see [Queries](reference/queries.md) for parameter locations)\n2. **Open Grafana** - Access `https://grafana.minikube.127.0.0.1.nip.io` in browser\n3. **Select datasource and query** - Use appropriate signal:\n\n| Signal | Backend | Datasource | Query Language | Use Case |\n|--------|---------|------------|----------------|----------|\n| Traces | Tempo | Tempo | TraceQL | Request flow, latency, access destinations |\n| Metrics | Mimir (Prometheus) | Mimir | PromQL | Resource usage, HTTP rates, alerting |\n| Logs | Loki | Loki | LogQL | Error investigation, audit |\n| Profiles | Pyroscope | Pyroscope | Flamegraph UI | CPU/memory hotspots |\n| Probes | Blackbox Exporter | Mimir | PromQL | Endpoint reachability |\n\n| Symptom | Signal | Query Approach |\n|---------|--------|----------------|\n| Errors in logs | Loki → Tempo | Extract traceid from logs, trace in Tempo |\n| Latency/5xx | Tempo | Search traces with `status = error` |\n| Unknown outbound dependencies | Tempo | Search traces, inspect spans for outbound calls |\n| Resource saturation | Mimir | Query CPU/memory metrics |\n| High CPU/memory | Pyroscope | Check flamegraphs |\n\n### Pod Direct Investigation (via kubectl)\n\nUse kubectl when Grafana cannot answer the question (e.g., pod not starting, container-level inspection).\n\n| Symptom | Action |\n|---------|--------|\n| Pod not starting | `kubectl get events -n <namespace>` |\n| CrashLoopBackOff | `kubectl logs <pod> -n <namespace> --previous` |\n| Network connectivity | `kubectl debug` with ephemeral container |\n| Process inspection | `kubectl debug` with ephemeral container |\n\n#### Ephemeral Container\n\n```bash\nkubectl debug <pod-name> -n <namespace> \\\n  --profile=restricted \\\n  --image=ghcr.io/hippocampus-dev/hippocampus/ephemeral-container:main \\\n  --target=<container-name> \\\n  -- <command>\n```\n\nNote: Do not use `-it` flag when executing commands. It causes output streaming issues.\n\n## Manual Changes\n\nRequired when directly modifying live cluster resources (e.g., `kubectl apply`, `kubectl patch`, `kubectl delete`) outside of the GitOps workflow.\n\n| Operation | Requires Manual Changes |\n|-----------|------------------------|\n| `kubectl apply/patch/delete` | Yes |\n| Debugging (read-only: logs, events, debug) | No |\n| Grafana queries | No |\n| Editing manifests in repo | No (ArgoCD syncs automatically) |\n\n### ArgoCD selfHeal Control\n\nArgoCD reverts manual changes unless selfHeal is disabled first. Always re-enable after.\n\n```bash\n# Disable selfHeal\nkubectl patch application <app-name> -n argocd --type=merge \\\n  -p ''{\"spec\":{\"syncPolicy\":{\"selfHeal\":false}}}''\n\n# Re-enable selfHeal (after work is complete)\nkubectl patch application <app-name> -n argocd --type=merge \\\n  -p ''{\"spec\":{\"syncPolicy\":{\"selfHeal\":true}}}''\n```\n\n## Observability Stack Manifests\n\n| Component | Path |\n|-----------|------|\n| Grafana | `cluster/manifests/grafana/` |\n| Tempo | `cluster/manifests/tempo/` |\n| Mimir | `cluster/manifests/mimir/` |\n| Loki | `cluster/manifests/loki/` |\n| Pyroscope | `cluster/manifests/pyroscope/` |\n| Prometheus | `cluster/manifests/prometheus/` |\n| Fluentd | `cluster/manifests/fluentd/` |\n| OpenTelemetry | `cluster/manifests/otel-agent/`, `cluster/manifests/otel-collector/` |\n\n## Reference\n\nIf writing observability queries:\n  See [Queries](reference/queries.md)\n"},"lastSynced":"2026-03-08T02:02:36.319Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Native Agents needing advanced Kubernetes troubleshooting and monitoring capabilities.","zh":"适合需要高级Kubernetes故障排除和监控能力的云原生代理。","ja":"クラウドネイティブエージェントが高度なKubernetesのトラブルシューティングと監視機能を必要とする場合に適しています。","ko":"고급 Kubernetes 문제 해결 및 모니터링 기능이 필요한 클라우드 네이티브 에이전트에 적합합니다.","es":"Perfecto para Agentes Nativos de la Nube que necesitan capacidades avanzadas de solución de problemas y monitoreo de Kubernetes.","fr":"Parfait pour les Agents Cloud Natifs qui ont besoin de capacités de dépannage et de surveillance avancées de Kubernetes.","de":"Perfekt für Cloud-Native-Agents, die erweiterte Kubernetes-Fehlerbehebungs- und Überwachungsfunktionen benötigen.","pt":"Perfeito para Agentes Nativos em Nuvem que necessitam de capacidades avançadas de solução de problemas e monitoramento do Kubernetes.","ru":"Идеально подходит для облачных агентов, которым необходимы продвинутые возможности для устранения неполадок и мониторинга Kubernetes.","ar":"مثالي للوكلاء الأصليين في السحابة الذين يحتاجون إلى إمكانيات متقدمة لتصحيح الأخطاء ومراقبة Kubernetes."},"recommendation":{"en":"Empowers agents to efficiently debug and investigate Kubernetes issues using Grafana for metrics and logs analysis, and kubectl for pod and namespace inspection, including disabling ArgoCD selfHeal for manual changes.","zh":"赋予代理高效地调试和调查Kubernetes问题的能力，使用Grafana进行指标和日志分析，并使用kubectl进行pod和命名空间检查，包括禁用ArgoCD selfHeal以进行手动更改。","ja":"Grafanaを使用したメトリクスとログの分析、およびkubectlを使用したポッドとネームスペースの検査（ArgoCD selfHealを無効にして手動で変更することを含む）により、エージェントがKubernetesの問題を効率的にデバッグして調査できるようにします。","ko":"Grafana를 사용하여 메트릭과 로그를 분석하고, kubectl을 사용하여 포드와 네임스페이스를 조사하여(수동 변경을 위해 ArgoCD selfHeal을 비활성화하는 것을 포함하여) 에이전트가 Kubernetes 문제를 효율적으로 디버깅하고 조사할 수 있도록 합니다.","es":"Habilita a los agentes a depurar y investigar eficientemente los problemas de Kubernetes utilizando Grafana para el análisis de métricas y registros, y kubectl para la inspección de pods y espacios de nombres, incluyendo la desactivación de ArgoCD selfHeal para cambios manuales.","fr":"Permet aux agents de déboguer et d''enquêter efficacement sur les problèmes de Kubernetes en utilisant Grafana pour l''analyse des métriques et des journaux, et kubectl pour l''inspection des pods et des espaces de noms, y compris la désactivation de ArgoCD selfHeal pour les modifications manuelles.","de":"Ermöglicht es den Agenten, Kubernetes-Probleme effizient zu debuggen und zu untersuchen, indem sie Grafana für die Analyse von Metriken und Protokollen sowie kubectl für die Inspektion von Pods und Namespaces verwenden, einschließlich der Deaktivierung von ArgoCD selfHeal für manuelle Änderungen.","pt":"Habilita os agentes a depurar e investigar problemas do Kubernetes de forma eficiente usando o Grafana para análise de métricas e logs, e o kubectl para inspeção de pod e namespace, incluindo a desativação do ArgoCD selfHeal para alterações manuais.","ru":"Позволяет агентам эффективно отлаживать и расследовать проблемы Kubernetes, используя Grafana для анализа метрик и журналов, и kubectl для инспекции pod и namespace, включая отключение ArgoCD selfHeal для ручных изменений.","ar":"يتمكن الوكلاء من تصحيح الأخطاء والتحقيق في مشاكل Kubernetes بفعالية باستخدام Grafana لتحليل المترات والسجلات، و kubectl لتحقيق pod و namespace، بما في ذلك تعطيل ArgoCD selfHeal للتغييرات اليدوية."},"useCases":{"en":["Debugging pod startup failures using kubectl","Analyzing traces and metrics with Grafana","Investigating in-container process and network issues"],"zh":["使用kubectl调试pod启动失败","使用Grafana分析跟踪和指标","调查容器内进程和网络问题"],"ja":["kubectlを使用したポッドの起動失敗のデバッグ","Grafanaを使用したトレースとメトリクスの分析","コンテナ内のプロセスとネットワークの問題の調査"],"ko":["kubectl을 사용하여 포드 시작 실패 디버깅","Grafana를 사용하여 추적 및 메트릭 분석","컨테이너 내 프로세스 및 네트워크 문제 조사"],"es":["Depuración de fallos de inicio de pod utilizando kubectl","Análisis de trazas y métricas con Grafana","Investigación de problemas de procesos y redes dentro de contenedores"],"fr":["Débogage des échecs de démarrage de pod à l''aide de kubectl","Analyse de traces et de métriques avec Grafana","Enquête sur les problèmes de processus et de réseau dans les conteneurs"],"de":["Fehlerbehebung bei Pod-Startfehlern mit kubectl","Analyse von Spuren und Metriken mit Grafana","Untersuchung von Prozess- und Netzwerkproblemen innerhalb von Containern"],"pt":["Depuração de falhas de inicialização de pod usando kubectl","Análise de rastros e métricas com o Grafana","Investigação de problemas de processo e rede dentro do contêiner"],"ru":["Отладка сбоев запуска pod с помощью kubectl","Анализ трассировки и метрик с помощью Grafana","Расследование проблем процесса и сети внутри контейнера"],"ar":["تصحيح أخطاء بدء تشغيل pod باستخدام kubectl","تحليل التتبع والمقاييس باستخدام Grafana","التحقيق في مشاكل العملية والشبكة داخل الحاوية"]},"limitations":{"en":["Requires access to Grafana at https://grafana.minikube.127.0.0.1.nip.io","Needs kubectl for command-line interactions","ArgoCD selfHeal must be disabled before manual changes"],"zh":["需要访问https://grafana.minikube.127.0.0.1.nip.io的Grafana","需要kubectl进行命令行交互","在进行手动更改之前必须禁用ArgoCD selfHeal"],"ja":["https://grafana.minikube.127.0.0.1.nip.ioのGrafanaにアクセスする必要がある","kubectlがコマンドラインのやり取りに必要","手動で変更する前にArgoCD selfHealを無効にする必要がある"],"ko":["https://grafana.minikube.127.0.0.1.nip.io의 Grafana에 액세스해야 함","kubectl이 명령줄 상호 작용에 필요","수동으로 변경하기 전에 ArgoCD selfHeal을 비활성화해야 함"],"es":["Requiere acceso a Grafana en https://grafana.minikube.127.0.0.1.nip.io","Necesita kubectl para interacciones de línea de comandos","ArgoCD selfHeal debe estar desactivado antes de los cambios manuales"],"fr":["Nécessite un accès à Grafana à l''adresse https://grafana.minikube.127.0.0.1.nip.io","Nécessite kubectl pour les interactions en ligne de commande","ArgoCD selfHeal doit être désactivé avant les modifications manuelles"],"de":["Erfordert Zugriff auf Grafana unter https://grafana.minikube.127.0.0.1.nip.io","Benötigt kubectl für Kommandozeileninteraktionen","ArgoCD selfHeal muss vor manuellen Änderungen deaktiviert werden"],"pt":["Requer acesso ao Grafana em https://grafana.minikube.127.0.0.1.nip.io","Necessita kubectl para interações de linha de comando","ArgoCD selfHeal deve ser desativado antes de alterações manuais"],"ru":["Требует доступа к Grafana по адресу https://grafana.minikube.127.0.0.1.nip.io","Требует kubectl для взаимодействия с командной строкой","ArgoCD selfHeal должен быть отключен перед ручными изменениями"],"ar":["يتطلب الوصول إلى Grafana على https://grafana.minikube.127.0.0.1.nip.io","يحتاج إلى kubectl للتفاعل مع سطر الأوامر","يجب تعطيل ArgoCD selfHeal قبل التغييرات اليدوية"]},"version":4},"contentHash":"4c446f154c8ce1582ad6fff59075a6b441ca2cccc8f21320426bcd1d1db45473","qualityScore":42}');
