INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hippocampus-dev/hippocampus/kubernetes-operations', 'kubernetes-operations', 'hippocampus-dev', 'hippocampus', 'community', 'kubernetes-operations hippocampus-dev hippocampus community The kubernetes-operations skill provides developers with a robust toolset for debugging and investigating Kubernetes issues, leveraging Grafana and kubectl for efficient troubleshooting. Kubernetes操作技能提供了访问Grafana、配置ArgoCD和使用kubectl进行调试的能力 KubernetesオペレーションスキルはGrafanaへのアクセス、ArgoCDの設定、kubectlによるデバッグを提供する Kubernetes 운영 스킬은 Grafana 접근, ArgoCD 설정, kubectl 디버깅을 제공합니다 La guía de operaciones de Kubernetes te permite configurar y depurar clústeres de manera eficiente. Accede a herramientas como Grafana y kubectl Le guide des opérations Kubernetes vous permet de configurer et de déboguer les clusters de manière efficace. Accédez aux outils tels que Grafana et kubectl Der Kubernetes-Betriebsleitfaden ermöglicht es Ihnen, Cluster effizient zu konfigurieren und zu debuggen. Zugriff auf Tools wie Grafana und kubectl O Kubernetes-Operations é uma ferramenta para gerenciar e monitorar clusters Kubernetes. Aprenda a configurá-lo com nosso guia. Kubernetes-Operations - это инструмент для управления и мониторинга кластеров Kubernetes. Узнайте, как его настроить. كوبيرنتس-أوبريشنز هي أداة لادارة وتحكم مجموعات كوبيرنتس. تعلم كيفية إعدادها مع دليلنا. how to use kubernetes-operations kubernetes-operations setup guide kubernetes debugging tools Grafana integration with Kubernetes kubectl commands for troubleshooting kubernetes-operations vs other debugging tools install kubernetes-operations kubernetes-operations alternative solutions what is kubernetes-operations Kubernetes操作 Grafana监控 ArgoCD自动化 kubectl调试 Kubernetes运维 Kubernetes管理 AIエージェント Kubernetes最佳实践 Access to Grafana at https://grafana.minikube.127.0.0.1.nip.io for comprehensive metrics and logging Disable and re-enable ArgoCD self-healing for manual changes Utilize kubectl for pod startup failure investigation and event analysis Leverage Grafana for tracing, metrics, logs, and profiles Investigate in-container process and network issues kubernetes-operations is a specialized AI agent skill for streamlining Kubernetes debugging and operations, utilizing key technologies like Grafana and kubectl.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('H2OSLabs/SynnovatorZero/spec-writer', 'community', 'H2OSLabs', 'SynnovatorZero', 'H2OSLabs/SynnovatorZero', 'spec-writer', 0, 0, 42, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:36.442Z', '774f32769541936c11ea1fadf892f114464fbf82d6505a6d6c56b97e2ce2735a', '{"id":"H2OSLabs/SynnovatorZero/spec-writer","name":"spec-writer","description":{"en":"The spec-writer skill helps users create structured SPEC.md files for AI coding agents using a 4-stage gated workflow, covering core domains like Commands and Git Workflow. It benefits developers working with AI agents.","zh":"Spec Writer 是一个帮助用户创建结构化 SPEC.md 文件的工具，用于 AI 编码代理的配置","ja":"Spec Writer は、AIエージェントの構成に使用される構造化された SPEC.md ファイルを作成するためのツールです","ko":"Spec Writer는 AI 에이전트의 구성에 사용되는 구조화된 SPEC.md 파일을 생성하기 위한 도구입니다","es":"Spec-writer es una herramienta para guiar a los usuarios en la creación de un SPEC.md estructurado para agentes de AI utilizando un flujo de trabajo de 4 etapas","fr":"Spec-writer est un outil pour guider les utilisateurs dans la création d''un SPEC.md structuré pour les agents d''IA en utilisant un flux de travail de 4 étapes","de":"Spec-writer ist ein Tool, um Benutzer bei der Erstellung eines strukturierten SPEC.md für KI-Agenten mit einem 4-Stufen-Workflow zu unterstützen","pt":"O Spec Writer é uma ferramenta que ajuda a criar agentes de IA com um fluxo de trabalho estruturado em 4 etapas e 6 domínios principais","ru":"Spec Writer - это инструмент, который помогает создавать ИИ Агентов с структурированным рабочим процессом в 4 этапа и 6 основных доменов","ar":"كاتب المواصفات هو أداة تساعد في إنشاء وكلاء ذكيين مع تدفق عمل منظم في 4 مراحل و 6 مجالات رئيسية"},"seo":{"title":{"en":"spec-writer: Structured SPEC.md Generation for AI Agents ...","zh":"Spec Writer 设置指南：结构化 SPEC.md 编写","ja":"Spec Writer セットアップガイド：AIエージェントの構造化 SPEC.md 作成","ko":"Spec Writer 설정 가이드: 구조화된 SPEC.md 작성","es":"Guía de configuración de spec-writer para agentes de AI","fr":"Guide de mise en place de spec-writer pour les agents d''IA","de":"Einrichtungsleitfaden für spec-writer in KI-Agenten","pt":"Guia de Configuração do Spec Writer para Ferramentas de IA","ru":"Настройка Spec Writer для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد كاتب المواصفات للوكلاء الذكيين"},"description":{"en":"Discover how spec-writer guides users through a 4-stage gated workflow to create structured SPEC.md files for AI coding agents. Learn more and get started to...","zh":"使用 Spec Writer 创建结构化的 SPEC.md 文件，实现 AI 编码代理的高效配置","ja":"Spec Writer を使用して構造化された SPEC.md ファイルを作成し、AIエージェントの効率的な構成を実現","ko":"Spec Writer를 사용하여 구조화된 SPEC.md 파일을 생성하고 AI 에이전트의 효율적인 구성 구현","es":"Aprende a configurar spec-writer para agentes de AI con nuestra guía paso a paso y mejora la eficiencia de tus proyectos","fr":"Découvrez comment configurer spec-writer pour les agents d''IA avec notre guide étape par étape et améliorez l''efficacité de vos projets","de":"Erfahren Sie, wie Sie spec-writer für KI-Agenten konfigurieren und die Effizienz Ihrer Projekte verbessern","pt":"Aprenda a configurar o Spec Writer para criar agentes de IA eficazes com um fluxo de trabalho em 4 etapas e 6 domínios principais","ru":"Узнайте, как настроить Spec Writer для создания эффективных ИИ Агентов с 4-этапным рабочим процессом и 6 основными доменами","ar":"تعلم كيفية إعداد كاتب المواصفات لإنشاء وكلاء ذكيين فعالين مع تدفق عمل في 4 مراحل و 6 مجالات رئيسية"},"definition":{"en":"spec-writer is a skill that guides users through writing structured SPEC.md files for AI coding agents using a 4-stage gated workflow, covering six core domains.","zh":"Spec Writer 是一种 AI 编码代理配置工具，帮助用户创建结构化的 SPEC.md 文件","ja":"Spec Writer は、AIエージェントの構成に使用される構造化された SPEC.md ファイルを作成するためのツールです","ko":"Spec Writer는 AI 에이전트의 구성에 사용되는 구조화된 SPEC.md 파일을 생성하기 위한 도구입니다","es":"Spec-writer es una herramienta de creación de especificaciones para agentes de AI que utiliza un flujo de trabajo de 4 etapas","fr":"Spec-writer est un outil de création de spécifications pour les agents d''IA qui utilise un flux de travail de 4 étapes","de":"Spec-writer ist ein Tool zur Erstellung von Spezifikationen für KI-Agenten mit einem 4-Stufen-Workflow","pt":"O Spec Writer é uma ferramenta de criação de agentes de IA que utiliza um fluxo de trabalho em 4 etapas","ru":"Spec Writer - это инструмент создания ИИ Агентов, который использует 4-этапный рабочий процесс","ar":"كاتب المواصفات هو أداة لإنشاء وكلاء ذكيين تستخدم تدفق عمل في 4 مراحل"},"features":{"en":["Guides users through a 4-stage gated workflow for structured SPEC.md creation","Covers six core domains: Commands, Testing, Project Structure, Code Style, Git Workflow, and Boundaries","Mirrors the user''s language for responsive interaction","Follows the key principle of Concrete over abstract for effective SPEC.md generation","Supports multiple languages without hardcoding, including Chinese and English"],"zh":["4 阶段的 gated 工作流程","6 个核心域：Commands、Testing、Project Structure、Code Style、Git Workflow 和 Boundaries","镜像用户语言：如果用户写中文，响应中文；如果用户写英文，响应英文","具体优于抽象：使用具体的例子和代码片段","支持多语言：包括中文、英文等"],"ja":["4 段階のゲート化されたワークフロー","6 つのコアドメイン：コマンド、テスト、プロジェクト構造、コードスタイル、Git ワークフロー、境界","ユーザーの言語をミラーリング：ユーザーが中国語を書く場合、中国語で応答；ユーザーが英語を書く場合、英語で応答","具体性を優先：具体的な例とコードスニペットを使用","多言語対応：中国語、英語など"],"ko":["4 단계의 게이트화된 워크플로","6 개의 핵심 도메인: 명령, 테스트, 프로젝트 구조, 코드 스타일, Git 워크플로, 경계","사용자의 언어를 미러링: 사용자가 중국어를 작성할 경우 중국어로 응답; 사용자가 영어를 작성할 경우 영어로 응답","구체적인 예와 코드 스니펫을 사용","다중 언어 지원: 중국어, 영어 등"],"es":["Flujo de trabajo de 4 etapas para la creación de SPEC.md","Cobertura de seis dominios core: Comandos, Pruebas, Estructura de proyecto, Estilo de código, Flujo de trabajo de Git y Límites","Compatibilidad con múltiples idiomas, incluyendo chino e inglés","Principio de concreción sobre abstracción para la creación de especificaciones"],"fr":["Flux de travail de 4 étapes pour la création de SPEC.md","Couverture de six domaines core : Commandes, Tests, Structure de projet, Style de code, Flux de travail Git et Limites","Compatibilité avec plusieurs langues, notamment le chinois et l''anglais","Principe de concrétisation sur abstraction pour la création de spécifications"],"de":["4-Stufen-Workflow für die Erstellung von SPEC.md","Abdeckung von sechs Kernbereichen: Befehle, Tests, Projektstruktur, Code-Stil, Git-Workflow und Grenzen","Unterstützung für mehrere Sprachen, einschließlich Chinesisch und Englisch","Prinzip der Konkretisierung gegenüber Abstraktion für die Erstellung von Spezifikationen"],"pt":["Fluxo de trabalho em 4 etapas","6 domínios principais: Comandos, Testes, Estrutura de Projeto, Estilo de Código, Fluxo de Trabalho do Git e Limites","Compatibilidade com linguagens múltiplas","Regras concretas para escrever especificações","Integração com ferramentas de desenvolvimento de IA","Suporte a configurações personalizadas"],"ru":["4-этапный рабочий процесс","6 основных доменов: Команды, Тестирование, Структура Проекта, Стиль Кодирования, Рабочий Процесс Git и Границы","Поддержка нескольких языков","Конкретные правила для написания спецификаций","Интеграция с инструментами разработки ИИ","Поддержка настраиваемых конфигураций"],"ar":["تدفق عمل في 4 مراحل","6 مجالات رئيسية: أوامر، اختبار، هيكل المشروع، أسلوب البرمجة، تدفق عمل جيت وحدود","دعم اللغات المتعددة","قواعد ملموسة لكتابة المواصفات","التكامل مع أدوات تطوير الذكاء الاصطناعي","دعم التكوينات المخصصة"]},"keywords":{"en":["how to use spec-writer","spec-writer setup guide","what is spec-writer","spec-writer alternative","spec-writer vs other AI agent skills","spec-writer install","structured SPEC.md generation","AI coding agent configuration","4-stage gated workflow"],"zh":["Spec Writer","AI 编码代理","结构化 SPEC.md","4 阶段的 gated 工作流程","核心域","镜像用户语言","具体优于抽象","多语言支持"],"ja":["Spec Writer","AIエージェント","構造化された SPEC.md","4 段階のゲート化されたワークフロー","コアドメイン","ユーザーの言語をミラーリング","具体性を優先","多言語対応"],"ko":["Spec Writer","AI 에이전트","구조화된 SPEC.md","4 단계의 게이트화된 워크플로","핵심 도메인","사용자의 언어를 미러링","구체적인 예와 코드 스니펫","다중 언어 지원"],"es":["agentes de AI","herramientas de AI","SPEC.md","flujo de trabajo de 4 etapas","creación de especificaciones","desarrollo de software","ingeniería de software","automatización de pruebas"],"fr":["agents d''IA","outils d''IA","SPEC.md","flux de travail de 4 étapes","création de spécifications","développement de logiciels","ingénierie de logiciels","automatisation de tests"],"de":["KI-Agenten","KI-Tools","SPEC.md","4-Stufen-Workflow","Erstellung von Spezifikationen","Software-Entwicklung","Software-Ingenieurwesen","Automatisierung von Tests"],"pt":["Spec Writer","Ferramentas de IA","Desenvolvimento de Agentes de IA","Fluxo de Trabalho em 4 Etapas","Domínios Principais","Linguagens Múltiplas","Regras Concretas","Integração com Ferramentas de Desenvolvimento de IA","Configurações Personalizadas"],"ru":["Spec Writer","ИИ Агенты","Разработка ИИ Агентов","4-этапный Рабочий Процесс","Основные Домены","Несколько Языков","Конкретные Правила","Интеграция с Инструментами Разработки ИИ","Настраиваемые Конфигурации"],"ar":["كاتب المواصفات","وكلاء الذكاء الاصطناعي","تطوير وكلاء الذكاء الاصطناعي","تدفق عمل في 4 مراحل","المجالات الرئيسية","لغات متعددة","قواعد ملموسة","التكامل مع أدوات تطوير الذكاء الاصطناعي","تكوينات مخصصة"]}},"owner":"H2OSLabs","repo":"SynnovatorZero","repoPath":"H2OSLabs/SynnovatorZero","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"spec-writer","description":"Guide structured specification writing for AI coding agents using a 4-stage gated workflow (Specify, Plan, Tasks, Implement) and a 6-domain framework (Commands, Testing, Project Structure, Code Style, Git Workflow, Boundaries). Produces a SPEC.md file that serves as a living reference for the project. Use when user mentions writing a spec, creating a SPEC.md, setting up project guidelines, onboarding an AI agent to a codebase, or asks for structured project specification. Trigger phrases include write a spec, create a SPEC.md, set up project guidelines, spec out this project, define project standards.","bodyPreview":"# Spec Writer\n\n## Overview\n\nGuide users through writing a structured SPEC.md for AI coding agents using a 4-stage gated workflow. The spec covers six core domains drawn from analysis of effective agent configurations: Commands, Testing, Project Structure, Code Style, Git Workflow, and Boundaries.\n\n**Core rule:** Mirror the user''s language. If they write in Chinese, respond in Chinese. If in English, respond in English. Never hardcode a language.\n\n**Key principle:** Concrete over abstract. A real","body":"# Spec Writer\n\n## Overview\n\nGuide users through writing a structured SPEC.md for AI coding agents using a 4-stage gated workflow. The spec covers six core domains drawn from analysis of effective agent configurations: Commands, Testing, Project Structure, Code Style, Git Workflow, and Boundaries.\n\n**Core rule:** Mirror the user''s language. If they write in Chinese, respond in Chinese. If in English, respond in English. Never hardcode a language.\n\n**Key principle:** Concrete over abstract. A real code snippet beats a paragraph of description. A runnable command beats a tool name. A specific file path beats \"see the docs.\"\n\n## When to Offer\n\nOffer this workflow when:\n- User says \"write a spec\", \"create a SPEC.md\", \"spec out this project\"\n- User wants to set up project guidelines or standards for an AI agent\n- User asks how to onboard an AI coding agent to their codebase\n- User mentions spec-driven development or structured project documentation\n- User wants to define boundaries/rules for an AI coding agent\n\n**Initial offer:** Explain the 4-stage workflow and ask if they want to proceed or work freeform. If they decline, work freeform. If they accept, proceed to Stage 1.\n\n## Stage 1: Specify (Vision Gathering)\n\n**Goal:** Understand what is being built, for whom, and why. No technical details yet.\n\n### Branching: Greenfield vs Existing\n\nDetermine which path applies:\n\n**Greenfield project (building from scratch):**\n1. Ask: What are you building? Who is it for? What problem does it solve?\n2. Ask: What does success look like? How will you know the project works?\n3. Ask: Any constraints or non-negotiables? (timeline, technology mandates, etc.)\n4. Draft a 2-3 sentence Vision statement and Success Criteria checklist\n5. Present for approval\n\n**Existing project (adding a spec to existing code):**\n1. Ask: What is this project? Point me to the codebase.\n2. Explore the codebase: read `package.json`/`pyproject.toml`/`Cargo.toml`, scan directory structure, read README if present\n3. Draft a Vision statement based on what exists\n4. Ask: Is this accurate? What''s missing or wrong?\n5. Present for approval\n\n### Stage 1 Gate\n\nPresent the Vision and Success Criteria. User must approve before advancing.\n\nIf user wants changes, iterate. Only proceed to Stage 2 when user explicitly approves.\n\n**Output so far:** Vision section + Success Criteria checklist.\n\n## Stage 2: Plan (Six Domain Framework)\n\n**Goal:** Systematically collect information for all six domains.\n\nRead [references/six-domains-checklist.md](references/six-domains-checklist.md) for the detailed checklist of what to collect, output formats, mistakes to avoid, and questions to ask for each domain.\n\n### Workflow\n\n1. **For each domain** (Commands, Testing, Project Structure, Code Style, Git Workflow, Boundaries), follow this loop:\n   - Ask the domain-specific questions from the checklist\n   - For existing projects: also probe the codebase (read configs, scan files, check for linters/formatters)\n   - Draft the domain section in the checklist''s output format\n   - Present for user review\n\n2. **Boundaries get special treatment:**\n   - Read [references/boundary-patterns.md](references/boundary-patterns.md) for project-type-specific examples\n   - Always produce all three tiers: Always, Ask First, Never\n   - The \"Never commit secrets\" rule is mandatory in every spec\n   - Adapt patterns to the specific project rather than copying generic lists\n\n3. **Tech Stack:** Also collect the full tech stack during this stage (language, framework, database, testing framework, package manager, versions).\n\n### Stage 2 Gate\n\nPresent a summary of all six domains plus the tech stack. User must approve before advancing.\n\nIf any domain is incomplete or wrong, iterate on that domain. Only proceed to Stage 3 when all six domains are approved.\n\n**Output so far:** Vision + Success Criteria + Tech Stack + all six domains in draft form.\n\n## Stage 3: Tasks (Decomposition and Scaffolding)\n\n**Goal:** Assemble the approved content into a SPEC.md file using the template scaffold.\n\nRead [references/spec-template.md](references/spec-template.md) for the output template.\n\n### Workflow\n\n1. Create a new file `SPEC.md` (or the user''s preferred filename/location) using the template scaffold\n2. Fill in each template section with the content approved in Stages 1-2\n3. For any optional sections (Architecture Notes, Version History), ask if the user wants them included\n4. Set Version History to `1.0 | [today''s date] | Initial specification`\n\n### Stage 3 Gate\n\nPresent the complete SPEC.md draft. User must approve the assembled document.\n\nKey review points to highlight:\n- Does the assembled document flow well as a whole?\n- Are there contradictions between sections?\n- Is anything missing that became obvious when seeing everything together?\n\nIterate until user approves.\n\n## Stage 4: Implement (Validation and Finalization)\n\n**Goal:** Validate completeness, finalize the spec, and establish it as the project''s living reference.\n\n### Workflow\n\n1. **Self-check:** Re-read the complete SPEC.md and verify:\n   - All six domains have substantive content (not placeholders)\n   - Boundaries has all three tiers\n   - Commands section has actual runnable commands with flags\n   - Code Style section has at least one real code snippet\n   - Success Criteria are measurable\n\n2. **Script validation:** Run the validation script:\n   ```bash\n   uv run python [skill-path]/scripts/validate_spec.py [spec-path]\n   ```\n   Replace `[skill-path]` with the path to this skill''s directory and `[spec-path]` with the SPEC.md file path.\n\n3. **Fix any failures:** If validation finds gaps, go back to the relevant section and fix it. Re-run until all checks pass.\n\n4. **Final presentation:** Show the user the validation results and the complete SPEC.md. Ask for final approval.\n\n### Stage 4 Gate\n\nUser gives final approval. The spec is done.\n\n## Post-Completion\n\nAfter the spec is approved:\n\n1. **Living document guidance:** Remind the user that SPEC.md is a living document:\n   - Update it when requirements change\n   - Update it when technical decisions are made\n   - Track changes in Version History\n   - Commit it to version control alongside code\n\n2. **Integration suggestions:**\n   - Place SPEC.md at the project root or in a `specs/` directory\n   - Reference it from CLAUDE.md or agents.md if applicable\n   - Consider adding the validation script to CI\n\n3. **Next steps:** Ask if the user wants to:\n   - Start implementing based on the spec\n   - Create task breakdowns from the spec\n   - Review an existing spec against this framework\n\n## Handling Deviations\n\n**User wants to skip stages:** Allow it, but warn that skipping Stage 2 (Plan) risks an incomplete spec. If they skip, note which domains weren''t covered.\n\n**User wants a partial spec:** Support single-domain mode — e.g., \"just help me define boundaries.\" Follow the Stage 2 workflow for that domain only, then validate just that section.\n\n**User has an existing SPEC.md to audit:** Run `validate_spec.py` on it first, then walk through any FAIL items using the six-domains checklist.\n\n**User is updating, not creating:** Read the existing SPEC.md, identify what changed, update the relevant sections, bump the version in Version History.\n\n## Quality Principles\n\n1. **Concrete over abstract:** A runnable command beats a tool name. A code snippet beats a style description. A file path beats \"see the docs.\"\n\n2. **Boundaries are non-negotiable:** Every spec must have all three tiers. \"Never commit secrets\" is always included. Generic boundaries (\"don''t break things\") are rejected — push for specifics.\n\n3. **Six domains are mandatory:** No spec is complete without all six. If the user insists on skipping one, note the gap explicitly in the spec.\n\n4. **The spec is for an AI agent, not a human:** Write for parsability. Use headers, lists, and code blocks. Avoid prose paragraphs where structured formats work better.\n\n5. **Medium freedom template:** The six domains are fixed scaffolding. Content within each domain is flexible and adapts to the project. Don''t force patterns that don''t fit.\n\n6. **Validate deterministically:** Always run the validation script. Human judgment catches semantic issues; the script catches structural ones. Both matter.\n"},"lastSynced":"2026-03-08T02:02:36.442Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Coding Agents needing structured SPEC.md files for efficient workflow management.","zh":"非常适合需要结构化SPEC.md文件以实现高效工作流管理的AI编码代理。","ja":"AIコーディングエージェントが効率的なワークフローマネジメントのために構造化されたSPEC.mdファイルを必要とする場合に最適です。","ko":"효율적인 워크플로우 관리를 위해 구조화된 SPEC.md 파일이 필요한 AI 코딩 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Codificación de IA que necesitan archivos SPEC.md estructurados para una gestión de flujo de trabajo eficiente.","fr":"Parfait pour les Agents de Codage IA ayant besoin de fichiers SPEC.md structurés pour une gestion de workflow efficace.","de":"Perfekt für AI-Coding-Agents, die strukturierte SPEC.md-Dateien für eine effiziente Workflow-Verwaltung benötigen.","pt":"Perfeito para Agentes de Codificação de IA que necessitam de arquivos SPEC.md estruturados para gerenciamento de fluxo de trabalho eficiente.","ru":"Идеально подходит для агентов кодирования ИИ, которым требуются структурированные файлы SPEC.md для эффективного управления рабочим процессом.","ar":"مثالي لعميل التشفير الاصطناعي الذي يحتاج إلى ملفات SPEC.md منظمة لإدارة تدفق العمل الفعال."},"recommendation":{"en":"Empowers agents to generate comprehensive SPEC.md files using a 4-stage gated workflow, covering core domains like Commands, Testing, Project Structure, Code Style, Git Workflow, and Boundaries, while mirroring the user''s language for seamless interaction.","zh":"使代理能够使用4阶段门控工作流生成全面SPEC.md文件，涵盖命令、测试、项目结构、代码样式、Git工作流和边界等核心领域，同时镜像用户的语言以实现无缝交互。","ja":"エージェントが4ステージのゲート付きワークフローを使用して包括的なSPEC.mdファイルを生成できるようにし、コマンド、テスト、プロジェクト構造、コードスタイル、Gitワークフロー、境界などのコアドメインをカバーし、ユーザーの言語をミラーリングしてシームレスな相互作用を実現します。","ko":"에이전트가 4단계 게이트 워크플로를 사용하여 포괄적인 SPEC.md 파일을 생성할 수 있도록 하며, 명령, 테스트, 프로젝트 구조, 코드 스타일, Git 워크플로, 경계 등 핵심 도메인을 다루며, 사용자의 언어를 미러링하여 무중단 상호 작용을 구현합니다.","es":"Habilita a los agentes para generar archivos SPEC.md completos utilizando un flujo de trabajo con 4 etapas, cubriendo dominios básicos como Comandos, Pruebas, Estructura de Proyecto, Estilo de Código, Flujo de trabajo de Git y Límites, al mismo tiempo que refleja el lenguaje del usuario para una interacción sin problemas.","fr":"Permet aux agents de générer des fichiers SPEC.md complets en utilisant un workflow à 4 étapes, couvrant des domaines clés tels que Commandes, Tests, Structure de Projet, Style de Code, Workflow Git et Limites, tout en reflétant le langage de l''utilisateur pour une interaction sans heurts.","de":"Ermöglicht es Agents, umfassende SPEC.md-Dateien mit einem 4-Stufen-Workflow zu generieren, der Kernbereiche wie Befehle, Tests, Projektstruktur, Code-Stil, Git-Workflow und Grenzen abdeckt, während gleichzeitig die Sprache des Benutzers für eine nahtlose Interaktion widerspiegelt.","pt":"Habilita os agentes a gerar arquivos SPEC.md abrangentes usando um fluxo de trabalho de 4 estágios, cobrindo domínios principais como Comandos, Testes, Estrutura de Projeto, Estilo de Código, Fluxo de Trabalho do Git e Limites, ao mesmo tempo em que reflete a linguagem do usuário para interação sem problemas.","ru":"Наделяет агентов возможностью генерировать всесторонние файлы SPEC.md, используя 4-этапный поток управления, охватывающий основные области, такие как Команды, Тестирование, Структура проекта, Стиль кода, Поток работы Git и Границы, одновременно отражая язык пользователя для беспрепятственного взаимодействия.","ar":"يمنح الوكلاء القدرة على إنشاء ملفات SPEC.md شاملة باستخدام تدفق عمل من 4 مراحل ، وتغطية المجالات الأساسية مثل الأوامر والاختبار وهيكلة المشروع وأسلوب الكود وتدفق عمل Git والحدود ، وفي الوقت نفسه يعكس لغة المستخدم للتفاعل السلس."},"useCases":{"en":["Automating SPEC.md file creation for AI coding projects","Generating structured documentation for Commands and Git Workflow","Streamlining agent configurations through concrete and abstract principle application"],"zh":["自动创建AI编码项目的SPEC.md文件","为命令和Git工作流生成结构化文档","通过具体和抽象原则的应用简化代理配置"],"ja":["AIコーディングプロジェクトのSPEC.mdファイルの自動作成","コマンドとGitワークフローに対する構造化ドキュメントの生成","具体的および抽象的な原則の適用によるエージェント設定の簡素化"],"ko":["AI 코딩 프로젝트의 SPEC.md 파일 자동 생성","명령 및 Git 워크플로에 대한 구조화된 문서 생성","구체적이고 추상적인 원칙의 적용을 통한 에이전트 구성의 간소화"],"es":["Automatización de la creación de archivos SPEC.md para proyectos de codificación de IA","Generación de documentación estructurada para Comandos y Flujo de trabajo de Git","Optimización de la configuración de los agentes a través de la aplicación de principios concretos y abstractos"],"fr":["Automatisation de la création de fichiers SPEC.md pour les projets de codage IA","Génération de documentation structurée pour les Commandes et le Workflow Git","Optimisation de la configuration des agents via l''application de principes concrets et abstraits"],"de":["Automatisierung der Erstellung von SPEC.md-Dateien für AI-Coding-Projekte","Generierung von strukturierter Dokumentation für Befehle und Git-Workflow","Optimierung der Agentenkonfiguration durch die Anwendung von konkreten und abstrakten Prinzipien"],"pt":["Automatizar a criação de arquivos SPEC.md para projetos de codificação de IA","Gerar documentação estruturada para Comandos e Fluxo de Trabalho do Git","Otificar as configurações dos agentes por meio da aplicação de princípios concretos e abstratos"],"ru":["Автоматизировать создание файлов SPEC.md для проектов кодирования ИИ","Генерировать структурированную документацию для Команд и Потока работы Git","Оптимизировать конфигурации агентов посредством применения конкретных и абстрактных принципов"],"ar":["تتمة إنشاء ملفات SPEC.md تلقائيًا لمشاريع التشفير الاصطناعي","إنشاء توثيق منظم للأوامر وتدفق عمل Git","جعل إعدادات الوكلاء أكثر كفاءة من خلال تطبيق المبادئ الملموسة والمجردة"]},"limitations":{"en":["Requires understanding of 4-stage gated workflow","Limited to six core domains","Mirrors user''s language, requiring adaptability"],"zh":["需要理解4阶段门控工作流","仅限六个核心领域","镜像用户的语言，需要适应性"],"ja":["4ステージのゲート付きワークフローの理解が必要","6つのコアドメインに限定される","ユーザーの言語をミラーリングするため、適応性が必要"],"ko":["4단계 게이트 워크플로의 이해가 필요","6개의 핵심 도메인으로 제한됨","사용자의 언어를 미러링하므로 적응성이 필요"],"es":["Requiere comprensión del flujo de trabajo con 4 etapas","Limitado a seis dominios básicos","Refleja el lenguaje del usuario, requiriendo adaptabilidad"],"fr":["Nécessite une compréhension du workflow à 4 étapes","Limité à six domaines clés","Reflette le langage de l''utilisateur, nécessitant une adaptabilité"],"de":["Benötigt Verständnis des 4-Stufen-Workflows","Begrenzt auf sechs Kernbereiche","Spiegelt die Sprache des Benutzers wider, erfordert Anpassungsfähigkeit"],"pt":["Requer entendimento do fluxo de trabalho de 4 estágios","Limitado a seis domínios principais","Reflete a linguagem do usuário, exigindo adaptabilidade"],"ru":["Требует понимания 4-этапного потока управления","Ограничен шестью основными областями","Отражает язык пользователя, требуя адаптивности"],"ar":["يتطلب فهم تدفق العمل من 4 مراحل","محدود بستة مجالات رئيسية","يعكس لغة المستخدم ، مما يتطلب المرونة"]},"version":4},"contentHash":"774f32769541936c11ea1fadf892f114464fbf82d6505a6d6c56b97e2ce2735a","qualityScore":42}');
