INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('H2OSLabs/SynnovatorZero/spec-writer', 'spec-writer', 'H2OSLabs', 'SynnovatorZero', 'community', 'spec-writer H2OSLabs SynnovatorZero community The spec-writer skill helps users create structured SPEC.md files for AI coding agents using a 4-stage gated workflow, covering core domains like Commands and Git Workflow. It benefits developers working with AI agents. Spec Writer 是一个帮助用户创建结构化 SPEC.md 文件的工具，用于 AI 编码代理的配置 Spec Writer は、AIエージェントの構成に使用される構造化された SPEC.md ファイルを作成するためのツールです Spec Writer는 AI 에이전트의 구성에 사용되는 구조화된 SPEC.md 파일을 생성하기 위한 도구입니다 Spec-writer es una herramienta para guiar a los usuarios en la creación de un SPEC.md estructurado para agentes de AI utilizando un flujo de trabajo de 4 etapas Spec-writer est un outil pour guider les utilisateurs dans la création d''un SPEC.md structuré pour les agents d''IA en utilisant un flux de travail de 4 étapes Spec-writer ist ein Tool, um Benutzer bei der Erstellung eines strukturierten SPEC.md für KI-Agenten mit einem 4-Stufen-Workflow zu unterstützen O Spec Writer é uma ferramenta que ajuda a criar agentes de IA com um fluxo de trabalho estruturado em 4 etapas e 6 domínios principais Spec Writer - это инструмент, который помогает создавать ИИ Агентов с структурированным рабочим процессом в 4 этапа и 6 основных доменов كاتب المواصفات هو أداة تساعد في إنشاء وكلاء ذكيين مع تدفق عمل منظم في 4 مراحل و 6 مجالات رئيسية how to use spec-writer spec-writer setup guide what is spec-writer spec-writer alternative spec-writer vs other AI agent skills spec-writer install structured SPEC.md generation AI coding agent configuration 4-stage gated workflow Spec Writer AI 编码代理 结构化 SPEC.md 4 阶段的 gated 工作流程 核心域 镜像用户语言 具体优于抽象 多语言支持 Guides users through a 4-stage gated workflow for structured SPEC.md creation Covers six core domains: Commands, Testing, Project Structure, Code Style, Git Workflow, and Boundaries Mirrors the user''s language for responsive interaction Follows the key principle of Concrete over abstract for effective SPEC.md generation Supports multiple languages without hardcoding, including Chinese and English spec-writer is a skill that guides users through writing structured SPEC.md files for AI coding agents using a 4-stage gated workflow, covering six core domains.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('maskelog/Daegu_bus_flutter_app/mobile-design', 'community', 'maskelog', 'Daegu_bus_flutter_app', 'maskelog/Daegu_bus_flutter_app', 'mobile-design', 0, 0, 42, '2026-03-08T01:57:15.318Z', '2026-03-08T02:02:55.508Z', 'ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682', '{"id":"maskelog/Daegu_bus_flutter_app/mobile-design","name":"mobile-design","description":{"en":"The mobile-design skill enables developers to create touch-first, battery-conscious, and platform-respectful mobile applications. It benefits developers who need to optimize their mobile apps for various platforms.","zh":"移动设计系统是一种基于触摸优先、电池意识、平台尊重和离线能力的设计哲学，通过Python脚本进行验证","ja":"モバイルデザインシステムは、タッチファースト、バッテリー意識、プラットフォーム尊重、オフライン機能を基本とした設計哲学であり、Pythonスクリプトを使用して検証します","ko":"모바일 디자인 시스템은 터치 우선, 배터리 인식, 플랫폼 존중, 오프라인 기능을 기본으로 하는 설계 철학이며, Python 스크립트를 사용하여 검증합니다","es":"El diseño móvil es fundamental para los agentes de IA. Aprende a crear experiencias de usuario móviles eficaces con nuestro enfoque en filosofía de diseño y principios básicos.","fr":"La conception mobile est essentielle pour les outils d''IA. Découvrez comment créer des expériences utilisateur mobiles efficaces avec notre approche de philosophie de conception et de principes de base.","de":"Das mobile Design ist für KI-Tools von entscheidender Bedeutung. Erfahren Sie, wie Sie effektive mobile Benutzererfahrungen mit unserem Designansatz und grundlegenden Prinzipien erstellen","pt":"O design móvel é uma abordagem touch-first, que respeita as plataformas e é capaz de funcionar offline, com scripts de auditoria para validação","ru":"Мобильный дизайн - это подход touch-first, который уважает платформы и способен работать offline, со скриптами аудита для валидации","ar":"التصميم المحمول هو نهج اللمس أولا، الذي يحترم المنصات ويمكنه العمل بدون اتصال، مع سكрипتات التدقيق للتحقق"},"seo