INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maskelog/Daegu_bus_flutter_app/mobile-design', 'mobile-design', 'maskelog', 'Daegu_bus_flutter_app', 'community', 'mobile-design maskelog Daegu_bus_flutter_app community The mobile-design skill enables developers to create touch-first, battery-conscious, and platform-respectful mobile applications. It benefits developers who need to optimize their mobile apps for various platforms. 移动设计系统是一种基于触摸优先、电池意识、平台尊重和离线能力的设计哲学，通过Python脚本进行验证 モバイルデザインシステムは、タッチファースト、バッテリー意識、プラットフォーム尊重、オフライン機能を基本とした設計哲学であり、Pythonスクリプトを使用して検証します 모바일 디자인 시스템은 터치 우선, 배터리 인식, 플랫폼 존중, 오프라인 기능을 기본으로 하는 설계 철학이며, Python 스크립트를 사용하여 검증합니다 El diseño móvil es fundamental para los agentes de IA. Aprende a crear experiencias de usuario móviles eficaces con nuestro enfoque en filosofía de diseño y principios básicos. La conception mobile est essentielle pour les outils d''IA. Découvrez comment créer des expériences utilisateur mobiles efficaces avec notre approche de philosophie de conception et de principes de base. Das mobile Design ist für KI-Tools von entscheidender Bedeutung. Erfahren Sie, wie Sie effektive mobile Benutzererfahrungen mit unserem Designansatz und grundlegenden Prinzipien erstellen O design móvel é uma abordagem touch-first, que respeita as plataformas e é capaz de funcionar offline, com scripts de auditoria para validação Мобильный дизайн - это подход touch-first, который уважает платформы и способен работать offline, со скриптами аудита для валидации التصميم المحمول هو نهج اللمس أولا، الذي يحترم المنصات ويمكنه العمل بدون اتصال، مع سكрипتات التدقيق للتحقق how to use mobile-design mobile-design setup guide mobile-design vs responsive design what is mobile-design mobile-design install mobile-design alternative touch-first design principles mobile UX audit tools platform-respectful development 移动设计系统 触摸优先设计 电池意识设计 平台尊重设计 离线能力支持 Python脚本验证 AIエージェント 移动设计最佳实践 Executes mobile UX and touch audits using scripts/mobile_audit.py Validates mobile applications for platform-respectful design Supports offline-capable development for mobile apps Runs on Python with scripts like mobile_audit.py Integrates with project paths for comprehensive audits Enforces mobile constraints and platform choice consideration mobile-design is a development approach that prioritizes touch-first, battery-conscious, and platform-respectful design principles for mobile applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pytorch/executorch/cortex-m', 'community', 'pytorch', 'executorch', 'pytorch/executorch', 'cortex-m', 0, 0, 42, '2026-03-08T01:57:15.319Z', '2026-03-08T02:02:56.760Z', '2c8fcf355b002f600e8ac08d17f1f9e1c7717ed4ceafae86d2427d48417a1fcd', '{"id":"pytorch/executorch/cortex-m","name":"cortex-m","description":{"en":"The cortex-m skill enables on-device AI across mobile, embedded, and edge for PyTorch, benefiting developers and data scientists. It provides a custom backend for CMSIS-NN.","zh":"Cortex-M是PyTorch_on-device_AI的解决方案，支持自定义ops和图passes","ja":"Cortex-MはPyTorch_on-device_AIのためのバックエンドで、CMSIS-NNを使用","ko":"Cortex-M은 PyTorch_on-device_AI를 위한 백엔드로 CMSIS-NN을 지원","es":"Cortex-M es un backend de PyTorch que permite la implementación de aprendizaje automático en dispositivos móviles y embebidos. Ofrece una arquitectura personalizada y reemplaza operaciones cuantizadas con equivalentes CMSIS-NN","fr":"Cortex-M est un backend PyTorch qui permet la mise en œuvre de l''apprentissage automatique sur les appareils mobiles et intégrés. Il propose une architecture personnalisée et remplace les opérations quantifiées par des équivalents CMSIS-NN","de":"Cortex-M ist ein PyTorch-Backend, das die Implementierung von künstlicher Intelligenz auf mobilen und eingebetteten Geräten ermöglicht. Es bietet eine benutzerdefinierte Architektur und ersetzt quantifizierte Operationen durch CMSIS-NN-Äquivalente","pt":"O Cortex-M é uma solução de AI on-device para PyTorch que melhora a eficiência da sua aplicação móvel. Ele utiliza a arquitetura CMSIS-NN para otimizar as operações de AI.","ru":"Cortex-M - это решение для AI на устройствах для PyTorch, которое улучшает эффективность вашего мобильного приложения. Он использует архитектуру CMSIS-NN для оптимизации операций AI.","ar":"Cortex-M هو حل للذكاء الاصطناعي على الأجهزة ل PyTorch الذي يحسن كفاءة تطبيقك الجوال. إنه يستخدم архيتيكتور CMSIS-NN لتحسين عمليات الذكاء الاصطناعي."},"seo":{"title":{"en":"cortex-m: On-Device AI Setup Guide | AI Agent Skill","zh":"Cortex-M_SETUP_GUIDE_ON-DEVICE_AI_PYTORCH","ja":"Cortex-M_BEST_PRACTICES_AIエージェント_FOR_PYTORCH","ko":"Cortex-M_TUTORIAL_ON-DEVICE_AI_PYTORCH_FOR_EMBEDDED","es":"Guía de configuración de Cortex-M para PyTorch","fr":"Guide d''installation de Cortex-M pour PyTorch","de":"Einrichtungsleitfaden für Cortex-M mit PyTorch","pt":"Guia de Configuração do Cortex-M para AI On-Device com Py...","ru":"Настройка Cortex-M для AI на устройствах с помощью PyTorch","ar":"دليل إعداد Cortex-M للذكاء الاصطناعي على الأجهزة باستخدام..."},"description":{"en":"Discover how to integrate on-device AI across mobile, embedded, and edge devices with cortex-m and PyTorch. Get started with our expert guide today!","zh":"了解Cortex-M的特点和优势，实现PyTorch_on-device_AI解决方案","ja":"AIエージェントのCortex-Mを使用してPyTorch_on-device_AIを実現","ko":"Cortex-M을 사용하여 PyTorch_on-device_AI를 구현하고 최적화하는 방법","es":"Aprende a implementar el backend de Cortex-M para PyTorch y aprovecha el aprendizaje automático en dispositivos móviles y embebidos","fr":"Découvrez comment mettre en œuvre le backend Cortex-M pour PyTorch et profitez de l''apprentissage automatique sur les appareils mobiles et intégrés","de":"Erfahren Sie, wie Sie den Cortex-M-Backend für PyTorch implementieren und künstliche Intelligenz auf mobilen und eingebetteten Geräten nutzen","pt":"Aprenda a configurar o Cortex-M para AI on-device com PyTorch e melhore a eficiência da sua aplicação móvel","ru":"Узнайте, как настроить Cortex-M для AI на устройствах с помощью PyTorch и повысьте эффективность вашего мобильного приложения","ar":"تعلم كيفية إعداد Cortex-M للذكاء الاصطناعي على الأجهزة باستخدام PyTorch و تحسين كفاءة تطبيقك الجوال"},"definition":{"en":"cortex-m is an on-device AI backend for PyTorch, utilizing CMSIS-NN for efficient inference on mobile, embedded, and edge devices.","zh":"Cortex-M是PyTorch_on-device_AI的解决方案，支持CMSIS-NN","ja":"Cortex-Mは、CMSIS-NNを使用したPyTorch_on-device_AIのバックエンド","ko":"Cortex-M은 CMSIS-NN을 지원하는 PyTorch_on-device_AI 백엔드","es":"Cortex-M es un backend de PyTorch que permite la implementación de aprendizaje automático en dispositivos móviles y embebidos","fr":"Cortex-M est un backend PyTorch qui permet la mise en œuvre de l''apprentissage automatique sur les appareils mobiles et intégrés","de":"Cortex-M ist ein PyTorch-Backend, das die Implementierung von künstlicher Intelligenz auf mobilen und eingebetteten Geräten ermöglicht","pt":"O Cortex-M é um backend de AI on-device que utiliza a arquitetura CMSIS-NN para otimizar as operações de AI em dispositivos móveis","ru":"Cortex-M - это бэкенд AI на устройствах, который использует архитектуру CMSIS-NN для оптимизации операций AI на мобильных устройствах","ar":"Cortex-M هو بيكند للذكاء الاصطناعي على الأجهزة الذي يستخدم архيتيكتور CMSIS-NN لتحسين عمليات الذكاء الاصطناعي على الأجهزة الجوالة"},"features":{"en":["Uses standard PT2E quantization with `prepare_pt2e` and `convert_pt2e`","Rewrites quantized ops to `cortex_m::` equivalents using `CortexMPassManager`","Supports custom ops and graph passes for CMSIS-NN","Utilizes `CortexMQuantizer` for quantization","Integrates with PyTorch for seamless on-device AI deployment"],"zh":["支持PyTorch_on-device_AI","自定义ops和图passes","使用CMSIS-NN","标准PT2E量化","CortexMPassManager重写量化ops"],"ja":["PyTorch_on-device_AIをサポート","カスタムopsとグラフパス","CMSIS-NNを使用","標準PT2E量化","CortexMPassManagerによる量化opsの書き換え"],"ko":["PyTorch_on-device_AI 지원","사용자 정의 ops 및 그래프 패스","CMSIS-NN 사용","표준 PT2E 양자화","CortexMPassManager를 통한 양자화 ops 재작성"],"es":["Arquitectura personalizada para aprendizaje automático en dispositivos móviles y embebidos","Reemplazo de operaciones cuantizadas con equivalentes CMSIS-NN","Uso de PyTorch para la implementación de modelos de aprendizaje automático","Compatibilidad con dispositivos móviles y embebidos","Soporte para operaciones de aprendizaje automático en tiempo real"],"fr":["Architecture personnalisée pour l''apprentissage automatique sur les appareils mobiles et intégrés","Remplacement des opérations quantifiées par des équivalents CMSIS-NN","Utilisation de PyTorch pour la mise en œuvre de modèles d''apprentissage automatique","Compatibilité avec les appareils mobiles et intégrés","Prise en charge des opérations d''apprentissage automatique en temps réel"],"de":["Benutzerdefinierte Architektur für künstliche Intelligenz auf mobilen und eingebetteten Geräten","Ersetzen von quantifizierten Operationen durch CMSIS-NN-Äquivalente","Verwendung von PyTorch für die Implementierung von künstlichen Intelligenzmodellen","Kompatibilität mit mobilen und eingebetteten Geräten","Unterstützung für Echtzeit-KI-Operationen"],"pt":["Utiliza a arquitetura CMSIS-NN para otimizar as operações de AI","Suporta quantização de modelos de AI com PyTorch","Permite a execução de operações de AI em dispositivos móveis","Utiliza o CortexMPassManager para reescrever operações de AI","Suporta a criação de modelos de AI personalizados com CMSIS-NN"],"ru":["Использует архитектуру CMSIS-NN для оптимизации операций AI","Поддерживает квантование моделей AI с помощью PyTorch","Позволяет выполнять операции AI на мобильных устройствах","Использует CortexMPassManager для переписывания операций AI","Поддерживает создание пользовательских моделей AI с помощью CMSIS-NN"],"ar":["يستخدم архيتيكتور CMSIS-NN لتحسين عمليات الذكاء الاصطناعي","يدعم الكمية من نماذج الذكاء الاصطناعي مع PyTorch","يسمح بتنفيذ عمليات الذكاء الاصطناعي على الأجهزة الجوالة","يستخدم CortexMPassManager لإعادة كتابة عمليات الذكاء الاصطناعي","يدعم إنشاء نماذج الذكاء الاصطناعي المخصصة مع CMSIS-NN"]},"keywords":{"en":["how to use cortex-m","cortex-m setup guide","cortex-m vs TensorFlow Lite","cortex-m install","what is cortex-m","cortex-m PyTorch integration","on-device AI with cortex-m","CMSIS-NN backend","cortex-m alternative"],"zh":["Cortex-M","PyTorch_on-device_AI","CMSIS-NN","量化","图passes","自定义ops","PyTorch量化","on-device_AI解决方案"],"ja":["Cortex-M","PyTorch_on-device_AI","AIエージェント","CMSIS-NN","量化","グラフパス","カスタムops","PyTorch量化"],"ko":["Cortex-M","PyTorch_on-device_AI","AI_tools","CMSIS-NN","양자화","그래프_패스","사용자_정의_ops","PyTorch_양자화"],"es":["cortex-m","pytorch","aprendizaje automático","dispositivos móviles","dispositivos embebidos","CMSIS-NN","arquitectura personalizada","operaciones cuantizadas"],"fr":["cortex-m","pytorch","apprentissage automatique","appareils mobiles","appareils intégrés","CMSIS-NN","architecture personnalisée","opérations quantifiées"],"de":["cortex-m","pytorch","künstliche Intelligenz","mobile Geräte","eingebettete Geräte","CMSIS-NN","benutzerdefinierte Architektur","quantifizierte Operationen"],"pt":["Cortex-M","AI on-device","PyTorch","CMSIS-NN","quantização de modelos de AI","execução de operações de AI em dispositivos móveis","CortexMPassManager","modelos de AI personalizados"],"ru":["Cortex-M","AI на устройствах","PyTorch","CMSIS-NN","квантование моделей AI","выполнение операций AI на мобильных устройствах","CortexMPassManager","пользовательские модели AI"],"ar":["Cortex-M","الذكاء الاصطناعي على الأجهزة","PyTorch","CMSIS-NN","الكمية من نماذج الذكاء الاصطناعي","تنفيذ عمليات الذكاء الاصطناعي على الأجهزة الجوالة","CortexMPassManager","نماذج الذكاء الاصطناعي المخصصة"]}},"owner":"pytorch","repo":"executorch","repoPath":"pytorch/executorch","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.319Z","topics":[],"category":"community","skillMd":{"name":"cortex-m","description":"Build, test, or develop the Cortex-M (CMSIS-NN) backend. Use when working on backends/cortex_m/, running Cortex-M tests, or exporting models for Cortex-M targets.","bodyPreview":"# Cortex-M (CMSIS-NN) Backend\n\n## Architecture\n\nNot a delegate backend — no partitioner. Custom ops and graph passes replace ATen quantized ops with CMSIS-NN equivalents at the graph level.\n\n## Pipeline\n\nUses standard PT2E quantization (`prepare_pt2e` / `convert_pt2e`), then `CortexMPassManager` rewrites quantized ops to `cortex_m::` equivalents.\n\n```python\nfrom executorch.backends.cortex_m.quantizer.quantizer import CortexMQuantizer\nfrom executorch.backends.cortex_m.passes.cortex_m_pass_manager","body":"# Cortex-M (CMSIS-NN) Backend\n\n## Architecture\n\nNot a delegate backend — no partitioner. Custom ops and graph passes replace ATen quantized ops with CMSIS-NN equivalents at the graph level.\n\n## Pipeline\n\nUses standard PT2E quantization (`prepare_pt2e` / `convert_pt2e`), then `CortexMPassManager` rewrites quantized ops to `cortex_m::` equivalents.\n\n```python\nfrom executorch.backends.cortex_m.quantizer.quantizer import CortexMQuantizer\nfrom executorch.backends.cortex_m.passes.cortex_m_pass_manager import CortexMPassManager\nfrom torch.export import export\nfrom torchao.quantization.pt2e.quantize_pt2e import convert_pt2e, prepare_pt2e\nfrom executorch.exir import to_edge_transform_and_lower, EdgeCompileConfig\n\nquantizer = CortexMQuantizer()\ncaptured = export(model, example_inputs).module()\nprepared = prepare_pt2e(captured, quantizer)\nprepared(*example_inputs)  # calibration\nquantized = convert_pt2e(prepared)\n\nexported = export(quantized, example_inputs)\nedge = to_edge_transform_and_lower(\n    exported,\n    compile_config=EdgeCompileConfig(_check_ir_validity=False),\n)\nedge._edge_programs[\"forward\"] = CortexMPassManager(\n    edge.exported_program(), CortexMPassManager.pass_list\n).transform()\net_program = edge.to_executorch()\n```\n\nIn tests, `CortexMTester` wraps this pipeline:\n\n```python\nfrom executorch.backends.cortex_m.test.tester import CortexMTester\n\ntester = CortexMTester(model, example_inputs)\ntester.quantize().export().to_edge().run_passes().to_executorch()\n```\n\n## Key Files\n\n| File | Purpose |\n|------|---------|\n| `backends/cortex_m/quantizer/quantizer.py` | `CortexMQuantizer` — quantizes model for CMSIS-NN |\n| `backends/cortex_m/passes/cortex_m_pass_manager.py` | `CortexMPassManager` — rewrites ATen ops → `cortex_m::` ops |\n| `backends/cortex_m/test/tester.py` | `CortexMTester` — test harness with `test_dialect()` and `test_implementation()` |\n| `backends/cortex_m/ops/operators.py` | Python op definitions and reference implementations (`cortex_m::` namespace) |\n| `backends/cortex_m/ops/operators.yaml` | C++ kernel registration schemas (used by build system) |\n\nC++ kernels calling CMSIS-NN APIs live under `backends/cortex_m/ops/`.\n\n## Testing\n\n**Toolchain setup (required for `test_implementation` tests):**\n```bash\n./examples/arm/setup.sh --i-agree-to-the-contained-eula\nsource ./examples/arm/arm-scratch/setup_path.sh\n```\n\n**Run all tests:**\n```bash\nsource ./examples/arm/arm-scratch/setup_path.sh\npytest backends/cortex_m/test/\n```\n\n`test_dialect_*` tests verify graph correctness (pure Python, no toolchain needed).\n`test_implementation_*` tests verify numerical accuracy on the Corstone-300 FVP (requires toolchain on PATH).\n\n**Baremetal build:**\n```bash\nbackends/cortex_m/test/build_test_runner.sh\n```\n\n## Adding a New Op\n\n1. Define the op schema, meta function, and reference implementation in `operators.py`\n2. Write the C++ kernel in `backends/cortex_m/ops/` calling CMSIS-NN APIs\n3. Register the `.out` kernel in `operators.yaml`\n4. Add a pass to rewrite the ATen op → `cortex_m::` op\n5. Test with `CortexMTester.test_dialect()` (graph correctness) and `test_implementation()` (numerical accuracy on FVP)\n"},"lastSynced":"2026-03-08T02:02:56.760Z","agentAnalysis":{"suitability":{"en":"Perfect for Edge AI Agents needing on-device PyTorch model optimization with CMSIS-NN backend","zh":"非常适合需要在设备上使用PyTorch模型优化的Edge AI代理，具有CMSIS-NN后端","ja":"Edge AIエージェントがデバイス上でPyTorchモデルを最適化する必要がある場合に最適です。CMSIS-NNバックエンドを使用します","ko":"Edge AI 에이전트가 디바이스에서 PyTorch 모델 최적화를 필요로 할 때 完全한 선택입니다. CMSIS-NN 백엔드를 사용합니다","es":"Perfecto para Agentes de Inteligencia Artificial de Edge que necesitan optimización de modelos PyTorch en dispositivo con backend CMSIS-NN","fr":"Parfait pour les Agents d''Intelligence Artificielle de Edge nécessitant une optimisation de modèles PyTorch sur appareil avec backend CMSIS-NN","de":"Perfekt für Edge-KI-Agents, die eine Optimierung von PyTorch-Modellen auf Geräten mit CMSIS-NN-Backend benötigen","pt":"Perfeito para Agentes de IA de Borda que necessitam de otimização de modelos PyTorch no dispositivo com backend CMSIS-NN","ru":"Идеально подходит для агентов Edge AI, которым требуется оптимизация моделей PyTorch на устройстве с помощью бэкенда CMSIS-NN","ar":"مثالي للوكلاء الذكاء الاصطناعي على الحواف التي تحتاج إلى تحسين نموذج PyTorch على الجهاز باستخدام خلفية CMSIS-NN"},"recommendation":{"en":"Empowers agents to deploy AI models on mobile and embedded devices using custom CMSIS-NN ops and graph passes, leveraging PT2E quantization and the CortexMPassManager for efficient model conversion","zh":"赋予代理在移动和嵌入式设备上部署AI模型的能力，使用自定义的CMSIS-NN操作和图形传递，利用PT2E量化和CortexMPassManager进行高效的模型转换","ja":"エージェントに、カスタムのCMSIS-NN操作とグラフパスを使用して、モバイルおよび組み込みデバイスにAIモデルをデプロイする能力を与え、PT2E量化とCortexMPassManagerを使用して効率的なモデル変換を行う","ko":"에이전트에 모바일 및 임베디드 디바이스에 AI 모델을 배포할 수 있는 능력을 부여합니다. 사용자 지정 CMSIS-NN 연산 및 그래프 전달을 사용하며, PT2E 양자화 및 CortexMPassManager를 사용하여 효율적인 모델 변환을 수행합니다","es":"Habilita a los agentes a implementar modelos de inteligencia artificial en dispositivos móviles y embebidos utilizando operaciones personalizadas CMSIS-NN y pases de gráficos, aprovechando la cuantificación PT2E y el CortexMPassManager para una conversión de modelos eficiente","fr":"Permet aux agents de déployer des modèles d''intelligence artificielle sur des appareils mobiles et intégrés en utilisant des opérations CMSIS-NN personnalisées et des passes de graphiques, en exploitant la quantification PT2E et le CortexMPassManager pour une conversion de modèles efficace","de":"Ermächtigt Agents, KI-Modelle auf mobilen und eingebetteten Geräten bereitzustellen, indem sie benutzerdefinierte CMSIS-NN-Operationen und Graph-Pässe verwenden, die PT2E-Quantifizierung und den CortexMPassManager für eine effiziente Modellkonvertierung nutzen","pt":"Habilita os agentes a implantar modelos de IA em dispositivos móveis e embarcados usando operações personalizadas CMSIS-NN e passes de gráfico, aproveitando a quantização PT2E e o CortexMPassManager para conversão eficiente de modelos","ru":"Наделяет агентов возможностью развертывать модели ИИ на мобильных и встроенных устройствах, используя пользовательские операции CMSIS-NN и проходы графа, используя квантование PT2E и CortexMPassManager для эффективного преобразования моделей","ar":"يمنح الوكلاء القدرة على نشر نماذج الذكاء الاصطناعي على الأجهزة المحمولة والمتأصلة باستخدام العمليات المخصصة CMSIS-NN والممرات الرسمية، واستغلال الكمية PT2E و CortexMPassManager لنقل نموذج فعال"},"useCases":{"en":["Optimizing PyTorch models for edge deployment","Converting models to CMSIS-NN format","Deploying AI models on resource-constrained devices"],"zh":["为边缘部署优化PyTorch模型","将模型转换为CMSIS-NN格式","将AI模型部署在资源受限的设备上"],"ja":["エッジデプロイのためにPyTorchモデルを最適化する","モデルをCMSIS-NN形式に変換する","リソースに制約のあるデバイスにAIモデルをデプロイする"],"ko":["엣지 배포를 위해 PyTorch 모델 최적화하기","모델을 CMSIS-NN 형식으로 변환하기","자원 제약이 있는 디바이스에 AI 모델 배포하기"],"es":["Optimización de modelos PyTorch para implementación de Edge","Conversión de modelos al formato CMSIS-NN","Implementación de modelos de inteligencia artificial en dispositivos con recursos limitados"],"fr":["Optimisation de modèles PyTorch pour un déploiement Edge","Conversion de modèles au format CMSIS-NN","Déploiement de modèles d''intelligence artificielle sur des appareils à ressources limitées"],"de":["Optimierung von PyTorch-Modellen für die Edge-Implementierung","Umwandlung von Modellen in das CMSIS-NN-Format","Bereitstellung von KI-Modellen auf geräten mit begrenzten Ressourcen"],"pt":["Otimização de modelos PyTorch para implantação de borda","Conversão de modelos para formato CMSIS-NN","Implantação de modelos de IA em dispositivos com recursos limitados"],"ru":["Оптимизация моделей PyTorch для развертывания на краю","Преобразование моделей в формат CMSIS-NN","Развертывание моделей ИИ на устройствах с ограниченными ресурсами"],"ar":["تحسين نماذج PyTorch للنشر على الحواف","تحويل النماذج إلى تنسيق CMSIS-NN","نشر نماذج الذكاء الاصطناعي على الأجهزة ذات الموارد المحدودة"]},"limitations":{"en":["Requires PyTorch support","Limited to CMSIS-NN backend","Custom ops and graph passes may require additional development"],"zh":["需要PyTorch支持","仅限CMSIS-NN后端","自定义操作和图形传递可能需要额外的开发"],"ja":["PyTorchのサポートが必要","CMSIS-NNバックエンドのみ","カスタム操作とグラフパスは追加の開発が必要になる場合がある"],"ko":["PyTorch 지원이 필요합니다","CMSIS-NN 백엔드만 해당됩니다","사용자 지정 연산 및 그래프 전달에는 추가 개발이 필요할 수 있습니다"],"es":["Requiere soporte de PyTorch","Limitado al backend CMSIS-NN","Las operaciones y pases de gráficos personalizados pueden requerir un desarrollo adicional"],"fr":["Nécessite un support PyTorch","Limité au backend CMSIS-NN","Les opérations et les passes de graphiques personnalisés peuvent nécessiter un développement supplémentaire"],"de":["Benötigt PyTorch-Unterstützung","Begrenzt auf CMSIS-NN-Backend","Benutzerdefinierte Operationen und Graph-Pässe können eine zusätzliche Entwicklung erfordern"],"pt":["Requer suporte PyTorch","Limitado ao backend CMSIS-NN","Operações personalizadas e passes de gráfico podem exigir desenvolvimento adicional"],"ru":["Требует поддержки PyTorch","Ограничен бэкендом CMSIS-NN","Пользовательские операции и проходы графа могут требовать дополнительного развития"],"ar":["يتطلب دعم PyTorch","محدود بخلفية CMSIS-NN","العمليات المخصصة وممرات الرسم البياني قد تتطلب تطويرًا إضافيًا"]},"version":4},"contentHash":"2c8fcf355b002f600e8ac08d17f1f9e1c7717ed4ceafae86d2427d48417a1fcd","qualityScore":42}');
