INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pytorch/executorch/cortex-m', 'cortex-m', 'pytorch', 'executorch', 'community', 'cortex-m pytorch executorch community The cortex-m skill enables on-device AI across mobile, embedded, and edge for PyTorch, benefiting developers and data scientists. It provides a custom backend for CMSIS-NN. Cortex-M是PyTorch_on-device_AI的解决方案，支持自定义ops和图passes Cortex-MはPyTorch_on-device_AIのためのバックエンドで、CMSIS-NNを使用 Cortex-M은 PyTorch_on-device_AI를 위한 백엔드로 CMSIS-NN을 지원 Cortex-M es un backend de PyTorch que permite la implementación de aprendizaje automático en dispositivos móviles y embebidos. Ofrece una arquitectura personalizada y reemplaza operaciones cuantizadas con equivalentes CMSIS-NN Cortex-M est un backend PyTorch qui permet la mise en œuvre de l''apprentissage automatique sur les appareils mobiles et intégrés. Il propose une architecture personnalisée et remplace les opérations quantifiées par des équivalents CMSIS-NN Cortex-M ist ein PyTorch-Backend, das die Implementierung von künstlicher Intelligenz auf mobilen und eingebetteten Geräten ermöglicht. Es bietet eine benutzerdefinierte Architektur und ersetzt quantifizierte Operationen durch CMSIS-NN-Äquivalente O Cortex-M é uma solução de AI on-device para PyTorch que melhora a eficiência da sua aplicação móvel. Ele utiliza a arquitetura CMSIS-NN para otimizar as operações de AI. Cortex-M - это решение для AI на устройствах для PyTorch, которое улучшает эффективность вашего мобильного приложения. Он использует архитектуру CMSIS-NN для оптимизации операций AI. Cortex-M هو حل للذكاء الاصطناعي على الأجهزة ل PyTorch الذي يحسن كفاءة تطبيقك الجوال. إنه يستخدم архيتيكتور CMSIS-NN لتحسين عمليات الذكاء الاصطناعي. how to use cortex-m cortex-m setup guide cortex-m vs TensorFlow Lite cortex-m install what is cortex-m cortex-m PyTorch integration on-device AI with cortex-m CMSIS-NN backend cortex-m alternative Cortex-M PyTorch_on-device_AI CMSIS-NN 量化 图passes 自定义ops PyTorch量化 on-device_AI解决方案 Uses standard PT2E quantization with `prepare_pt2e` and `convert_pt2e` Rewrites quantized ops to `cortex_m::` equivalents using `CortexMPassManager` Supports custom ops and graph passes for CMSIS-NN Utilizes `CortexMQuantizer` for quantization Integrates with PyTorch for seamless on-device AI deployment cortex-m is an on-device AI backend for PyTorch, utilizing CMSIS-NN for efficient inference on mobile, embedded, and edge devices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mr-karan/logchef/logchef', 'community', 'mr-karan', 'logchef', 'mr-karan/logchef', 'logchef', 0, 0, 42, '2026-03-08T01:57:15.324Z', '2026-03-08T02:02:59.869Z', 'c106a0a40d625cd7a24d5133239f6ac0c4c15e9b44c166ecca4f29a8b85354ef', '{"id":"mr-karan/logchef/logchef","name":"logchef","description":{"en":"logchef is a lightweight log analytics interface for ClickHouse, enabling developers to query logs safely and accurately. It provides high-performance querying and visualization capabilities.","zh":"LogChef 是一个用于 ClickHouse 的轻量级日志分析接口，专注于高性能查询和可视化","ja":"LogChef は ClickHouse 用の軽量ログ分析インターフェイスで、高性能クエリと可視化に重点を置いています","ko":"LogChef는 클릭하우스용 가벼운 로그 분석 인터페이스로, 높은 성능의 쿼리와 시각화를 제공합니다","es":"LogChef es una interfaz de análisis de registros ligera y de un solo binario para ClickHouse, enfocada en consultas de alto rendimiento y visualización","fr":"LogChef est une interface d''analyse de journaux légère et mono-binaire pour ClickHouse, axée sur les requêtes haute performance et la visualisation","de":"LogChef ist eine leichte und einbinäre Schnittstelle für die Analyse von ClickHouse-Protokollen, die sich auf Hochleistungsabfragen und Visualisierung konzentriert","pt":"O LogChef é uma interface de análise de logs leve e de alta performance para ClickHouse, que oferece consultas de logs seguras e precisas","ru":"LogChef - это легкий и высокопроизводительный интерфейс анализа журналов для ClickHouse, обеспечивающий безопасные и точные запросы журналов","ar":"LogChef هو واجهة تحليل السجلات الخفيفة ذات الأداء العالي ل ClickHouse، يوفر استفسارات سجلات آمنة و دقيقة"},"seo":{"title":{"en":"logchef: High-Performance Log Analytics Setup Guide | AI ...","zh":"LogChef 设置指南：高性能日志分析接口","ja":"LogChef のベストプラクティス: 高性能ログ分析インターフェイス","ko":"LogChef 사용자 가이드: 클릭하우스용 가벼운 로그 분석 인터페이스","es":"Guía de configuración de LogChef: Análisis de registros d...","fr":"Guide de configuration de LogChef: Interface d''analyse de...","de":"LogChef-Setup-Anleitung: Hochleistungs-Abfragen und Visua...","pt":"Guia de Configuração do LogChef: Interface de Análise de ...","ru":"ИИ Агент LogChef: Руководство по Настройке Интерфейса Ана...","ar":"دليل إعداد LogChef: واجهة تحليل السجلات الخفيفة ذات الأدا..."},"description":{"en":"Unlock efficient log querying with logchef. Learn how to authenticate, set defaults, and query logs with LogChefQL filters. Get started now!","zh":"了解 LogChef 的高性能日志分析功能，包括 CLI 查询和可视化，以及如何使用 OIDC 进行身份验证","ja":"LogChef の機能を紹介します。高性能ログ分析、CLI クエリ、可視化、および OIDC 認証","ko":"LogChef 의 강력한 로그 분석 기능을 살펴보세요. CLI 쿼리, 시각화 및 OIDC 인증을 포함합니다","es":"Aprende a utilizar LogChef para analizar registros de ClickHouse de manera segura y precisa con nuestra guía de configuración","fr":"Découvrez comment utiliser LogChef pour analyser les journaux ClickHouse de manière sécurisée et précise avec notre guide de configuration","de":"Erfahren Sie, wie Sie LogChef verwenden können, um ClickHouse-Protokolle sicher und genau zu analysieren, mit unserer Konfigurationsanleitung","pt":"Aprenda a configurar o LogChef, uma interface de análise de logs leve e de alta performance para ClickHouse, e melhore a segurança e a precisão das suas cons...","ru":"Узнайте, как настроить LogChef, легкий и высокопроизводительный интерфейс анализа журналов для ClickHouse, и улучшите безопасность и точность запросов журналов","ar":"تعلم كيفية إعداد LogChef، واجهة تحليل السجلات الخفيفة ذات الأداء العالي ل ClickHouse، و提高 أمان و دقة استفسارات السجلات"},"definition":{"en":"logchef is a single-binary log analytics interface for ClickHouse, focused on high-performance querying and visualization","zh":"LogChef 是一个用于 ClickHouse 的轻量级单二进制日志分析接口","ja":"LogChef は ClickHouse 用の軽量單バイナリログ分析インターフェイスです","ko":"LogChef는 클릭하우스용 가벼운 단일 바이너리 로그 분석 인터페이스입니다","es":"LogChef es una herramienta de análisis de registros que permite consultas seguras y precisas de registros de ClickHouse","fr":"LogChef est un outil d''analyse de journaux qui permet des requêtes sécurisées et précises de journaux ClickHouse","de":"LogChef ist ein Tool für die Analyse von Protokollen, das sichere und genaue Abfragen von ClickHouse-Protokollen ermöglicht","pt":"O LogChef é uma ferramenta de análise de logs que fornece uma interface de usuário leve e de alta performance para consultar e visualizar logs do ClickHouse","ru":"LogChef - это инструмент анализа журналов, обеспечивающий легкий и высокопроизводительный интерфейс для запросов и визуализации журналов ClickHouse","ar":"LogChef هو أداة تحليل السجلات التي توفر واجهة مستخدم خفيفة ذات أداء عالي لاستفسار وتصوير السجلات من ClickHouse"},"features":{"en":["Authenticate with OIDC using `logchef auth --server` command","Set defaults with `logchef config set` command for team and source","Query logs with LogChefQL filters using `logchef query` command","Supports filtering by level, time, and limit using `--since` and `--limit` flags","Provides a command cheat sheet for easy reference","Enables safe and accurate log querying"],"zh":["高性能日志分析和查询","支持 OIDC 身份验证","CLI 查询和可视化功能","设置 team 和 source 默认值","支持 LogChefQL 过滤器"],"ja":["高性能ログ分析とクエリ","OIDC 認証のサポート","CLI クエリと可視化機能","チームとソースのデフォルト値の設定","LogChefQL フィルタのサポート"],"ko":["높은 성능의 로그 분석 및 쿼리","OIDC 인증 지원","CLI 쿼리 및 시각화 기능","팀 및 소스 기본값 설정","LogChefQL 필터 지원"],"es":["Autenticación segura con OIDC","Consultas de registros con LogChefQL","Configuración de defaults para equipo y fuente de registros","Visualización de resultados de consultas","Soporte para consultas de alto rendimiento","Interfaz de línea de comandos (CLI) para facilidad de uso"],"fr":["Authentification sécurisée avec OIDC","Requêtes de journaux avec LogChefQL","Configuration des valeurs par défaut pour l''équipe et la source de journaux","Visualisation des résultats de requêtes","Prise en charge des requêtes haute performance","Interface de ligne de commande (CLI) pour une utilisation facile"],"de":["Sichere Authentifizierung mit OIDC","Abfragen von Protokollen mit LogChefQL","Konfiguration von Standardwerten für Team und Protokollquelle","Visualisierung von Abfrageergebnissen","Unterstützung für Hochleistungsabfragen","Kommandozeilen-Schnittstelle (CLI) für einfache Bedienung"],"pt":["Autenticação segura com OIDC","Configuração de parâmetros de consulta de logs","Suporte a filtros LogChefQL","Visualização de logs em tempo real","Integração com ClickHouse","Interface de linha de comando (CLI) para consultas de logs"],"ru":["Безопасная аутентификация с OIDC","Настройка параметров запросов журналов","Поддержка фильтров LogChefQL","Визуализация журналов в режиме реального времени","Интеграция с ClickHouse","Интерфейс командной строки (CLI) для запросов журналов"],"ar":["التحقق الآمن باستخدام OIDC","تهيئة 매개 VARIABLES ل استفسار السجلات","دعم مرشحات LogChefQL","تصوير السجلات في الوقت الفعلي","التكامل مع ClickHouse","واجهة سطر الأوامر (CLI) لاستفسارات السجلات"]},"keywords":{"en":["how to use logchef","logchef setup guide","logchef alternative","logchef vs elk","logchef install","what is logchef","logchef clickhouse integration","logchef query language","logchef authentication"],"zh":["LogChef","ClickHouse","日志分析","高性能查询","CLI","OIDC","AIエージェント","日志可视化"],"ja":["LogChef","ClickHouse","ログ分析","高性能クエリ","CLI","OIDC","AIエージェント","ログ可視化"],"ko":["LogChef","ClickHouse","로그 분석","높은 성능의 쿼리","CLI","OIDC","AI 에이전트","로그 시각화"],"es":["LogChef","análisis de registros","ClickHouse","OIDC","LogChefQL","consultas de registros","visualización de datos","herramientas de análisis de registros","seguridad de registros","alto rendimiento"],"fr":["LogChef","analyse de journaux","ClickHouse","OIDC","LogChefQL","requêtes de journaux","visualisation de données","outils d''analyse de journaux","sécurité de journaux","haute performance"],"de":["LogChef","Protokollanalyse","ClickHouse","OIDC","LogChefQL","Abfragen von Protokollen","Datenvisualisierung","Tools für die Analyse von Protokollen","Sicherheit von Protokollen","Hochleistungsabfragen"],"pt":["logchef","análise de logs","clickhouse","oidc","logchefql","visualização de logs","segurança de logs","consultas de logs","ferramentas de análise de logs"],"ru":["logchef","анализ журналов","clickhouse","oidc","logchefql","визуализация журналов","безопасность журналов","запросы журналов","инструменты анализа журналов"],"ar":["logchef","تحليل السجلات","clickhouse","oidc","logchefql","تصوير السجلات","أمان السجلات","استفسارات السجلات","أدوات تحليل السجلات"]}},"owner":"mr-karan","repo":"logchef","repoPath":"mr-karan/logchef","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.324Z","topics":[],"category":"community","skillMd":{"name":"logchef","description":"Query and analyze LogChef logs from the terminal using the LogChef CLI. Use for incident triage, debugging errors, exploring LogChefQL filters, running ClickHouse SQL, and executing saved collections.","bodyPreview":"# LogChef CLI\n\nUse the LogChef CLI to query logs safely and accurately.\n\n**Quick Start**\n1. Authenticate with OIDC: `logchef auth --server https://logs.example.com`\n2. Set defaults: `logchef config set team \"my-team\"` and `logchef config set source \"nginx-logs\"`\n3. Query logs: `logchef query ''level=\"error\"'' --since 15m --limit 20`\n\n**Command Cheat Sheet**\n| Command | Use |\n| --- | --- |\n| `logchef auth` | Authenticate (browser-based OIDC) |\n| `logchef query ''...''` | Run LogChefQL filters with ti","body":"# LogChef CLI\n\nUse the LogChef CLI to query logs safely and accurately.\n\n**Quick Start**\n1. Authenticate with OIDC: `logchef auth --server https://logs.example.com`\n2. Set defaults: `logchef config set team \"my-team\"` and `logchef config set source \"nginx-logs\"`\n3. Query logs: `logchef query ''level=\"error\"'' --since 15m --limit 20`\n\n**Command Cheat Sheet**\n| Command | Use |\n| --- | --- |\n| `logchef auth` | Authenticate (browser-based OIDC) |\n| `logchef query ''...''` | Run LogChefQL filters with time flags |\n| `logchef sql ''...''` | Run raw ClickHouse SQL (use `LIMIT` in SQL) |\n| `logchef collections` | List or run saved collections |\n| `logchef teams` | List teams available to you |\n| `logchef sources` | List sources for a team |\n| `logchef schema` | Show columns/types for a source |\n| `logchef config ...` | Manage contexts and defaults |\n\n**Auth And Context**\nUse `logchef auth --server <url>` to create a context and store a token.\nUse `logchef auth --status` and `logchef auth --logout` to check or clear auth.\nUse `--context <name>` or `LOGCHEF_CONTEXT` to target a specific context.\nUse `--server <url>` and `--token <token>` (or `LOGCHEF_SERVER_URL` and `LOGCHEF_AUTH_TOKEN`) for one-off, ephemeral use.\nUse `logchef config list` to view contexts and `logchef config use <name>` to switch.\nAvoid `logchef config set auth.token` because it is not supported by the CLI.\n\n**Required Context**\nProvide `--team` and `--source` on every command unless defaults are set.\nSet defaults with `logchef config set team <name_or_id>` and `logchef config set source <name_or_id>`.\nUse interactive mode by running `logchef query` or `logchef sql` with no args in a TTY and no defaults.\nUse case-insensitive names, numeric IDs, or `database.table` as the `--source` value.\nDiscover names and IDs with `logchef teams` and `logchef sources --team <name_or_id>`.\n\n**Time Range And Limit**\nUse `--since` on `logchef query` and `logchef collections` for relative ranges with `m`, `h`, `d`, or `w` (default is `15m` for `query`).\nUse `--from` and `--to` together for absolute ranges on `logchef query` only.\nUse the exact format `YYYY-MM-DD HH:MM:SS` for `--from` and `--to`.\nSet timezone with `logchef config set timezone \"UTC\"` (or IANA name like `America/Los_Angeles`) and provide absolute times in that timezone.\nExpect `--limit` default to `100` for `logchef query` unless overridden via `logchef config set limit <n>`.\nUse `LIMIT` in SQL because `logchef sql` does not accept `--limit` or `--since`.\nExpect collections to use their saved time range and limit unless overridden.\n\n**LogChefQL Basics**\nQuote the entire query with single quotes to avoid shell piping and expansion.\nUse `=` `!=` `>` `<` `>=` `<=` for comparisons.\nUse `~` and `!~` for case-insensitive substring match (not regex).\nUse `and` / `or` with parentheses for grouping.\nUse `| field1 field2` to select output columns.\nQuote values with spaces or special characters.\nQuote field names that contain dots or special characters.\n\n```bash\n# Exact match\nlogchef query ''level=\"error\" and service=\"api\"'' --since 15m\n\n# Substring match (case-insensitive)\nlogchef query ''msg~\"timeout\"'' --since 1h --limit 20\n\n# Field selection with pipe (note the single quotes)\nlogchef query ''status>=500 and path~\"/v1/\" | _timestamp status path msg'' --since 30m\n\n# Field name with dots\nlogchef query ''k8s.labels.\"app.kubernetes.io/name\"=\"api\"'' --since 1h\n```\n\n**SQL Usage**\nUse `logchef sql` for aggregations, joins, or complex logic.\nAlways include a time filter on the timestamp column (often `_timestamp`).\nUse `LIMIT` in SQL to control result size.\nUse `-` to read SQL from stdin for longer queries.\n\n```bash\nlogchef sql \"SELECT level, count() AS cnt FROM logs.app WHERE _timestamp > now() - INTERVAL 1 HOUR GROUP BY level ORDER BY cnt DESC LIMIT 10\"\n\ncat query.sql | logchef sql -\n```\n\n**Collections**\nList collections: `logchef collections --team \"production\" --source \"nginx-logs\"`.\nRun a collection by name: `logchef collections \"Error Dashboard\" --team \"production\" --source \"nginx-logs\"`.\nOverride time range: `--since 1h`.\nOverride limit: `--limit 50`.\nOverride variables: `--var name=value` (repeatable).\n\n**Teams, Sources, Schema**\nList teams: `logchef teams`.\nList sources for a team: `logchef sources --team \"production\"`.\nShow columns/types: `logchef schema --team \"production\" --source \"nginx-logs\"`.\n\n**Output And Highlighting**\nUse `--output text|json|jsonl|table` on `query`, `sql`, and `collections`.\nUse `--output list` on `collections` when listing.\nUse `--no-highlight` and `--no-timestamp` for clean piping.\nUse `--highlight color:WORD1,WORD2` and `--disable-highlight GROUP` for ad-hoc formatting.\nUse `--show-sql` on `logchef query` to display the generated SQL.\n\n```bash\nlogchef query ''status=500'' --output json | jq ''.count''\nlogchef query ''status=500'' --output jsonl | jq ''.msg''\nlogchef query ''level=\"error\"'' --no-highlight | grep -i \"timeout\"\n```\n\n**Common Errors And Fixes**\n`No context configured` → run `logchef auth --server <url>` or set `LOGCHEF_SERVER_URL` and `LOGCHEF_AUTH_TOKEN`.\n`Team not specified` → pass `--team` or run `logchef config set team <name_or_id>`.\n`Source not specified` → pass `--source` or run `logchef config set source <name_or_id>`.\n`--from requires --to` → always set both `--from` and `--to`.\n`invalid time format` → use `YYYY-MM-DD HH:MM:SS` (no `T`, no `Z`, no offset).\n`SQL query required` → pass SQL as an argument or use `-` to read from stdin.\nShell pipe errors → wrap LogChefQL in single quotes.\n\n**Safety Rules**\nAlways bound time (start with `15m`, expand gradually).\nAlways scope with at least one filter besides time (service, level, host, trace_id).\nAlways use `--limit` for `query` and `collections`.\nKeep raw samples small (≤20 lines) and redact secrets or PII.\nPrefer aggregations before pulling raw logs.\n\n**Investigation Workflow**\n1. Count volume with a narrow window.\n2. Group by a small dimension to find dominant errors.\n3. Sample a few representative logs.\n4. Pivot on `trace_id` or `request_id`.\n5. Expand time range only after counts look reasonable.\n\n```bash\n# Count errors (SQL)\nlogchef sql \"SELECT count() AS cnt FROM logs.app WHERE _timestamp > now() - INTERVAL 15 MINUTE AND level=''error''\"\n\n# Top error messages (SQL)\nlogchef sql \"SELECT msg, count() AS cnt FROM logs.app WHERE _timestamp > now() - INTERVAL 15 MINUTE AND msg ILIKE ''%error%'' GROUP BY msg ORDER BY cnt DESC LIMIT 10\"\n\n# Sample specific error\nlogchef query ''msg~\"connection refused\"'' --since 15m --limit 10\n```\n"},"lastSynced":"2026-03-08T02:02:59.869Z","agentAnalysis":{"suitability":{"en":"Perfect for Log Analysis Agents needing high-performance querying and visualization capabilities for ClickHouse logs.","zh":"非常适合需要高性能查询和可视化能力的日志分析代理，用于ClickHouse日志。","ja":"ClickHouseログの高性能なクエリと可視化機能が必要なログ分析エージェントに最適です。","ko":"클릭하우스 로그에 대한 고성능 쿼리 및 시각화 기능이 필요한 로그 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Registros que necesitan capacidades de consulta y visualización de alto rendimiento para registros de ClickHouse.","fr":"Parfait pour les Agents d''Analyse de Journaux nécessitant des capacités de requêtage et de visualisation de haute performance pour les journaux ClickHouse.","de":"Perfekt für Log-Analyse-Agents, die eine hohe Leistung bei der Abfrage und Visualisierung von ClickHouse-Protokollen benötigen.","pt":"Perfeito para Agentes de Análise de Logs que necessitam de capacidades de consulta e visualização de alto desempenho para logs do ClickHouse.","ru":"Идеально подходит для агентов анализа журналов, требующих высокопроизводительных возможностей запроса и визуализации для журналов ClickHouse.","ar":"مثالي لعميل تحليل السجلات الذي يحتاج إلى إمكانيات استعلام وتصوير عالية الأداء لسجلات ClickHouse."},"recommendation":{"en":"Empowers agents to query logs safely and accurately using LogChefQL filters, with features like OIDC authentication and customizable defaults for teams and log sources, all while leveraging ClickHouse for high-performance analytics.","zh":"赋予代理安全、准确地使用LogChefQL过滤器查询日志的能力，具有OIDC身份验证和可自定义的默认设置，团队和日志源，同时利用ClickHouse进行高性能分析。","ja":"LogChefQLフィルタを使用してログを安全に、正確に検索するエージェントを可能にし、OIDC認証やチームとログソースのカスタマイズ可能なデフォルト設定などを提供し、ClickHouseを使用した高性能な分析を実現します。","ko":"로그쉐프QL 필터를 사용하여 로그를 안전하고 정확하게 쿼리할 수 있는 에이전트를 강화하여 OIDC 인증 및 팀과 로그 소스의 사용자 정의 가능한 기본 설정과 같은 기능을 제공하여 클릭하우스를 사용한 고성능 분석을 제공합니다.","es":"Habilita a los agentes a consultar registros de manera segura y precisa utilizando filtros LogChefQL, con características como la autenticación OIDC y valores predeterminados personalizables para equipos y fuentes de registros, todo mientras aprovecha ClickHouse para analíticas de alto rendimiento.","fr":"Permet aux agents d''interroger les journaux de manière sécurisée et précise en utilisant des filtres LogChefQL, avec des fonctionnalités telles que l''authentification OIDC et des valeurs par défaut personnalisables pour les équipes et les sources de journaux, tout en exploitant ClickHouse pour des analyses haute performance.","de":"Ermächtigt Agents, Protokolle sicher und genau abzufragen, indem LogChefQL-Filter verwendet werden, mit Funktionen wie OIDC-Authentifizierung und anpassbaren Standardwerten für Teams und Protokollquellen, während ClickHouse für Hochleistungsanalysen genutzt wird.","pt":"Habilita os agentes a consultar logs de forma segura e precisa usando filtros LogChefQL, com recursos como autenticação OIDC e padrões personalizáveis para equipes e fontes de log, ao mesmo tempo em que aproveita o ClickHouse para análise de alto desempenho.","ru":"Наделяет агентов возможностью безопасного и точного запроса журналов с помощью фильтров LogChefQL, с функциями, такими как аутентификация OIDC и настраиваемые значения по умолчанию для команд и источников журналов, при этом используя ClickHouse для высокопроизводительного анализа.","ar":"يمنح العملاء khảية استعلام السجلات بأمان ودقة باستخدام مرشحات LogChefQL، مع ميزات مثل مصادقة OIDC وأفتراضيات قابلة للتعديل للفرق ومصادر السجلات، في الوقت نفسه يستفيد من ClickHouse لتحليل أداء عال."},"useCases":{"en":["Querying logs for error levels","Visualizing log data for specific time ranges","Authenticating with OIDC for secure log access"],"zh":["查询错误级别的日志","可视化特定时间范围的日志数据","使用OIDC进行安全的日志访问身份验证"],"ja":["エラーレベルのログを照会する","特定の時間範囲のログデータを視覚化する","OIDCを使用した安全なログアクセスの認証"],"ko":["에러 레벨의 로그 쿼리","특정 시간 범위의 로그 데이터 시각화","OIDC를 사용한 보안 로그 액세스 인증"],"es":["Consulta de registros para niveles de error","Visualización de datos de registro para rangos de tiempo específicos","Autenticación con OIDC para acceso seguro a registros"],"fr":["Interrogation des journaux pour les niveaux d''erreur","Visualisation des données de journal pour des plages de temps spécifiques","Authentification avec OIDC pour un accès sécurisé aux journaux"],"de":["Abfrage von Protokollen für Fehlerstufen","Visualisierung von Protokolldaten für bestimmte Zeitbereiche","Authentifizierung mit OIDC für sicheren Zugriff auf Protokolle"],"pt":["Consultar logs para níveis de erro","Visualizar dados de log para intervalos de tempo específicos","Autenticar com OIDC para acesso seguro ao log"],"ru":["Запрос журналов для уровней ошибок","Визуализация данных журнала для определенных диапазонов времени","Аутентификация с помощью OIDC для безопасного доступа к журналу"],"ar":["استعلام السجلات لمستويات الخطأ","تصوير بيانات السجل لفترات زمنية محددة","التحقق بمصادقة OIDC للوصول الآمن إلى السجل"]},"limitations":{"en":["Requires ClickHouse setup","OIDC authentication necessary","Limited to LogChefQL filters"],"zh":["需要ClickHouse设置","需要OIDC身份验证","仅限LogChefQL过滤器"],"ja":["ClickHouseの設定が必要","OIDC認証が必要","LogChefQLフィルタのみ"],"ko":["클릭하우스 설정이 필요","OIDC 인증이 필요","로그쉐프QL 필터만"],"es":["Requiere configuración de ClickHouse","Autenticación OIDC necesaria","Limitado a filtros LogChefQL"],"fr":["Nécessite une configuration ClickHouse","Authentification OIDC nécessaire","Limité aux filtres LogChefQL"],"de":["Benötigt ClickHouse-Konfiguration","OIDC-Authentifizierung erforderlich","Begrenzt auf LogChefQL-Filter"],"pt":["Requer configuração do ClickHouse","Autenticação OIDC necessária","Limitado a filtros LogChefQL"],"ru":["Требуется настройка ClickHouse","Необходима аутентификация OIDC","Ограничен фильтрами LogChefQL"],"ar":["يتطلب إعداد ClickHouse","مصادقة OIDC ضرورية","محدود بمرشحات LogChefQL"]},"version":4},"contentHash":"c106a0a40d625cd7a24d5133239f6ac0c4c15e9b44c166ecca4f29a8b85354ef","qualityScore":42}');
