INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mr-karan/logchef/logchef', 'logchef', 'mr-karan', 'logchef', 'community', 'logchef mr-karan logchef community logchef is a lightweight log analytics interface for ClickHouse, enabling developers to query logs safely and accurately. It provides high-performance querying and visualization capabilities. LogChef 是一个用于 ClickHouse 的轻量级日志分析接口，专注于高性能查询和可视化 LogChef は ClickHouse 用の軽量ログ分析インターフェイスで、高性能クエリと可視化に重点を置いています LogChef는 클릭하우스용 가벼운 로그 분석 인터페이스로, 높은 성능의 쿼리와 시각화를 제공합니다 LogChef es una interfaz de análisis de registros ligera y de un solo binario para ClickHouse, enfocada en consultas de alto rendimiento y visualización LogChef est une interface d''analyse de journaux légère et mono-binaire pour ClickHouse, axée sur les requêtes haute performance et la visualisation LogChef ist eine leichte und einbinäre Schnittstelle für die Analyse von ClickHouse-Protokollen, die sich auf Hochleistungsabfragen und Visualisierung konzentriert O LogChef é uma interface de análise de logs leve e de alta performance para ClickHouse, que oferece consultas de logs seguras e precisas LogChef - это легкий и высокопроизводительный интерфейс анализа журналов для ClickHouse, обеспечивающий безопасные и точные запросы журналов LogChef هو واجهة تحليل السجلات الخفيفة ذات الأداء العالي ل ClickHouse، يوفر استفسارات سجلات آمنة و دقيقة how to use logchef logchef setup guide logchef alternative logchef vs elk logchef install what is logchef logchef clickhouse integration logchef query language logchef authentication LogChef ClickHouse 日志分析 高性能查询 CLI OIDC AIエージェント 日志可视化 Authenticate with OIDC using `logchef auth --server` command Set defaults with `logchef config set` command for team and source Query logs with LogChefQL filters using `logchef query` command Supports filtering by level, time, and limit using `--since` and `--limit` flags Provides a command cheat sheet for easy reference Enables safe and accurate log querying logchef is a single-binary log analytics interface for ClickHouse, focused on high-performance querying and visualization');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('codervisor/lean-spec/github-actions', 'community', 'codervisor', 'lean-spec', 'codervisor/lean-spec', 'github-actions', 0, 0, 42, '2026-03-08T01:57:15.325Z', '2026-03-08T02:03:01.534Z', '4316d64dcd52df1ad9d413094729f0f2fd810042ef00c8fe21591395d5cb3a48', '{"id":"codervisor/lean-spec/github-actions","name":"github-actions","description":{"en":"The github-actions skill enables AI agents to automate workflow interactions using the GitHub CLI. It benefits developers by streamlining Spec-Driven Development for modern AI-powered projects.","zh":"GitHub Actions Skill 教程：使用 GitHub CLI（gh）触发、监控和管理工作流，并确保 Spec-Driven Development (SDD) 的高效实施","ja":"GitHub Actions Skill を使用して、GitHub CLI（gh）でワークフローをトリガー、監視、管理し、Spec-Driven Development (SDD) を効率的に実現します","ko":"GitHub Actions Skill 을 사용하여 GitHub CLI（gh）로 워크플로를 트리거, 모니터링, 관리하고 Spec-Driven Development (SDD) 를 효율적으로 구현합니다","es":"GitHub Actions es una herramienta de desarrollo de software que permite a los agentes de IA automatizar flujos de trabajo y mejorar la eficiencia","fr":"GitHub Actions est un outil de développement logiciel qui permet aux outils d''IA d''automatiser les flux de travail et d''améliorer l''efficacité","de":"GitHub Actions ist ein Software-Entwicklungstool, das es künstlicher Intelligenz ermöglicht, Arbeitsabläufe zu automatisieren und die Effizienz zu verbessern","pt":"O GitHub Actions é uma ferramenta de desenvolvimento de IA que permite trigger, monitorar e gerenciar workflows","ru":"GitHub Actions - инструмент для разработки ИИ Агенты, позволяющий запускать, отслеживать и управлять рабочими процессами","ar":"GitHub Actions هو أداة تطوير الإنسان المصغرة التي تمكن من تشغيل ومراقبة وادارة سير العمل"},"seo":{"title":{"en":"github-actions: Setup Guide for AI Agents | AI Agent Skill","zh":"GitHub Actions Setup Guide - AIエージェント工作流管理","ja":"GitHub Actions を使用した AIエージェントのベストプラクティス","ko":"GitHub Actions AI 에이전트_workflow 관리 가이드","es":"Guía de configuración de GitHub Actions para agentes de IA","fr":"Guide de configuration de GitHub Actions pour les outils ...","de":"Einrichtungsleitfaden für GitHub Actions in der künstlich...","pt":"Guia de Configuração do GitHub Actions para Desenvolvimen...","ru":"Настройка GitHub Actions для инструментов ИИ Агенты","ar":"دليل إعداد GitHub Actions لعمليات تطوير الإنسان المصغرة"},"description":{"en":"Discover how to trigger, monitor, and manage GitHub Actions workflows with ease. Learn the core principles and get started with github-actions today!","zh":"使用 GitHub Actions 实现轻量级、灵活的 Spec-Driven Development (SDD) ，并学习如何触发、监控和管理工作流","ja":"GitHub Actions を使用して、Spec-Driven Development (SDD) を実現し、AIエージェントのワークフローを管理する方法を学びます","ko":"GitHub Actions 를 사용하여 경량, 유연한 Spec-Driven Development (SDD) 를 구현하고 워크플로를 트리거, 모니터링, 관리하는 방법을 알아보세요","es":"Aprende a configurar y utilizar GitHub Actions con agentes de IA para un desarrollo de software más eficiente","fr":"Découvrez comment configurer et utiliser GitHub Actions avec les outils d''IA pour un développement logiciel plus efficace","de":"Erfahren Sie, wie Sie GitHub Actions mit künstlicher Intelligenz konfigurieren und verwenden, um die Software-Entwicklung zu optimieren","pt":"Aprenda a configurar o GitHub Actions para desenvolvimento de IA com nossa guia passo a passo","ru":"Узнайте, как настроить GitHub Actions для инструментов ИИ Агенты с нашей пошаговой инструкцией","ar":"تعلم كيفية إعداد GitHub Actions لعمليات تطوير الإنسان المصغرة مع دليلنا خطوة بخطوة"},"definition":{"en":"github-actions is a lightweight, flexible skill for Spec-Driven Development that utilizes the GitHub CLI for workflow automation","zh":"GitHub Actions 是一种轻量级、灵活的 Spec-Driven Development (SDD) 工具，用于触发、监控和管理 GitHub Actions 工作流","ja":"GitHub Actions は、Spec-Driven Development (SDD) を実現するための軽量で柔軟なツールであり、GitHub Actions ワークフローをトリガー、監視、管理するために使用されます","ko":"GitHub Actions 는 경량, 유연한 Spec-Driven Development (SDD) 도구로 GitHub Actions 워크플로를 트리거, 모니터링, 관리하는 데 사용됩니다","es":"GitHub Actions es una característica de GitHub que permite a los desarrolladores automatizar flujos de trabajo utilizando el comando gh","fr":"GitHub Actions est une fonctionnalité de GitHub qui permet aux développeurs d''automatiser les flux de travail en utilisant la commande gh","de":"GitHub Actions ist eine Funktion von GitHub, die es Entwicklern ermöglicht, Arbeitsabläufe mit dem Befehl gh zu automatisieren","pt":"O que é GitHub Actions? É uma ferramenta de desenvolvimento de IA que usa o CLI do GitHub","ru":"Что такое GitHub Actions? Это инструмент для разработки ИИ Агенты, использующий CLI GitHub","ar":"ما هو GitHub Actions؟ هو أداة تطوير الإنسان المصغرة التي تستخدم واجهة سطر الأوامر الخاصة بـ GitHub"},"features":{"en":["Uses GitHub CLI (`gh`) for workflow interactions","Checks status before acting to prevent duplicate runs","Monitors workflows until completion for reliable automation","Downloads artifacts before expiration to prevent data loss","Utilizes background workflows with periodic status checks"],"zh":["使用 GitHub CLI（gh）触发和监控工作流","检查工作流状态之前触发新工作流","后台工作流需要周期性状态检查","下载重要的工作流产物（默认 30 天过期）"],"ja":["GitHub CLI（gh）を使用してワークフローをトリガー、監視する","新しいワークフローをトリガーする前に、ワークフローのステータスを確認する","バックグラウンドワークフローには、周期的なステータスチェックが必要","重要なワークフローアーティファクトをダウンロードする（デフォルトで 30 日後に期限切れ）"],"ko":["GitHub CLI（gh）를 사용하여 워크플로를 트리거, 모니터링하는 기능","새로운 워크플로를 트리거하기 전에 워크플로의 상태를 확인하는 기능","백그라운드 워크플로에는 주기적인 상태 확인이 필요","중요한 워크플로 아티팩트를 다운로드하는 기능（기본 30일 후 만료）"],"es":["Uso de la CLI de GitHub (gh) para interactuar con flujos de trabajo","Verificación del estado de ejecución antes de realizar acciones","Monitoreo de flujos de trabajo en segundo plano hasta su finalización","Descarga de artefactos importantes antes de su expiración"],"fr":["Utilisation de la CLI GitHub (gh) pour interagir avec les flux de travail","Vérification de l''état d''exécution avant de réaliser des actions","Surveillance des flux de travail en arrière-plan jusqu''à leur achèvement","Téléchargement d''artefacts importants avant leur expiration"],"de":["Verwendung der GitHub-CLI (gh) zur Interaktion mit Arbeitsabläufen","Überprüfung des Ausführungsstatus vor der Ausführung von Aktionen","Überwachung von Hintergrundarbeitsabläufen bis zur Fertigstellung","Herunterladen wichtiger Artefakte vor ihrem Ablauf"],"pt":["Uso do GitHub CLI (gh) para interações de workflow","Verificação do status antes de executar ações","Monitoramento até a conclusão dos workflows","Download de artefatos importantes antes da expiração"],"ru":["Использование GitHub CLI (gh) для взаимодействия с рабочими процессами","Проверка статуса перед выполнением действий","Отслеживание до завершения рабочих процессов","Скачивание важных артефактов до истечения срока"],"ar":["استخدام واجهة سطر الأوامر الخاصة بـ GitHub (gh) للتفاعل مع سير العمل","التحقق من الحالة قبل تنفيذ الإجراءات","مراقبة سير العمل حتى الانتهاء","تحميل الملفات المهمة قبل انتهاء الصلاحية"]},"keywords":{"en":["how to use github-actions","github-actions setup guide","github-actions alternative","github-actions vs circleci","github-actions install","github-actions tutorial"],"zh":["GitHub Actions","Spec-Driven Development","AIエージェント","工作流管理","GitHub CLI","轻量级开发","灵活的 SDD"],"ja":["GitHub Actions","Spec-Driven Development","AIエージェント","ワークフローマネジメント","GitHub CLI","軽量開発","柔軟な SDD"],"ko":["GitHub Actions","Spec-Driven Development","AI 에이전트","워크플로우 관리","GitHub CLI","경량 개발","유연한 SDD"],"es":["GitHub Actions","agentes de IA","desarrollo de software","automatización de flujos de trabajo","CLI de GitHub","gh","IA y desarrollo"],"fr":["GitHub Actions","outils d''IA","développement logiciel","automatisation de flux de travail","CLI GitHub","gh","IA et développement"],"de":["GitHub Actions","künstliche Intelligenz","Software-Entwicklung","Automatisierung von Arbeitsabläufen","GitHub-CLI","gh","KI und Entwicklung"],"pt":["github actions","desenvolvimento de ia","cli do github","workflow","monitoramento","artefatos","ia tools","ferramentas de desenvolvimento"],"ru":["github actions","инструменты ии агенты","cli github","рабочий процесс","отслеживание","артефакты","ии агенты","инструменты разработки"],"ar":["github actions","أدوات تطوير الإنسان المصغرة","واجهة سطر الأوامر الخاصة بـ github","سير العمل","مراقبة","الملفات المهمة","أدوات تطوير","تطوير الإنسان المصغرة"]}},"owner":"codervisor","repo":"lean-spec","repoPath":"codervisor/lean-spec","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.325Z","topics":[],"category":"community","skillMd":{"name":"github-actions","description":"GitHub Actions workflow management for LeanSpec. Use when triggering CI/CD workflows, monitoring build status, debugging failed runs, managing artifacts, or checking CI before releases.","bodyPreview":"# GitHub Actions Skill\n\nTeach agents how to trigger, monitor, and manage GitHub Actions workflows for the LeanSpec project.\n\n## Core Principles\n\n1. **Use GitHub CLI (`gh`)** - All workflow interactions use the `gh` CLI tool\n2. **Check Status Before Acting** - Always verify current run status before triggering new ones\n3. **Monitor Until Completion** - Background workflows need periodic status checks\n4. **Artifacts Are Ephemeral** - Download important artifacts before they expire (default: 30 day","body":"# GitHub Actions Skill\n\nTeach agents how to trigger, monitor, and manage GitHub Actions workflows for the LeanSpec project.\n\n## Core Principles\n\n1. **Use GitHub CLI (`gh`)** - All workflow interactions use the `gh` CLI tool\n2. **Check Status Before Acting** - Always verify current run status before triggering new ones\n3. **Monitor Until Completion** - Background workflows need periodic status checks\n4. **Artifacts Are Ephemeral** - Download important artifacts before they expire (default: 30 days)\n5. **Respect Rate Limits** - Don''t poll too frequently (minimum 30s between checks)\n\n## Available Workflows\n\n| Workflow | File | Triggers | Purpose |\n|----------|------|----------|---------|\n| **CI** | `ci.yml` | push, PR to main | Build, test, lint (Node.js + Rust) |\n| **Publish** | `publish.yml` | release, manual | Publish to npm (all platforms) |\n| **Desktop Build** | `desktop-build.yml` | push, PR, manual | Build Tauri desktop apps |\n| **Copilot Setup** | `copilot-setup-steps.yml` | push, PR, manual | Setup environment for Copilot agent |\n\n## Quick Reference\n\n### Check Workflow Status\n\n```bash\n# List recent workflow runs\ngh run list --limit 10\n\n# View specific workflow runs\ngh run list --workflow ci.yml --limit 5\ngh run list --workflow publish.yml --limit 5\n\n# Get details of a specific run\ngh run view <run-id>\n\n# Watch a run in progress\ngh run watch <run-id>\n```\n\n### Trigger Workflows\n\n```bash\n# Trigger CI manually (usually automatic on push/PR)\ngh workflow run ci.yml\n\n# Trigger publish (dev version)\ngh workflow run publish.yml --field dev=true\n\n# Trigger publish (dry run - validates without publishing)\ngh workflow run publish.yml --field dev=true --field dry_run=true\n\n# Trigger desktop build\ngh workflow run desktop-build.yml\n```\n\n### Debug Failed Runs\n\n```bash\n# View failed run logs\ngh run view <run-id> --log-failed\n\n# View full logs\ngh run view <run-id> --log\n\n# Re-run failed jobs only\ngh run rerun <run-id> --failed\n\n# Re-run entire workflow\ngh run rerun <run-id>\n```\n\n### Manage Artifacts\n\n```bash\n# List artifacts from a run\ngh run view <run-id>\n\n# Download all artifacts from a run\ngh run download <run-id>\n\n# Download specific artifact\ngh run download <run-id> --name ui-dist\ngh run download <run-id> --name binaries-linux-x64\n```\n\n## Decision Tree\n\n```\nNeed to check if build passing?\n└─> gh run list --workflow ci.yml --limit 1\n\nNeed to publish packages?\n├─> Production: Create GitHub Release (recommended)\n└─> Testing: gh workflow run publish.yml --field dev=true\n\nWorkflow failed?\n├─> View logs: gh run view <id> --log-failed\n├─> Transient: gh run rerun <id> --failed\n└─> Real issue: Fix locally, push, let CI re-run\n\nNeed build artifacts?\n└─> gh run download <run-id> --name <artifact-name>\n```\n\n## Reference Documentation\n\n- [references/WORKFLOWS.md](./references/WORKFLOWS.md) - Detailed workflow documentation (jobs, triggers, durations)\n- [references/COMMANDS.md](./references/COMMANDS.md) - Complete `gh` command reference\n- [references/TROUBLESHOOTING.md](./references/TROUBLESHOOTING.md) - Common issues and solutions"},"lastSynced":"2026-03-08T02:03:01.534Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring seamless GitHub Actions workflow automation using the GitHub CLI","zh":"适合需要无缝 GitHub Actions 工作流自动化的 DevOps Agent，使用 GitHub CLI","ja":"GitHub CLI を使用したシームレスな GitHub Actions ワークフロー自動化を必要とする DevOps エージェントに適しています","ko":"GitHub CLI를 사용한 무결점 GitHub Actions 워크플로 자동화를 요구하는 DevOps 에이전트에 적합합니다","es":"Ideal para agentes de DevOps que requieren una automatización de flujo de trabajo de GitHub Actions sin problemas utilizando el CLI de GitHub","fr":"Idéal pour les agents DevOps nécessitant une automatisation du workflow GitHub Actions sans accroc en utilisant le CLI GitHub","de":"Ideal für DevOps-Agents, die eine nahtlose Automatisierung des GitHub-Actions-Workflows unter Verwendung des GitHub-CLI benötigen","pt":"Ideal para Agentes DevOps que requerem automação de fluxo de trabalho de GitHub Actions sem interrupções usando o GitHub CLI","ru":"Идеально для агентов DevOps, требующих бесшовную автоматизацию рабочего процесса GitHub Actions с помощью GitHub CLI","ar":"مثالي لعميل DevOps الذين يحتاجون إلى تautomatisation سلسة لتدفق العمل GitHub Actions باستخدام GitHub CLI"},"recommendation":{"en":"Empowers agents to trigger, monitor, and manage GitHub Actions workflows using the `gh` CLI tool, ensuring efficient Spec-Driven Development for modern AI-powered projects with features like periodic status checks and artifact management","zh":"赋予代理触发、监控和管理 GitHub Actions 工作流的能力，使用 `gh` CLI 工具，确保现代 AI 驱动项目的高效 Spec-Driven Development，具有周期性状态检查和制品管理等功能","ja":"エージェントに `gh` CLI ツールを使用して GitHub Actions ワークフローをトリガー、監視、管理する能力を与え、現代の AI パワード プロジェクトの効率的な Spec-Driven Development を可能にします。周期的なステータス チェックやアーティファクト管理などの機能を備えています","ko":"에이전트에 `gh` CLI 도구를 사용하여 GitHub Actions 워크플로를 트리거, 모니터링 및 관리할 수 있는 능력을 부여하여 현대의 AI 구동 프로젝트에 대한 효율적인 Spec-Driven 개발을 보장합니다. 주기적인 상태 확인 및 아티팩트 관리와 같은 기능을 제공합니다","es":"Habilita a los agentes para desencadenar, monitorear y gestionar flujos de trabajo de GitHub Actions utilizando la herramienta CLI `gh`, garantizando un desarrollo impulsado por especificaciones eficiente para proyectos modernos impulsados por AI con características como comprobaciones de estado periódicas y administración de artefactos","fr":"Permet aux agents de déclencher, de surveiller et de gérer les flux de travail GitHub Actions en utilisant l''outil CLI `gh`, garantissant un développement piloté par des spécifications efficace pour les projets modernes alimentés par l''IA avec des fonctionnalités comme les vérifications d''état périodiques et la gestion d''artefacts","de":"Ermächtigt Agenten, GitHub-Actions-Workflows mithilfe des `gh`-CLI-Tools auszulösen, zu überwachen und zu verwalten, und stellt so eine effiziente spezifikationsgetriebene Entwicklung für moderne KI-gesteuerte Projekte mit Funktionen wie periodischen Statusprüfungen und Artefaktnutzung sicher","pt":"Habilita os agentes a acionar, monitorar e gerenciar fluxos de trabalho do GitHub Actions usando a ferramenta CLI `gh`, garantindo desenvolvimento orientado a especificações eficiente para projetos modernos alimentados por IA com recursos como verificações de status periódicas e gerenciamento de artefatos","ru":"Наделяет агентов возможностью запускать, отслеживать и управлять рабочими процессами GitHub Actions с помощью инструмента CLI `gh`, обеспечивая эффективное развитие, управляемое спецификациями, для современных проектов, работающих на ИИ, с функциями, такими как периодические проверки статуса и управление артефактами","ar":"يمنح الوكلاء القدرة على تشغيل ومراقبة وإدارة تدفقات العمل GitHub Actions باستخدام أداة CLI `gh` ، مما يضمن التطوير الفعال القائم على المواصفات لمشاريع حديثة تعمل بالذكاء الاصطناعي مع ميزات مثل فحوصات الحالة الدورية وإدارة المكونات"},"useCases":{"en":["Automating workflow interactions for the LeanSpec project","Monitoring GitHub Actions workflow status until completion","Downloading important artifacts before expiration"],"zh":["为 LeanSpec 项目自动化工作流交互","监控 GitHub Actions 工作流状态直到完成","在过期之前下载重要的制品"],"ja":["LeanSpec プロジェクトのワークフロー インタラクションを自動化する","GitHub Actions ワークフローのステータスを完了するまで監視する","重要なアーティファクトを期限切れになる前にダウンロードする"],"ko":["LeanSpec 프로젝트의 워크플로 상호작용 자동화","GitHub Actions 워크플로 상태를 완료할 때까지 모니터링","만료되기 전에 중요한 아티팩트 다운로드"],"es":["Automatizar las interacciones de flujo de trabajo para el proyecto LeanSpec","Supervisar el estado del flujo de trabajo de GitHub Actions hasta su finalización","Descargar artefactos importantes antes de su caducidad"],"fr":["Automatiser les interactions de flux de travail pour le projet LeanSpec","Surveiller l''état du flux de travail GitHub Actions jusqu''à son achèvement","Télécharger des artefacts importants avant leur expiration"],"de":["Automatisierung von Workflow-Interaktionen für das LeanSpec-Projekt","Überwachung des GitHub-Actions-Workflow-Status bis zum Abschluss","Herunterladen wichtiger Artefakte vor deren Ablauf"],"pt":["Automatizar interações de fluxo de trabalho para o projeto LeanSpec","Monitorar status do fluxo de trabalho do GitHub Actions até a conclusão","Baixar artefatos importantes antes do vencimento"],"ru":["Автоматизировать взаимодействия рабочего процесса для проекта LeanSpec","Отслеживать статус рабочего процесса GitHub Actions до завершения","Скачивать важные артефакты до истечения срока"],"ar":["تأتمة تفاعلات تدفق العمل لمشروع LeanSpec","مراقبة حالة تدفق العمل GitHub Actions حتى الانتهاء","تنزيل مكونات مهمة قبل انتهاء الصلاحية"]},"limitations":{"en":["Requires GitHub CLI (`gh`) installation","Dependent on GitHub Actions workflow configuration","Artifact storage limited to 30 days by default"],"zh":["需要 GitHub CLI (`gh`) 安装","依赖于 GitHub Actions 工作流配置","制品存储默认限制为 30 天"],"ja":["GitHub CLI (`gh`) のインストールが必要","GitHub Actions ワークフローの構成に依存する","アーティファクトの保存はデフォルトで 30 日に制限される"],"ko":["GitHub CLI(`gh`) 설치 필요","GitHub Actions 워크플로 구성에 의존","아티팩트 저장소는 기본적으로 30일로 제한"],"es":["Requiere la instalación del CLI de GitHub (`gh`)","Dependiente de la configuración del flujo de trabajo de GitHub Actions","El almacenamiento de artefactos está limitado a 30 días por defecto"],"fr":["Nécessite l''installation du CLI GitHub (`gh`)","Dépend de la configuration du flux de travail GitHub Actions","Le stockage d''artefacts est limité à 30 jours par défaut"],"de":["Benötigt die Installation des GitHub-CLI (`gh`)","Abhängig von der Konfiguration des GitHub-Actions-Workflows","Die Artefakt-Speicherung ist standardmäßig auf 30 Tage beschränkt"],"pt":["Requer instalação do GitHub CLI (`gh`)","Dependente da configuração do fluxo de trabalho do GitHub Actions","Armazenamento de artefatos limitado a 30 dias por padrão"],"ru":["Требует установки GitHub CLI (`gh`)","Зависит от конфигурации рабочего процесса GitHub Actions","Хранилище артефактов ограничено 30 днями по умолчанию"],"ar":["يتطلب تثبيت GitHub CLI (`gh`)","يعتمد على تكوين تدفق العمل GitHub Actions","تخزين المكونات محدود ب 30 يومًا افتراضيًا"]},"version":4},"contentHash":"4316d64dcd52df1ad9d413094729f0f2fd810042ef00c8fe21591395d5cb3a48","qualityScore":42}');
