INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('codervisor/lean-spec/github-actions', 'github-actions', 'codervisor', 'lean-spec', 'community', 'github-actions codervisor lean-spec community The github-actions skill enables AI agents to automate workflow interactions using the GitHub CLI. It benefits developers by streamlining Spec-Driven Development for modern AI-powered projects. GitHub Actions Skill 教程：使用 GitHub CLI（gh）触发、监控和管理工作流，并确保 Spec-Driven Development (SDD) 的高效实施 GitHub Actions Skill を使用して、GitHub CLI（gh）でワークフローをトリガー、監視、管理し、Spec-Driven Development (SDD) を効率的に実現します GitHub Actions Skill 을 사용하여 GitHub CLI（gh）로 워크플로를 트리거, 모니터링, 관리하고 Spec-Driven Development (SDD) 를 효율적으로 구현합니다 GitHub Actions es una herramienta de desarrollo de software que permite a los agentes de IA automatizar flujos de trabajo y mejorar la eficiencia GitHub Actions est un outil de développement logiciel qui permet aux outils d''IA d''automatiser les flux de travail et d''améliorer l''efficacité GitHub Actions ist ein Software-Entwicklungstool, das es künstlicher Intelligenz ermöglicht, Arbeitsabläufe zu automatisieren und die Effizienz zu verbessern O GitHub Actions é uma ferramenta de desenvolvimento de IA que permite trigger, monitorar e gerenciar workflows GitHub Actions - инструмент для разработки ИИ Агенты, позволяющий запускать, отслеживать и управлять рабочими процессами GitHub Actions هو أداة تطوير الإنسان المصغرة التي تمكن من تشغيل ومراقبة وادارة سير العمل how to use github-actions github-actions setup guide github-actions alternative github-actions vs circleci github-actions install github-actions tutorial GitHub Actions Spec-Driven Development AIエージェント 工作流管理 GitHub CLI 轻量级开发 灵活的 SDD Uses GitHub CLI (`gh`) for workflow interactions Checks status before acting to prevent duplicate runs Monitors workflows until completion for reliable automation Downloads artifacts before expiration to prevent data loss Utilizes background workflows with periodic status checks github-actions is a lightweight, flexible skill for Spec-Driven Development that utilizes the GitHub CLI for workflow automation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wevm/viem/tempo-codegen', 'community', 'wevm', 'viem', 'wevm/viem', 'tempo-codegen', 0, 0, 42, '2026-03-08T01:57:15.327Z', '2026-03-08T02:03:05.502Z', '2bdad55fe4ed7d38350e90cb781370032f54d16db05ad642de2329b3983d898b', '{"id":"wevm/viem/tempo-codegen","name":"tempo-codegen","description":{"en":"tempo-codegen is a TypeScript interface for Ethereum, enabling developers to generate actions based on precompile contract specifications. It benefits Ethereum developers and smart contract creators.","zh":"Tempo Codegen是一个TypeScript接口，为以太坊提供基于预编译合约规范的动作生成","ja":"Tempo Codegenは、事前コンパイルされたコントラクト仕様に基づくアクション生成を提供するEthereum用TypeScriptインターフェースです","ko":"Tempo Codegen은 이더리움을 위한 TypeScript 인터페이스로서, 事前 컴파일된 계약 사양을 기반으로 한 액션 생성을 제공합니다","es":"Tempo-codegen es una interfaz de TypeScript para Ethereum que permite generar acciones basadas en especificaciones de contratos precompilados","fr":"Tempo-codegen est une interface TypeScript pour Ethereum qui permet de générer des actions basées sur des spécifications de contrats précompilés","de":"Tempo-codegen ist eine TypeScript-Schnittstelle für Ethereum, die die Generierung von Aktionen basierend auf Spezifikationen vorcompilierter Verträge ermöglicht","pt":"O tempo-codegen é uma interface TypeScript para Ethereum que permite gerar ações com base em especificações de contrato pré-compilado.","ru":"Tempo-codegen — это интерфейс TypeScript для Ethereum, который позволяет генерировать действия на основе спецификаций pré-скомпилированного контракта.","ar":"tempo-codegen هو واجهة TypeScript لشبكة Ethereum التي تمكنك من生成 إجراءات بناءً على مواصفات عقد معالجة مسبقة."},"seo":{"title":{"en":"tempo-codegen: Ethereum TypeScript Interface Setup Guide ...","zh":"Tempo Codegen Setup Guide - TypeScript 接口为以太坊","ja":"Tempo Codegen ベストプラクティス - Ethereum用TypeScriptインターフェース","ko":"Tempo Codegen 사용자 가이드 - 이더리움을 위한 TypeScript 인터페이스","es":"Guía de configuración de tempo-codegen para Ethereum","fr":"Guide de mise en place de tempo-codegen pour Ethereum","de":"Einrichtungsleitfaden für tempo-codegen mit Ethereum","pt":"Guia de Configuração do tempo-codegen: TypeScript para Et...","ru":"ИИ Агенты: Настройка tempo-codegen для Ethereum с TypeScript","ar":"دليل إعداد tempo-codegen: واجهة TypeScript لشبكة Ethereum"},"description":{"en":"Discover how to leverage tempo-codegen for seamless Ethereum development. Learn to generate actions with our expert guide and unlock the full potential of Ty...","zh":"了解Tempo Codegen的功能和特点，包括基于预编译合约规范的动作生成和TypeScript接口","ja":"Tempo Codegenの機能と特徴を紹介します。事前コンパイルされたコントラクト仕様に基づくアクション生成やTypeScriptインターフェースなど","ko":"Tempo Codegen의 기능과 특징을 알아보세요. 事前 컴파일된 계약 사양을 기반으로 한 액션 생성 및 TypeScript 인터페이스 등","es":"Aprende a utilizar tempo-codegen para generar acciones en Ethereum con nuestra guía paso a paso","fr":"Découvrez comment utiliser tempo-codegen pour générer des actions sur Ethereum avec notre guide étape par étape","de":"Erfahren Sie, wie Sie tempo-codegen verwenden, um Aktionen in Ethereum zu generieren, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o tempo-codegen para desenvolver aplicações Ethereum com TypeScript. Descubra as melhores práticas e recursos técnicos.","ru":"Узнайте, как настроить tempo-codegen для разработки приложений Ethereum с помощью TypeScript. Откройте для себя лучшие практики и технические возможности.","ar":"تعرف على كيفية إعداد tempo-codegen لتطوير تطبيقات Ethereum باستخدام TypeScript. اكتشف أفضل الممارسات والميزات الفنية."},"definition":{"en":"tempo-codegen is a TypeScript interface for Ethereum, providing a framework for generating actions based on precompile contract specifications.","zh":"Tempo Codegen是一种TypeScript接口，用于为以太坊生成动作","ja":"Tempo Codegenは、Ethereum用のTypeScriptインターフェースの一種です","ko":"Tempo Codegen은 이더리움을 위한 TypeScript 인터페이스의 한 종류입니다","es":"Tempo-codegen es una herramienta de código abierto que proporciona una interfaz de TypeScript para interactuar con la red Ethereum","fr":"Tempo-codegen est un outil open source qui fournit une interface TypeScript pour interagir avec le réseau Ethereum","de":"Tempo-codegen ist ein Open-Source-Tool, das eine TypeScript-Schnittstelle zur Interaktion mit dem Ethereum-Netzwerk bietet","pt":"O que é tempo-codegen? É uma interface TypeScript para Ethereum que facilita a geração de ações com base em especificações de contrato.","ru":"Что такое tempo-codegen? Это интерфейс TypeScript для Ethereum, который облегчает генерирование действий на основе спецификаций контракта.","ar":"ما هو tempo-codegen؟ هو واجهة TypeScript لشبكة Ethereum التي تسهل việc توليد الإجراءات بناءً على مواصفات العقد."},"features":{"en":["Generates actions based on precompile contract specifications in test/tempo/docs/specs/","Ensures consistency between specs and precompiles in test/tempo/crates/contracts/src/precompiles","Supports action set generation, as seen in src/tempo/actions/token.ts","Follows guidelines for generating actions in src/tempo/actions/","Prioritizes specs as the source of truth for interface consistency"],"zh":["基于预编译合约规范的动作生成","TypeScript接口","与以太坊生态系统集成","高度可定制","支持事前编译的合同"],"ja":["事前コンパイルされたコントラクト仕様に基づくアクション生成","TypeScriptインターフェース","Ethereumエコシステムとの統合","高度なカスタマイズ","事前コンパイルされたコントラクトのサポート"],"ko":["事前 컴파일된 계약 사양을 기반으로 한 액션 생성","TypeScript 인터페이스","이더리움 에코시스템과 통합","높은 수준의 맞춤 설정","事前 컴파일된 계약의 지원"],"es":["Generación de acciones basadas en especificaciones de contratos precompilados","Compatibilidad con la red Ethereum","Interfaz de TypeScript para una integración fácil","Ejemplos de acciones generadas en src/tempo/actions/token.ts","Documentación de especificaciones en test/tempo/docs/specs/"],"fr":["Génération d''actions basées sur des spécifications de contrats précompilés","Compatibilité avec le réseau Ethereum","Interface TypeScript pour une intégration facile","Exemples d''actions générées dans src/tempo/actions/token.ts","Documentation des spécifications dans test/tempo/docs/specs/"],"de":["Generierung von Aktionen basierend auf Spezifikationen vorcompilierter Verträge","Kompatibilität mit dem Ethereum-Netzwerk","TypeScript-Schnittstelle für eine einfache Integration","Beispiele für generierte Aktionen in src/tempo/actions/token.ts","Dokumentation der Spezifikationen in test/tempo/docs/specs/"],"pt":["Geração de ações com base em especificações de contrato pré-compilado","Interface TypeScript para Ethereum","Compatibilidade com pré-compilados em `test/tempo/crates/contracts/src/precompiles`","Exemplo de conjunto de ações geradas em `src/tempo/actions/token.ts`","Prioridade às especificações de contrato em `test/tempo/docs/specs/`"],"ru":["Генерирование действий на основе спецификаций pré-скомпилированного контракта","Интерфейс TypeScript для Ethereum","Совместимость с pré-скомпилированными контрактами в `test/tempo/crates/contracts/src/precompiles`","Пример сгенерированного набора действий в `src/tempo/actions/token.ts`","Приоритет спецификациям контракта в `test/tempo/docs/specs/`"],"ar":["توليد الإجراءات بناءً على مواصفات عقد معالجة مسبقة","واجهة TypeScript لشبكة Ethereum","التوافق مع العقود المعالجة مسبقًا في `test/tempo/crates/contracts/src/precompiles`","مثال على مجموعة الإجراءات المولدة في `src/tempo/actions/token.ts`","الأولوية لمواصفات العقد في `test/tempo/docs/specs/`"]},"keywords":{"en":["how to use tempo-codegen","tempo-codegen setup guide","tempo-codegen alternative","tempo-codegen vs ethers.js","tempo-codegen install","tempo-codegen TypeScript interface","Ethereum development with tempo-codegen","tempo-codegen documentation","tempo-codegen tutorial"],"zh":["Tempo Codegen","TypeScript接口","以太坊","预编译合约规范","动作生成","AIエージェント","AI工具"],"ja":["Tempo Codegen","TypeScriptインターフェース","Ethereum","事前コンパイルされたコントラクト仕様","アクション生成","AIエージェント","AIツール"],"ko":["Tempo Codegen","TypeScript 인터페이스","이더리움","事前 컴파일된 계약 사양","액션 생성","AI 에이전트","AI 도구"],"es":["tempo-codegen","Ethereum","TypeScript","contratos precompilados","generación de acciones","herramientas de desarrollo","AI Agentes","desarrollo de blockchain"],"fr":["tempo-codegen","Ethereum","TypeScript","contrats précompilés","génération d''actions","outils de développement","Agents IA","développement de blockchain"],"de":["tempo-codegen","Ethereum","TypeScript","vorcompilierte Verträge","Aktionen generieren","Entwicklertools","KI-Agents","Blockchain-Entwicklung"],"pt":["tempo-codegen","TypeScript para Ethereum","geração de ações","especificações de contrato","pré-compilados","desenvolvimento de aplicações Ethereum","interface TypeScript"],"ru":["tempo-codegen","TypeScript для Ethereum","генерирование действий","спецификации контракта","пре-скомпилированные контракты","разработка приложений Ethereum","интерфейс TypeScript"],"ar":["tempo-codegen","TypeScript لشبكة Ethereum","توليد الإجراءات","مواصفات العقد","العقود المعالجة مسبقًا","تطوير تطبيقات Ethereum","واجهة TypeScript"]}},"owner":"wevm","repo":"viem","repoPath":"wevm/viem","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.327Z","topics":[],"category":"community","skillMd":{"name":"tempo-codegen","description":"Skill for generating Tempo code.","bodyPreview":"# Tempo Code Generation\n\nWhen generating actions (in `src/tempo/actions/`), follow these guidelines.\n\nAn example of a generated action set can be found in `src/tempo/actions/token.ts`.\n\n## Source of Truth\n\n- **All actions must be based on precompile contract specifications** in `test/tempo/docs/specs/`.\n- It could be likely that some interfaces may be inconsistent between the specs (`test/tempo/docs/specs`) and the precompiles (`test/tempo/crates/contracts/src/precompiles`). Always prefer the pr","body":"# Tempo Code Generation\n\nWhen generating actions (in `src/tempo/actions/`), follow these guidelines.\n\nAn example of a generated action set can be found in `src/tempo/actions/token.ts`.\n\n## Source of Truth\n\n- **All actions must be based on precompile contract specifications** in `test/tempo/docs/specs/`.\n- It could be likely that some interfaces may be inconsistent between the specs (`test/tempo/docs/specs`) and the precompiles (`test/tempo/crates/contracts/src/precompiles`). Always prefer the precompile interfaces over the specs.\n- If the specification is unclear or missing details, **prompt the developer** for guidance rather than making assumptions\n\n## Documentation Requirements\n\nAll actions **must include comprehensive JSDoc** with:\n\n1. **Function description** - What the action does\n2. **`@example` block** - Complete working example showing:\n   - Required imports (`createClient`, `http`, action imports)\n   - Client setup with chain and transport\n   - Action usage with realistic parameters\n   - Expected return value handling (if applicable)\n3. **`@param` tags** - For each parameter (client, parameters)\n4. **`@returns` tag** - Description of the return value\n\nExample:\n```typescript\n/**\n * Gets the pool ID for a token pair.\n *\n * @example\n * ```ts\n * import { createClient, http } from ''viem''\n * import { tempo } from ''tempo.ts/chains''\n * import { Actions } from ''tempo.ts/viem''\n *\n * const client = createClient({\n *   chain: tempo({ feeToken: ''0x20c0000000000000000000000000000000000001'' })\n *   transport: http(),\n * })\n *\n * const poolId = await Actions.amm.getPoolId(client, {\n *   userToken: ''0x...'',\n *   validatorToken: ''0x...'',\n * })\n * ```\n *\n * @param client - Client.\n * @param parameters - Parameters.\n * @returns The pool ID.\n */\n```\n\n## Action Types\n\n### Read-Only Actions\n\nFor view/pure functions that only read state:\n\n- Use `readContract` from `viem/actions`\n- Return type should use `ReadContractReturnType`\n- Parameters extend `ReadParameters`\n\n### Mutate-Based Actions\n\nFor state-changing functions, **both variants must be implemented**:\n\n**1. Standard Async Variant**\n\n- Uses `writeContract` from `viem/actions`\n- Returns transaction hash\n- Async operation that doesn''t wait for confirmation\n\n```typescript\nexport async function myAction<\n  chain extends Chain | undefined,\n  account extends Account | undefined,\n>(\n  client: Client<Transport, chain, account>,\n  parameters: myAction.Parameters<chain, account>,\n): Promise<myAction.ReturnValue> {\n  return myAction.inner(writeContract, client, parameters)\n}\n```\n\n**2. Sync Variant (`*Sync`)**\n\n- Named with `Sync` suffix (e.g., `mintSync`, `burnSync`, `rebalanceSwapSync`)\n- Uses `writeContractSync` from `viem/actions`\n- **Waits for transaction confirmation**\n- Returns both the receipt and extracted event data\n- **Must use `extractEvent` to get return values** (not `simulateContract`)\n\n```typescript\nexport async function myActionSync<\n  chain extends Chain | undefined,\n  account extends Account | undefined,\n>(\n  client: Client<Transport, chain, account>,\n  parameters: myActionSync.Parameters<chain, account>,\n): Promise<myActionSync.ReturnValue> {\n  const { throwOnReceiptRevert = true, ...rest } = parameters\n  const receipt = await myAction.inner(writeContractSync, client, {\n    ...rest,\n    throwOnReceiptRevert,\n  } as never)\n  const { args } = myAction.extractEvent(receipt.logs)\n  return {\n    ...args,\n    receipt,\n  } as never\n}\n```\n\n## Namespace Properties\n\nAll actions **must include** the following components within their namespace:\n\n### 1. `Parameters` Type\n\n```typescript\n// Read actions\nexport type Parameters = ReadParameters & Args \n\n// Write actions\nexport type Parameters<\n  chain extends Chain | undefined = Chain | undefined,\n  account extends Account | undefined = Account | undefined,\n> = WriteParameters<chain, account> & Args \n```\n\n### 2. `Args` Type\n\nArguments must be documented with JSDoc.\n\n```typescript\nexport type Args = {\n  /** JSDoc for each argument */\n  argName: Type\n}\n```\n\n### 3. `ReturnValue` Type\n\n```typescript\n// Read actions\nexport type ReturnValue = ReadContractReturnType<typeof Abis.myAbi, ''functionName'', never>\n\n// Write actions\nexport type ReturnValue = WriteContractReturnType\n```\n\n### 4. `ErrorType` Type (for write actions)\n\nWrite actions must include an `ErrorType` export. Use `BaseErrorType` from `viem` as a placeholder with a TODO comment for future exhaustive error typing:\n\n```typescript\n// TODO: exhaustive error type\nexport type ErrorType = BaseErrorType\n```\n\n### 5. `call` Function\n\n**Required for all actions** - enables composition with other viem actions:\n\n```typescript\n/**\n * Defines a call to the `functionName` function.\n *\n * Can be passed as a parameter to:\n * - [`estimateContractGas`](https://viem.sh/docs/contract/estimateContractGas): estimate the gas cost of the call\n * - [`simulateContract`](https://viem.sh/docs/contract/simulateContract): simulate the call\n * - [`sendCalls`](https://viem.sh/docs/actions/wallet/sendCalls): send multiple calls\n *\n * @example\n * ```ts\n * import { createClient, http, walletActions } from ''viem''\n * import { tempo } from ''tempo.ts/chains''\n * import { Actions } from ''tempo.ts/viem''\n *\n * const client = createClient({\n *   chain: tempo({ feeToken: ''0x20c0000000000000000000000000000000000001'' })\n *   transport: http(),\n * }).extend(walletActions)\n *\n * const hash = await client.sendTransaction({\n *   calls: [actions.amm.myAction.call({ arg1, arg2 })],\n * })\n * ```\n *\n * @param args - Arguments.\n * @returns The call.\n */\nexport function call(args: Args) {\n  return defineCall({\n    address: Addresses.contractName,\n    abi: Abis.contractName,\n    args: [/* transformed args */],\n    functionName: ''functionName'',\n  })\n}\n```\n\nThe `call` function enables these use cases:\n- `sendCalls` - Batch multiple calls in one transaction\n- `sendTransaction` with `calls` - Send transaction with multiple operations\n- `multicall` - Execute multiple calls in parallel\n- `estimateContractGas` - Estimate gas costs\n- `simulateContract` - Simulate execution\n\n### 6. `extractEvent` Function (for mutate-based actions)\n\n**Required for all actions that emit events**:\n\n```typescript\n/**\n * Extracts the `EventName` event from logs.\n *\n * @param logs - The logs.\n * @returns The `EventName` event.\n */\nexport function extractEvent(logs: Log[]) {\n  const [log] = parseEventLogs({\n    abi: Abis.contractName,\n    logs,\n    eventName: ''EventName'',\n    strict: true,\n  })\n  if (!log) throw new Error(''`EventName` event not found.'')\n  return log\n}\n```\n\n### 7. `inner` Function (for write actions)\n\n```typescript\n/** @internal */\nexport async function inner<\n  action extends typeof writeContract | typeof writeContractSync,\n  chain extends Chain | undefined,\n  account extends Account | undefined,\n>(\n  action: action,\n  client: Client<Transport, chain, account>,\n  parameters: Parameters<chain, account>,\n): Promise<ReturnType<action>> {\n  const { arg1, arg2, ...rest } = parameters\n  const call = myAction.call({ arg1, arg2 })\n  return (await action(client, {\n    ...rest,\n    ...call,\n  } as never)) as never\n}\n```\n\n## Namespace Structure\n\nOrganize actions using namespace pattern:\n\n```typescript\nexport async function myAction(...) { ... }\n\nexport namespace myAction {\n  export type Parameters = ...\n  export type Args = ...\n  export type ReturnValue = ...\n  \n  export async function inner(...) { ... }  // for write actions\n  export function call(args: Args) { ... }\n  export function extractEvent(logs: Log[]) { ... }  // for mutate actions\n}\n```\n\n## Decision-Making\n\nWhen encountering situations that require judgment:\n\n- **Specification ambiguities**: Prompt developer for clarification\n- **Missing contract details**: Request ABI or specification update\n- **Event structure uncertainty**: Ask for event definition\n- **Parameter transformations**: Confirm expected input/output formats\n- **Edge cases**: Discuss handling strategy with developer\n\n## Naming Conventions\n\n- Action names should match contract function names (in camelCase)\n- Sync variants use `Sync` suffix (e.g., `myActionSync`)\n- Event names in `extractEvent` should match contract event names exactly\n- Namespace components should be exported within the action''s namespace\n\n## Testing\n\nTests should be co-located with actions in `*action-name*.test.ts` files. Reference contract tests in `test/tempo/crates/precompiles/` for expected behavior. \n\nSee `src/tempo/actions/token.test.ts` for a comprehensive example of test patterns and structure.\n\n### Test Structure\n\nOrganize tests by action name with a default test case and behavior-specific tests:\n\n```typescript\ndescribe(''actionName'', () => {\n  test(''default'', async () => {\n    // Test the primary/happy path scenario\n    const { receipt, ...result } = await Actions.namespace.actionSync(client, {\n      param1: value1,\n      param2: value2,\n    })\n    \n    expect(receipt).toBeDefined()\n    expect(result).toMatchInlineSnapshot(`...`)\n  })\n\n  test(''behavior: specific edge case'', async () => {\n    // Test specific behaviors, edge cases, or variations\n  })\n\n  test(''behavior: error conditions'', async () => {\n    // Test error handling\n    await expect(\n      actions.namespace.actionSync(client, { ... })\n    ).rejects.toThrow()\n  })\n})\n\ndescribe.todo(''unimplementedAction'')\n```"},"lastSynced":"2026-03-08T02:03:05.502Z","agentAnalysis":{"suitability":{"en":"Perfect for Ethereum-focused AI Agents needing advanced smart contract generation and management capabilities based on precompile contract specifications.","zh":"适合于需要高级智能合约生成和管理功能的以太坊专注的AI代理，基于预编译合约规范。","ja":"Ethereumに焦点を当てた高度なスマートコントラクト生成および管理機能を必要とするAIエージェントに最適です。事前にコンパイルされたコントラクト仕様に基づいています。","ko":"고급 스마트 계약 생성 및 관리 기능이 필요한 이더리움 중심의 AI 에이전트에게 적합합니다. 사전 컴파일 된 계약 사양을 기반으로 합니다.","es":"Perfecto para Agentes de IA centrados en Ethereum que necesitan capacidades avanzadas de generación y administración de contratos inteligentes basadas en especificaciones de contratos precompilados.","fr":"Parfait pour les agents d''IA axés sur Ethereum nécessitant des capacités avancées de génération et de gestion de contrats intelligents basées sur des spécifications de contrats précompilés.","de":"Perfekt für Ethereum-fokussierte KI-Agents, die erweiterte Funktionen zur Generierung und Verwaltung von Smart Contracts auf Basis von Spezifikationen vorcompilierter Verträge benötigen.","pt":"Perfeito para Agentes de IA focados em Ethereum que necessitam de capacidades avançadas de geração e gerenciamento de contratos inteligentes com base em especificações de contratos pré-compilados.","ru":"Идеально для агентов ИИ, ориентированных на Ethereum, которые нуждаются в продвинутых возможностях генерации и управления умными контрактами на основе предварительно скомпилированных спецификаций контрактов.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يركزون على Ethereum والذين يحتاجون إلى قدرات متقدمة لإنشاء وتحكم عقود ذكية بناءً على مواصفات عقد مجمعة مسبقًا."},"recommendation":{"en":"Empowers agents to generate actions based on precompile contract specifications, utilizing TypeScript for Ethereum development and interacting with smart contracts through the tempo-codegen interface, specifically leveraging precompiles and specs from directories like `test/tempo/docs/specs/` and `test/tempo/crates/contracts/src/precompiles`.","zh":"赋予代理人基于预编译合约规范生成操作的能力，利用TypeScript进行以太坊开发，并通过tempo-codegen接口与智能合约交互，特别利用来自目录如`test/tempo/docs/specs/`和`test/tempo/crates/contracts/src/precompiles`的预编译和规格。","ja":"事前にコンパイルされたコントラクト仕様に基づいて操作を生成するエージェントを可能にします。Ethereum開発にはTypeScriptを使用し、tempo-codegenインターフェイスを介してスマートコントラクトとやり取りします。特に、`test/tempo/docs/specs/`および`test/tempo/crates/contracts/src/precompiles`などのディレクトリからの事前コンパイルおよび仕様を活用します。","ko":"사전 컴파일 된 계약 사양을 기반으로 동작을 생성할 수 있는 에이전트를 가능하게 합니다. 이더리움 개발에는 TypeScript를 사용하며, tempo-codegen 인터페이스를 통해 스마트 계약과 상호 작용합니다. 특히, `test/tempo/docs/specs/` 및 `test/tempo/crates/contracts/src/precompiles`와 같은 디렉토리에서 사전 컴파일 및 사양을 활용합니다.","es":"Habilita a los agentes a generar acciones basadas en especificaciones de contratos precompilados, utilizando TypeScript para el desarrollo de Ethereum e interactuando con contratos inteligentes a través de la interfaz tempo-codegen, aprovechando específicamente precompilados y especificaciones de directorios como `test/tempo/docs/specs/` y `test/tempo/crates/contracts/src/precompiles`.","fr":"Permet aux agents de générer des actions basées sur des spécifications de contrats précompilés, en utilisant TypeScript pour le développement Ethereum et en interagissant avec des contrats intelligents via l''interface tempo-codegen, en exploitant spécifiquement des précompilés et des spécifications de répertoires tels que `test/tempo/docs/specs/` et `test/tempo/crates/contracts/src/precompiles`.","de":"Ermöglicht es Agents, Aktionen basierend auf Spezifikationen vorcompilierter Verträge zu generieren, indem TypeScript für die Ethereum-Entwicklung verwendet wird und mit Smart Contracts über die tempo-codegen-Schnittstelle interagiert, insbesondere indem auf Spezifikationen und Vorcompilierungen in Verzeichnissen wie `test/tempo/docs/specs/` und `test/tempo/crates/contracts/src/precompiles` zugegriffen wird.","pt":"Habilita os agentes a gerar ações com base em especificações de contratos pré-compilados, utilizando TypeScript para desenvolvimento do Ethereum e interagindo com contratos inteligentes por meio da interface tempo-codegen, aproveitando especificações e pré-compilados de diretórios como `test/tempo/docs/specs/` e `test/tempo/crates/contracts/src/precompiles`.","ru":"Наделяет агентов возможностью генерировать действия на основе предварительно скомпилированных спецификаций контрактов, используя TypeScript для разработки на Ethereum и взаимодействуя с умными контрактами через интерфейс tempo-codegen, в частности, используя предварительно скомпилированные и спецификации из директорий, таких как `test/tempo/docs/specs/` и `test/tempo/crates/contracts/src/precompiles`.","ar":"تمكين الوكلاء من إنشاء إجراءات بناءً على مواصفات عقد مجمعة مسبقًا، باستخدام TypeScript لتطوير Ethereum والتفاعل مع العقود الذكية من خلال واجهة tempo-codegen، وتحديداً من خلال الاستفادة من المواصفات والبرامج المجمعة من الدلائل مثل `test/tempo/docs/specs/` و `test/tempo/crates/contracts/src/precompiles`."},"useCases":{"en":["Generating actions for Ethereum smart contracts","Creating custom precompile contract specifications","Automating smart contract deployment based on pre-defined specs"],"zh":["为Ethereum智能合约生成操作","创建自定义预编译合约规范","根据预定义规范自动化智能合约部署"],"ja":["Ethereumスマートコントラクトの操作を生成する","カスタム事前コンパイルコントラクト仕様を作成する","事前に定義された仕様に基づいてスマートコントラクトのデプロイを自動化する"],"ko":["이더리움 스마트 계약을 위한 동작 생성","사전 컴파일 계약 사양을 사용한 맞춤형 생성","사전 정의된 사양을 기반으로 스마트 계약 배포 자동화"],"es":["Generación de acciones para contratos inteligentes de Ethereum","Creación de especificaciones personalizadas de contratos precompilados","Automatización de la implementación de contratos inteligentes basada en especificaciones predefinidas"],"fr":["Génération d''actions pour les contrats intelligents Ethereum","Création de spécifications de contrats précompilés personnalisés","Automatisation du déploiement de contrats intelligents basé sur des spécifications prédéfinies"],"de":["Generierung von Aktionen für Ethereum-Smart-Contracts","Erstellung benutzerdefinierter Spezifikationen vorcompilierter Verträge","Automatisierung der Bereitstellung von Smart Contracts basierend auf vordefinierten Spezifikationen"],"pt":["Gerar ações para contratos inteligentes do Ethereum","Criar especificações personalizadas de contratos pré-compilados","Automatizar a implantação de contratos inteligentes com base em especificações pré-definidas"],"ru":["Генерировать действия для умных контрактов Ethereum","Создавать пользовательские спецификации предварительно скомпилированных контрактов","Автоматизировать развертывание умных контрактов на основе предварительно определенных спецификаций"],"ar":["إنشاء إجراءات لعقود ذكية Ethereum","إنشاء مواصفات عقد مجمعة مخصصة","توفير تلقائي لتثبيت عقود ذكية بناءً على مواصفات محددة مسبقًا"]},"limitations":{"en":["Requires knowledge of Ethereum development and smart contracts","Dependent on consistency between specs and precompiles","TypeScript expertise necessary for effective utilization"],"zh":["需要以太坊开发和智能合约的知识","依赖于规范和预编译之间的一致性","需要TypeScript专长以有效利用"],"ja":["Ethereum開発およびスマートコントラクトの知識が必要","仕様と事前コンパイルの間の一貫性に依存","効果的に利用するにはTypeScriptの専門知識が必要"],"ko":["이더리움 개발 및 스마트 계약에 대한 지식이 필요합니다","사양 및 사전 컴파일 간의 일관성에 의존","유효한 활용을 위해서는 TypeScript 전문 지식이 필요"],"es":["Requiere conocimientos de desarrollo de Ethereum y contratos inteligentes","Dependiente de la consistencia entre especificaciones y precompilados","Se requiere experiencia en TypeScript para una utilización efectiva"],"fr":["Nécessite des connaissances en développement Ethereum et en contrats intelligents","Dépend de la cohérence entre les spécifications et les précompilés","L''expertise en TypeScript est nécessaire pour une utilisation efficace"],"de":["Erfordert Kenntnisse in Ethereum-Entwicklung und Smart Contracts","Abhängig von der Konsistenz zwischen Spezifikationen und Vorcompilierungen","TypeScript-Expertise ist für eine effektive Nutzung erforderlich"],"pt":["Requer conhecimento de desenvolvimento do Ethereum e contratos inteligentes","Dependente da consistência entre especificações e pré-compilados","É necessário conhecimento de TypeScript para utilização eficaz"],"ru":["Требует знания разработки на Ethereum и умных контрактов","Зависит от согласованности между спецификациями и предварительно скомпилированными","Требуется опыт работы с TypeScript для эффективного использования"],"ar":["يتطلب معرفة بتطوير Ethereum وعقود ذكية","يعتمد على الاتساق بين المواصفات والبرامج المجمعة","يحتاج إلى معرفة TypeScript للاستخدام الفعال"]},"version":4},"contentHash":"2bdad55fe4ed7d38350e90cb781370032f54d16db05ad642de2329b3983d898b","qualityScore":42}');
